-- Renal question bank: exactly 850 hand-written NCLEX-style
-- single-best-answer questions, 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/Renal System/Kidney-Anatomy.html
--   Notes/Renal System/Urinary-Tract-Infections.html
--   Notes/Renal System/Cystitis.html
--   Notes/Renal System/Pyelonephritis.html
--   Notes/Renal System/Urine-Sample-Collection.html
--   Notes/Renal System/Urinary-Catheters-and-CBI.html
--   Notes/Renal System/Urinary-Incontinence.html
--   Notes/Renal System/Renal-Calculi.html
--   Notes/Renal System/Acute-Kidney-Injury.html
--   Notes/Renal System/Chronic-Kidney-Disease.html
--   Notes/Renal System/Dialysis.html
--   Notes/Renal System/Dialysis-Disequilibrium-Syndrome.html
--   Notes/Renal System/Glomerulonephritis.html
--   Notes/Renal System/Hemolytic-Uremic-Syndrome.html
--   Notes/Renal System/Polycystic-Kidney-Disease.html
--   Notes/Renal System/Wilms-Tumor.html
--   Notes/Renal System/Pheochromocytoma.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (850) exist after insert.
BEGIN;

CREATE TEMP TABLE _renal_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _renal_sources (source_key, source_path, category) VALUES
  ('anatomy', 'Notes/Renal System/Kidney-Anatomy.html', 'Renal NCLEX seed v1 - kidney anatomy'),
  ('uti', 'Notes/Renal System/Urinary-Tract-Infections.html', 'Renal NCLEX seed v1 - urinary tract infections'),
  ('cystitis', 'Notes/Renal System/Cystitis.html', 'Renal NCLEX seed v1 - cystitis'),
  ('pyelo', 'Notes/Renal System/Pyelonephritis.html', 'Renal NCLEX seed v1 - pyelonephritis'),
  ('urine_collection', 'Notes/Renal System/Urine-Sample-Collection.html', 'Renal NCLEX seed v1 - urine sample collection'),
  ('catheters', 'Notes/Renal System/Urinary-Catheters-and-CBI.html', 'Renal NCLEX seed v1 - urinary catheters and cbi'),
  ('incontinence', 'Notes/Renal System/Urinary-Incontinence.html', 'Renal NCLEX seed v1 - urinary incontinence'),
  ('calculi', 'Notes/Renal System/Renal-Calculi.html', 'Renal NCLEX seed v1 - renal calculi'),
  ('aki', 'Notes/Renal System/Acute-Kidney-Injury.html', 'Renal NCLEX seed v1 - acute kidney injury'),
  ('ckd', 'Notes/Renal System/Chronic-Kidney-Disease.html', 'Renal NCLEX seed v1 - chronic kidney disease'),
  ('dialysis', 'Notes/Renal System/Dialysis.html', 'Renal NCLEX seed v1 - dialysis'),
  ('dds', 'Notes/Renal System/Dialysis-Disequilibrium-Syndrome.html', 'Renal NCLEX seed v1 - dialysis disequilibrium syndrome'),
  ('gn', 'Notes/Renal System/Glomerulonephritis.html', 'Renal NCLEX seed v1 - glomerulonephritis'),
  ('hus', 'Notes/Renal System/Hemolytic-Uremic-Syndrome.html', 'Renal NCLEX seed v1 - hemolytic uremic syndrome'),
  ('pkd', 'Notes/Renal System/Polycystic-Kidney-Disease.html', 'Renal NCLEX seed v1 - polycystic kidney disease'),
  ('wilms', 'Notes/Renal System/Wilms-Tumor.html', 'Renal NCLEX seed v1 - wilms tumor'),
  ('pheo', 'Notes/Renal System/Pheochromocytoma.html', 'Renal NCLEX seed v1 - pheochromocytoma');

CREATE TEMP TABLE _renal_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _renal_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'renal'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Renal"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'renal'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _renal_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Renal subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Renal points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _renal_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Renal seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _renal_seed_map) <> 17 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 17 note mappings, found %.',
      (SELECT count(*) FROM _renal_seed_map);
  END IF;

  INSERT INTO _renal_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _renal_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, false, v.display_order, 1, true
  FROM (VALUES
  ('anatomy', 1, 'A client reviewing an abdominal imaging report asks why the right kidney sits lower than the left. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The spleen pushes the right kidney downward.\""}, {"id": "b", "text": "\"The right kidney is normally twice as large.\""}, {"id": "c", "text": "\"The liver displaces the right kidney downward.\""}, {"id": "d", "text": "\"The right kidney sits inside the peritoneum.\""}]'::jsonb, '["c"]', 'The right kidney is slightly lower than the left because the liver displaces it downward. Both kidneys are retroperitoneal, and the spleen is not the structure that pushes the right kidney down.'),
  ('anatomy', 2, 'A nurse reviews a client''s renal ultrasound report. Which finding should the nurse recognize as normal kidney anatomy?', '[{"id": "a", "text": "The right kidney lies slightly lower than the left."}, {"id": "b", "text": "The left kidney lies lower because of the liver."}, {"id": "c", "text": "Both kidneys lie within the peritoneal cavity."}, {"id": "d", "text": "Each kidney measures about 25 to 30 cm long."}]'::jsonb, '["a"]', 'Normally the right kidney is slightly lower than the left because the liver pushes it down. The kidneys are retroperitoneal and each is about 10–12 cm long, so the other findings are not normal anatomy.'),
  ('anatomy', 3, 'A client scheduled for a kidney procedure asks where the kidneys are located. Which statement by the nurse is accurate?', '[{"id": "a", "text": "\"Inside the peritoneal cavity, in front of the intestines.\""}, {"id": "b", "text": "\"Behind the peritoneum, in the lower back.\""}, {"id": "c", "text": "\"In the pelvis, directly beside the bladder.\""}, {"id": "d", "text": "\"In the upper chest, just under the diaphragm.\""}]'::jsonb, '["b"]', 'The kidneys lie in the retroperitoneal space, behind the peritoneum, in the lower back. They are not inside the peritoneal cavity.'),
  ('anatomy', 4, 'A client asks the nurse how large a kidney is. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"About the size of a grape, roughly 2 to 3 cm long.\""}, {"id": "b", "text": "\"About the size of a thumb, roughly 5 cm long.\""}, {"id": "c", "text": "\"About the size of a football, roughly 30 cm long.\""}, {"id": "d", "text": "\"About the size of a fist, roughly 10 to 12 cm long.\""}]'::jsonb, '["d"]', 'Each kidney is approximately the size of a fist, about 10–12 cm long. The other sizes are far smaller or larger than a normal kidney.'),
  ('anatomy', 5, 'After a minor fall, a client asks what protects the kidneys from injury. Which structures should the nurse identify?', '[{"id": "a", "text": "The ribcage, fat, and fascia"}, {"id": "b", "text": "The sternum and the pelvic bones"}, {"id": "c", "text": "The bladder wall and the ureters"}, {"id": "d", "text": "The diaphragm and the spleen"}]'::jsonb, '["a"]', 'The kidneys are protected by the ribcage, fat, and fascia. The sternum, pelvic bones, bladder, and spleen are not the protective structures described for the kidneys.'),
  ('anatomy', 6, 'A client''s blood pressure drops significantly after blood loss. The nurse anticipates that the kidneys will respond by secreting which substance?', '[{"id": "a", "text": "Erythropoietin"}, {"id": "b", "text": "Renin"}, {"id": "c", "text": "Antidiuretic hormone"}, {"id": "d", "text": "Calcitriol"}]'::jsonb, '["b"]', 'Renin is secreted when blood pressure drops and raises blood pressure by activating RAAS. ADH comes from the posterior pituitary, not the kidney, and erythropoietin stimulates RBC production.'),
  ('anatomy', 7, 'A nurse is teaching a client with hypertension how the kidneys influence blood pressure. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"My kidneys secrete renin.\""}, {"id": "b", "text": "\"Renin activates the RAAS system.\""}, {"id": "c", "text": "\"Renin works to raise blood pressure.\""}, {"id": "d", "text": "\"Renin is released to lower my blood pressure.\""}]'::jsonb, '["d"]', 'The kidneys secrete renin, which activates RAAS and raises blood pressure. Stating that renin lowers blood pressure reverses its action and needs correction.'),
  ('anatomy', 8, 'A client with chronic kidney disease (CKD) is found to have anemia and reports fatigue. The nurse recognizes the anemia is most likely related to which change?', '[{"id": "a", "text": "Decreased erythropoietin production"}, {"id": "b", "text": "Increased renin secretion"}, {"id": "c", "text": "Decreased antidiuretic hormone release"}, {"id": "d", "text": "Increased calcitriol production"}]'::jsonb, '["a"]', 'In CKD, the kidneys produce less erythropoietin (EPO), so RBC production falls and anemia results. Renin affects blood pressure, not RBC production.'),
  ('anatomy', 9, 'A nurse is teaching a client with chronic kidney disease about anemia. Which client statement indicates understanding?', '[{"id": "a", "text": "\"My kidneys make too much renin, which destroys red cells.\""}, {"id": "b", "text": "\"My kidneys activate too much vitamin D, which slows red cells.\""}, {"id": "c", "text": "\"My kidneys make less erythropoietin, so my marrow makes fewer red cells.\""}, {"id": "d", "text": "\"My kidneys release too much aldosterone, which dilutes my red cells.\""}]'::jsonb, '["c"]', 'Erythropoietin from the kidneys stimulates the bone marrow to make RBCs; CKD lowers EPO and causes anemia. Renin and vitamin D activation are not the mechanism of RBC production.'),
  ('anatomy', 10, 'A client with severely impaired kidney function has decreased calcium absorption. Which loss of kidney function best explains this finding?', '[{"id": "a", "text": "Reduced secretion of renin"}, {"id": "b", "text": "Reduced secretion of erythropoietin"}, {"id": "c", "text": "Reduced reabsorption of glucose"}, {"id": "d", "text": "Reduced activation of vitamin D"}]'::jsonb, '["d"]', 'The kidneys convert inactive vitamin D to active calcitriol, which allows calcium absorption. Renin controls blood pressure and erythropoietin controls RBC production, not calcium absorption.'),
  ('anatomy', 11, 'A nurse is reviewing kidney functions with a client. Which client statement about vitamin D indicates a need for further teaching?', '[{"id": "a", "text": "\"My kidneys turn inactive vitamin D into its active form.\""}, {"id": "b", "text": "\"My kidneys store vitamin D but never change its form.\""}, {"id": "c", "text": "\"Calcitriol is the active form of vitamin D.\""}, {"id": "d", "text": "\"Active vitamin D helps my body absorb calcium.\""}]'::jsonb, '["b"]', 'The kidneys activate vitamin D by converting the inactive form to calcitriol, which supports calcium absorption. Saying the kidneys only store vitamin D without changing it is incorrect.'),
  ('anatomy', 12, 'A client''s urinalysis shows albumin in the urine. The nurse recognizes this finding most likely indicates damage to which kidney structure?', '[{"id": "a", "text": "Renal pelvis"}, {"id": "b", "text": "Glomerulus"}, {"id": "c", "text": "Collecting duct"}, {"id": "d", "text": "Calyx"}]'::jsonb, '["b"]', 'When the glomerulus is damaged, protein/albumin leaks into the urine (proteinuria). The renal pelvis and calyces collect urine rather than filter blood.'),
  ('anatomy', 13, 'A nurse is caring for a client with damage to the glomeruli. Which finding should the nurse expect?', '[{"id": "a", "text": "Protein leaking into the urine"}, {"id": "b", "text": "Increased red blood cell production"}, {"id": "c", "text": "Decreased blood urea nitrogen"}, {"id": "d", "text": "Increased vitamin D activation"}]'::jsonb, '["a"]', 'Glomerular damage allows protein/albumin to leak into the urine. Kidney injury causes BUN to build up rather than decrease.'),
  ('anatomy', 14, 'A client is admitted with acute kidney injury. Which laboratory findings should the nurse expect?', '[{"id": "a", "text": "Decreased BUN and decreased creatinine"}, {"id": "b", "text": "Decreased BUN and elevated creatinine"}, {"id": "c", "text": "Elevated BUN and elevated creatinine"}, {"id": "d", "text": "Elevated BUN and decreased creatinine"}]'::jsonb, '["c"]', 'Kidney injury causes waste products, BUN and creatinine, to build up in the blood. Both values rise rather than fall.'),
  ('anatomy', 15, 'A nurse is planning care for a client with kidney injury. Which problems should the nurse anticipate?', '[{"id": "a", "text": "Fluid loss only, with normal waste removal"}, {"id": "b", "text": "Increased red blood cell and vitamin D production"}, {"id": "c", "text": "Lowered BUN with improved acid-base balance"}, {"id": "d", "text": "Fluid and electrolyte imbalance with waste buildup"}]'::jsonb, '["d"]', 'Kidney injury produces fluid and electrolyte imbalance plus buildup of wastes such as BUN and creatinine. Waste removal is impaired, so BUN rises rather than falls.'),
  ('anatomy', 16, 'A client with kidney injury is at risk for an acid-base imbalance. The nurse explains that healthy kidneys maintain pH by which action?', '[{"id": "a", "text": "Reabsorbing H+ ions and excreting HCO3–"}, {"id": "b", "text": "Excreting H+ ions and reabsorbing HCO3–"}, {"id": "c", "text": "Secreting renin and excreting glucose"}, {"id": "d", "text": "Secreting EPO and reabsorbing urea"}]'::jsonb, '["b"]', 'The kidneys maintain pH by excreting hydrogen ions and reabsorbing bicarbonate. Option A reverses both actions.'),
  ('anatomy', 17, 'A nursing student is explaining renal acid-base regulation to a client. Which statement by the student requires correction?', '[{"id": "a", "text": "\"The kidneys excrete hydrogen ions.\""}, {"id": "b", "text": "\"The kidneys reabsorb bicarbonate.\""}, {"id": "c", "text": "\"These actions help maintain the pH.\""}, {"id": "d", "text": "\"The kidneys retain hydrogen ions to keep pH stable.\""}]'::jsonb, '["d"]', 'The kidneys excrete, not retain, hydrogen ions and reabsorb bicarbonate to maintain pH. The other statements are accurate.'),
  ('anatomy', 18, 'A client asks how the kidneys handle electrolytes. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"They reabsorb or excrete sodium, potassium, calcium, and chloride as needed.\""}, {"id": "b", "text": "\"They excrete all filtered electrolytes and never reabsorb them.\""}, {"id": "c", "text": "\"They produce new sodium and potassium for the bloodstream.\""}, {"id": "d", "text": "\"They regulate only sodium; other electrolytes are unaffected.\""}]'::jsonb, '["a"]', 'For fluid and electrolyte regulation, the kidneys reabsorb or excrete Na+, K+, Ca2+, and Cl– as needed. They do not simply excrete everything or regulate sodium alone.'),
  ('anatomy', 19, 'A client asks which part of the kidney actually filters blood to form urine. The nurse identifies which structure as the functional unit of the kidney?', '[{"id": "a", "text": "Renal pelvis"}, {"id": "b", "text": "Calyx"}, {"id": "c", "text": "Nephron"}, {"id": "d", "text": "Ureter"}]'::jsonb, '["c"]', 'The nephron is the basic filtering unit of the kidney. The renal pelvis and calyces collect urine rather than filter blood.'),
  ('anatomy', 20, 'Which statement by a nursing student about the nephron is accurate?', '[{"id": "a", "text": "\"Each kidney contains about 1,000 nephrons.\""}, {"id": "b", "text": "\"Each kidney contains about 1 million nephrons.\""}, {"id": "c", "text": "\"Nephrons are found only in the renal pelvis.\""}, {"id": "d", "text": "\"Nephrons store urine until the bladder fills.\""}]'::jsonb, '["b"]', 'Each kidney has about 1 million nephrons, which filter blood to produce urine. Nephrons filter rather than store urine.'),
  ('anatomy', 21, 'A pathology report describes tissue taken from a client''s renal cortex. Which structures should the nurse expect this tissue to contain?', '[{"id": "a", "text": "Renal pyramids and loops of Henle"}, {"id": "b", "text": "Calyces and the renal pelvis"}, {"id": "c", "text": "Glomeruli and proximal/distal tubules"}, {"id": "d", "text": "Collecting ducts and the ureter"}]'::jsonb, '["c"]', 'The cortex is the outer layer containing the glomeruli and the proximal and distal tubules. Renal pyramids and the loop of Henle are in the medulla.'),
  ('anatomy', 22, 'Which kidney region does the nurse identify as being made of renal pyramids and as the site where urine is concentrated?', '[{"id": "a", "text": "Cortex"}, {"id": "b", "text": "Medulla"}, {"id": "c", "text": "Renal pelvis"}, {"id": "d", "text": "Calyx"}]'::jsonb, '["b"]', 'The medulla is the inner region made of renal pyramids, where urine concentrates and the loop of Henle resides. The cortex is the outer layer containing glomeruli.'),
  ('anatomy', 23, 'A nurse is describing the path urine takes after it leaves the renal pyramids. Which sequence is correct?', '[{"id": "a", "text": "Calyces → renal pelvis → ureter"}, {"id": "b", "text": "Renal pelvis → calyces → ureter"}, {"id": "c", "text": "Ureter → calyces → renal pelvis"}, {"id": "d", "text": "Calyces → ureter → renal pelvis"}]'::jsonb, '["a"]', 'Calyces collect urine from the renal pyramids and pass it to the renal pelvis, which funnels it into the ureter. The pelvis comes after the calyces, not before.'),
  ('anatomy', 24, 'A client asks which part of the kidney empties urine directly into the ureter. Which structure should the nurse identify?', '[{"id": "a", "text": "Calyx"}, {"id": "b", "text": "Glomerulus"}, {"id": "c", "text": "Proximal tubule"}, {"id": "d", "text": "Renal pelvis"}]'::jsonb, '["d"]', 'The funnel-shaped renal pelvis collects urine from the calyces and funnels it into the ureter. The calyces pass urine to the renal pelvis, not directly to the ureter.'),
  ('anatomy', 25, 'A nursing student is labeling a kidney diagram. Which description of the renal calyces is accurate?', '[{"id": "a", "text": "Tiny capillaries that surround the tubules for reabsorption"}, {"id": "b", "text": "The outer layer of the kidney that contains the glomeruli"}, {"id": "c", "text": "A funnel-shaped structure that drains directly to the bladder"}, {"id": "d", "text": "Small cup-shaped chambers that collect urine from renal pyramids"}]'::jsonb, '["d"]', 'Calyces are small cup-shaped chambers that collect urine from the renal pyramids and pass it to the renal pelvis. Capillaries surrounding tubules are the peritubular capillaries.'),
  ('anatomy', 26, 'A nurse is explaining to a client how urine begins to form. Which structure performs the initial filtration of blood?', '[{"id": "a", "text": "Loop of Henle"}, {"id": "b", "text": "Collecting duct"}, {"id": "c", "text": "Glomerulus"}, {"id": "d", "text": "Distal convoluted tubule"}]'::jsonb, '["c"]', 'The glomerulus performs the initial filtration of blood into filtrate. The loop of Henle concentrates urine, and the collecting duct performs final water reabsorption.'),
  ('anatomy', 27, 'A nursing student is describing glomerular filtrate. Which substances does the glomerulus normally filter into the filtrate?', '[{"id": "a", "text": "Water, ions, glucose, and urea"}, {"id": "b", "text": "Water only; ions and glucose stay in the blood"}, {"id": "c", "text": "Urea only; water and ions stay in the blood"}, {"id": "d", "text": "Glucose only; water and urea stay in the blood"}]'::jsonb, '["a"]', 'The glomerulus filters water, ions, glucose, and urea into the filtrate. Each other option wrongly limits filtration to a single substance.'),
  ('anatomy', 28, 'A nursing student is asked where the glomerulus is located. Which answer is correct?', '[{"id": "a", "text": "In the renal pelvis near the ureter"}, {"id": "b", "text": "In the renal pyramids of the medulla"}, {"id": "c", "text": "In Bowman''s capsule within the cortex"}, {"id": "d", "text": "In the calyces near the renal pelvis"}]'::jsonb, '["c"]', 'The glomerulus sits in Bowman''s capsule in the cortex. The renal pyramids make up the medulla, not the site of the glomerulus.'),
  ('anatomy', 29, 'Which nephron segment reabsorbs approximately 65% of filtered water along with all of the filtered glucose?', '[{"id": "a", "text": "Collecting duct"}, {"id": "b", "text": "Proximal convoluted tubule"}, {"id": "c", "text": "Distal convoluted tubule"}, {"id": "d", "text": "Glomerulus"}]'::jsonb, '["b"]', 'The proximal convoluted tubule reabsorbs about 65% of water, all glucose, amino acids, and electrolytes. The collecting duct handles final ADH-controlled water reabsorption.'),
  ('anatomy', 30, 'A nursing student states that glucose and amino acids are reabsorbed in the collecting duct. Which response by the instructor is correct?', '[{"id": "a", "text": "\"Correct; the collecting duct reabsorbs all glucose.\""}, {"id": "b", "text": "\"Incorrect; the proximal convoluted tubule reabsorbs them.\""}, {"id": "c", "text": "\"Incorrect; the glomerulus reabsorbs them.\""}, {"id": "d", "text": "\"Incorrect; the renal pelvis reabsorbs them.\""}]'::jsonb, '["b"]', 'All glucose and amino acids are reabsorbed in the proximal convoluted tubule. The glomerulus filters rather than reabsorbs, and the collecting duct performs final water reabsorption.'),
  ('anatomy', 31, 'Which statement about the loop of Henle is accurate?', '[{"id": "a", "text": "The descending limb reabsorbs water; the ascending limb reabsorbs Na+/Cl–."}, {"id": "b", "text": "The descending limb reabsorbs Na+/Cl–; the ascending limb reabsorbs water."}, {"id": "c", "text": "Both limbs of the loop secrete water into the filtrate."}, {"id": "d", "text": "The loop sits in the cortex and performs initial filtration."}]'::jsonb, '["a"]', 'The loop of Henle concentrates urine by reabsorbing water in the descending limb and Na+/Cl– in the ascending limb. Option B reverses the limbs.'),
  ('anatomy', 32, 'Which nephron structure resides in the medulla and concentrates urine?', '[{"id": "a", "text": "Glomerulus"}, {"id": "b", "text": "Proximal convoluted tubule"}, {"id": "c", "text": "Distal convoluted tubule"}, {"id": "d", "text": "Loop of Henle"}]'::jsonb, '["d"]', 'The loop of Henle resides in the medulla, where urine is concentrated. The glomerulus and the proximal and distal tubules are located in the cortex.'),
  ('anatomy', 33, 'A client has elevated aldosterone levels. The nurse knows this hormone acts on which nephron segment?', '[{"id": "a", "text": "Glomerulus"}, {"id": "b", "text": "Distal convoluted tubule"}, {"id": "c", "text": "Loop of Henle"}, {"id": "d", "text": "Proximal convoluted tubule"}]'::jsonb, '["b"]', 'Aldosterone works in the distal convoluted tubule (DCT), where it retains Na+ and excretes K+. The glomerulus performs filtration, not aldosterone-driven reabsorption.'),
  ('anatomy', 34, 'A client has excess aldosterone. Which effects should the nurse anticipate?', '[{"id": "a", "text": "Sodium excretion, potassium retention, decreased blood pressure"}, {"id": "b", "text": "Sodium retention, potassium retention, decreased blood pressure"}, {"id": "c", "text": "Sodium retention, potassium excretion, increased blood pressure"}, {"id": "d", "text": "Sodium excretion, potassium excretion, increased blood pressure"}]'::jsonb, '["c"]', 'Aldosterone causes the DCT to reabsorb sodium and excrete potassium, increasing water retention and blood pressure. Option A reverses every effect.'),
  ('anatomy', 35, 'A nurse is teaching a client about aldosterone. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Aldosterone causes my body to hold on to water.\""}, {"id": "b", "text": "\"Aldosterone can raise my blood pressure.\""}, {"id": "c", "text": "\"Aldosterone helps my kidneys get rid of potassium.\""}, {"id": "d", "text": "\"Aldosterone makes my kidneys get rid of sodium.\""}]'::jsonb, '["d"]', 'Aldosterone retains sodium and excretes potassium, which increases water retention and blood pressure. Saying it rids the body of sodium is incorrect.'),
  ('anatomy', 36, 'A nursing student is reviewing hormones that affect the kidney. Which hormone is correctly paired with its source?', '[{"id": "a", "text": "Aldosterone — adrenal cortex"}, {"id": "b", "text": "ADH — adrenal cortex"}, {"id": "c", "text": "Aldosterone — posterior pituitary"}, {"id": "d", "text": "Renin — posterior pituitary"}]'::jsonb, '["a"]', 'Aldosterone comes from the adrenal cortex, whereas ADH comes from the posterior pituitary and renin is secreted by the kidneys. The other pairings mix up these sources.'),
  ('anatomy', 37, 'A client''s laboratory results show an elevated antidiuretic hormone (ADH) level. Which urine characteristic should the nurse expect?', '[{"id": "a", "text": "Dilute, large-volume urine"}, {"id": "b", "text": "Concentrated urine"}, {"id": "c", "text": "Urine with protein leakage"}, {"id": "d", "text": "Urine with no urea present"}]'::jsonb, '["b"]', 'ADH controls water reabsorption in the collecting duct, so increased ADH produces concentrated urine. Dilute urine is the opposite effect, and protein leakage reflects glomerular damage.'),
  ('anatomy', 38, 'A nurse is teaching a client about antidiuretic hormone (ADH). Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"ADH comes from the posterior pituitary.\""}, {"id": "b", "text": "\"ADH helps my kidneys reabsorb water.\""}, {"id": "c", "text": "\"More ADH makes my urine more dilute.\""}, {"id": "d", "text": "\"ADH acts on the collecting duct.\""}]'::jsonb, '["c"]', 'ADH from the posterior pituitary acts on the collecting duct to reabsorb water, producing concentrated urine. More ADH does not make urine more dilute.'),
  ('anatomy', 39, 'A nursing student asks which hormone controls the final reabsorption of water in the collecting duct. Which answer by the nurse is correct?', '[{"id": "a", "text": "Renin"}, {"id": "b", "text": "Aldosterone"}, {"id": "c", "text": "Erythropoietin"}, {"id": "d", "text": "Antidiuretic hormone"}]'::jsonb, '["d"]', 'Final water reabsorption in the collecting duct is controlled by ADH. Aldosterone acts on the DCT to retain sodium and excrete potassium.'),
  ('anatomy', 40, 'In which nephron structure does final water reabsorption take place before urine reaches the renal pelvis?', '[{"id": "a", "text": "Collecting duct"}, {"id": "b", "text": "Glomerulus"}, {"id": "c", "text": "Proximal convoluted tubule"}, {"id": "d", "text": "Bowman''s capsule"}]'::jsonb, '["a"]', 'The collecting duct, which runs from the medulla to the renal pelvis, performs ADH-controlled final water reabsorption. The proximal tubule reabsorbs about 65% of water earlier in the nephron.'),
  ('anatomy', 41, 'A nurse is explaining renal circulation to a client. Which sequence correctly describes blood flow through the kidney?', '[{"id": "a", "text": "Renal artery → efferent arteriole → glomerulus → afferent arteriole → peritubular capillaries → renal vein"}, {"id": "b", "text": "Renal artery → afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries → renal vein"}, {"id": "c", "text": "Renal vein → afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries → renal artery"}, {"id": "d", "text": "Renal artery → afferent arteriole → peritubular capillaries → glomerulus → efferent arteriole → renal vein"}]'::jsonb, '["b"]', 'Blood enters by the renal artery, reaches the glomerulus through the afferent arteriole, leaves through the efferent arteriole to the peritubular capillaries, and exits by the renal vein. Option A reverses the afferent and efferent arterioles.'),
  ('anatomy', 42, 'A nursing student is labeling a diagram of renal blood flow. Which vessel delivers blood to the glomerulus?', '[{"id": "a", "text": "Efferent arteriole"}, {"id": "b", "text": "Afferent arteriole"}, {"id": "c", "text": "Peritubular capillaries"}, {"id": "d", "text": "Renal vein"}]'::jsonb, '["b"]', 'The afferent arteriole delivers blood to the glomerulus. The efferent arteriole carries remaining blood away from it.'),
  ('anatomy', 43, 'Which vessel carries the remaining blood away from the glomerulus after filtration?', '[{"id": "a", "text": "Afferent arteriole"}, {"id": "b", "text": "Renal artery"}, {"id": "c", "text": "Peritubular capillaries"}, {"id": "d", "text": "Efferent arteriole"}]'::jsonb, '["d"]', 'The efferent arteriole carries the remaining blood away from the glomerulus. The afferent arteriole delivers blood to the glomerulus.'),
  ('anatomy', 44, 'Which vessels surround the renal tubules and allow reabsorbed substances to return to the blood?', '[{"id": "a", "text": "Afferent arterioles"}, {"id": "b", "text": "Renal arteries"}, {"id": "c", "text": "Efferent arterioles"}, {"id": "d", "text": "Peritubular capillaries"}]'::jsonb, '["d"]', 'Peritubular capillaries surround the tubules and allow reabsorption back into the blood. Efferent arterioles carry blood away from the glomerulus to these capillaries.'),
  ('anatomy', 45, 'Which vessel returns filtered, cleaned blood from the kidney to the systemic circulation?', '[{"id": "a", "text": "Renal artery"}, {"id": "b", "text": "Afferent arteriole"}, {"id": "c", "text": "Renal vein"}, {"id": "d", "text": "Efferent arteriole"}]'::jsonb, '["c"]', 'The renal vein returns filtered, cleaned blood to the systemic circulation. The renal artery brings unfiltered blood into the kidney.'),
  ('anatomy', 46, 'Which description best fits the blood entering the kidney through the renal artery?', '[{"id": "a", "text": "Oxygenated and unfiltered"}, {"id": "b", "text": "Deoxygenated and filtered"}, {"id": "c", "text": "Oxygenated and already filtered"}, {"id": "d", "text": "Deoxygenated and unfiltered"}]'::jsonb, '["a"]', 'The renal artery brings oxygenated, unfiltered blood into the kidney. Filtered blood leaves through the renal vein.'),
  ('anatomy', 47, 'A nurse is reviewing kidney functions with a nursing student. Which function is correctly matched with how the kidney accomplishes it?', '[{"id": "a", "text": "Blood pressure control — secretes calcitriol"}, {"id": "b", "text": "Vitamin D activation — secretes renin"}, {"id": "c", "text": "RBC production — secretes erythropoietin"}, {"id": "d", "text": "Acid-base balance — reabsorbs glucose"}]'::jsonb, '["c"]', 'The kidneys support RBC production by secreting erythropoietin, which stimulates the bone marrow. Blood pressure is controlled by renin, and acid-base balance depends on H+ excretion and HCO3– reabsorption.'),
  ('anatomy', 48, 'A client with kidney disease asks why the provider keeps checking BUN and creatinine levels. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"These wastes build up when the kidneys are injured.\""}, {"id": "b", "text": "\"These levels fall when the kidneys are injured.\""}, {"id": "c", "text": "\"These measure how much renin the kidney secretes.\""}, {"id": "d", "text": "\"These show how much vitamin D has been activated.\""}]'::jsonb, '["a"]', 'Kidney injury causes waste buildup, reflected by rising BUN and creatinine. These values rise, not fall, with injury.'),
  ('anatomy', 49, 'A nursing student is asked which nephron segment regulates K+, Na+, and Ca2+ and responds to aldosterone. Which answer is correct?', '[{"id": "a", "text": "Glomerulus"}, {"id": "b", "text": "Loop of Henle"}, {"id": "c", "text": "Collecting duct"}, {"id": "d", "text": "Distal convoluted tubule"}]'::jsonb, '["d"]', 'The distal convoluted tubule regulates K+, Na+, and Ca2+ and responds to aldosterone. The collecting duct is controlled by ADH for final water reabsorption.'),
  ('anatomy', 50, 'A nurse is describing the internal structures of the kidney to a client. Which statement by the nurse is accurate?', '[{"id": "a", "text": "\"The cortex is the inner region made of renal pyramids.\""}, {"id": "b", "text": "\"The medulla is the outer layer containing glomeruli.\""}, {"id": "c", "text": "\"The cortex is the outer layer containing glomeruli.\""}, {"id": "d", "text": "\"The renal pelvis is a cup-shaped chamber in the cortex.\""}]'::jsonb, '["c"]', 'The cortex is the outer layer and contains the glomeruli; the medulla is the inner region made of renal pyramids. Options A and B reverse the two regions.'),
  ('uti', 1, 'An 82-year-old resident of a long-term care facility has new-onset confusion but no urinary complaints and no fever. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Document the change as expected progression of aging"}, {"id": "b", "text": "Wait to see whether dysuria or frequency develops"}, {"id": "c", "text": "Reassess only if the resident develops flank pain"}, {"id": "d", "text": "Obtain a urinalysis to assess for a urinary tract infection"}]'::jsonb, '["d"]', 'Older adults with a UTI may present with confusion only and no classic urinary symptoms, so a UA should always be checked in a confused elder. Waiting for dysuria or other classic symptoms could miss the infection.'),
  ('uti', 2, 'The nurse is reviewing how urinary tract infections present in older adults. Which finding may be the only sign of a UTI in an 88-year-old client?', '[{"id": "a", "text": "Suprapubic pressure"}, {"id": "b", "text": "Costovertebral angle tenderness"}, {"id": "c", "text": "High fever with chills"}, {"id": "d", "text": "Acute confusion"}]'::jsonb, '["d"]', 'In confused elderly clients, confusion is often the only presenting symptom of a UTI. Suprapubic pressure and CVA tenderness are classic findings that may be absent in older adults.'),
  ('uti', 3, 'The daughter of an older adult says, ''My father can''t have a bladder infection; he never complains of burning.'' Which response by the nurse is best?', '[{"id": "a", "text": "Older adults may show confusion as the only sign of infection."}, {"id": "b", "text": "Without burning on urination, a urine test is not needed."}, {"id": "c", "text": "Burning on urination is present in every urinary infection."}, {"id": "d", "text": "Confusion in older adults is unrelated to urinary infection."}]'::jsonb, '["a"]', 'Elderly clients with a UTI may present with confusion only and no classic symptoms such as burning. Assuming a UTI is ruled out because dysuria is absent is incorrect.'),
  ('uti', 4, 'A client at 20 weeks'' gestation has bacteria on a routine urine culture but no urinary symptoms. She asks why she needs an antibiotic. Which response by the nurse is accurate?', '[{"id": "a", "text": "Untreated bacteriuria can lead to kidney infection and preterm labor."}, {"id": "b", "text": "Treatment is needed only if you develop burning or urgency."}, {"id": "c", "text": "Bacteriuria during pregnancy usually clears without any treatment."}, {"id": "d", "text": "Antibiotics are given only to relieve bladder pressure and pain."}]'::jsonb, '["a"]', 'Pregnant women should always be treated because even asymptomatic bacteriuria can lead to pyelonephritis and preterm labor. Waiting for symptoms is unsafe in pregnancy.'),
  ('uti', 5, 'A pregnant client with asymptomatic bacteriuria is prescribed cephalexin. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''I will drink plenty of fluids while taking this medicine.''"}, {"id": "b", "text": "''Since I feel fine, I can skip the antibiotic this time.''"}, {"id": "c", "text": "''I will take every dose, even after I feel well.''"}, {"id": "d", "text": "''I will return for a urine culture after treatment.''"}]'::jsonb, '["b"]', 'Pregnant clients with bacteriuria are always treated, even without symptoms. Increasing fluids, completing the course, and a follow-up culture to confirm clearance are all correct.'),
  ('uti', 6, 'A client at 30 weeks'' gestation has had an untreated urinary tract infection. The nurse should monitor closely for which complication?', '[{"id": "a", "text": "Struvite stone formation"}, {"id": "b", "text": "Orange-red urine color"}, {"id": "c", "text": "Onset of preterm labor"}, {"id": "d", "text": "Prostate enlargement"}]'::jsonb, '["c"]', 'An untreated UTI in pregnancy can cause preterm labor and low birth weight. Struvite stones are associated with Proteus mirabilis, not specifically with pregnancy.'),
  ('uti', 7, 'A client in the third trimester of pregnancy is diagnosed with a urinary tract infection. Which prescribed treatment should the nurse question?', '[{"id": "a", "text": "Cephalexin"}, {"id": "b", "text": "Nitrofurantoin"}, {"id": "c", "text": "Amoxicillin"}, {"id": "d", "text": "Fluids of 2 to 3 L/day"}]'::jsonb, '["b"]', 'Nitrofurantoin is an option in pregnancy but should be avoided in the third trimester. Cephalexin and amoxicillin are listed antibiotics for pregnant clients, and increased fluids are a nursing priority.'),
  ('uti', 8, 'A pregnant client has completed antibiotic treatment for a urinary tract infection. Which follow-up does the nurse anticipate?', '[{"id": "a", "text": "Lifelong prophylactic antibiotic therapy"}, {"id": "b", "text": "A repeat urine culture to confirm clearance"}, {"id": "c", "text": "No follow-up once symptoms have resolved"}, {"id": "d", "text": "A two-day course of phenazopyridine"}]'::jsonb, '["b"]', 'For pregnant clients, a urine culture is done to confirm clearance after treatment. Ending follow-up because symptoms resolved is incorrect because even asymptomatic bacteriuria must be treated in pregnancy.'),
  ('uti', 9, 'The parent of a 5-year-old girl calls the clinic about changes in the child. Which reported change should make the nurse suspect a urinary tract infection?', '[{"id": "a", "text": "Increased appetite at meals"}, {"id": "b", "text": "Sleeping longer than usual at night"}, {"id": "c", "text": "New bedwetting after being dry at night"}, {"id": "d", "text": "Darker stools than usual"}]'::jsonb, '["c"]', 'Children with a UTI may present with dysuria, bedwetting, and abdominal pain. The other changes are not listed presentations of a UTI in children.'),
  ('uti', 10, 'The nurse is teaching the parents of a 4-year-old girl who was treated for a urinary tract infection. Which instruction is most appropriate?', '[{"id": "a", "text": "Wipe from front to back after toileting"}, {"id": "b", "text": "Wipe from back to front after toileting"}, {"id": "c", "text": "Encourage her to hold urine when possible"}, {"id": "d", "text": "Restrict daily fluids to reduce voiding"}]'::jsonb, '["a"]', 'Proper hygiene should be taught for children with UTIs, including wiping front to back to prevent fecal contamination. Holding urine and restricting fluids contradict the priorities to void frequently and increase fluid intake.'),
  ('uti', 11, 'A 45-year-old man is diagnosed with a urinary tract infection. Which plan of care does the nurse anticipate?', '[{"id": "a", "text": "Discharge without any further evaluation"}, {"id": "b", "text": "Phenazopyridine as the only treatment"}, {"id": "c", "text": "Fluid restriction until symptoms resolve"}, {"id": "d", "text": "Evaluation for a structural cause such as BPH"}]'::jsonb, '["d"]', 'UTIs are uncommon in men, so a structural cause such as BPH or kidney stones should be investigated. Phenazopyridine is a urinary analgesic, not an antibiotic, so it cannot be the only treatment.'),
  ('uti', 12, 'The nurse reviews four clients newly diagnosed with urinary tract infections. Which client''s UTI should prompt the nurse to anticipate an investigation for a structural cause?', '[{"id": "a", "text": "A 60-year-old man"}, {"id": "b", "text": "A 24-year-old sexually active woman"}, {"id": "c", "text": "A 30-year-old pregnant woman"}, {"id": "d", "text": "A 7-year-old girl"}]'::jsonb, '["a"]', 'UTIs are uncommon in men, so a structural cause such as BPH or kidney stones is investigated. UTIs are common in young sexually active women and girls, and pregnant women require treatment rather than a structural workup.'),
  ('uti', 13, 'A client with a first urinary tract infection asks how she developed it. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Bacteria traveled down from the kidneys into the bladder."}, {"id": "b", "text": "Bacteria usually enter the bladder from the bloodstream."}, {"id": "c", "text": "Bacteria from the hands are the most common cause of UTI."}, {"id": "d", "text": "Bowel bacteria such as E. coli moved up the urethra to the bladder."}]'::jsonb, '["d"]', 'E. coli, a gram-negative bacterium from bowel flora, is the most common cause and causes an ascending infection from the urethra to the bladder. Describing bacteria moving down from the kidneys reverses the direction of spread.'),
  ('uti', 14, 'A client with recurrent urinary tract infections has a urine culture that grows Proteus mirabilis. The nurse recognizes this organism is associated with which problem?', '[{"id": "a", "text": "Hospital-acquired catheter infections"}, {"id": "b", "text": "Infection in young sexually active women"}, {"id": "c", "text": "Struvite (urease-producing) stones"}, {"id": "d", "text": "Confusion as the only symptom in elders"}]'::jsonb, '["c"]', 'Proteus mirabilis is associated with struvite/urease-producing stones. Hospital-acquired UTIs are associated with Klebsiella pneumoniae, and infection in young sexually active women with Staphylococcus saprophyticus.'),
  ('uti', 15, 'The nurse is reviewing organisms that cause urinary tract infections. Which pairing of organism and typical association is correct?', '[{"id": "a", "text": "Klebsiella pneumoniae — young sexually active women"}, {"id": "b", "text": "Proteus mirabilis — most hospital-acquired infections"}, {"id": "c", "text": "Staphylococcus saprophyticus — young sexually active women"}, {"id": "d", "text": "E. coli — an uncommon cause of UTIs"}]'::jsonb, '["c"]', 'Staphylococcus saprophyticus is common in young sexually active women. Klebsiella pneumoniae is common in hospital-acquired UTIs, and E. coli is the most common cause overall.'),
  ('uti', 16, 'A client hospitalized for 6 days develops a urinary tract infection, and the urine culture grows Klebsiella pneumoniae. Which statement about this organism is accurate?', '[{"id": "a", "text": "It is linked to struvite stone formation."}, {"id": "b", "text": "It is most common in young women."}, {"id": "c", "text": "It is the most common cause of all UTIs."}, {"id": "d", "text": "It is common in hospital-acquired UTIs."}]'::jsonb, '["d"]', 'Klebsiella pneumoniae is common in hospital-acquired UTIs. Struvite stones are associated with Proteus mirabilis, and E. coli is the most common cause of UTIs.'),
  ('uti', 17, 'A client is being evaluated for a urinary tract infection. Which assessment finding indicates upper urinary tract involvement rather than a lower UTI alone?', '[{"id": "a", "text": "Painful, burning urination"}, {"id": "b", "text": "Urinary urgency and frequency"}, {"id": "c", "text": "Suprapubic pain and pressure"}, {"id": "d", "text": "Costovertebral angle tenderness"}]'::jsonb, '["d"]', 'CVA tenderness is a sign of upper UTI (pyelonephritis). Dysuria, urgency, and suprapubic pressure are lower UTI symptoms and can also be present with an upper UTI, so they do not indicate kidney involvement.'),
  ('uti', 18, 'The nurse assesses a client with a lower urinary tract infection. Which findings does the nurse expect?', '[{"id": "a", "text": "Flank pain with a high fever and chills"}, {"id": "b", "text": "CVA tenderness with nausea and vomiting"}, {"id": "c", "text": "Suprapubic pressure with low-grade or no fever"}, {"id": "d", "text": "Back pain with high fever and shaking"}]'::jsonb, '["c"]', 'Lower UTI (cystitis) causes suprapubic pain or pressure with a low-grade or no fever. Flank pain, high fever with chills, CVA tenderness, and nausea and vomiting indicate upper UTI.'),
  ('uti', 19, 'A client is suspected of having a urinary tract infection. Which urinalysis results does the nurse expect?', '[{"id": "a", "text": "Negative nitrites and no white blood cells"}, {"id": "b", "text": "No bacteria and a normal white cell count"}, {"id": "c", "text": "Positive nitrites and leukocyte esterase"}, {"id": "d", "text": "Negative leukocyte esterase and no bacteria"}]'::jsonb, '["c"]', 'A UA in UTI shows positive nitrites, leukocyte esterase, WBCs, and bacteria, with possible RBCs. Results with no bacteria or WBCs do not fit an infection.'),
  ('uti', 20, 'A client with suspected pyelonephritis is about to start antibiotic therapy. Which diagnostic test is required before the first antibiotic dose?', '[{"id": "a", "text": "Complete blood count only"}, {"id": "b", "text": "Urinalysis dipstick only"}, {"id": "c", "text": "No testing before antibiotics"}, {"id": "d", "text": "Urine culture and sensitivity"}]'::jsonb, '["d"]', 'A urine culture and sensitivity is required for pyelonephritis and must be obtained before antibiotics. A CBC or UA alone does not meet this requirement.'),
  ('uti', 21, 'The nurse reviews the complete blood count of a client with pyelonephritis. Which result does the nurse expect?', '[{"id": "a", "text": "Decreased white blood cell count"}, {"id": "b", "text": "Elevated white blood cell count"}, {"id": "c", "text": "Normal white blood cell count"}, {"id": "d", "text": "Decreased red blood cell count"}]'::jsonb, '["b"]', 'The CBC shows an elevated WBC count with upper UTI/pyelonephritis. A decreased or normal WBC count is not the expected finding.'),
  ('uti', 22, 'The nurse is teaching a female client how to collect a midstream clean-catch urine specimen. Which instruction is correct?', '[{"id": "a", "text": "Clean front to back, begin voiding, then collect midstream urine."}, {"id": "b", "text": "Clean back to front, then collect the first urine voided."}, {"id": "c", "text": "Collect the first portion, then clean the perineum after."}, {"id": "d", "text": "Touch the inside rim of the cup to position it correctly."}]'::jsonb, '["a"]', 'Women clean the perineum front to back, begin urinating to flush contaminants, and then catch the midstream urine without touching the rim. Collecting the first urine voided would include the contaminants that are meant to be flushed away.'),
  ('uti', 23, 'The nurse has taught a client how to collect a clean-catch urine specimen for culture. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''I''ll catch the very first urine that comes out.''"}, {"id": "b", "text": "''I''ll wipe front to back three times first.''"}, {"id": "c", "text": "''I won''t touch the inside rim of the container.''"}, {"id": "d", "text": "''I''ll start urinating before I collect the sample.''"}]'::jsonb, '["a"]', 'The client should begin urinating to flush contaminants and then catch the midstream portion, not the first urine. Wiping front to back three times and not touching the rim are correct.'),
  ('uti', 24, 'The nurse is teaching a male client to collect a midstream clean-catch urine specimen. Which cleansing instruction is correct?', '[{"id": "a", "text": "Cleanse once with a back-and-forth motion."}, {"id": "b", "text": "Cleanse in a circular motion from the meatus."}, {"id": "c", "text": "Skip cleansing because men have fewer UTIs."}, {"id": "d", "text": "Wipe from back to front three separate times."}]'::jsonb, '["b"]', 'Men cleanse in a circular motion starting from the meatus before collecting a clean-catch specimen. Skipping cleansing would contaminate the culture specimen.'),
  ('uti', 25, 'A UAP has collected a clean-catch urine specimen for culture. Which action by the UAP requires correction by the nurse?', '[{"id": "a", "text": "Leaving the specimen on the counter for 3 hours"}, {"id": "b", "text": "Sending the specimen to the lab within 30 minutes"}, {"id": "c", "text": "Refrigerating the specimen until it is transported"}, {"id": "d", "text": "Using a sterile container to collect the specimen"}]'::jsonb, '["a"]', 'A urine culture specimen should be sent to the lab within 30 minutes or refrigerated. Sending it promptly, refrigerating it, and using a sterile container are all correct actions.'),
  ('uti', 26, 'A woman with simple cystitis is prescribed fosfomycin and asks how many days she will take it. Which response by the nurse is accurate?', '[{"id": "a", "text": "It is given as a single dose."}, {"id": "b", "text": "It is taken for 7 to 14 days."}, {"id": "c", "text": "It is taken for 3 to 7 days."}, {"id": "d", "text": "It is taken until urine clears."}]'::jsonb, '["a"]', 'Fosfomycin is a single-dose option for simple cystitis in women. A 3- to 7-day course applies to other simple cystitis regimens, and 7 to 14 days applies to complicated or male UTIs.'),
  ('uti', 27, 'A male client with a urinary tract infection is prescribed ciprofloxacin. Which course length does the nurse anticipate?', '[{"id": "a", "text": "A single dose"}, {"id": "b", "text": "7 to 14 days"}, {"id": "c", "text": "No more than 2 days"}, {"id": "d", "text": "3 days only"}]'::jsonb, '["b"]', 'Complicated and male UTIs are treated with ciprofloxacin or cephalosporins for a 7- to 14-day course. A single dose applies to fosfomycin for simple cystitis.'),
  ('uti', 28, 'The nurse is teaching a client who is prescribed phenazopyridine for urinary burning. Which information should the nurse include?', '[{"id": "a", "text": "The medication cures the infection without antibiotics."}, {"id": "b", "text": "The medication may turn the urine orange or red."}, {"id": "c", "text": "The medication should be taken for at least two weeks."}, {"id": "d", "text": "The medication may turn the urine dark green or blue."}]'::jsonb, '["b"]', 'Phenazopyridine causes orange/red urine, and clients should be warned. It is not an antibiotic and should not be used for more than 2 days.'),
  ('uti', 29, 'A client with a urinary tract infection is prescribed an antibiotic and phenazopyridine. Which statement by the client indicates understanding of phenazopyridine?', '[{"id": "a", "text": "''I can stop my antibiotic since this pill treats the infection.''"}, {"id": "b", "text": "''This pill is a stronger antibiotic that works faster.''"}, {"id": "c", "text": "''If my urine turns orange, I should go to the emergency room.''"}, {"id": "d", "text": "''This pill eases the burning but does not treat the infection.''"}]'::jsonb, '["d"]', 'Phenazopyridine is a urinary analgesic that relieves burning and urgency; it is not an antibiotic. Orange urine is an expected effect that clients should be warned about, not an emergency.'),
  ('uti', 30, 'A client says, ''I''ll take the phenazopyridine for the full 10 days along with my antibiotic.'' Which response by the nurse is best?', '[{"id": "a", "text": "This medication should not be used for more than 2 days."}, {"id": "b", "text": "That is correct; take both medicines for the full 10 days."}, {"id": "c", "text": "Stop the antibiotic once your urine turns orange."}, {"id": "d", "text": "Take this medicine only if you develop a fever."}]'::jsonb, '["a"]', 'Phenazopyridine should not be used for more than 2 days. Orange urine is an expected effect and is not a reason to stop the antibiotic.'),
  ('uti', 31, 'The nurse is teaching a client with a urinary tract infection about fluid intake. Which instruction is appropriate?', '[{"id": "a", "text": "Drink 2 to 3 liters of fluid each day."}, {"id": "b", "text": "Limit fluids to 1 liter each day."}, {"id": "c", "text": "Drink fluids only when you feel thirsty."}, {"id": "d", "text": "Restrict fluids until antibiotics end."}]'::jsonb, '["a"]', 'Increasing fluid intake to 2 to 3 L/day helps flush bacteria. Limiting or restricting fluids works against this goal.'),
  ('uti', 32, 'A teacher with recurrent urinary tract infections says she rarely has time to use the restroom during the school day. Which teaching is most appropriate?', '[{"id": "a", "text": "Limit fluids during the school day."}, {"id": "b", "text": "Wait to void until after school ends."}, {"id": "c", "text": "Void only before and after lunch."}, {"id": "d", "text": "Void frequently rather than holding urine."}]'::jsonb, '["d"]', 'Clients should void frequently and not hold urine to help prevent UTIs. Limiting fluids conflicts with the priority to increase fluid intake to flush bacteria.'),
  ('uti', 33, 'A sexually active woman with recurrent urinary tract infections asks how to lower her risk related to intercourse. Which instruction should the nurse give?', '[{"id": "a", "text": "Avoid voiding for an hour after intercourse."}, {"id": "b", "text": "Void before and after intercourse."}, {"id": "c", "text": "Void only before intercourse."}, {"id": "d", "text": "Limit fluid intake before intercourse."}]'::jsonb, '["b"]', 'Voiding before and after intercourse is a nursing priority for UTI prevention. Voiding only before intercourse omits the post-intercourse void.'),
  ('uti', 34, 'The nurse is evaluating a client''s understanding of antibiotic therapy for a urinary tract infection. Which statement indicates understanding?', '[{"id": "a", "text": "''I''ll take every dose even after I feel better.''"}, {"id": "b", "text": "''I''ll stop the antibiotic when the burning goes away.''"}, {"id": "c", "text": "''I''ll save leftover pills for my next infection.''"}, {"id": "d", "text": "''I''ll take the antibiotic only when I have pain.''"}]'::jsonb, '["a"]', 'Clients should complete the full course of antibiotics. Stopping when symptoms improve or saving pills does not complete the course.'),
  ('uti', 35, 'A client being treated for a urinary tract infection discusses beverage choices. Which statement indicates the client understands the teaching?', '[{"id": "a", "text": "''I''ll have a beer instead of my usual coffee.''"}, {"id": "b", "text": "''An extra cup of coffee will help flush my bladder.''"}, {"id": "c", "text": "''I''ll drink water instead of my usual coffee.''"}, {"id": "d", "text": "''A glass of wine each evening will be fine.''"}]'::jsonb, '["c"]', 'Caffeine and alcohol should be avoided during UTI treatment, while fluid intake should increase. Choosing beer, wine, or extra coffee adds alcohol or caffeine.'),
  ('uti', 36, 'A client being treated for a urinary tract infection selects lunch items. Which choice indicates a need for further teaching?', '[{"id": "a", "text": "Grilled chicken with rice"}, {"id": "b", "text": "Spicy chili with hot peppers"}, {"id": "c", "text": "Baked fish with vegetables"}, {"id": "d", "text": "Turkey sandwich with fruit"}]'::jsonb, '["b"]', 'Spicy foods should be avoided during UTI treatment, along with caffeine and alcohol. The other meals do not contain the listed foods to avoid.'),
  ('uti', 37, 'The nurse is caring for a client with an indwelling urinary catheter. Which intervention is the top priority for preventing a catheter-associated UTI?', '[{"id": "a", "text": "Irrigate the catheter every shift"}, {"id": "b", "text": "Open the system to check urine flow"}, {"id": "c", "text": "Rest the drainage bag on the abdomen"}, {"id": "d", "text": "Remove the catheter as soon as possible"}]'::jsonb, '["d"]', 'The number one priority in CAUTI prevention is removing indwelling catheters as soon as possible. Irrigating without an order and opening the closed system are incorrect.'),
  ('uti', 38, 'A UAP is caring for a client with an indwelling urinary catheter. Which action by the UAP requires correction?', '[{"id": "a", "text": "Keeping the drainage bag below the level of the bladder"}, {"id": "b", "text": "Recording the urine output at the end of the shift"}, {"id": "c", "text": "Placing the drainage bag on the client''s lap for transport"}, {"id": "d", "text": "Keeping the catheter drainage system closed"}]'::jsonb, '["c"]', 'The drainage bag must be kept below bladder level at all times, so resting it on the lap requires correction. Keeping the system closed and documenting output every shift are correct.'),
  ('uti', 39, 'The nurse observes a UAP caring for a client with an indwelling urinary catheter. Which action requires correction?', '[{"id": "a", "text": "Documenting the urine output at the end of every shift"}, {"id": "b", "text": "Disconnecting the catheter from the tubing to empty urine"}, {"id": "c", "text": "Leaving the drainage system closed during care"}, {"id": "d", "text": "Keeping the drainage bag lower than the bladder"}]'::jsonb, '["b"]', 'A closed drainage system must be maintained and not opened, so disconnecting the catheter from the tubing is incorrect. Documenting output each shift and keeping the bag below the bladder are correct.'),
  ('uti', 40, 'The nurse is observing a newly hired nurse who is caring for a client with an indwelling urinary catheter. Which action requires correction?', '[{"id": "a", "text": "Documenting the urine output at the end of each shift"}, {"id": "b", "text": "Irrigating the catheter each shift without an order"}, {"id": "c", "text": "Keeping the urinary drainage system closed"}, {"id": "d", "text": "Asking the provider about catheter removal"}]'::jsonb, '["b"]', 'The catheter should not be irrigated unless ordered. Documenting output every shift, keeping the system closed, and pursuing early removal are correct CAUTI prevention measures.'),
  ('uti', 41, 'Which nursing action is appropriate when caring for a client with an indwelling urinary catheter?', '[{"id": "a", "text": "Open the system to obtain samples."}, {"id": "b", "text": "Irrigate routinely to prevent blockage."}, {"id": "c", "text": "Hang the bag above bladder level."}, {"id": "d", "text": "Document urine output every shift."}]'::jsonb, '["d"]', 'Urine output should be documented every shift. The system must stay closed, the catheter should not be irrigated unless ordered, and the bag must stay below bladder level.'),
  ('uti', 42, 'A client being treated for a urinary tract infection develops signs of septic shock. The nurse recognizes which complication?', '[{"id": "a", "text": "Asymptomatic bacteriuria"}, {"id": "b", "text": "Urosepsis"}, {"id": "c", "text": "Simple cystitis"}, {"id": "d", "text": "Struvite stones"}]'::jsonb, '["b"]', 'Urosepsis is a life-threatening systemic infection from a UTI that can lead to septic shock. Simple cystitis and asymptomatic bacteriuria do not cause septic shock.'),
  ('uti', 43, 'A client being treated for cystitis now reports flank pain and fever, and the nurse finds CVA tenderness. Which complication does the nurse suspect?', '[{"id": "a", "text": "Recurrence of simple lower cystitis"}, {"id": "b", "text": "Urinary retention from holding urine"}, {"id": "c", "text": "Pyelonephritis from an ascending infection"}, {"id": "d", "text": "An expected effect of phenazopyridine"}]'::jsonb, '["c"]', 'Pyelonephritis is an ascending infection marked by flank pain, fever, and CVA tenderness. Simple cystitis causes low-grade or no fever and does not cause CVA tenderness.'),
  ('uti', 44, 'A client has recurrent urinary tract infections related to a structural anomaly of the urinary tract. Which treatment does the nurse anticipate may be needed?', '[{"id": "a", "text": "Long-term phenazopyridine"}, {"id": "b", "text": "Daily catheter irrigation"}, {"id": "c", "text": "Ongoing fluid restriction"}, {"id": "d", "text": "Prophylactic antibiotics"}]'::jsonb, '["d"]', 'Chronic or recurrent UTIs related to structural anomalies may require prophylactic antibiotics. Phenazopyridine is not an antibiotic and should not be used for more than 2 days.'),
  ('uti', 45, 'A client hospitalized with pyelonephritis has been receiving IV ceftriaxone. Which next step in antibiotic therapy does the nurse anticipate?', '[{"id": "a", "text": "Transition to an oral antibiotic"}, {"id": "b", "text": "Switch to phenazopyridine alone"}, {"id": "c", "text": "Change to single-dose fosfomycin"}, {"id": "d", "text": "Stop all antibiotics at discharge"}]'::jsonb, '["a"]', 'Inpatient pyelonephritis is treated with IV ceftriaxone and then transitioned to oral therapy. Phenazopyridine is not an antibiotic, and fosfomycin is the single-dose option for simple cystitis.'),
  ('uti', 46, 'The nurse is teaching a woman about preventing urinary tract infections. Which statement by the client indicates understanding?', '[{"id": "a", "text": "''I wipe from back to front after a bowel movement.''"}, {"id": "b", "text": "''The direction I wipe does not affect my risk.''"}, {"id": "c", "text": "''I wipe from front to back to keep stool bacteria away.''"}, {"id": "d", "text": "''I wipe front to back only during my period.''"}]'::jsonb, '["c"]', 'Women should wipe front to back to prevent fecal contamination. Wiping back to front moves bowel flora such as E. coli toward the urethra.'),
  ('uti', 47, 'The nurse receives report on four clients with urinary tract infections. Which client should the nurse see first?', '[{"id": "a", "text": "The client reporting dysuria and urgency"}, {"id": "b", "text": "The client with signs of septic shock"}, {"id": "c", "text": "The client with orange urine on phenazopyridine"}, {"id": "d", "text": "The client with cloudy, foul-smelling urine"}]'::jsonb, '["b"]', 'Urosepsis is a life-threatening systemic infection that can progress to septic shock, so this client is the priority. Dysuria, urgency, and cloudy urine are expected lower UTI findings, and orange urine is an expected phenazopyridine effect.'),
  ('uti', 48, 'The parent of 6-year-old boy-girl twins asks which child is more likely to develop a urinary tract infection. Which response by the nurse is accurate?', '[{"id": "a", "text": "The boy, because UTIs are more common in boys"}, {"id": "b", "text": "Both children are equally likely at this age"}, {"id": "c", "text": "The girl, because UTIs are more common in girls"}, {"id": "d", "text": "Neither child, because UTIs do not affect children"}]'::jsonb, '["c"]', 'In children, UTIs are more common in girls. Children can develop UTIs and may present with dysuria, bedwetting, or abdominal pain.'),
  ('uti', 49, 'A woman with simple cystitis is prescribed TMP-SMX. Which course length does the nurse anticipate?', '[{"id": "a", "text": "3 to 7 days"}, {"id": "b", "text": "7 to 14 days"}, {"id": "c", "text": "A single dose"}, {"id": "d", "text": "No more than 2 days"}]'::jsonb, '["a"]', 'Simple cystitis in women is treated with nitrofurantoin, TMP-SMX, or fosfomycin for a 3- to 7-day course. A 7- to 14-day course is for complicated or male UTIs, and the single dose applies to fosfomycin.'),
  ('uti', 50, 'A client with a lower urinary tract infection reports pink-tinged urine. How should the nurse interpret this finding?', '[{"id": "a", "text": "Pink urine confirms a kidney infection."}, {"id": "b", "text": "Pink urine means the antibiotic failed."}, {"id": "c", "text": "Hematuria can occur with a lower UTI."}, {"id": "d", "text": "Pink urine is expected from fosfomycin."}]'::jsonb, '["c"]', 'Hematuria (pink/red urine) is a lower UTI symptom. Signs of kidney involvement are flank pain, high fever with chills, CVA tenderness, and nausea and vomiting, not hematuria alone.'),
  ('cystitis', 1, 'A client reports burning with urination, voiding small amounts every hour, and a sudden urge to void that is hard to control. The nurse recognizes this cluster as which?', '[{"id": "a", "text": "The classic triad of cystitis"}, {"id": "b", "text": "The classic signs of kidney spread"}, {"id": "c", "text": "Early signs of urosepsis"}, {"id": "d", "text": "Expected effects of phenazopyridine"}]'::jsonb, '["a"]', 'Dysuria, frequency, and urgency are the classic triad of cystitis. Spread to the kidney is signaled by fever, chills, flank pain, and nausea and vomiting instead.'),
  ('cystitis', 2, 'A client with cystitis reports pain. Where does the nurse expect the client to localize the pain?', '[{"id": "a", "text": "Above the pubic bone"}, {"id": "b", "text": "At the costovertebral angle"}, {"id": "c", "text": "In one flank"}, {"id": "d", "text": "Across the lower back"}]'::jsonb, '["a"]', 'Cystitis causes suprapubic pain, a pressure above the pubic bone. Flank or back pain at the costovertebral angle signals infection spread to the kidney.'),
  ('cystitis', 3, 'The nurse assesses a client with uncomplicated cystitis. Which finding does the nurse expect?', '[{"id": "a", "text": "Suprapubic pressure without fever"}, {"id": "b", "text": "Temperature elevation with chills"}, {"id": "c", "text": "Flank pain with CVA tenderness"}, {"id": "d", "text": "Nausea, vomiting, and ill appearance"}]'::jsonb, '["a"]', 'Uncomplicated cystitis causes no fever. Fever with chills, flank pain, and nausea and vomiting are signs that infection has spread to the kidney.'),
  ('cystitis', 4, 'A client being treated for cystitis develops a fever with chills. Which interpretation by the nurse is most accurate?', '[{"id": "a", "text": "This is expected with uncomplicated cystitis."}, {"id": "b", "text": "The infection may have spread to the kidneys."}, {"id": "c", "text": "This is a side effect of phenazopyridine."}, {"id": "d", "text": "This indicates noninfectious interstitial cystitis."}]'::jsonb, '["b"]', 'Fever with uncomplicated cystitis is not expected; fever means the infection has spread to the kidneys, and treatment should be escalated immediately. Interstitial cystitis has no bacterial cause.'),
  ('cystitis', 5, 'The nurse is caring for a client with cystitis. Which new finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Burning and pain with each urination"}, {"id": "b", "text": "Frequent, urgent voiding of small amounts"}, {"id": "c", "text": "Flank pain with costovertebral angle tenderness"}, {"id": "d", "text": "Orange urine after taking phenazopyridine"}]'::jsonb, '["c"]', 'Flank or back pain with costovertebral angle tenderness signals that the infection is spreading to the kidney. Burning, frequency, and urgency are classic bladder symptoms, and orange urine is an expected phenazopyridine effect.'),
  ('cystitis', 6, 'Which assessment in a client with cystitis most strongly suggests that the infection has spread to the kidney?', '[{"id": "a", "text": "The client appears ill and is vomiting."}, {"id": "b", "text": "The client reports cloudy urine."}, {"id": "c", "text": "The client is voiding very often."}, {"id": "d", "text": "The client reports suprapubic pressure."}]'::jsonb, '["a"]', 'Nausea and vomiting and a client who looks sick, not just uncomfortable, are signs the infection has spread to the kidney. Cloudy urine, frequency, and suprapubic pressure are classic bladder symptoms.'),
  ('cystitis', 7, 'A client with a urinary infection becomes confused and is found to be hypotensive and tachycardic. Which complication does the nurse suspect?', '[{"id": "a", "text": "Interstitial cystitis"}, {"id": "b", "text": "Radiation cystitis"}, {"id": "c", "text": "Uncomplicated cystitis"}, {"id": "d", "text": "Urosepsis"}]'::jsonb, '["d"]', 'Hypotension, tachycardia, and confusion are signs of urosepsis, a systemic infection from an untreated or spreading UTI. Uncomplicated cystitis does not cause these systemic signs.'),
  ('cystitis', 8, 'A client is diagnosed with urosepsis. Which interventions does the nurse anticipate?', '[{"id": "a", "text": "Oral fosfomycin and discharge home"}, {"id": "b", "text": "Phenazopyridine and fluid restriction"}, {"id": "c", "text": "Cranberry products and oral fluids"}, {"id": "d", "text": "IV antibiotics and fluid resuscitation"}]'::jsonb, '["d"]', 'Urosepsis is a medical emergency treated with IV antibiotics and fluid resuscitation. Single-dose fosfomycin is for uncomplicated cystitis, and phenazopyridine is not an antibiotic.'),
  ('cystitis', 9, 'A client''s urinalysis shows positive nitrites. The nurse interprets this finding as suggesting which?', '[{"id": "a", "text": "Interstitial cystitis with no bacteria"}, {"id": "b", "text": "Radiation injury to the bladder wall"}, {"id": "c", "text": "Gram-negative bacteria such as E. coli"}, {"id": "d", "text": "Normal urine without infection"}]'::jsonb, '["c"]', 'Positive nitrites on UA point to gram-negative bacteria such as E. coli. Interstitial cystitis has no bacterial cause.'),
  ('cystitis', 10, 'A client''s urinalysis shows positive leukocyte esterase and pyuria. How should the nurse interpret these results?', '[{"id": "a", "text": "Irritation from caffeine only"}, {"id": "b", "text": "A normal finding after fluids"}, {"id": "c", "text": "Evidence of an active infection"}, {"id": "d", "text": "An effect of phenazopyridine"}]'::jsonb, '["c"]', 'Leukocyte esterase plus pyuria indicates an active infection. Caffeine is a bladder irritant, but these UA findings point to infection.'),
  ('cystitis', 11, 'Which urinalysis result does the nurse expect in a client with cystitis?', '[{"id": "a", "text": "Increased WBCs and positive nitrites"}, {"id": "b", "text": "Decreased WBCs and negative nitrites"}, {"id": "c", "text": "Normal WBCs and negative esterase"}, {"id": "d", "text": "No WBCs and no nitrites present"}]'::jsonb, '["a"]', 'The UA in cystitis shows increased WBCs (pyuria), positive nitrites, and positive leukocyte esterase. Negative nitrites with low or normal WBCs do not fit cystitis.'),
  ('cystitis', 12, 'A client with suspected cystitis has new prescriptions for TMP-SMX and a urine culture and sensitivity. Which action should the nurse take first?', '[{"id": "a", "text": "Administer the first TMP-SMX dose"}, {"id": "b", "text": "Teach about bladder irritants"}, {"id": "c", "text": "Teach front-to-back wiping"}, {"id": "d", "text": "Collect the urine culture specimen"}]'::jsonb, '["d"]', 'A urine culture should always be obtained before starting antibiotics. Teaching can follow, but giving TMP-SMX before the culture is collected is incorrect.'),
  ('cystitis', 13, 'A client asks why a urine culture and sensitivity is needed for cystitis. Which response by the nurse is accurate?', '[{"id": "a", "text": "It shows how inflamed the bladder wall looks."}, {"id": "b", "text": "It identifies the organism and guides antibiotic choice."}, {"id": "c", "text": "It measures how well the kidneys filter blood."}, {"id": "d", "text": "It confirms that phenazopyridine is working."}]'::jsonb, '["b"]', 'A urine culture and sensitivity identifies the organism and guides antibiotic choice. Visualizing the bladder wall is the purpose of cystoscopy.'),
  ('cystitis', 14, 'A client with recurrent cystitis is scheduled for a cystoscopy and asks about its purpose. Which response by the nurse is accurate?', '[{"id": "a", "text": "It identifies bacteria and antibiotic sensitivity."}, {"id": "b", "text": "It allows the bladder wall to be visualized."}, {"id": "c", "text": "It flushes bacteria out of the bladder."}, {"id": "d", "text": "It removes irritants from the bladder."}]'::jsonb, '["b"]', 'Cystoscopy is used for chronic or recurrent cystitis to visualize the bladder wall. Identifying the organism and its antibiotic sensitivity is the role of the urine culture.'),
  ('cystitis', 15, 'A client has chronic bladder symptoms, and repeated urine cultures show no bacterial growth. The nurse recognizes this presentation is consistent with which condition?', '[{"id": "a", "text": "E. coli cystitis"}, {"id": "b", "text": "Catheter-associated UTI"}, {"id": "c", "text": "Staphylococcal cystitis"}, {"id": "d", "text": "Interstitial cystitis"}]'::jsonb, '["d"]', 'Interstitial cystitis is chronic and has no bacterial cause. E. coli, catheter-associated, and staphylococcal cystitis are bacterial infections.'),
  ('cystitis', 16, 'A client with recurrent bladder irritation reports taking bubble baths daily and douching weekly. Which teaching is most appropriate?', '[{"id": "a", "text": "Use bubble baths more often."}, {"id": "b", "text": "Douche after intercourse."}, {"id": "c", "text": "Keep using them with extra fluids."}, {"id": "d", "text": "Avoid bubble baths and douches."}]'::jsonb, '["d"]', 'Chemical exposure from bubble baths and douches is a cause of cystitis, so these products should be avoided. Increasing fluids does not remove the chemical irritant.'),
  ('cystitis', 17, 'A client who recently completed radiation therapy to the pelvis develops bladder inflammation. The nurse recognizes this as which cause of cystitis?', '[{"id": "a", "text": "Interstitial cystitis"}, {"id": "b", "text": "Catheter-associated UTI"}, {"id": "c", "text": "Chemical exposure"}, {"id": "d", "text": "Radiation cystitis"}]'::jsonb, '["d"]', 'Radiation cystitis is listed among the other causes of cystitis, separate from bacterial infection. Chemical exposure refers to products such as bubble baths and douches.'),
  ('cystitis', 18, 'A client with cystitis asks which beverage to avoid during treatment. Which beverage should the nurse identify?', '[{"id": "a", "text": "Coffee"}, {"id": "b", "text": "Water"}, {"id": "c", "text": "Cranberry juice"}, {"id": "d", "text": "Milk"}]'::jsonb, '["a"]', 'Caffeine is a bladder irritant that should be avoided. Fluids such as water are encouraged at 2 to 3 L/day, and cranberry products may reduce bacterial adherence.'),
  ('cystitis', 19, 'The nurse has taught a client with cystitis about self-care. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''A glass of wine each night will soothe my bladder.''"}, {"id": "b", "text": "''I will drink 2 to 3 liters of fluid every day.''"}, {"id": "c", "text": "''I will wipe from front to back after toileting.''"}, {"id": "d", "text": "''I will urinate after sexual intercourse.''"}]'::jsonb, '["a"]', 'Alcohol is a bladder irritant to avoid with cystitis. Fluids of 2 to 3 L/day, front-to-back wiping, and voiding after intercourse are correct.'),
  ('cystitis', 20, 'A client with uncomplicated cystitis and no antibiotic resistance is seen in the clinic. Which medication does the nurse anticipate as first-line treatment?', '[{"id": "a", "text": "Ciprofloxacin (Cipro)"}, {"id": "b", "text": "TMP-SMX (Bactrim)"}, {"id": "c", "text": "Phenazopyridine (AZO)"}, {"id": "d", "text": "Cranberry tablets"}]'::jsonb, '["b"]', 'TMP-SMX is first-line for uncomplicated UTI. Ciprofloxacin is used for complicated UTIs or resistance, and phenazopyridine is a urinary analgesic, not an antibiotic.'),
  ('cystitis', 21, 'A client with cystitis who has kidney impairment receives a new prescription for nitrofurantoin. Which action should the nurse take?', '[{"id": "a", "text": "Question the prescription with the provider"}, {"id": "b", "text": "Administer the medication as prescribed"}, {"id": "c", "text": "Give it with phenazopyridine for effect"}, {"id": "d", "text": "Restrict fluids while giving the drug"}]'::jsonb, '["a"]', 'Nitrofurantoin should not be used with kidney impairment, so the nurse should question the prescription. Fluids should be increased, not restricted, with cystitis.'),
  ('cystitis', 22, 'A client asks why nitrofurantoin works well for bladder infections. Which response by the nurse is accurate?', '[{"id": "a", "text": "It relieves burning as an analgesic."}, {"id": "b", "text": "It becomes concentrated in the urine."}, {"id": "c", "text": "It is a single-dose antibiotic."}, {"id": "d", "text": "It is reserved for resistant infections."}]'::jsonb, '["b"]', 'Nitrofurantoin is a first-line drug that is concentrated in the urine. Fosfomycin is the single-dose option, and ciprofloxacin is used for resistance.'),
  ('cystitis', 23, 'A client has a complicated UTI and a history of antibiotic resistance. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Fosfomycin"}, {"id": "b", "text": "Ciprofloxacin"}, {"id": "c", "text": "Phenazopyridine"}, {"id": "d", "text": "Cranberry tablets"}]'::jsonb, '["b"]', 'Ciprofloxacin, a fluoroquinolone, is used for complicated UTIs or antibiotic resistance. Fosfomycin is a single-dose option for uncomplicated cystitis.'),
  ('cystitis', 24, 'A client with uncomplicated cystitis worries about remembering a multiday medication schedule. Which antibiotic is the nurse likely to discuss?', '[{"id": "a", "text": "Ciprofloxacin"}, {"id": "b", "text": "Fosfomycin"}, {"id": "c", "text": "Phenazopyridine"}, {"id": "d", "text": "Cranberry tablets"}]'::jsonb, '["b"]', 'Fosfomycin is a single-dose option that is good for uncomplicated cystitis. Ciprofloxacin is for complicated UTIs or resistance, and phenazopyridine is not an antibiotic.'),
  ('cystitis', 25, 'A client taking phenazopyridine calls the clinic, alarmed that the urine is bright orange. Which response by the nurse is best?', '[{"id": "a", "text": "Stop the drug and go to the emergency room."}, {"id": "b", "text": "This color change is an expected drug effect."}, {"id": "c", "text": "This means the infection reached your kidneys."}, {"id": "d", "text": "This shows heavy bleeding from the bladder."}]'::jsonb, '["b"]', 'Phenazopyridine turns urine orange or red, and clients should be warned about this effect. Kidney spread is signaled by fever, flank pain, and nausea and vomiting, not urine color.'),
  ('cystitis', 26, 'A client with cystitis asks to take only over-the-counter phenazopyridine instead of the prescribed TMP-SMX. Which response by the nurse is accurate?', '[{"id": "a", "text": "It will cure the infection faster than TMP-SMX."}, {"id": "b", "text": "It relieves pain but does not treat the infection."}, {"id": "c", "text": "It can replace the antibiotic after one day."}, {"id": "d", "text": "It works best when taken for several weeks."}]'::jsonb, '["b"]', 'Phenazopyridine is for pain relief only and is not an antibiotic, so it cannot replace TMP-SMX. It is used only 1 to 2 days.'),
  ('cystitis', 27, 'The nurse reviews the plan of care for a client with cystitis. Which part of the plan should the nurse question?', '[{"id": "a", "text": "Phenazopyridine for 14 days"}, {"id": "b", "text": "TMP-SMX for the infection"}, {"id": "c", "text": "Fluids of 2 to 3 L/day"}, {"id": "d", "text": "Avoiding caffeine and spicy food"}]'::jsonb, '["a"]', 'Phenazopyridine is used only 1 to 2 days. TMP-SMX, increased fluids, and avoiding bladder irritants are appropriate.'),
  ('cystitis', 28, 'The nurse is teaching a client with cystitis about fluid intake. Which goal should the nurse include?', '[{"id": "a", "text": "1 L/day to rest the bladder"}, {"id": "b", "text": "500 mL/day to reduce urgency"}, {"id": "c", "text": "2 to 3 L/day to flush bacteria"}, {"id": "d", "text": "Fluids only with meals"}]'::jsonb, '["c"]', 'Increased fluid intake of 2 to 3 L/day flushes bacteria. Limiting fluids works against this goal.'),
  ('cystitis', 29, 'The nurse is teaching a client recovering from cystitis about prevention. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''I''ll wait several hours before urinating after sex.''"}, {"id": "b", "text": "''I''ll wipe from front to back after toileting.''"}, {"id": "c", "text": "''I''ll drink an adequate amount of fluid daily.''"}, {"id": "d", "text": "''I may try using cranberry products.''"}]'::jsonb, '["a"]', 'Voiding after sexual intercourse is a prevention measure, so delaying urination after sex is incorrect. Front-to-back wiping, adequate fluids, and cranberry products are listed prevention measures.'),
  ('cystitis', 30, 'The nurse teaches a female client how to prevent cystitis. Which toileting instruction is correct?', '[{"id": "a", "text": "Wipe from back to front."}, {"id": "b", "text": "Wipe in any direction."}, {"id": "c", "text": "Wipe from front to back."}, {"id": "d", "text": "Douche after toileting."}]'::jsonb, '["c"]', 'Wiping front to back after toileting is a prevention measure. Douches are a chemical exposure that can cause cystitis.'),
  ('cystitis', 31, 'A client asks whether cranberry products help prevent bladder infections. Which response by the nurse is accurate?', '[{"id": "a", "text": "They cure an active infection."}, {"id": "b", "text": "They replace the need for fluids."}, {"id": "c", "text": "They irritate the bladder lining."}, {"id": "d", "text": "They may reduce bacterial adherence."}]'::jsonb, '["d"]', 'Cranberry products may reduce adherence of bacteria and are listed as a prevention measure. Adequate daily fluid intake is still needed, and an active infection is treated with antibiotics.'),
  ('cystitis', 32, 'A postoperative client is now ambulating and no longer needs the indwelling urinary catheter. Which nursing action best prevents catheter-associated cystitis?', '[{"id": "a", "text": "Keep the catheter for convenience"}, {"id": "b", "text": "Leave the catheter until discharge"}, {"id": "c", "text": "Advocate for prompt catheter removal"}, {"id": "d", "text": "Replace it with a new catheter"}]'::jsonb, '["c"]', 'Removing the catheter as soon as possible is the number one way to prevent CAUTI. Prolonged catheter use should be avoided.'),
  ('cystitis', 33, 'The nurse observes a colleague inserting an indwelling urinary catheter. Which action requires correction?', '[{"id": "a", "text": "Securing the catheter after insertion"}, {"id": "b", "text": "Hanging the bag below bladder level"}, {"id": "c", "text": "Using clean technique during insertion"}, {"id": "d", "text": "Keeping the bag off the floor"}]'::jsonb, '["c"]', 'Sterile technique must be maintained during catheter insertion. Securing the catheter, keeping the bag below the bladder, and keeping the bag off the floor are correct.'),
  ('cystitis', 34, 'A UAP asks why a catheter drainage bag must stay below the level of the bladder. Which response by the nurse is accurate?', '[{"id": "a", "text": "It keeps the catheter from moving."}, {"id": "b", "text": "It prevents urine from flowing back."}, {"id": "c", "text": "It lets the urine color be seen."}, {"id": "d", "text": "It keeps the bag clean and dry."}]'::jsonb, '["b"]', 'Keeping the drainage bag below bladder level at all times prevents reflux. Securing the catheter is what prevents trauma from movement.'),
  ('cystitis', 35, 'Which action by a UAP caring for a client with an indwelling urinary catheter requires correction?', '[{"id": "a", "text": "Keeping the bag below bladder level"}, {"id": "b", "text": "Keeping the catheter secured"}, {"id": "c", "text": "Reporting cloudy urine to the nurse"}, {"id": "d", "text": "Letting the drainage bag rest on the floor"}]'::jsonb, '["d"]', 'The drainage bag must not be allowed to touch the floor. Keeping the bag below the bladder and keeping the catheter secured are correct.'),
  ('cystitis', 36, 'The nurse secures an indwelling urinary catheter to a client''s leg. What is the purpose of this action?', '[{"id": "a", "text": "To allow urine to flow back to the bladder"}, {"id": "b", "text": "To prevent trauma from catheter movement"}, {"id": "c", "text": "To keep the drainage bag off the floor"}, {"id": "d", "text": "To make catheter removal unnecessary"}]'::jsonb, '["b"]', 'The catheter is kept secured to prevent trauma and movement. Urine flowing back into the bladder is reflux, which is what keeping the bag below the bladder prevents.'),
  ('cystitis', 37, 'Which assessment should the nurse complete each shift for a client with an indwelling urinary catheter?', '[{"id": "a", "text": "Cystoscopy of the bladder wall"}, {"id": "b", "text": "Replacement of the catheter"}, {"id": "c", "text": "Urine color, clarity, and odor"}, {"id": "d", "text": "Placement of the bag on the floor"}]'::jsonb, '["c"]', 'Urine color, clarity, and odor should be assessed each shift. Cystoscopy is for chronic, recurrent, or interstitial cystitis, and the bag must not touch the floor.'),
  ('cystitis', 38, 'A client''s cystitis has progressed to severe pyelonephritis. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "IV antibiotics"}, {"id": "b", "text": "Phenazopyridine alone"}, {"id": "c", "text": "Single-dose fosfomycin"}, {"id": "d", "text": "Cranberry products only"}]'::jsonb, '["a"]', 'Pyelonephritis requires IV antibiotics if severe. Fosfomycin is a single-dose option for uncomplicated cystitis, and phenazopyridine is not an antibiotic.'),
  ('cystitis', 39, 'The nurse is teaching a client newly diagnosed with cystitis. Which statement best describes the condition?', '[{"id": "a", "text": "Infection of the kidneys from ascending bacteria"}, {"id": "b", "text": "Blood infection that began in the urinary tract"}, {"id": "c", "text": "Bladder pain that is never caused by bacteria"}, {"id": "d", "text": "Inflammation of the bladder, most often from E. coli"}]'::jsonb, '["d"]', 'Cystitis is inflammation of the bladder, most commonly caused by E. coli. Infection that ascends to the kidneys is pyelonephritis, and a systemic infection from a UTI is urosepsis.'),
  ('cystitis', 40, 'The nurse is reviewing causes of cystitis. Which statement is accurate?', '[{"id": "a", "text": "E. coli is an uncommon cause of cystitis."}, {"id": "b", "text": "Interstitial cystitis is caused by E. coli."}, {"id": "c", "text": "Staphylococcus saprophyticus is common in young women."}, {"id": "d", "text": "Radiation cystitis is caused by bacteria."}]'::jsonb, '["c"]', 'Staphylococcus saprophyticus is a common bacterial cause in young women, while E. coli is the number one cause overall. Interstitial cystitis has no bacterial cause, and radiation cystitis is listed among the other causes, separate from bacterial infection.'),
  ('cystitis', 41, 'A client with cystitis reports seeing blood in the urine and is frightened. Which response by the nurse is accurate?', '[{"id": "a", "text": "Blood in the urine means kidney failure."}, {"id": "b", "text": "Blood in the urine is caused by the antibiotic."}, {"id": "c", "text": "Blood in the urine can occur with cystitis."}, {"id": "d", "text": "Blood in the urine rules out a bladder infection."}]'::jsonb, '["c"]', 'Hematuria is a classic bladder symptom of cystitis, and the UA may show hematuria. It does not rule out infection.'),
  ('cystitis', 42, 'A UAP reports that a client with cystitis has cloudy urine with a foul odor. How should the nurse interpret this report?', '[{"id": "a", "text": "It is consistent with cystitis."}, {"id": "b", "text": "It is a sign of urosepsis."}, {"id": "c", "text": "It rules out a bacterial cause."}, {"id": "d", "text": "It is caused by phenazopyridine."}]'::jsonb, '["a"]', 'Cloudy or foul-smelling urine is a classic bladder symptom of cystitis. Urosepsis is signaled by hypotension, tachycardia, and confusion.'),
  ('cystitis', 43, 'A client reports a painful, burning sensation when urinating. Which term should the nurse use to document this symptom?', '[{"id": "a", "text": "Urgency"}, {"id": "b", "text": "Frequency"}, {"id": "c", "text": "Dysuria"}, {"id": "d", "text": "Hematuria"}]'::jsonb, '["c"]', 'Dysuria is painful or burning urination. Urgency is a sudden urge that is hard to control, and frequency is the urge to urinate often.'),
  ('cystitis', 44, 'A client with cystitis describes a sudden need to urinate that is hard to control. Which term should the nurse use to document this symptom?', '[{"id": "a", "text": "Dysuria"}, {"id": "b", "text": "Frequency"}, {"id": "c", "text": "Hematuria"}, {"id": "d", "text": "Urgency"}]'::jsonb, '["d"]', 'Urgency is a sudden urge to urinate that is hard to control. Frequency is the urge to urinate often, and dysuria is painful or burning urination.'),
  ('cystitis', 45, 'The nurse receives report on four clients. Which client should the nurse see first?', '[{"id": "a", "text": "A client with cystitis who reports burning on urination"}, {"id": "b", "text": "A client with cystitis who is hypotensive and tachycardic"}, {"id": "c", "text": "A client on phenazopyridine who reports orange urine"}, {"id": "d", "text": "A client asking about the use of cranberry products"}]'::jsonb, '["b"]', 'Hypotension and tachycardia are signs of urosepsis, a medical emergency. Burning is an expected cystitis symptom, and orange urine is an expected phenazopyridine effect.'),
  ('cystitis', 46, 'A client is suspected of having interstitial cystitis. Which test does the nurse anticipate to visualize the bladder wall?', '[{"id": "a", "text": "Urine culture and sensitivity"}, {"id": "b", "text": "Urinalysis for nitrites"}, {"id": "c", "text": "Cystoscopy"}, {"id": "d", "text": "Leukocyte esterase dipstick"}]'::jsonb, '["c"]', 'Cystoscopy is used for interstitial cystitis to visualize the bladder wall. Urine culture identifies an organism, which is not the cause in interstitial cystitis.'),
  ('cystitis', 47, 'The nurse observes a newly hired nurse caring for a client with suspected cystitis. Which action requires correction?', '[{"id": "a", "text": "Encouraging the client to drink 2 to 3 L of fluid daily"}, {"id": "b", "text": "Teaching the client to wipe front to back after toileting"}, {"id": "c", "text": "Giving the antibiotic before collecting a urine culture"}, {"id": "d", "text": "Warning that phenazopyridine colors urine"}]'::jsonb, '["c"]', 'A urine culture must be obtained before starting antibiotics. Encouraging fluids, teaching front-to-back wiping, and warning about orange urine are correct.'),
  ('cystitis', 48, 'The nurse is reviewing risk factors for cystitis. Which client has the greatest risk?', '[{"id": "a", "text": "A client who drinks 2 to 3 L of fluid daily"}, {"id": "b", "text": "A client who voids after sexual intercourse"}, {"id": "c", "text": "A client who wipes front to back after toileting"}, {"id": "d", "text": "A client with a long-term indwelling catheter"}]'::jsonb, '["d"]', 'Catheter-associated UTI is a bacterial cause of cystitis, and prolonged catheter use should be avoided. Adequate fluids, voiding after intercourse, and front-to-back wiping are prevention measures.'),
  ('cystitis', 49, 'A client with cystitis asks why spicy foods should be avoided during treatment. Which response by the nurse is accurate?', '[{"id": "a", "text": "Spicy foods block the antibiotic."}, {"id": "b", "text": "Spicy foods irritate the bladder."}, {"id": "c", "text": "Spicy foods cause kidney infection."}, {"id": "d", "text": "Spicy foods turn urine orange."}]'::jsonb, '["b"]', 'Caffeine, alcohol, and spicy foods are bladder irritants and should be avoided. Orange urine is caused by phenazopyridine.'),
  ('cystitis', 50, 'Which finding indicates that a client has pyelonephritis rather than simple cystitis?', '[{"id": "a", "text": "Painful urination"}, {"id": "b", "text": "Urinary frequency"}, {"id": "c", "text": "Suprapubic pressure"}, {"id": "d", "text": "Fever with flank pain"}]'::jsonb, '["d"]', 'Fever plus flank pain indicates pyelonephritis, not simple cystitis. Dysuria, frequency, and suprapubic pressure are classic bladder symptoms.'),
  ('pyelo', 1, 'The nurse is assessing a client admitted with an acute kidney infection. Which set of findings represents the classic triad of pyelonephritis?', '[{"id": "a", "text": "Dysuria, frequency, and urinary urgency"}, {"id": "b", "text": "Flank pain, high fever, and CVA tenderness"}, {"id": "c", "text": "Nausea, malaise, and generalized fatigue"}, {"id": "d", "text": "Pyuria, hematuria, and positive nitrites"}]'::jsonb, '["b"]', 'The classic triad of pyelonephritis is flank pain, high fever, and CVA tenderness. Dysuria, frequency, and urgency are lower UTI symptoms that may also be present but are not the triad.'),
  ('pyelo', 2, 'The nurse prepares to assess a client for costovertebral angle tenderness. Where should the nurse percuss?', '[{"id": "a", "text": "The area just above the pubic bone"}, {"id": "b", "text": "The lower abdomen near the umbilicus"}, {"id": "c", "text": "The upper back between the shoulder blades"}, {"id": "d", "text": "The lower back where the ribs meet the spine"}]'::jsonb, '["d"]', 'CVA tenderness is assessed by tapping the area at the lower back where the ribs meet the spine. The other sites are not the costovertebral angle.'),
  ('pyelo', 3, 'The nurse percusses the costovertebral angle of a client with suspected pyelonephritis. Which client response indicates a positive finding?', '[{"id": "a", "text": "The client winces and reports pain."}, {"id": "b", "text": "The client reports no discomfort."}, {"id": "c", "text": "The client reports an urge to void."}, {"id": "d", "text": "The client reports mild tickling."}]'::jsonb, '["a"]', 'A positive CVA tenderness finding is when the client winces or reports pain as the area is tapped. Absence of discomfort is a negative finding.'),
  ('pyelo', 4, 'Which assessment finding does the nurse expect in a client with acute pyelonephritis?', '[{"id": "a", "text": "Low-grade fever without chills"}, {"id": "b", "text": "Normal temperature and no chills"}, {"id": "c", "text": "High fever with shaking chills"}, {"id": "d", "text": "Low temperature with warm skin"}]'::jsonb, '["c"]', 'Pyelonephritis classically causes a high fever with rigors (shaking chills). A low-grade or absent fever does not match the classic presentation.'),
  ('pyelo', 5, 'A client with pyelonephritis reports an aching pain in both flanks and asks whether this is unusual. Which response by the nurse is accurate?', '[{"id": "a", "text": "Flank pain occurs only on one side."}, {"id": "b", "text": "Pain in both flanks rules out this infection."}, {"id": "c", "text": "Flank pain is not a feature of this infection."}, {"id": "d", "text": "Flank pain may occur on one or both sides."}]'::jsonb, '["d"]', 'Flank pain in pyelonephritis may be unilateral or bilateral and ranges from a dull to a severe ache. Bilateral pain does not rule out the infection.'),
  ('pyelo', 6, 'A client with pyelonephritis also reports dysuria, urgency, and frequency. How should the nurse interpret these symptoms?', '[{"id": "a", "text": "They indicate a second, unrelated infection."}, {"id": "b", "text": "They rule out involvement of the kidney."}, {"id": "c", "text": "Lower UTI symptoms may also be present."}, {"id": "d", "text": "They are adverse effects of ceftriaxone."}]'::jsonb, '["c"]', 'Dysuria, frequency, and urgency are lower UTI symptoms that may also be present in pyelonephritis, because bacteria ascend through the bladder to the kidney. Their presence does not rule out kidney involvement.'),
  ('pyelo', 7, 'Which gastrointestinal findings does the nurse anticipate in a client with pyelonephritis?', '[{"id": "a", "text": "Increased appetite"}, {"id": "b", "text": "Nausea and vomiting"}, {"id": "c", "text": "Black tarry stools"}, {"id": "d", "text": "Constipation and bloating"}]'::jsonb, '["b"]', 'Nausea and vomiting are classic signs and symptoms of pyelonephritis. The other findings are not listed signs of this infection.'),
  ('pyelo', 8, 'A client admitted with suspected pyelonephritis has prescriptions for IV ceftriaxone and a urine culture and sensitivity. Which action should the nurse take first?', '[{"id": "a", "text": "Start the IV ceftriaxone infusion"}, {"id": "b", "text": "Obtain the urine culture specimen"}, {"id": "c", "text": "Teach about voiding after intercourse"}, {"id": "d", "text": "Schedule a follow-up urine culture"}]'::jsonb, '["b"]', 'A urine culture and sensitivity must be obtained before starting antibiotics. Starting ceftriaxone first could interfere with correct organism identification.'),
  ('pyelo', 9, 'A client with suspected pyelonephritis asks why urine must be collected before the first antibiotic dose. Which response by the nurse is accurate?', '[{"id": "a", "text": "It confirms the kidneys are filtering well."}, {"id": "b", "text": "It shows whether a kidney abscess is present."}, {"id": "c", "text": "It ensures the correct organism is identified."}, {"id": "d", "text": "It measures the blood level of the antibiotic."}]'::jsonb, '["c"]', 'Obtaining the culture before antibiotics ensures correct organism identification. A CT scan, not the culture, rules out an abscess.'),
  ('pyelo', 10, 'The nurse is observing a newly hired nurse caring for a client with suspected pyelonephritis. Which action requires correction?', '[{"id": "a", "text": "Tapping the costovertebral angle to assess for pain"}, {"id": "b", "text": "Hanging IV ciprofloxacin before collecting the culture"}, {"id": "c", "text": "Encouraging 2 to 3 L of fluid intake per day"}, {"id": "d", "text": "Giving prescribed acetaminophen for the fever"}]'::jsonb, '["b"]', 'The UA and culture must be obtained before antibiotics are started. CVA percussion, 2 to 3 L/day of fluid, and acetaminophen for fever are appropriate.'),
  ('pyelo', 11, 'The nurse reviews the urinalysis of a client with pyelonephritis. Which finding does the nurse expect?', '[{"id": "a", "text": "No white blood cells"}, {"id": "b", "text": "Pyuria and bacteriuria"}, {"id": "c", "text": "Negative leukocyte esterase"}, {"id": "d", "text": "Clear urine without bacteria"}]'::jsonb, '["b"]', 'The UA in pyelonephritis shows pyuria (WBCs) and bacteriuria, with possible casts and hematuria and positive nitrites and leukocyte esterase. Absence of WBCs or bacteria does not fit.'),
  ('pyelo', 12, 'Which complete blood count result supports a diagnosis of pyelonephritis?', '[{"id": "a", "text": "Decreased white blood cell count"}, {"id": "b", "text": "Elevated white blood cell count"}, {"id": "c", "text": "Normal white blood cell count"}, {"id": "d", "text": "Decreased platelet count"}]'::jsonb, '["b"]', 'The CBC shows an elevated WBC count (leukocytosis), which confirms infection or inflammation. A decreased or normal WBC count is not the expected finding.'),
  ('pyelo', 13, 'A client hospitalized with pyelonephritis has rising serum creatinine and BUN levels. Which complication does the nurse suspect?', '[{"id": "a", "text": "Renal abscess"}, {"id": "b", "text": "Gas-forming infection"}, {"id": "c", "text": "Acute kidney injury"}, {"id": "d", "text": "Expected recovery"}]'::jsonb, '["c"]', 'An elevated creatinine and BUN on the BMP indicate that AKI has developed. A renal abscess is a pus collection identified on CT, and a gas-forming infection is emphysematous pyelonephritis.'),
  ('pyelo', 14, 'A CT scan is prescribed for a client with pyelonephritis. The nurse explains that the purpose of the scan is to do which?', '[{"id": "a", "text": "Identify the bacterial organism"}, {"id": "b", "text": "Measure the white blood cell count"}, {"id": "c", "text": "Determine antibiotic sensitivity"}, {"id": "d", "text": "Rule out obstruction or abscess"}]'::jsonb, '["d"]', 'A CT scan, if needed, rules out obstruction, abscess, or structural abnormality. The urine culture and sensitivity identifies the organism and guides antibiotic choice.'),
  ('pyelo', 15, 'A CT scan shows a collection of pus in the kidney of a client with pyelonephritis. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Drainage of the collection"}, {"id": "b", "text": "Discontinuation of antibiotics"}, {"id": "c", "text": "Restriction of oral fluids"}, {"id": "d", "text": "Holding urine to rest the kidney"}]'::jsonb, '["a"]', 'A renal abscess is a pus collection in the kidney that may need drainage. Restricting fluids and holding urine contradict the teaching for pyelonephritis.'),
  ('pyelo', 16, 'A client with diabetes has pyelonephritis, and imaging shows gas within the kidney. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is an expected, benign finding."}, {"id": "b", "text": "It is a sign the infection is healing."}, {"id": "c", "text": "It is a surgical emergency."}, {"id": "d", "text": "It allows outpatient oral treatment."}]'::jsonb, '["c"]', 'Emphysematous pyelonephritis is a gas-forming infection that is more common in diabetics and is a surgical emergency. It is not a benign or healing finding.'),
  ('pyelo', 17, 'The nurse is caring for four clients with pyelonephritis. Which client has the greatest risk for emphysematous pyelonephritis?', '[{"id": "a", "text": "A client who voids after intercourse"}, {"id": "b", "text": "A client who drinks 8 to 10 glasses of water daily"}, {"id": "c", "text": "A client with diabetes"}, {"id": "d", "text": "A client who wipes front to back"}]'::jsonb, '["c"]', 'Emphysematous pyelonephritis, a gas-forming infection, is more common in diabetics. The other clients are following recommended prevention teaching.'),
  ('pyelo', 18, 'A client with pyelonephritis develops septic shock. The nurse understands that this complication results from which process?', '[{"id": "a", "text": "Gas forming within the kidney"}, {"id": "b", "text": "Scarring from repeated infections"}, {"id": "c", "text": "Pus collecting in the kidney"}, {"id": "d", "text": "Bacteria entering the bloodstream"}]'::jsonb, '["d"]', 'Urosepsis or septicemia occurs when bacteria enter the bloodstream, leading to septic shock. Scarring from repeated infections leads to CKD, and a pus collection is a renal abscess.'),
  ('pyelo', 19, 'A client with a history of repeated episodes of pyelonephritis asks about long-term effects on the kidneys. Which response by the nurse is accurate?', '[{"id": "a", "text": "Repeated infections can permanently scar the kidneys."}, {"id": "b", "text": "Repeated infections strengthen the kidneys'' defenses."}, {"id": "c", "text": "Repeated infections cause only temporary changes."}, {"id": "d", "text": "Repeated infections affect only the bladder lining."}]'::jsonb, '["a"]', 'Repeated infections lead to scarring and permanent damage, resulting in chronic kidney disease. The damage is not temporary.'),
  ('pyelo', 20, 'The nurse explains how acute kidney injury can develop in a client with pyelonephritis. Which statement is accurate?', '[{"id": "a", "text": "Inflammation causes a sudden increase in GFR."}, {"id": "b", "text": "Gas in the kidney slowly increases GFR."}, {"id": "c", "text": "Inflammation causes a sudden decrease in GFR."}, {"id": "d", "text": "Scarring causes a sudden increase in GFR."}]'::jsonb, '["c"]', 'AKI in pyelonephritis is a sudden decrease in GFR from inflammation. An increase in GFR reverses the direction of change.'),
  ('pyelo', 21, 'A client with mild pyelonephritis will be treated as an outpatient. Which prescription does the nurse anticipate?', '[{"id": "a", "text": "Oral ciprofloxacin for 7 to 14 days"}, {"id": "b", "text": "IV ceftriaxone with hospital admission"}, {"id": "c", "text": "A single dose of an oral antibiotic"}, {"id": "d", "text": "Antibiotics only if the fever persists"}]'::jsonb, '["a"]', 'Mild pyelonephritis is treated as an outpatient with oral ciprofloxacin for 7 to 14 days. IV ceftriaxone is used for moderate to severe inpatient cases.'),
  ('pyelo', 22, 'A client with mild pyelonephritis is prescribed TMP-SMX for 14 days. Which finding makes this choice appropriate?', '[{"id": "a", "text": "The organism is sensitive to TMP-SMX."}, {"id": "b", "text": "The client is in the third trimester."}, {"id": "c", "text": "The infection is moderate to severe."}, {"id": "d", "text": "The culture has not been collected."}]'::jsonb, '["a"]', 'TMP-SMX for 14 days is an outpatient option for mild pyelonephritis if the organism is sensitive. Moderate to severe infection requires IV therapy, and pregnant clients receive IV cephalosporins.'),
  ('pyelo', 23, 'A client receiving IV ceftriaxone for severe pyelonephritis asks when oral antibiotics can begin. Which finding indicates readiness for the switch?', '[{"id": "a", "text": "After the first IV dose is given"}, {"id": "b", "text": "Afebrile for 24 to 48 hours"}, {"id": "c", "text": "Flank pain present but tolerable"}, {"id": "d", "text": "Fever lower but still present"}]'::jsonb, '["b"]', 'IV ceftriaxone or IV ciprofloxacin is transitioned to oral therapy when the client has been afebrile for 24 to 48 hours. A persistent fever, even if lower, does not meet this criterion.'),
  ('pyelo', 24, 'A client is admitted with moderate to severe pyelonephritis. Which medication does the nurse anticipate administering?', '[{"id": "a", "text": "Oral TMP-SMX only"}, {"id": "b", "text": "IV ceftriaxone"}, {"id": "c", "text": "Oral ciprofloxacin only"}, {"id": "d", "text": "Acetaminophen only"}]'::jsonb, '["b"]', 'Moderate to severe pyelonephritis is treated as an inpatient with IV ceftriaxone or IV ciprofloxacin, then transitioned to oral therapy. Oral-only regimens are for mild outpatient cases.'),
  ('pyelo', 25, 'A pregnant client is diagnosed with severe pyelonephritis. Which plan of care does the nurse anticipate?', '[{"id": "a", "text": "Outpatient oral ciprofloxacin"}, {"id": "b", "text": "Hospitalization with IV cephalosporins"}, {"id": "c", "text": "Oral TMP-SMX taken at home"}, {"id": "d", "text": "Observation without antibiotics"}]'::jsonb, '["b"]', 'Pregnant clients with pyelonephritis receive IV cephalosporins and are hospitalized if severe. Outpatient oral regimens are for mild cases in nonpregnant clients.'),
  ('pyelo', 26, 'A female client asks why being a woman increases her risk for pyelonephritis. Which response by the nurse is accurate?', '[{"id": "a", "text": "The female urethra is short."}, {"id": "b", "text": "The female bladder is larger."}, {"id": "c", "text": "Female kidneys are smaller."}, {"id": "d", "text": "Women produce more urine."}]'::jsonb, '["a"]', 'Female anatomy, specifically a short urethra, is a risk factor because bacteria ascend from the urethra to the bladder and kidneys. The other explanations are not listed risk factors.'),
  ('pyelo', 27, 'The nurse is reviewing hospitalized clients for risk factors for pyelonephritis. Which client has a listed risk factor?', '[{"id": "a", "text": "A client with an indwelling urinary catheter"}, {"id": "b", "text": "A client who drinks 2 to 3 L of fluid daily"}, {"id": "c", "text": "A client who empties the bladder regularly"}, {"id": "d", "text": "A client who completes each antibiotic course"}]'::jsonb, '["a"]', 'Catheterization is a risk factor for pyelonephritis. Adequate hydration, avoiding prolonged holding of urine, and completing antibiotic courses are recommended teaching points.'),
  ('pyelo', 28, 'A child with recurrent pyelonephritis is diagnosed with vesicoureteral reflux. The parent asks what this means. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Urine flows too quickly from the kidneys to the bladder."}, {"id": "b", "text": "The bladder is unable to store any urine at all."}, {"id": "c", "text": "A stone in the urethra is blocking the flow of urine."}, {"id": "d", "text": "Urine flows backward from the bladder toward the kidneys."}]'::jsonb, '["d"]', 'Vesicoureteral reflux allows urine to flow backward from the bladder into the ureters and kidneys, leading to ascending infection. It does not describe rapid forward flow.'),
  ('pyelo', 29, 'Which sequence describes how bacteria typically travel to cause pyelonephritis?', '[{"id": "a", "text": "Urethra, bladder, ureters, kidney"}, {"id": "b", "text": "Kidney, ureters, bladder, urethra"}, {"id": "c", "text": "Bladder, urethra, ureters, kidney"}, {"id": "d", "text": "Ureters, urethra, bladder, kidney"}]'::jsonb, '["a"]', 'Bacteria ascend from the urethra to the bladder, then the ureters, and then the kidneys. Starting at the kidney reverses the ascending direction of infection.'),
  ('pyelo', 30, 'A client with pyelonephritis asks whether E. coli is a likely cause of the infection. Which response by the nurse is accurate?', '[{"id": "a", "text": "E. coli causes very few cases."}, {"id": "b", "text": "E. coli infects only the bladder."}, {"id": "c", "text": "E. coli enters only from the blood."}, {"id": "d", "text": "E. coli causes about 80% of cases."}]'::jsonb, '["d"]', 'E. coli is the most common pathogen, causing about 80% of cases, and it ascends from the urethra to the kidney. It does not infect only the bladder.'),
  ('pyelo', 31, 'Which fluid instruction should the nurse include in the plan of care for a client with pyelonephritis?', '[{"id": "a", "text": "Limit fluids to 1 L per day."}, {"id": "b", "text": "Drink 2 to 3 L of fluid per day."}, {"id": "c", "text": "Drink fluids only with meals."}, {"id": "d", "text": "Restrict fluids until afebrile."}]'::jsonb, '["b"]', 'Adequate hydration of 2 to 3 L/day flushes the kidneys. Limiting or restricting fluids works against this goal.'),
  ('pyelo', 32, 'The nurse provides discharge teaching to a client recovering from pyelonephritis. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''I will cut back on water so I urinate less.''"}, {"id": "b", "text": "''I will drink 8 to 10 glasses of water each day.''"}, {"id": "c", "text": "''I will wipe from front to back after toileting.''"}, {"id": "d", "text": "''I will finish all of my antibiotic pills.''"}]'::jsonb, '["a"]', 'Clients should drink 8 to 10 glasses of water per day, so cutting back on water is incorrect. Front-to-back wiping and completing the full antibiotic course are correct.'),
  ('pyelo', 33, 'A client with pyelonephritis has a high fever. Which prescribed medication should the nurse administer as an antipyretic?', '[{"id": "a", "text": "Ceftriaxone"}, {"id": "b", "text": "Ciprofloxacin"}, {"id": "c", "text": "TMP-SMX"}, {"id": "d", "text": "Acetaminophen"}]'::jsonb, '["d"]', 'Acetaminophen is the antipyretic used for fever management. Ceftriaxone, ciprofloxacin, and TMP-SMX are antibiotics that treat the infection.'),
  ('pyelo', 34, 'A client with pyelonephritis rates flank pain as 7 on a 0-to-10 scale. Which action should the nurse take?', '[{"id": "a", "text": "Restrict fluids to rest the kidney."}, {"id": "b", "text": "Delay pain relief until cultures return."}, {"id": "c", "text": "Explain that flank pain is unexpected."}, {"id": "d", "text": "Give the prescribed analgesic."}]'::jsonb, '["d"]', 'Analgesics are part of the treatment plan for flank pain in pyelonephritis. Flank pain is a classic finding, and fluids should be encouraged, not restricted.'),
  ('pyelo', 35, 'On day 5 of a 14-day antibiotic course, a client with pyelonephritis feels well and wants to stop the medication. Which response by the nurse is best?', '[{"id": "a", "text": "Stop now because your fever has resolved."}, {"id": "b", "text": "Save the remaining pills for later use."}, {"id": "c", "text": "Take the pills only if your pain returns."}, {"id": "d", "text": "Finish the full course even though you feel better."}]'::jsonb, '["d"]', 'Clients should complete the full antibiotic course even if feeling better. Stopping early because symptoms resolved contradicts this teaching.'),
  ('pyelo', 36, 'The nurse evaluates discharge teaching for a client treated for pyelonephritis. Which statement by the client indicates understanding?', '[{"id": "a", "text": "''A fever that lasts after discharge is expected.''"}, {"id": "b", "text": "''I will wait for my next visit if symptoms worsen.''"}, {"id": "c", "text": "''Worsening flank pain is normal while I heal.''"}, {"id": "d", "text": "''I will call my provider if my fever does not go away.''"}]'::jsonb, '["d"]', 'Clients should return to the provider if symptoms worsen or fever persists. Waiting for a scheduled visit when symptoms worsen is incorrect.'),
  ('pyelo', 37, 'A client has completed antibiotic therapy for pyelonephritis. Which follow-up does the nurse anticipate?', '[{"id": "a", "text": "A CT scan to confirm clearance"}, {"id": "b", "text": "No follow-up once pain resolves"}, {"id": "c", "text": "A urine culture to confirm clearance"}, {"id": "d", "text": "Another 14 days of antibiotics"}]'::jsonb, '["c"]', 'A follow-up urine culture after treatment confirms clearance of the infection. A CT scan is used to rule out obstruction, abscess, or structural abnormality.'),
  ('pyelo', 38, 'The nurse is teaching a client how to prevent another episode of pyelonephritis. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''I will urinate before and after intercourse.''"}, {"id": "b", "text": "''I will wipe from front to back after toileting.''"}, {"id": "c", "text": "''I usually hold my urine until I get home from work.''"}, {"id": "d", "text": "''I will drink 8 to 10 glasses of water daily.''"}]'::jsonb, '["c"]', 'Clients should avoid prolonged holding of urine. Voiding before and after intercourse, front-to-back wiping, and drinking 8 to 10 glasses of water daily are correct.'),
  ('pyelo', 39, 'A sexually active client recovering from pyelonephritis discusses prevention. Which statement by the client indicates understanding?', '[{"id": "a", "text": "''I will urinate before and after sex.''"}, {"id": "b", "text": "''I will urinate only before sex.''"}, {"id": "c", "text": "''I will wait an hour to urinate after sex.''"}, {"id": "d", "text": "''Urinating around sex does not matter.''"}]'::jsonb, '["a"]', 'Clients should void before and after intercourse, because sexual intercourse is a risk factor for pyelonephritis. Voiding only before sex omits the post-intercourse void.'),
  ('pyelo', 40, 'Which instruction should the nurse include in discharge teaching for a woman recovering from pyelonephritis?', '[{"id": "a", "text": "Hold urine to help strengthen the bladder."}, {"id": "b", "text": "Stop antibiotics once the fever resolves."}, {"id": "c", "text": "Wipe from front to back after toileting."}, {"id": "d", "text": "Drink fluids only when you feel thirsty."}]'::jsonb, '["c"]', 'Women should wipe front to back after toileting. Prolonged holding of urine should be avoided, and the full antibiotic course should be completed.'),
  ('pyelo', 41, 'A urine culture has just been collected from a client with pyelonephritis. Why should the nurse avoid delaying the first antibiotic dose?', '[{"id": "a", "text": "Delay improves the culture''s accuracy."}, {"id": "b", "text": "Antibiotics work best after fever peaks."}, {"id": "c", "text": "Prompt treatment helps prevent sepsis."}, {"id": "d", "text": "Delay gives the kidney time to heal."}]'::jsonb, '["c"]', 'Pyelonephritis should be treated promptly with no delay to prevent sepsis. Once the culture is collected, delaying antibiotics does not improve its accuracy.'),
  ('pyelo', 42, 'A client on initial antibiotic therapy for pyelonephritis asks to switch to a different antibiotic before culture results return. Which response by the nurse is best?', '[{"id": "a", "text": "Any antibiotic can be switched at any time."}, {"id": "b", "text": "Culture results are not used to pick antibiotics."}, {"id": "c", "text": "Switching now makes the culture more accurate."}, {"id": "d", "text": "Antibiotic changes are guided by culture results."}]'::jsonb, '["d"]', 'Culture results should be obtained before changing antibiotics, because the culture and sensitivity guides antibiotic choice. Culture results are central to antibiotic selection.'),
  ('pyelo', 43, 'The nurse receives report on four clients with pyelonephritis. Which client should the nurse see first?', '[{"id": "a", "text": "A client with flank pain rated 4 awaiting an analgesic"}, {"id": "b", "text": "A client with diabetes whose CT shows gas in the kidney"}, {"id": "c", "text": "A client asking questions about discharge teaching"}, {"id": "d", "text": "A client with dysuria and urinary frequency"}]'::jsonb, '["b"]', 'A gas-forming infection in the kidney, more common in diabetics, is emphysematous pyelonephritis, a surgical emergency. Flank pain, dysuria, and frequency are expected findings that are not emergencies.'),
  ('pyelo', 44, 'In addition to flank pain and fever, which finding does the nurse expect in a client with pyelonephritis?', '[{"id": "a", "text": "Increased energy level"}, {"id": "b", "text": "Absence of CVA pain"}, {"id": "c", "text": "Low body temperature"}, {"id": "d", "text": "Malaise and fatigue"}]'::jsonb, '["d"]', 'Malaise and fatigue are classic signs and symptoms of pyelonephritis. CVA tenderness and high fever are expected, so their absence would not fit.'),
  ('pyelo', 45, 'The nurse explains pyelonephritis to a newly diagnosed client. Which statement is accurate?', '[{"id": "a", "text": "It is an infection limited to the bladder."}, {"id": "b", "text": "It is an infection of the urethra only."}, {"id": "c", "text": "It is an upper UTI that involves the kidney."}, {"id": "d", "text": "It is a kidney problem without infection."}]'::jsonb, '["c"]', 'Pyelonephritis is an upper UTI, an ascending infection that reaches the kidneys. Infection limited to the bladder is cystitis.'),
  ('pyelo', 46, 'A client asks what ''pyuria'' on the urinalysis report means. Which response by the nurse is accurate?', '[{"id": "a", "text": "There is pus, or WBCs, in the urine."}, {"id": "b", "text": "There is gas forming in the kidney."}, {"id": "c", "text": "There are no bacteria in the urine."}, {"id": "d", "text": "There is too little urine produced."}]'::jsonb, '["a"]', 'Pyuria means pus in the urine, made up of WBCs. Gas in the kidney describes emphysematous pyelonephritis.'),
  ('pyelo', 47, 'Which urinalysis result supports a diagnosis of pyelonephritis?', '[{"id": "a", "text": "Positive nitrites and leukocyte esterase"}, {"id": "b", "text": "Negative nitrites and leukocyte esterase"}, {"id": "c", "text": "No white blood cells and no bacteria"}, {"id": "d", "text": "Clear urine with no casts or blood"}]'::jsonb, '["a"]', 'The UA in pyelonephritis shows positive nitrites and leukocyte esterase, along with pyuria, bacteriuria, and possible casts and hematuria. Negative results do not support the diagnosis.'),
  ('pyelo', 48, 'The nurse reviews the histories of four women. Which client has a listed risk factor for pyelonephritis?', '[{"id": "a", "text": "A client who voids every few hours"}, {"id": "b", "text": "A client who wipes front to back"}, {"id": "c", "text": "A client who drinks 2 to 3 L daily"}, {"id": "d", "text": "A client who is currently pregnant"}]'::jsonb, '["d"]', 'Pregnancy is a listed risk factor for pyelonephritis. Avoiding prolonged holding of urine, front-to-back wiping, and adequate hydration are prevention measures.'),
  ('pyelo', 49, 'The nurse is reviewing risk factors for pyelonephritis. Which client is at increased risk?', '[{"id": "a", "text": "A client who voids after sexual intercourse"}, {"id": "b", "text": "A client receiving immunosuppressive therapy"}, {"id": "c", "text": "A client who completes every antibiotic course"}, {"id": "d", "text": "A client who returns for a follow-up culture"}]'::jsonb, '["b"]', 'Immunosuppression is a listed risk factor for pyelonephritis. Voiding after intercourse, completing antibiotic courses, and follow-up cultures are recommended teaching points.'),
  ('pyelo', 50, 'The nurse is caring for children with recurrent pyelonephritis. Which condition does the nurse recognize as a common risk factor in this age group?', '[{"id": "a", "text": "Vesicoureteral reflux"}, {"id": "b", "text": "Emphysematous pyelonephritis"}, {"id": "c", "text": "Renal abscess"}, {"id": "d", "text": "Chronic kidney disease"}]'::jsonb, '["a"]', 'Vesicoureteral reflux is a common risk in children because it allows urine to flow backward toward the kidneys. Renal abscess, emphysematous pyelonephritis, and CKD are complications, not risk factors.'),
  ('urine_collection', 1, 'A nurse is teaching a female client how to collect a midstream clean-catch urine specimen. Which cleansing instruction should the nurse give?', '[{"id": "a", "text": "\"Wipe the perineum from back to front.\""}, {"id": "b", "text": "\"Wipe the perineum from front to back.\""}, {"id": "c", "text": "\"Skip cleansing because the first stream rinses the area.\""}, {"id": "d", "text": "\"Wipe the perineum only after collecting the urine.\""}]'::jsonb, '["b"]', 'Women clean the perineum/urethral meatus with antiseptic wipes from front to back before voiding. Cleansing must happen before collection; the first stream does not replace it.'),
  ('urine_collection', 2, 'A nurse is teaching an uncircumcised male client to collect a midstream clean-catch urine specimen. Which instruction is correct?', '[{"id": "a", "text": "\"Clean the shaft only and leave the meatus untouched.\""}, {"id": "b", "text": "\"Clean the meatus from back to front without retracting the foreskin.\""}, {"id": "c", "text": "\"Retract the foreskin and clean the meatus in a circular motion.\""}, {"id": "d", "text": "\"Rinse the meatus with tap water instead of antiseptic wipes.\""}]'::jsonb, '["c"]', 'Men clean the urethral meatus with antiseptic wipes in a circular motion, retracting the foreskin if uncircumcised. Front-to-back cleansing is the instruction for women.'),
  ('urine_collection', 3, 'A client collecting a midstream clean-catch specimen asks why the first portion of urine goes into the toilet. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The first stream is the most concentrated urine.\""}, {"id": "b", "text": "\"The first stream is too small an amount to test.\""}, {"id": "c", "text": "\"The first stream is saved for a separate test.\""}, {"id": "d", "text": "\"The first stream flushes out contaminants.\""}]'::jsonb, '["d"]', 'Voiding first into the toilet allows the first stream to flush out contaminants before the midstream sample is caught. First-morning urine, not the first stream, is described as most concentrated.'),
  ('urine_collection', 4, 'A nurse is teaching a client the steps of a midstream clean-catch urine collection. Which sequence is correct?', '[{"id": "a", "text": "Clean meatus → void into toilet → catch midstream → finish in toilet → cap container"}, {"id": "b", "text": "Void into toilet → clean meatus → catch midstream → cap container → finish in toilet"}, {"id": "c", "text": "Clean meatus → catch first stream → finish in toilet → leave container uncapped"}, {"id": "d", "text": "Catch midstream → clean meatus → finish in toilet → cap container"}]'::jsonb, '["a"]', 'The client cleans the perineum, starts voiding into the toilet, catches the middle stream, finishes voiding into the toilet, and caps the container immediately. Catching the first stream or cleaning after voiding defeats the technique.'),
  ('urine_collection', 5, 'A nurse observes a client collecting a midstream clean-catch urine specimen. Which client action indicates a need for further teaching?', '[{"id": "a", "text": "Holds the container in the stream without touching the rim"}, {"id": "b", "text": "Wipes the inside of the lid with a finger to remove moisture"}, {"id": "c", "text": "Finishes voiding into the toilet after catching the sample"}, {"id": "d", "text": "Caps the container right after collecting the specimen"}]'::jsonb, '["b"]', 'The client must not touch the inside of the container or lid. Holding the container without touching the rim, finishing in the toilet, and capping immediately are all correct.'),
  ('urine_collection', 6, 'A client collects a clean-catch urine specimen at 0900, but transport to the laboratory will not be available until 1000. Which action should the nurse take?', '[{"id": "a", "text": "Leave the specimen at room temperature until pickup"}, {"id": "b", "text": "Discard the specimen and recollect one at 1000"}, {"id": "c", "text": "Refrigerate the specimen until it can be sent"}, {"id": "d", "text": "Send the specimen whenever transport is convenient"}]'::jsonb, '["c"]', 'A specimen that will not reach the lab within 30 minutes should be refrigerated. Leaving it at room temperature for an hour risks inaccurate results.'),
  ('urine_collection', 7, 'A nurse has collected a urine specimen from a client. Which information should the nurse include on the specimen label?', '[{"id": "a", "text": "Client name, date, and time of collection"}, {"id": "b", "text": "Client name only, with no date or time"}, {"id": "c", "text": "Date only, with no client identifier"}, {"id": "d", "text": "Room number and diagnosis only"}]'::jsonb, '["a"]', 'The specimen is labeled with the patient''s name and the date/time, then sent to the lab promptly. Labels missing the name or the date/time are incomplete.'),
  ('urine_collection', 8, 'A nurse needs a urine specimen for culture from a client with an indwelling urinary catheter. Which action is correct?', '[{"id": "a", "text": "Pour urine from the drainage bag into a sterile cup"}, {"id": "b", "text": "Empty the drainage bag and save the first urine that drains"}, {"id": "c", "text": "Aspirate urine from the sampling port with a sterile syringe"}, {"id": "d", "text": "Ask the client to void around the catheter into a cup"}]'::jsonb, '["c"]', 'Urine from a catheter is aspirated from the sampling port using a sterile syringe. Urine from the drainage bag is stagnant and contaminated.'),
  ('urine_collection', 9, 'A charge nurse observes a newly hired nurse collecting a urine specimen from a client''s indwelling catheter. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Clamps the tubing for 15 to 30 minutes before sampling"}, {"id": "b", "text": "Cleanses the sampling port with alcohol"}, {"id": "c", "text": "Transfers the urine into a sterile specimen container"}, {"id": "d", "text": "Obtains the urine from the drainage bag"}]'::jsonb, '["d"]', 'Urine should never be collected from the drainage bag because it is stagnant, contaminated, and not fresh. Clamping the tubing, cleansing the port with alcohol, and using a sterile container are correct.'),
  ('urine_collection', 10, 'A family member asks why the nurse does not simply take the urine sample from the client''s catheter drainage bag. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Bag urine is stagnant, contaminated, and not fresh.\""}, {"id": "b", "text": "\"Bag urine is too concentrated to be cultured.\""}, {"id": "c", "text": "\"The bag contains a preservative that alters results.\""}, {"id": "d", "text": "\"Bag urine is sterile but much too dilute.\""}]'::jsonb, '["a"]', 'Bag urine is stagnant, contaminated, and not fresh, so it is never used for a specimen. It is not sterile.'),
  ('urine_collection', 11, 'Before aspirating a urine specimen from a client''s indwelling catheter, the nurse clamps the drainage tubing. For how long should the tubing remain clamped?', '[{"id": "a", "text": "1 to 2 minutes"}, {"id": "b", "text": "15 to 30 minutes"}, {"id": "c", "text": "2 to 3 hours"}, {"id": "d", "text": "4 to 6 hours"}]'::jsonb, '["b"]', 'The catheter tubing is clamped for 15–30 minutes to allow urine to collect. One to two minutes is too short, and several hours far exceeds the recommended time.'),
  ('urine_collection', 12, 'A nurse is preparing to obtain a urine specimen from a client''s catheter sampling port. Which solution should the nurse use to cleanse the port?', '[{"id": "a", "text": "Sterile water"}, {"id": "b", "text": "Tap water"}, {"id": "c", "text": "Alcohol"}, {"id": "d", "text": "Soap and water"}]'::jsonb, '["c"]', 'The sampling port is cleansed with alcohol before a sterile syringe is used to aspirate urine. Water or soap is not the cleansing agent for the port.'),
  ('urine_collection', 13, 'A nurse is obtaining a catheterized urine specimen. Which sequence of actions is correct?', '[{"id": "a", "text": "Cleanse port → aspirate urine → clamp tubing → transfer to container → unclamp tubing"}, {"id": "b", "text": "Clamp tubing → aspirate urine → cleanse port → unclamp tubing → transfer to container"}, {"id": "c", "text": "Unclamp tubing → cleanse port → aspirate urine → clamp tubing → transfer to container"}, {"id": "d", "text": "Clamp tubing → cleanse port → aspirate urine → transfer to container → unclamp tubing"}]'::jsonb, '["d"]', 'The nurse clamps the tubing so urine collects, cleanses the port with alcohol, aspirates with a sterile syringe, transfers the urine to a sterile container, and then unclamps the tubing. Cleansing must precede aspiration.'),
  ('urine_collection', 14, 'A nurse has aspirated urine from a catheter port and transferred it to a sterile specimen container. Which action should the nurse take next?', '[{"id": "a", "text": "Leave the tubing clamped until the lab result returns"}, {"id": "b", "text": "Unclamp the tubing and send the specimen to the lab"}, {"id": "c", "text": "Pour the leftover urine back into the drainage bag"}, {"id": "d", "text": "Store the filled syringe at the bedside for later"}]'::jsonb, '["b"]', 'After transferring the urine to a sterile container, the nurse unclamps the tubing and sends the specimen to the lab. Leaving the tubing clamped is not part of the procedure.'),
  ('urine_collection', 15, 'A client begins a 24-hour urine collection at 0700. Which instruction should the nurse give about the 0700 void?', '[{"id": "a", "text": "\"Save this void as the first sample in the jug.\""}, {"id": "b", "text": "\"Discard this void and note the time.\""}, {"id": "c", "text": "\"Save this void in a separate sterile cup.\""}, {"id": "d", "text": "\"Discard this void and start timing at noon.\""}]'::jsonb, '["b"]', 'The first morning void is discarded and not collected; the time is noted as the start. Timing begins at that void, not hours later.'),
  ('urine_collection', 16, 'A client started a 24-hour urine collection by discarding the 0800 void on Monday. When should the client collect the final void?', '[{"id": "a", "text": "At 2000 on Monday"}, {"id": "b", "text": "At 0800 on Wednesday"}, {"id": "c", "text": "At 0800 on Tuesday"}, {"id": "d", "text": "At the first void after midnight"}]'::jsonb, '["c"]', 'The final void is collected at the same time as the start, 24 hours later, which is 0800 on Tuesday. 2000 on Monday is only 12 hours into the collection.'),
  ('urine_collection', 17, 'During a 24-hour urine collection, a client reports flushing one void down the toilet at hour 14. Which action should the nurse take?', '[{"id": "a", "text": "Continue the collection and document the missed void"}, {"id": "b", "text": "Extend the collection by one additional hour"}, {"id": "c", "text": "Send the urine collected so far to the laboratory"}, {"id": "d", "text": "Restart the entire collection from the beginning"}]'::jsonb, '["d"]', 'If any void is missed, the entire 24-hour collection must be restarted from the beginning. Continuing or extending the collection would produce an inaccurate result.'),
  ('urine_collection', 18, 'A nurse is teaching a client about a 24-hour urine collection. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"If I miss saving a void, I will add an extra hour.\""}, {"id": "b", "text": "\"I will keep the jug on ice during the collection.\""}, {"id": "c", "text": "\"I will throw away the first void and note the time.\""}, {"id": "d", "text": "\"I will save all of my urine for the next 24 hours.\""}]'::jsonb, '["a"]', 'A missed void requires restarting the entire collection; adding time does not fix it. Keeping the jug on ice, discarding the first void, and saving all urine are correct.'),
  ('urine_collection', 19, 'A client asks why the 24-hour urine collection container must be kept on ice. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Cold keeps the urine from becoming concentrated.\""}, {"id": "b", "text": "\"Cold prevents bacterial growth in the urine.\""}, {"id": "c", "text": "\"Cold dilutes the urine for more accurate testing.\""}, {"id": "d", "text": "\"Cold mainly reduces odor in the bathroom.\""}]'::jsonb, '["b"]', 'The container is kept on ice or refrigerated throughout the collection to prevent bacterial growth. Its purpose is not to change concentration or control odor.'),
  ('urine_collection', 20, 'A nurse is supervising a UAP who is managing a client''s 24-hour urine collection. Which action by the UAP requires correction?', '[{"id": "a", "text": "Places the collection jug on ice"}, {"id": "b", "text": "Saves all urine voided after the first void"}, {"id": "c", "text": "Labels the jug and sends it to the lab"}, {"id": "d", "text": "Adds the first morning void to the jug"}]'::jsonb, '["d"]', 'The first morning void is discarded and is not collected. Keeping the jug on ice, saving all later urine, and labeling the jug are correct.'),
  ('urine_collection', 21, 'A client starting a 24-hour urine collection asks where to put the urine from each void. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Pour every void into the large collection jug.\""}, {"id": "b", "text": "\"Save only the voids that look concentrated.\""}, {"id": "c", "text": "\"Use a separate labeled cup for each void.\""}, {"id": "d", "text": "\"Collect only the daytime voids in the jug.\""}]'::jsonb, '["a"]', 'After the first void is discarded, all urine for the next 24 hours is collected into the large collection jug. Saving only some voids would mean a missed void and a restart.'),
  ('urine_collection', 22, 'A provider orders a test to measure a client''s creatinine clearance. Which urine collection method should the nurse anticipate?', '[{"id": "a", "text": "24-hour urine collection"}, {"id": "b", "text": "First-morning urine"}, {"id": "c", "text": "Suprapubic aspiration"}, {"id": "d", "text": "Single midstream clean-catch"}]'::jsonb, '["a"]', 'Creatinine clearance is measured with a 24-hour urine collection. First-morning urine is best for pregnancy tests, and midstream clean-catch is used for urinalysis and culture.'),
  ('urine_collection', 23, 'A client is scheduled for measurement of urinary cortisol and catecholamines. Which collection method should the nurse prepare to teach?', '[{"id": "a", "text": "Midstream clean-catch specimen"}, {"id": "b", "text": "First-morning urine specimen"}, {"id": "c", "text": "24-hour urine collection"}, {"id": "d", "text": "Catheter port specimen"}]'::jsonb, '["c"]', 'A 24-hour urine collection is used to measure hormones such as cortisol and catecholamines. A midstream clean-catch is used for urinalysis and culture.'),
  ('urine_collection', 24, 'A client with a suspected urinary tract infection (UTI) is able to void. Which specimen method should the nurse use to obtain a urine culture?', '[{"id": "a", "text": "24-hour urine collection"}, {"id": "b", "text": "Midstream clean-catch specimen"}, {"id": "c", "text": "Suprapubic aspiration"}, {"id": "d", "text": "First urine stream of a void"}]'::jsonb, '["b"]', 'The midstream clean-catch specimen is preferred for urinalysis and urine culture for UTI. The first stream is flushed into the toilet because it contains contaminants.'),
  ('urine_collection', 25, 'A client plans to take a urine pregnancy test. Which urine specimen should the nurse recommend?', '[{"id": "a", "text": "Last void of the evening"}, {"id": "b", "text": "Urine from a 24-hour collection"}, {"id": "c", "text": "Midstream urine from any void"}, {"id": "d", "text": "First-morning urine"}]'::jsonb, '["d"]', 'First-morning urine is the most concentrated and is best for pregnancy tests. A 24-hour collection is used for creatinine clearance, protein, and hormones.'),
  ('urine_collection', 26, 'A client asks why a first-morning specimen is requested for a pregnancy test. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is the most dilute urine of the day.\""}, {"id": "b", "text": "\"It is the most concentrated urine of the day.\""}, {"id": "c", "text": "\"It is completely free of contaminants.\""}, {"id": "d", "text": "\"It is the only sterile urine of the day.\""}]'::jsonb, '["b"]', 'First-morning urine is the most concentrated, giving the best sensitivity for pregnancy testing. It is not the most dilute.'),
  ('urine_collection', 27, 'A nurse in an outpatient clinic is asked which urine collection method is most commonly used for routine urinalysis. Which method should the nurse identify?', '[{"id": "a", "text": "Suprapubic aspiration"}, {"id": "b", "text": "24-hour urine collection"}, {"id": "c", "text": "Midstream clean-catch"}, {"id": "d", "text": "Catheterized specimen"}]'::jsonb, '["c"]', 'The midstream clean-catch is the most common method and is used for urinalysis and urine culture. Suprapubic aspiration is reserved for infants needing a truly sterile culture.'),
  ('urine_collection', 28, 'For which client should the nurse anticipate obtaining a catheterized specimen for a sterile urine culture?', '[{"id": "a", "text": "An adult who needs a pregnancy test"}, {"id": "b", "text": "An adult who needs creatinine clearance"}, {"id": "c", "text": "An adult who voids and needs a urinalysis"}, {"id": "d", "text": "An adult who is unable to void"}]'::jsonb, '["d"]', 'A catheterized specimen is used for a sterile culture when the client cannot void. A client who can void uses a midstream clean-catch for urinalysis.'),
  ('urine_collection', 29, 'A truly sterile urine culture is needed from an infant. Which collection method should the nurse anticipate?', '[{"id": "a", "text": "Suprapubic aspiration"}, {"id": "b", "text": "First-morning urine"}, {"id": "c", "text": "24-hour urine collection"}, {"id": "d", "text": "Midstream clean-catch"}]'::jsonb, '["a"]', 'Suprapubic aspiration is used for infants when a truly sterile culture is needed. A 24-hour collection measures creatinine clearance, protein, and hormones.'),
  ('urine_collection', 30, 'The parents of an infant ask how a suprapubic aspiration is performed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A catheter is passed through the urethra into the bladder.\""}, {"id": "b", "text": "\"A bag is taped over the genitals to catch the urine.\""}, {"id": "c", "text": "\"A needle is passed through the lower abdomen into the bladder.\""}, {"id": "d", "text": "\"The first stream is caught in a sterile cup.\""}]'::jsonb, '["c"]', 'Suprapubic aspiration uses a needle passed through the lower abdomen into the bladder. A catheter passed through the urethra describes a catheterized specimen.'),
  ('urine_collection', 31, 'A client is about to collect a midstream clean-catch urine specimen. Which action by the nurse is the priority before collection?', '[{"id": "a", "text": "Hand the client a clean nonsterile cup"}, {"id": "b", "text": "Teach correct perineal cleaning technique"}, {"id": "c", "text": "Instruct the client to catch the first stream"}, {"id": "d", "text": "Tell the client to label the cup afterward"}]'::jsonb, '["b"]', 'Teaching correct perineal cleaning technique before collection is a nursing priority. The first stream goes into the toilet, and the container must be sterile.'),
  ('urine_collection', 32, 'A nurse is teaching a client how to collect a midstream clean-catch urine specimen. Which step should the client perform first?', '[{"id": "a", "text": "Begin voiding into the toilet"}, {"id": "b", "text": "Open the container and hold it ready"}, {"id": "c", "text": "Label the specimen container"}, {"id": "d", "text": "Wash hands thoroughly"}]'::jsonb, '["d"]', 'The first step of a midstream clean-catch is to wash hands thoroughly, followed by cleansing the perineum/urethral meatus. Voiding begins only after cleansing.'),
  ('urine_collection', 33, 'A client has just caught the midstream portion of urine in a sterile container. What should the client do next?', '[{"id": "a", "text": "Finish voiding into the toilet and cap the container immediately"}, {"id": "b", "text": "Continue voiding into the container until it overflows"}, {"id": "c", "text": "Leave the container uncapped until the nurse arrives"}, {"id": "d", "text": "Stop voiding and wait 30 minutes before finishing"}]'::jsonb, '["a"]', 'After catching the midstream urine, the client finishes voiding into the toilet and caps the container immediately. Leaving it uncapped risks contamination.'),
  ('urine_collection', 34, 'A nurse is evaluating a client''s technique during a midstream clean-catch collection. Which client action indicates correct technique?', '[{"id": "a", "text": "Rests the rim of the container against the skin"}, {"id": "b", "text": "Holds the container in the stream without touching the rim"}, {"id": "c", "text": "Places a finger inside the container to steady it"}, {"id": "d", "text": "Sets the open lid face down on the counter"}]'::jsonb, '["b"]', 'The client holds the sterile container in the stream mid-void without touching the rim. Touching the inside of the container or lid contaminates the specimen.'),
  ('urine_collection', 35, 'A nurse is reviewing specimen handling with a UAP. Within what time frame should an unrefrigerated urine specimen be sent to the laboratory?', '[{"id": "a", "text": "Within 2 hours"}, {"id": "b", "text": "Within 4 hours"}, {"id": "c", "text": "Within 30 minutes"}, {"id": "d", "text": "Within 8 hours"}]'::jsonb, '["c"]', 'A urine specimen should be sent within 30 minutes or refrigerated. Longer times at room temperature are not acceptable.'),
  ('urine_collection', 36, 'A nursing student asks why the nurse is so careful about urine collection technique. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Technique matters only for 24-hour collections.\""}, {"id": "b", "text": "\"Technique only affects how fast results return.\""}, {"id": "c", "text": "\"Correct technique prevents contamination and false results.\""}, {"id": "d", "text": "\"Technique matters only when a catheter is present.\""}]'::jsonb, '["c"]', 'The collection method directly affects accuracy; correct technique prevents contamination and false results. This applies to every collection type, not just one.'),
  ('urine_collection', 37, 'A nurse is reviewing urine collection types with a nursing student. Which collection type is matched with its correct use?', '[{"id": "a", "text": "24-hour urine — pregnancy test"}, {"id": "b", "text": "First-morning urine — creatinine clearance"}, {"id": "c", "text": "Catheter drainage bag — sterile culture"}, {"id": "d", "text": "Suprapubic aspiration — infant sterile culture"}]'::jsonb, '["d"]', 'Suprapubic aspiration is used for infants needing a truly sterile culture. Pregnancy tests use first-morning urine, creatinine clearance uses a 24-hour collection, and bag urine is never used.'),
  ('urine_collection', 38, 'A nurse is teaching a nursing student about obtaining a specimen from a client with an indwelling catheter. Which statement by the student indicates understanding?', '[{"id": "a", "text": "\"I will always sample from the port, never the bag.\""}, {"id": "b", "text": "\"I will sample from the bag if the port is hard to reach.\""}, {"id": "c", "text": "\"I will use the bag for urinalysis and the port for culture.\""}, {"id": "d", "text": "\"I will empty the bag first and then sample from it.\""}]'::jsonb, '["a"]', 'When a catheter is present, the specimen is always taken from the sampling port and never from the bag. Bag urine is stagnant and contaminated for any test.'),
  ('urine_collection', 39, 'After aspirating urine from a catheter sampling port, the nurse should place the urine into which container?', '[{"id": "a", "text": "The drainage bag"}, {"id": "b", "text": "A clean nonsterile cup"}, {"id": "c", "text": "A sterile specimen container"}, {"id": "d", "text": "The 24-hour collection jug"}]'::jsonb, '["c"]', 'Urine aspirated from the port is transferred to a sterile specimen container. Returning it to the drainage bag or using a nonsterile cup would contaminate the specimen.'),
  ('urine_collection', 40, 'A client on a 24-hour urine collection wakes to void at 0300 and asks what to do with this urine. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Add it to the collection jug.\""}, {"id": "b", "text": "\"Discard it because it is a night void.\""}, {"id": "c", "text": "\"Save it in a separate cup for the lab.\""}, {"id": "d", "text": "\"Discard it and extend the collection.\""}]'::jsonb, '["a"]', 'After the first void is discarded, all urine for the next 24 hours is collected into the large jug. Discarding any void would require restarting the collection.'),
  ('urine_collection', 41, 'A provider orders a 24-hour urine collection for a client. The nurse recognizes this collection may be used to measure which value?', '[{"id": "a", "text": "Pregnancy status"}, {"id": "b", "text": "Urinary protein levels"}, {"id": "c", "text": "Infant sterile culture"}, {"id": "d", "text": "Bacterial growth for UTI"}]'::jsonb, '["b"]', 'A 24-hour urine collection measures creatinine clearance, protein levels, hormones, and electrolytes. Pregnancy testing uses first-morning urine, and UTI culture uses a midstream clean-catch.'),
  ('urine_collection', 42, 'A nurse needs a urine culture from a client with an indwelling catheter. Which action should the nurse take first?', '[{"id": "a", "text": "Cleanse the sampling port with alcohol"}, {"id": "b", "text": "Aspirate urine with a sterile syringe"}, {"id": "c", "text": "Unclamp the drainage tubing"}, {"id": "d", "text": "Clamp the tubing to allow urine to collect"}]'::jsonb, '["d"]', 'The first step is clamping the catheter tubing for 15–30 minutes so urine collects. Cleansing the port and aspirating follow, and the tubing is unclamped last.'),
  ('urine_collection', 43, 'A nurse is checking on several clients completing 24-hour urine collections. Which event requires the nurse to restart a collection?', '[{"id": "a", "text": "The jug has been kept on ice throughout"}, {"id": "b", "text": "The first morning void was discarded"}, {"id": "c", "text": "The client discarded one void by mistake"}, {"id": "d", "text": "The final void was saved at the 24-hour mark"}]'::jsonb, '["c"]', 'If any void is missed, the entire collection is restarted. Keeping the jug on ice, discarding the first void, and saving the final void are all correct steps.'),
  ('urine_collection', 44, 'A nurse is evaluating a client''s midstream clean-catch collection. Which client action is correct?', '[{"id": "a", "text": "Begins voiding directly into the sterile container"}, {"id": "b", "text": "Catches the middle portion of the stream in the container"}, {"id": "c", "text": "Fills the container with the last portion of the stream"}, {"id": "d", "text": "Collects the urine in the toilet and scoops a sample"}]'::jsonb, '["b"]', 'The client starts voiding into the toilet and then catches the midstream urine in the sterile container. Collecting the first stream defeats the purpose of flushing out contaminants.'),
  ('urine_collection', 45, 'A client asks what to use to clean the urethral meatus before a midstream clean-catch collection. Which item should the nurse provide?', '[{"id": "a", "text": "Dry tissue"}, {"id": "b", "text": "Antiseptic wipes"}, {"id": "c", "text": "A damp washcloth"}, {"id": "d", "text": "Plain tap water"}]'::jsonb, '["b"]', 'The perineum/urethral meatus is cleaned with antiseptic wipes before collection. Dry tissue or plain water does not provide the antiseptic cleansing required.'),
  ('urine_collection', 46, 'A nurse is reviewing urine collection types with a new graduate nurse. Which statement by the new graduate requires correction?', '[{"id": "a", "text": "\"Midstream clean-catch is used for urinalysis and culture.\""}, {"id": "b", "text": "\"Catheterized specimens are taken from the sampling port.\""}, {"id": "c", "text": "\"A 24-hour urine collection includes the first morning void.\""}, {"id": "d", "text": "\"Suprapubic aspiration is used for sterile cultures in infants.\""}]'::jsonb, '["c"]', 'In a 24-hour collection, the first void is discarded and not collected. The other statements are accurate.'),
  ('urine_collection', 47, 'A client asks which container to use when collecting a midstream clean-catch urine specimen. Which container should the nurse provide?', '[{"id": "a", "text": "A clean drinking cup"}, {"id": "b", "text": "A bedpan"}, {"id": "c", "text": "The 24-hour collection jug"}, {"id": "d", "text": "A sterile specimen container"}]'::jsonb, '["d"]', 'The midstream urine is caught in a sterile container held in the stream mid-void. A drinking cup or bedpan is not sterile.'),
  ('urine_collection', 48, 'A nurse is teaching a client the steps of a 24-hour urine collection. Which sequence is correct?', '[{"id": "a", "text": "Discard first void → collect all urine on ice → collect final void at 24 hours → label and send"}, {"id": "b", "text": "Save first void → collect all urine at room temperature → discard final void → label and send"}, {"id": "c", "text": "Discard first void → collect urine as convenient → collect final void at 12 hours → label and send"}, {"id": "d", "text": "Save first void → collect all urine on ice → discard final void → label and send"}]'::jsonb, '["a"]', 'The client discards the first void, collects all urine on ice for 24 hours, collects the final void at the same time as the start, and then labels and sends it. The first void is not saved, and the final void is collected.'),
  ('urine_collection', 49, 'A home health nurse teaches a client how to store a 24-hour urine collection jug. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I will keep the jug in a warm bathroom cabinet.\""}, {"id": "b", "text": "\"I will keep the jug on the counter at room temperature.\""}, {"id": "c", "text": "\"I will keep the jug in the refrigerator during collection.\""}, {"id": "d", "text": "\"I will refrigerate the jug only after the collection ends.\""}]'::jsonb, '["c"]', 'The container is kept on ice or refrigerated throughout the collection to prevent bacterial growth. Refrigerating only at the end leaves urine at room temperature for most of the collection.'),
  ('urine_collection', 50, 'A nurse is teaching a client about a midstream clean-catch urine specimen. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will wash my hands before I start.\""}, {"id": "b", "text": "\"I will catch the very first part of my stream in the cup.\""}, {"id": "c", "text": "\"I will finish voiding into the toilet.\""}, {"id": "d", "text": "\"I will not touch the inside of the lid.\""}]'::jsonb, '["b"]', 'The client begins voiding into the toilet so the first stream flushes out contaminants, then catches the midstream. Catching the first portion contaminates the specimen.'),
  ('catheters', 1, 'A nurse is caring for a client with an indwelling urinary catheter. Which nursing action is the priority for preventing catheter-associated urinary tract infection (CAUTI)?', '[{"id": "a", "text": "Irrigate the catheter every shift"}, {"id": "b", "text": "Remove the catheter as soon as possible"}, {"id": "c", "text": "Disconnect the bag daily for cleaning"}, {"id": "d", "text": "Hang the bag on the bed rail above the bladder"}]'::jsonb, '["b"]', 'Removing the catheter as soon as possible is the number-one CAUTI prevention priority because every catheter day increases infection risk. Irrigation is not done unless specifically ordered.'),
  ('catheters', 2, 'A client has had an indwelling urinary catheter for 3 days. Which daily nursing action best reduces this client''s risk for CAUTI?', '[{"id": "a", "text": "Reassess whether the catheter is still necessary"}, {"id": "b", "text": "Irrigate the catheter routinely to keep it patent"}, {"id": "c", "text": "Disconnect the tubing to inspect for sediment"}, {"id": "d", "text": "Replace the drainage bag with a larger one"}]'::jsonb, '["a"]', 'Catheter necessity should be reassessed daily so the catheter can be removed as soon as possible. Routine irrigation and disconnecting the system are not recommended.'),
  ('catheters', 3, 'A nurse observes a UAP place a client''s urinary drainage bag on the client''s lap while transporting the client in a wheelchair. Which explanation should the nurse give the UAP?', '[{"id": "a", "text": "\"The bag should be emptied before every transport.\""}, {"id": "b", "text": "\"The bag should be disconnected during transport.\""}, {"id": "c", "text": "\"A bag raised above the bladder lets urine flow back in.\""}, {"id": "d", "text": "\"A bag on the lap will make it fill too quickly.\""}]'::jsonb, '["c"]', 'The drainage bag must never be raised above bladder level because urine flows backward into the bladder, causing contamination and infection. The system should also never be disconnected.'),
  ('catheters', 4, 'A client with an indwelling catheter asks why the drainage bag must hang lower than the bed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It keeps urine from flowing back into your bladder.\""}, {"id": "b", "text": "\"It makes the bag easier for staff to empty.\""}, {"id": "c", "text": "\"It keeps the catheter balloon from deflating.\""}, {"id": "d", "text": "\"It helps the bag hold a larger urine volume.\""}]'::jsonb, '["a"]', 'Keeping the drainage bag below bladder level at all times prevents backflow of urine into the bladder. Convenience and bag capacity are not the reason.'),
  ('catheters', 5, 'During rounds, a nurse finds a client''s urinary drainage bag hanging from the IV pole above the level of the bed. Which action should the nurse take first?', '[{"id": "a", "text": "Disconnect the bag and attach a new one"}, {"id": "b", "text": "Irrigate the catheter to flush backflow"}, {"id": "c", "text": "Remove the catheter immediately"}, {"id": "d", "text": "Reposition the bag below bladder level"}]'::jsonb, '["d"]', 'The drainage bag must always be positioned below bladder level to prevent backflow. Disconnecting the system or irrigating without an order is not appropriate.'),
  ('catheters', 6, 'A nurse is supervising a UAP caring for a client with an indwelling catheter. Which action by the UAP requires correction?', '[{"id": "a", "text": "Keeps the drainage bag below bladder level"}, {"id": "b", "text": "Disconnects the tubing to collect a urine sample"}, {"id": "c", "text": "Straightens kinks in the drainage tubing"}, {"id": "d", "text": "Uses a separate container to empty the bag"}]'::jsonb, '["b"]', 'A closed drainage system must be maintained; it is not disconnected for a specimen, which is taken from the sampling port. The other actions support CAUTI prevention.'),
  ('catheters', 7, 'A nurse notices that a client''s catheter drainage tubing is kinked and coiled into a loop under the client''s leg. Which action should the nurse take?', '[{"id": "a", "text": "Clamp the tubing until the client changes position"}, {"id": "b", "text": "Disconnect and reconnect the tubing to reset flow"}, {"id": "c", "text": "Straighten the tubing so it is free of kinks and loops"}, {"id": "d", "text": "Raise the drainage bag to the level of the mattress"}]'::jsonb, '["c"]', 'Drainage tubing should be kept free of kinks and loops as part of CAUTI prevention. Disconnecting the system or raising the bag increases infection risk.'),
  ('catheters', 8, 'A nurse is teaching a UAP how to provide catheter care. Which instruction is correct?', '[{"id": "a", "text": "\"Clean the catheter from the bag toward the meatus.\""}, {"id": "b", "text": "\"Clean the catheter from the meatus outward.\""}, {"id": "c", "text": "\"Clean the catheter only once a week.\""}, {"id": "d", "text": "\"Clean only the drainage bag, not the catheter.\""}]'::jsonb, '["b"]', 'Pericare is performed daily and after bowel movements, cleaning the catheter from the meatus outward. Cleaning toward the meatus is the reverse direction.'),
  ('catheters', 9, 'A client with an indwelling urinary catheter has just had a bowel movement. Which action should the nurse take?', '[{"id": "a", "text": "Perform pericare now"}, {"id": "b", "text": "Wait until the scheduled daily pericare"}, {"id": "c", "text": "Remove and reinsert the catheter"}, {"id": "d", "text": "Irrigate the catheter with saline"}]'::jsonb, '["a"]', 'Pericare is performed daily and after bowel movements. Waiting for the routine daily care leaves the area soiled, and irrigation is not done unless ordered.'),
  ('catheters', 10, 'A newly hired nurse plans to irrigate a client''s indwelling catheter every shift to keep it patent. There is no prescription for irrigation. Which response by the charge nurse is appropriate?', '[{"id": "a", "text": "\"Irrigate it every 4 hours instead of every shift.\""}, {"id": "b", "text": "\"Irrigate it only when the bag is more than half full.\""}, {"id": "c", "text": "\"Irrigate it once daily during pericare.\""}, {"id": "d", "text": "\"Do not irrigate it unless it is specifically ordered.\""}]'::jsonb, '["d"]', 'Catheters are not irrigated unless specifically ordered, as part of CAUTI prevention. Routine irrigation on any schedule is not recommended.'),
  ('catheters', 11, 'A UAP asks when a client''s urinary drainage bag should be emptied. Which response by the nurse is correct?', '[{"id": "a", "text": "\"When it is one-quarter full.\""}, {"id": "b", "text": "\"Only once at the end of each day.\""}, {"id": "c", "text": "\"When it is one-half to three-quarters full.\""}, {"id": "d", "text": "\"Only when it is completely full.\""}]'::jsonb, '["c"]', 'The drainage bag is emptied when it is one-half to three-quarters full. Waiting until it is completely full is not recommended.'),
  ('catheters', 12, 'A nurse observes a UAP emptying the urinary drainage bags of two clients. Which action by the UAP requires correction?', '[{"id": "a", "text": "Uses the same container to empty both clients'' bags"}, {"id": "b", "text": "Empties each bag when it is one-half to three-quarters full"}, {"id": "c", "text": "Keeps each bag below bladder level after emptying"}, {"id": "d", "text": "Keeps each drainage system closed while emptying"}]'::jsonb, '["a"]', 'A separate container must be used for each patient when emptying drainage bags. The other actions follow CAUTI prevention guidance.'),
  ('catheters', 13, 'A nurse is preparing to insert an indwelling urinary catheter. Which technique should the nurse use to reduce the client''s CAUTI risk?', '[{"id": "a", "text": "Clean technique with nonsterile gloves"}, {"id": "b", "text": "Aseptic technique with a sterile field"}, {"id": "c", "text": "Clean technique without a sterile field"}, {"id": "d", "text": "Aseptic technique only if the client has a fever"}]'::jsonb, '["b"]', 'Aseptic technique is used during insertion, including opening the sterile kit and setting up a sterile field. Clean technique does not meet this standard.'),
  ('catheters', 14, 'A nurse is reviewing urinary catheter types. Which type carries the highest risk for CAUTI?', '[{"id": "a", "text": "Condom (Texas) catheter"}, {"id": "b", "text": "Intermittent (straight) catheter"}, {"id": "c", "text": "Suprapubic catheter"}, {"id": "d", "text": "Foley (indwelling) catheter"}]'::jsonb, '["d"]', 'The Foley (indwelling) catheter remains in the bladder and carries the highest CAUTI risk. The condom catheter has the lowest risk because it is not inserted.'),
  ('catheters', 15, 'An incontinent male client needs urinary drainage. Which catheter type carries the lowest infection risk for this client?', '[{"id": "a", "text": "Condom (Texas) catheter"}, {"id": "b", "text": "Foley (indwelling) catheter"}, {"id": "c", "text": "Three-way catheter"}, {"id": "d", "text": "Coudé catheter"}]'::jsonb, '["a"]', 'The condom (Texas) catheter is an external catheter for incontinent men that is not inserted into the urethra and has the lowest risk. The Foley catheter carries the highest CAUTI risk.'),
  ('catheters', 16, 'A client is using a condom (Texas) catheter. Which assessment should the nurse perform daily?', '[{"id": "a", "text": "Check balloon inflation volume"}, {"id": "b", "text": "Check the skin"}, {"id": "c", "text": "Check irrigation inflow rate"}, {"id": "d", "text": "Check the sampling port"}]'::jsonb, '["b"]', 'The skin should be checked daily for a client with a condom catheter. It is external and has no balloon or irrigation lumen.'),
  ('catheters', 17, 'A nurse is caring for a male client with urinary retention and a male client with incontinence. Which client is the most appropriate candidate for a condom (Texas) catheter?', '[{"id": "a", "text": "The client who needs bladder drainage for retention"}, {"id": "b", "text": "The client who needs continuous bladder irrigation"}, {"id": "c", "text": "The client who has incontinence"}, {"id": "d", "text": "The client who has a urethral stricture"}]'::jsonb, '["c"]', 'The condom catheter is an external catheter for incontinent men. Retention is managed with an intermittent catheter, and a urethral stricture calls for a coudé catheter.'),
  ('catheters', 18, 'A client with a neurogenic bladder needs regular bladder emptying. Which catheter type with lower CAUTI risk should the nurse anticipate?', '[{"id": "a", "text": "Three-way catheter"}, {"id": "b", "text": "Foley (indwelling) catheter"}, {"id": "c", "text": "Suprapubic catheter"}, {"id": "d", "text": "Intermittent (straight) catheter"}]'::jsonb, '["d"]', 'An intermittent (straight) catheter is inserted, drains, and is removed; it is used for retention and neurogenic bladder and has lower CAUTI risk. The Foley carries the highest CAUTI risk.'),
  ('catheters', 19, 'A client asks how an intermittent (straight) catheter differs from a Foley catheter. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is inserted, drains the bladder, and is then removed.\""}, {"id": "b", "text": "\"It stays in the bladder held by an inflated balloon.\""}, {"id": "c", "text": "\"It is placed through the abdominal wall into the bladder.\""}, {"id": "d", "text": "\"It is worn externally and never enters the urethra.\""}]'::jsonb, '["a"]', 'An intermittent catheter is inserted, drains the bladder, and is removed. A Foley stays in the bladder held by an inflated balloon.'),
  ('catheters', 20, 'A client''s urethra cannot be accessed for catheterization. Which catheter type should the nurse anticipate?', '[{"id": "a", "text": "Condom (Texas) catheter"}, {"id": "b", "text": "Suprapubic catheter"}, {"id": "c", "text": "Intermittent (straight) catheter"}, {"id": "d", "text": "Three-way catheter"}]'::jsonb, '["b"]', 'A suprapubic catheter is surgically inserted through the abdominal wall into the bladder when urethral access is not possible. Straight and three-way catheters require urethral insertion.'),
  ('catheters', 21, 'A nurse is unable to pass a straight catheter in a male client with benign prostatic hyperplasia (BPH). Which catheter should the nurse obtain?', '[{"id": "a", "text": "Condom (Texas) catheter"}, {"id": "b", "text": "Intermittent catheter of the same style"}, {"id": "c", "text": "Coudé catheter"}, {"id": "d", "text": "Suprapubic catheter kit for bedside use"}]'::jsonb, '["c"]', 'A coudé catheter has a curved tip and is used for BPH or urethral stricture when a straight catheter cannot pass. A suprapubic catheter is surgically inserted, not placed at the bedside by the nurse.'),
  ('catheters', 22, 'A client with a urethral stricture requires catheterization. Which catheter feature does the nurse expect to be most helpful?', '[{"id": "a", "text": "A curved tip"}, {"id": "b", "text": "Three lumens"}, {"id": "c", "text": "An external sheath"}, {"id": "d", "text": "A wider balloon"}]'::jsonb, '["a"]', 'The coudé catheter has a curved tip for BPH or urethral stricture where a straight catheter cannot pass. Three lumens describe the CBI catheter.'),
  ('catheters', 23, 'A client returns from a transurethral resection of the prostate (TURP) with continuous bladder irrigation (CBI). Which catheter type does the nurse expect to be in place?', '[{"id": "a", "text": "Coudé catheter"}, {"id": "b", "text": "Condom (Texas) catheter"}, {"id": "c", "text": "Intermittent catheter"}, {"id": "d", "text": "Three-way catheter"}]'::jsonb, '["d"]', 'CBI uses a 3-way Foley catheter with lumens for irrigation in, urine out, and the balloon. It is used after prostate surgery.'),
  ('catheters', 24, 'A nursing student is identifying the lumens of a three-way catheter used for continuous bladder irrigation. Which set of lumens is correct?', '[{"id": "a", "text": "Irrigation in, urine out, balloon port"}, {"id": "b", "text": "Irrigation in, sampling port, suction port"}, {"id": "c", "text": "Urine out, medication port, vent port"}, {"id": "d", "text": "Irrigation in, urine out, suction port"}]'::jsonb, '["a"]', 'The three-way catheter has three lumens: irrigation in, urine plus irrigation out, and the balloon port. It has no suction or medication lumen.'),
  ('catheters', 25, 'A client who had a transurethral resection of the prostate (TURP) asks why continuous bladder irrigation is running. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It delivers antibiotics directly into your bladder.\""}, {"id": "b", "text": "\"It prevents blood clots from blocking the catheter.\""}, {"id": "c", "text": "\"It measures how much urine your kidneys make.\""}, {"id": "d", "text": "\"It keeps the catheter balloon inflated.\""}]'::jsonb, '["b"]', 'CBI is used after TURP to prevent blood clots from obstructing the catheter lumen. True urine output must be calculated separately because irrigant is included in the drainage.'),
  ('catheters', 26, 'A client receiving continuous bladder irrigation (CBI) had 2,400 mL of irrigation solution instilled during the shift. The total drainage emptied from the bag was 3,200 mL. What is the client''s true urine output?', '[{"id": "a", "text": "5,600 mL"}, {"id": "b", "text": "3,200 mL"}, {"id": "c", "text": "2,400 mL"}, {"id": "d", "text": "800 mL"}]'::jsonb, '["d"]', 'True urine output equals total drainage minus total irrigation instilled: 3,200 mL − 2,400 mL = 800 mL. Adding the two volumes (5,600 mL) is incorrect.'),
  ('catheters', 27, 'Over 8 hours, a client with continuous bladder irrigation (CBI) received 1,800 mL of irrigant, and the drainage bag collected a total of 2,250 mL. Which amount should the nurse record as the client''s true urine output?', '[{"id": "a", "text": "4,050 mL"}, {"id": "b", "text": "450 mL"}, {"id": "c", "text": "1,800 mL"}, {"id": "d", "text": "2,250 mL"}]'::jsonb, '["b"]', 'True urine output = total drainage − irrigation instilled: 2,250 mL − 1,800 mL = 450 mL. Recording the full 2,250 mL counts the irrigant as urine.'),
  ('catheters', 28, 'A nurse is reviewing intake and output for a client with continuous bladder irrigation (CBI). Which statement by a new nurse requires correction?', '[{"id": "a", "text": "\"I subtract the irrigant instilled from the total drainage.\""}, {"id": "b", "text": "\"I track how much irrigant goes in during the shift.\""}, {"id": "c", "text": "\"I add the irrigant instilled to the drainage to get urine output.\""}, {"id": "d", "text": "\"I measure the total drainage emptied from the bag.\""}]'::jsonb, '["c"]', 'True urine output is total drainage minus irrigation input, so adding the irrigant to the drainage is incorrect. Tracking both volumes and subtracting is correct.'),
  ('catheters', 29, 'A client receiving continuous bladder irrigation after a TURP has bright red urine with large clots in the drainage. Which action should the nurse take?', '[{"id": "a", "text": "Decrease the CBI rate"}, {"id": "b", "text": "Stop the CBI"}, {"id": "c", "text": "Clamp the outflow tubing"}, {"id": "d", "text": "Increase the CBI rate"}]'::jsonb, '["d"]', 'Bright red urine or large clots call for increasing the CBI rate to flush out clots and notifying the provider if there is no improvement. Decreasing the rate is appropriate only for light pink urine.'),
  ('catheters', 30, 'A nurse increased the continuous bladder irrigation rate for a post-TURP client whose drainage was bright red with clots. One hour later, the drainage remains bright red. Which action should the nurse take next?', '[{"id": "a", "text": "Notify the provider"}, {"id": "b", "text": "Decrease the CBI rate"}, {"id": "c", "text": "Document the expected finding"}, {"id": "d", "text": "Stop the irrigation"}]'::jsonb, '["a"]', 'If bright red drainage does not improve after the CBI rate is increased, the provider is notified because bright red urine indicates active bleeding. Bright red drainage is not an expected finding.'),
  ('catheters', 31, 'A client is 1 day post-TURP with continuous bladder irrigation. The drainage is light pink without clots. Which action is appropriate?', '[{"id": "a", "text": "Increase the CBI rate"}, {"id": "b", "text": "Notify the provider at once"}, {"id": "c", "text": "Decrease the CBI rate"}, {"id": "d", "text": "Irrigate manually with a syringe"}]'::jsonb, '["c"]', 'Light pink urine is normal after TURP and the CBI rate can be decreased. Increasing the rate is the action for bright red urine or large clots.'),
  ('catheters', 32, 'A nurse is assessing four clients who had a TURP and are receiving continuous bladder irrigation. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Light pink urine in the drainage bag"}, {"id": "b", "text": "Bright red urine in the drainage bag"}, {"id": "c", "text": "Bladder spasms reported by the client"}, {"id": "d", "text": "Irrigant flowing continuously in and out"}]'::jsonb, '["b"]', 'Bright red urine after TURP is not normal; it indicates active bleeding and requires an increased CBI rate plus provider notification. Light pink urine and bladder spasms are normal after TURP.'),
  ('catheters', 33, 'A nurse is evaluating a post-TURP client''s continuous bladder irrigation. Which drainage color indicates an expected outcome?', '[{"id": "a", "text": "Bright red"}, {"id": "b", "text": "Dark red with clots"}, {"id": "c", "text": "Bright red with large clots"}, {"id": "d", "text": "Light pink"}]'::jsonb, '["d"]', 'Light pink urine is normal after TURP. Bright red urine or large clots are abnormal and require an increased CBI rate.'),
  ('catheters', 34, 'A client receiving continuous bladder irrigation suddenly has no output in the drainage bag. Which action should the nurse take first?', '[{"id": "a", "text": "Check the tubing for kinks"}, {"id": "b", "text": "Increase the irrigation rate"}, {"id": "c", "text": "Notify the provider"}, {"id": "d", "text": "Remove the catheter"}]'::jsonb, '["a"]', 'With no output or possible obstruction, the nurse first checks the tubing for kinks, then manually irrigates per order, and notifies the provider if unresolved. Notifying the provider comes after these steps.'),
  ('catheters', 35, 'A client receiving continuous bladder irrigation has no drainage output. The nurse has confirmed the tubing is not kinked. Which action should the nurse take next?', '[{"id": "a", "text": "Increase the irrigation inflow rate"}, {"id": "b", "text": "Raise the drainage bag above the bladder"}, {"id": "c", "text": "Remove and reinsert the catheter"}, {"id": "d", "text": "Manually irrigate with a syringe per order"}]'::jsonb, '["d"]', 'After checking for kinks, the next step for no output is manual irrigation with a syringe per order, followed by provider notification if unresolved. Raising the bag above the bladder causes backflow.'),
  ('catheters', 36, 'A client receiving continuous bladder irrigation has no output and a possible obstruction. In which order should the nurse take these actions?', '[{"id": "a", "text": "Notify provider → check tubing for kinks → manually irrigate per order"}, {"id": "b", "text": "Manually irrigate per order → notify provider → check tubing for kinks"}, {"id": "c", "text": "Check tubing for kinks → manually irrigate per order → notify provider if unresolved"}, {"id": "d", "text": "Check tubing for kinks → notify provider → manually irrigate without an order"}]'::jsonb, '["c"]', 'For no output, the nurse checks the tubing for kinks, manually irrigates with a syringe per order, and notifies the provider if the problem is unresolved. Irrigation is done only per order.'),
  ('catheters', 37, 'A client who had a TURP and is receiving continuous bladder irrigation reports painful bladder spasms. Which statement by the nurse is accurate?', '[{"id": "a", "text": "\"Spasms mean the catheter must be removed.\""}, {"id": "b", "text": "\"Spasms are normal, and medication may be ordered.\""}, {"id": "c", "text": "\"Spasms mean the irrigation must be stopped.\""}, {"id": "d", "text": "\"Spasms mean the bladder is actively bleeding.\""}]'::jsonb, '["b"]', 'Bladder spasms are normal after TURP, and antispasmodics such as oxybutynin or belladonna and opium suppositories may be ordered. Bright red urine, not spasms, signals active bleeding.'),
  ('catheters', 38, 'A nurse is teaching a client after a TURP about continuous bladder irrigation. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Light pink urine is normal after my surgery.\""}, {"id": "b", "text": "\"The irrigation helps keep clots from blocking my catheter.\""}, {"id": "c", "text": "\"Bladder spasms mean my surgery has failed.\""}, {"id": "d", "text": "\"I should report bright red urine to the nurse.\""}]'::jsonb, '["c"]', 'Bladder spasms are a normal finding after TURP and may be treated with antispasmodics. The other statements reflect correct understanding.'),
  ('catheters', 39, 'A nurse is ranking urinary catheter types from highest to lowest CAUTI risk. Which order is correct?', '[{"id": "a", "text": "Condom → intermittent → Foley"}, {"id": "b", "text": "Intermittent → Foley → condom"}, {"id": "c", "text": "Foley → condom → intermittent"}, {"id": "d", "text": "Foley → intermittent → condom"}]'::jsonb, '["d"]', 'The Foley catheter has the highest CAUTI risk, the intermittent catheter has lower risk, and the external condom catheter has the lowest risk. Option A reverses the order.'),
  ('catheters', 40, 'A nurse is setting up continuous bladder irrigation for a client after a TURP. Which irrigant should the nurse anticipate?', '[{"id": "a", "text": "Normal saline"}, {"id": "b", "text": "Sterile water"}, {"id": "c", "text": "Dextrose 5% in water"}, {"id": "d", "text": "Hypotonic saline"}]'::jsonb, '["a"]', 'The irrigant for CBI is normal saline, which is non-hypotonic. Hypotonic solutions are not the CBI irrigant.'),
  ('catheters', 41, 'A nurse is setting up continuous bladder irrigation. Which describes the correct setup?', '[{"id": "a", "text": "Irrigant bags hang on an IV pole with continuous flow"}, {"id": "b", "text": "Irrigant bags lie on the bed with intermittent flow"}, {"id": "c", "text": "Irrigant is given by syringe every 4 hours routinely"}, {"id": "d", "text": "Irrigant bags hang below the bladder with no outflow"}]'::jsonb, '["a"]', 'CBI bags are hung on an IV pole with continuous flow in and out. Manual syringe irrigation is used only per order for no output or obstruction.'),
  ('catheters', 42, 'A nurse is preparing to insert an indwelling urinary catheter in a female client. In which position should the nurse place the client?', '[{"id": "a", "text": "Prone"}, {"id": "b", "text": "Dorsal recumbent"}, {"id": "c", "text": "High Fowler''s"}, {"id": "d", "text": "Left side-lying"}]'::jsonb, '["b"]', 'Women are positioned dorsal recumbent for catheter insertion, while men are positioned supine.'),
  ('catheters', 43, 'A nurse is preparing to insert an indwelling urinary catheter in a male client. In which position should the nurse place the client?', '[{"id": "a", "text": "Prone"}, {"id": "b", "text": "Left side-lying"}, {"id": "c", "text": "Supine"}, {"id": "d", "text": "High Fowler''s"}]'::jsonb, '["c"]', 'Men are positioned supine for catheter insertion; women are positioned dorsal recumbent.'),
  ('catheters', 44, 'A nurse is cleansing the urethral meatus before inserting a catheter in a female client. Which technique is correct?', '[{"id": "a", "text": "Separate the labia and clean from back to front"}, {"id": "b", "text": "Clean in a circular motion without separating the labia"}, {"id": "c", "text": "Clean the outer thighs only, avoiding the labia"}, {"id": "d", "text": "Separate the labia and clean from front to back"}]'::jsonb, '["d"]', 'For women, the nurse separates the labia and cleans from front to back. A circular motion with foreskin retraction is the technique for men.'),
  ('catheters', 45, 'A nurse is inserting an indwelling urinary catheter. At which point should the nurse inflate the balloon?', '[{"id": "a", "text": "Only after urine returns through the catheter"}, {"id": "b", "text": "As soon as the catheter tip enters the meatus"}, {"id": "c", "text": "Before lubricating the catheter tip"}, {"id": "d", "text": "Halfway through insertion to anchor the catheter"}]'::jsonb, '["a"]', 'The balloon is inflated only after urine returns. Inflating earlier risks the balloon being in the urethra rather than the bladder.'),
  ('catheters', 46, 'A charge nurse observes a new nurse begin to inflate a catheter balloon before any urine has returned. The charge nurse intervenes because of the risk for which complication?', '[{"id": "a", "text": "Backflow of urine into the bladder"}, {"id": "b", "text": "Urethral trauma"}, {"id": "c", "text": "Bladder spasms"}, {"id": "d", "text": "Clot obstruction of the lumen"}]'::jsonb, '["b"]', 'Inflating the balloon before urine returns may place it in the urethra rather than the bladder, causing urethral trauma. Backflow results from raising the bag above the bladder.'),
  ('catheters', 47, 'A nurse is inflating the balloon of an indwelling catheter after urine returns. Which fluid should the nurse use?', '[{"id": "a", "text": "Normal saline"}, {"id": "b", "text": "Lubricant gel"}, {"id": "c", "text": "Sterile water"}, {"id": "d", "text": "Air"}]'::jsonb, '["c"]', 'The balloon is inflated with sterile water per the label size, such as 10 mL. Normal saline is the CBI irrigant, not the balloon fluid.'),
  ('catheters', 48, 'A nurse has inserted an indwelling catheter and connected it to a closed drainage bag. Where should the nurse secure the tubing?', '[{"id": "a", "text": "To the bed rail"}, {"id": "b", "text": "To the lower abdomen above the bladder"}, {"id": "c", "text": "To the inner thigh"}, {"id": "d", "text": "To the client''s gown"}]'::jsonb, '["c"]', 'After connecting the catheter to a closed drainage bag, the tubing is secured to the inner thigh, and the bag is positioned below bladder level.'),
  ('catheters', 49, 'A nurse is inserting an indwelling urinary catheter. Which sequence of steps is correct?', '[{"id": "a", "text": "Inflate balloon → insert until urine flows → clean meatus → connect bag"}, {"id": "b", "text": "Clean meatus → inflate balloon → insert until urine flows → connect bag"}, {"id": "c", "text": "Clean meatus → connect bag → insert catheter → inflate balloon before urine flows"}, {"id": "d", "text": "Clean meatus → insert until urine flows → inflate balloon → connect bag"}]'::jsonb, '["d"]', 'The nurse cleans the meatus, lubricates and inserts the catheter until urine flows, inflates the balloon only after urine returns, then connects the closed drainage bag. Inflating before urine returns risks urethral trauma.'),
  ('catheters', 50, 'A nurse is about to insert a urinary catheter in a client. Which action should the nurse perform first?', '[{"id": "a", "text": "Gather supplies, perform hand hygiene, and explain the procedure"}, {"id": "b", "text": "Open the sterile kit and set up the sterile field"}, {"id": "c", "text": "Lubricate the catheter tip and begin insertion"}, {"id": "d", "text": "Cleanse the urethral meatus with the kit swabs"}]'::jsonb, '["a"]', 'Insertion begins with gathering supplies, performing hand hygiene, and explaining the procedure, followed by positioning and setting up the sterile field. Cleansing and insertion come later.'),
  ('incontinence', 1, 'A 52-year-old woman who has had three vaginal births reports that she leaks small amounts of urine whenever she coughs, sneezes, or laughs. The nurse recognizes this pattern as which type of incontinence?', '[{"id": "a", "text": "Urge incontinence"}, {"id": "b", "text": "Stress incontinence"}, {"id": "c", "text": "Overflow incontinence"}, {"id": "d", "text": "Functional incontinence"}]'::jsonb, '["b"]', 'Leakage with increased intra-abdominal pressure such as coughing, sneezing, or laughing is stress incontinence, often from pelvic floor weakness after childbirth. Urge incontinence is a sudden intense urge followed by leakage rather than leakage triggered by pressure.'),
  ('incontinence', 2, 'A client who walks independently 3 months after a stroke reports a sudden, intense need to void followed by leakage before reaching the toilet. Which type of incontinence does the nurse suspect?', '[{"id": "a", "text": "Functional incontinence"}, {"id": "b", "text": "Reflex incontinence"}, {"id": "c", "text": "Urge incontinence"}, {"id": "d", "text": "Stress incontinence"}]'::jsonb, '["c"]', 'A sudden intense urge followed by involuntary loss ("can''t make it in time") is urge incontinence, and stroke causes detrusor overactivity. Functional incontinence involves normal bladder function with mobility or cognitive barriers, which this independently ambulating client does not have.'),
  ('incontinence', 3, 'A 70-year-old man with benign prostatic hyperplasia (BPH) reports constant dribbling of urine and a feeling that his bladder never empties completely. The nurse documents these findings as consistent with which type of incontinence?', '[{"id": "a", "text": "Overflow incontinence"}, {"id": "b", "text": "Urge incontinence"}, {"id": "c", "text": "Stress incontinence"}, {"id": "d", "text": "Mixed incontinence"}]'::jsonb, '["a"]', 'Overflow incontinence occurs when the bladder does not fully empty, producing constant dribbling and a feeling of incomplete voiding; BPH is a listed cause. Urge incontinence presents as a sudden intense urge with leakage, not continuous dribbling.'),
  ('incontinence', 4, 'A long-term care resident with advanced dementia has normal bladder function but is frequently incontinent because she cannot find the bathroom in time. Which type of incontinence is this?', '[{"id": "a", "text": "Reflex incontinence"}, {"id": "b", "text": "Overflow incontinence"}, {"id": "c", "text": "Urge incontinence"}, {"id": "d", "text": "Functional incontinence"}]'::jsonb, '["d"]', 'Functional incontinence means the bladder works normally but the client cannot reach the toilet in time, and dementia is a listed cause. Overflow incontinence involves a bladder that does not fully empty, which is not the problem here.'),
  ('incontinence', 5, 'A client with a spinal cord injury states, "My urine just comes out. I never feel any need to go beforehand." The nurse identifies this as which type of incontinence?', '[{"id": "a", "text": "Urge incontinence"}, {"id": "b", "text": "Reflex incontinence"}, {"id": "c", "text": "Functional incontinence"}, {"id": "d", "text": "Stress incontinence"}]'::jsonb, '["b"]', 'Reflex incontinence is involuntary urination with no warning or urge and is caused by neurologic dysfunction such as spinal cord injury. Urge incontinence, by contrast, is preceded by a sudden intense urge.'),
  ('incontinence', 6, 'A client reports leaking urine when sneezing and also having sudden strong urges with leakage before reaching the toilet. Which plan of care best addresses this client''s incontinence?', '[{"id": "a", "text": "Pelvic floor therapy plus bladder training"}, {"id": "b", "text": "Indwelling catheter plus fluid restriction"}, {"id": "c", "text": "Bedside commode plus scheduled toileting"}, {"id": "d", "text": "Intermittent catheterization plus alpha-blocker"}]'::jsonb, '["a"]', 'Leakage with sneezing plus urge leakage is mixed incontinence (stress + urge), which is treated by addressing both causes with pelvic floor therapy and bladder training. Intermittent catheterization and alpha-blockers are interventions for overflow incontinence.'),
  ('incontinence', 7, 'A postmenopausal client who leaks urine while jogging asks what is causing the problem. The nurse''s response should be based on which underlying cause?', '[{"id": "a", "text": "Overactivity of the detrusor muscle"}, {"id": "b", "text": "Weakness of the pelvic floor muscles"}, {"id": "c", "text": "An enlarged prostate blocking outflow"}, {"id": "d", "text": "Inability to reach the toilet in time"}]'::jsonb, '["b"]', 'Leakage with exercise is stress incontinence, which is caused by weak pelvic floor muscles related to childbirth, aging, or menopause. Detrusor overactivity is the cause of urge incontinence.'),
  ('incontinence', 8, 'A client with multiple sclerosis has been diagnosed with urge incontinence (overactive bladder). The nurse understands that the underlying mechanism of this type of incontinence is', '[{"id": "a", "text": "weak pelvic floor muscles."}, {"id": "b", "text": "incomplete bladder emptying."}, {"id": "c", "text": "impaired mobility or cognition."}, {"id": "d", "text": "detrusor muscle overactivity."}]'::jsonb, '["d"]', 'Urge incontinence is caused by detrusor overactivity, which can follow stroke, MS, or Parkinson''s disease. Weak pelvic floor muscles cause stress incontinence, not urge incontinence.'),
  ('incontinence', 9, 'The nurse is teaching Kegel exercises to a client with stress incontinence. Which instruction should the nurse include?', '[{"id": "a", "text": "\"Limit your fluids so the exercises work faster.\""}, {"id": "b", "text": "\"Expect the leaking to stop within a day or two.\""}, {"id": "c", "text": "\"Contract your pelvic floor muscles three times a day.\""}, {"id": "d", "text": "\"Do the exercises only when you feel an urge to void.\""}]'::jsonb, '["c"]', 'Kegel exercises involve contracting the pelvic floor muscles three times a day, and results take weeks. Restricting fluids is not recommended because it worsens incontinence and infection risk.'),
  ('incontinence', 10, 'A client with stress incontinence began Kegel exercises 1 week ago. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I am doing my pelvic floor exercises three times a day.\""}, {"id": "b", "text": "\"I have cut back on coffee and alcohol to help with leaking.\""}, {"id": "c", "text": "\"I know a pessary is another option if I need more support.\""}, {"id": "d", "text": "\"I''m still leaking, so the exercises must not work for me.\""}]'::jsonb, '["d"]', 'Kegel exercises take weeks to show an effect, so stopping after 1 week reflects a misunderstanding. Doing the exercises three times daily, avoiding caffeine and alcohol, and knowing about a pessary are all correct stress incontinence measures.'),
  ('incontinence', 11, 'In addition to Kegel exercises, which treatment would the nurse anticipate for a client with stress incontinence?', '[{"id": "a", "text": "A pessary"}, {"id": "b", "text": "Tamsulosin"}, {"id": "c", "text": "Self-catheterization"}, {"id": "d", "text": "A bedside commode"}]'::jsonb, '["a"]', 'Stress incontinence is treated with Kegel exercises, a pessary, and avoiding caffeine/alcohol. Tamsulosin and intermittent catheterization are overflow interventions, and a bedside commode is used for functional incontinence.'),
  ('incontinence', 12, 'A client with stress incontinence has performed Kegel exercises and used a pessary for many months without improvement. The nurse anticipates the provider will discuss which option next?', '[{"id": "a", "text": "Starting oxybutynin therapy"}, {"id": "b", "text": "Placing an indwelling catheter"}, {"id": "c", "text": "Surgical bladder sling placement"}, {"id": "d", "text": "Restricting fluids to reduce leaking"}]'::jsonb, '["c"]', 'A bladder sling is the surgical option for stress incontinence when conservative measures fail. Oxybutynin is used for urge incontinence, not stress incontinence.'),
  ('incontinence', 13, 'The nurse is teaching bladder training to a client with urge incontinence. Which instruction is correct?', '[{"id": "a", "text": "\"Void only when you feel a very strong urge.\""}, {"id": "b", "text": "\"Shorten the time between voids each week.\""}, {"id": "c", "text": "\"Void on a schedule and gradually lengthen the intervals.\""}, {"id": "d", "text": "\"Catheterize yourself whenever you feel an urge.\""}]'::jsonb, '["c"]', 'Bladder training uses scheduled voiding with intervals gradually increased. Shortening the intervals is the reverse of the technique.'),
  ('incontinence', 14, 'A client with urge incontinence has been taught bladder training. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will make the time between my voids shorter each week.\""}, {"id": "b", "text": "\"I will use the bathroom at set times during the day.\""}, {"id": "c", "text": "\"I will try to avoid caffeine, alcohol, and spicy foods.\""}, {"id": "d", "text": "\"I will keep drinking about 2 to 3 liters of fluid daily.\""}]'::jsonb, '["a"]', 'Bladder training gradually increases, not shortens, the interval between scheduled voids. Scheduled voiding, avoiding irritants, and drinking 2–3 L/day are all correct.'),
  ('incontinence', 15, 'A client is started on oxybutynin for urge incontinence. Which side effect should the nurse teach the client to expect?', '[{"id": "a", "text": "Diarrhea"}, {"id": "b", "text": "Increased saliva"}, {"id": "c", "text": "Frequent urination"}, {"id": "d", "text": "Dry mouth"}]'::jsonb, '["d"]', 'Oxybutynin is an anticholinergic, and dry mouth, constipation, and urinary retention are its side effects. Diarrhea and increased saliva are the opposite of the expected anticholinergic effects.'),
  ('incontinence', 16, 'The nurse is reviewing the medication plan for a client with an overactive bladder. The nurse identifies oxybutynin (Ditropan) as belonging to which drug class?', '[{"id": "a", "text": "Anticholinergic"}, {"id": "b", "text": "Alpha-blocker"}, {"id": "c", "text": "Diuretic"}, {"id": "d", "text": "Beta-blocker"}]'::jsonb, '["a"]', 'Oxybutynin and tolterodine are anticholinergics used for urge incontinence. Alpha-blockers such as tamsulosin are used for overflow incontinence from BPH.'),
  ('incontinence', 17, 'A client taking tolterodine for urge incontinence reports difficulty emptying the bladder and a feeling of fullness after voiding. The nurse recognizes these findings most likely indicate', '[{"id": "a", "text": "worsening detrusor overactivity."}, {"id": "b", "text": "a weakened pelvic floor."}, {"id": "c", "text": "urinary retention from the drug."}, {"id": "d", "text": "progression to stress incontinence."}]'::jsonb, '["c"]', 'Tolterodine is an anticholinergic, and urinary retention is a listed side effect. Detrusor overactivity is what the drug treats, so retention does not indicate it is worsening.'),
  ('incontinence', 18, 'A client with overflow incontinence from BPH is started on tamsulosin. Which instruction is most important for the nurse to include?', '[{"id": "a", "text": "\"Expect a very dry mouth.\""}, {"id": "b", "text": "\"Rise slowly when standing up.\""}, {"id": "c", "text": "\"Limit fluids in the evening.\""}, {"id": "d", "text": "\"Expect loose stools at first.\""}]'::jsonb, '["b"]', 'Tamsulosin is an alpha-blocker that carries a risk of orthostatic hypotension, so the client should change position slowly. Dry mouth is a side effect of anticholinergics such as oxybutynin, not tamsulosin.'),
  ('incontinence', 19, 'A client with BPH asks how tamsulosin will help his overflow incontinence. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"It relaxes the prostate and bladder neck.\""}, {"id": "b", "text": "\"It strengthens the pelvic floor muscles.\""}, {"id": "c", "text": "\"It calms an overactive detrusor muscle.\""}, {"id": "d", "text": "\"It increases the amount of urine produced.\""}]'::jsonb, '["a"]', 'Tamsulosin is an alpha-blocker that relaxes the prostate and bladder neck in overflow incontinence from BPH. Calming detrusor overactivity describes anticholinergics used for urge incontinence.'),
  ('incontinence', 20, 'A client reports constant dribbling and a sense of incomplete bladder emptying. To assess for urinary retention, which action should the nurse take?', '[{"id": "a", "text": "Send a urine specimen for urinalysis"}, {"id": "b", "text": "Assess the client''s cognition"}, {"id": "c", "text": "Review the client''s mobility"}, {"id": "d", "text": "Bladder scan for post-void residual"}]'::jsonb, '["d"]', 'A bladder scan measures post-void residual (PVR) to assess retention. Urinalysis is used to rule out UTI as a cause, not to measure retention.'),
  ('incontinence', 21, 'A client with chronic urinary retention and overflow incontinence is preparing for discharge. Which bladder management approach does the nurse expect to teach?', '[{"id": "a", "text": "Indwelling catheter care"}, {"id": "b", "text": "Kegel exercise routine"}, {"id": "c", "text": "Intermittent self-catheterization"}, {"id": "d", "text": "Bedside commode use"}]'::jsonb, '["c"]', 'Intermittent catheterization is preferred over an indwelling catheter for chronic retention, and the client is taught self-catheterization. Kegel exercises treat stress incontinence, not overflow.'),
  ('incontinence', 22, 'Which interventions should the nurse include in the plan of care for a client with functional incontinence related to limited mobility?', '[{"id": "a", "text": "Scheduled toileting and a bedside commode"}, {"id": "b", "text": "Oxybutynin and bladder training"}, {"id": "c", "text": "Kegel exercises and a pessary"}, {"id": "d", "text": "Tamsulosin and self-catheterization"}]'::jsonb, '["a"]', 'Functional incontinence is managed with scheduled toileting, a bedside commode, and a safe environment. Oxybutynin and bladder training are interventions for urge incontinence.'),
  ('incontinence', 23, 'An older adult with poor vision has functional incontinence. Which home modification should the nurse recommend?', '[{"id": "a", "text": "Restrict fluids after the evening meal"}, {"id": "b", "text": "Add lighting and grab bars near the toilet"}, {"id": "c", "text": "Keep the bathroom door closed and dark"}, {"id": "d", "text": "Replace the toilet trips with an indwelling catheter"}]'::jsonb, '["b"]', 'For functional incontinence, safety measures include lighting, grab bars, and a commode. Restricting fluids is discouraged because it worsens incontinence and infection risk.'),
  ('incontinence', 24, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a resident with functional incontinence. Which UAP action requires correction?', '[{"id": "a", "text": "Offering toileting at the scheduled times"}, {"id": "b", "text": "Placing the commode next to the bed"}, {"id": "c", "text": "Turning off all bathroom lights at night"}, {"id": "d", "text": "Speaking respectfully during incontinence care"}]'::jsonb, '["c"]', 'Adequate lighting is a safety measure for functional incontinence, so darkening the bathroom path is unsafe. Scheduled toileting, a bedside commode, and preserving dignity are all appropriate.'),
  ('incontinence', 25, 'A client with a spinal cord injury and reflex incontinence suddenly reports a pounding headache, and the blood pressure is severely elevated. The nurse suspects which complication?', '[{"id": "a", "text": "Urinary tract infection"}, {"id": "b", "text": "Orthostatic hypotension"}, {"id": "c", "text": "Functional incontinence"}, {"id": "d", "text": "Autonomic dysreflexia"}]'::jsonb, '["d"]', 'In reflex incontinence with SCI, sudden severe hypertension with a pounding headache signals autonomic dysreflexia. Orthostatic hypotension involves low, not high, blood pressure.'),
  ('incontinence', 26, 'A client with a spinal cord injury develops a pounding headache and severe hypertension, and the bladder is distended. What is the nurse''s priority positioning?', '[{"id": "a", "text": "Raise the client to a sitting position"}, {"id": "b", "text": "Place the client flat with legs raised"}, {"id": "c", "text": "Turn the client onto the left side"}, {"id": "d", "text": "Lower the head of the bed below the feet"}]'::jsonb, '["a"]', 'Autonomic dysreflexia requires sitting the client upright and emptying the bladder immediately, then notifying the provider. Lying the client flat with legs raised is the opposite of the required upright position.'),
  ('incontinence', 27, 'A client with a spinal cord injury and reflex incontinence develops life-threatening hypertension. The nurse recognizes the most likely trigger is', '[{"id": "a", "text": "dehydration from low fluid intake."}, {"id": "b", "text": "a full bladder."}, {"id": "c", "text": "weak pelvic floor muscles."}, {"id": "d", "text": "a dose of an alpha-blocker."}]'::jsonb, '["b"]', 'A full bladder in an SCI patient triggers autonomic dysreflexia with life-threatening hypertension and pounding headache. Weak pelvic floor muscles cause stress incontinence, not hypertension.'),
  ('incontinence', 28, 'A client reports leaking urine when coughing and also when a sudden strong urge comes on. The nurse recognizes this as which type of incontinence?', '[{"id": "a", "text": "Overflow incontinence"}, {"id": "b", "text": "Reflex incontinence"}, {"id": "c", "text": "Mixed incontinence"}, {"id": "d", "text": "Functional incontinence"}]'::jsonb, '["c"]', 'Mixed incontinence is a combination of two types, usually stress (leakage with coughing) plus urge. Reflex incontinence occurs with no warning or urge at all.'),
  ('incontinence', 29, 'A client with urge incontinence is being taught self-care measures. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will drink about 2 to 3 liters of fluid each day.\""}, {"id": "b", "text": "\"I will wear cotton underwear and avoid tight pants.\""}, {"id": "c", "text": "\"I will cut back on caffeine and carbonated drinks.\""}, {"id": "d", "text": "\"I will drink as little as possible so I leak less.\""}]'::jsonb, '["d"]', 'Clients should drink 2–3 L/day because restricting fluids worsens incontinence and increases infection risk. Cotton underwear and avoiding caffeine and carbonated drinks are correct measures.'),
  ('incontinence', 30, 'A client with incontinence says, "I''ve stopped drinking water during the day so I won''t have accidents." Which response by the nurse is best?', '[{"id": "a", "text": "\"Cutting back fluids can worsen leakage and raise infection risk.\""}, {"id": "b", "text": "\"Cutting back fluids is helpful for most types of incontinence.\""}, {"id": "c", "text": "\"Cutting back fluids is fine as long as you do Kegel exercises.\""}, {"id": "d", "text": "\"Cutting back fluids is the main treatment for overactive bladder.\""}]'::jsonb, '["a"]', 'Restricting fluids worsens incontinence and increases infection risk, so 2–3 L/day is encouraged. Fluid restriction is not a treatment for overactive bladder, which is managed with bladder training and oxybutynin.'),
  ('incontinence', 31, 'The nurse teaches a client with urge incontinence about bladder irritants. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I will limit my water to two glasses a day.\""}, {"id": "b", "text": "\"I will replace my coffee and soda with water.\""}, {"id": "c", "text": "\"I will add hot spicy sauces to my meals.\""}, {"id": "d", "text": "\"I will have a glass of wine to help me relax.\""}]'::jsonb, '["b"]', 'Caffeine, alcohol, carbonated drinks, and spicy foods are bladder irritants, so replacing coffee and soda with water is appropriate. Limiting water is wrong because fluid intake of 2–3 L/day is encouraged.'),
  ('incontinence', 32, 'A woman with incontinence asks how she can lower her risk of urinary tract infection. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Limit fluids to less than 1 liter daily.\""}, {"id": "b", "text": "\"Wear snug synthetic undergarments.\""}, {"id": "c", "text": "\"Void soon after sexual intercourse.\""}, {"id": "d", "text": "\"Drink a carbonated beverage daily.\""}]'::jsonb, '["c"]', 'Voiding after intercourse reduces UTI risk. Fluid restriction increases infection risk, and cotton underwear with loose clothing is recommended instead of tight garments.'),
  ('incontinence', 33, 'A newly admitted client reports frequent urinary leakage. Before planning interventions, what should the nurse do first?', '[{"id": "a", "text": "Insert an indwelling urinary catheter"}, {"id": "b", "text": "Request an order for oxybutynin"}, {"id": "c", "text": "Restrict the client''s fluid intake"}, {"id": "d", "text": "Identify the type of incontinence"}]'::jsonb, '["d"]', 'The type of incontinence must be identified before choosing interventions because treatment differs by type. Starting oxybutynin before the type is known could be wrong, since it treats urge incontinence specifically.'),
  ('incontinence', 34, 'The nurse asks a client with incontinence to keep a voiding diary. Which information should the client record?', '[{"id": "a", "text": "Daily weight and blood pressure"}, {"id": "b", "text": "Medications taken each morning"}, {"id": "c", "text": "Foods eaten at each meal only"}, {"id": "d", "text": "Voiding frequency, volume, triggers, and leaks"}]'::jsonb, '["d"]', 'A voiding diary tracks frequency, volume, triggers, and leaks to help determine the type of incontinence. Recording only meals or medications would not capture the voiding pattern.'),
  ('incontinence', 35, 'A client with new-onset incontinence has a urinalysis ordered. The client asks why. The nurse explains that the test is done to', '[{"id": "a", "text": "measure post-void residual."}, {"id": "b", "text": "rule out a UTI as the cause."}, {"id": "c", "text": "confirm detrusor overactivity."}, {"id": "d", "text": "check for an enlarged prostate."}]'::jsonb, '["b"]', 'Urinalysis is done to rule out UTI as a cause of incontinence. Post-void residual is measured with a bladder scan, not a urinalysis.'),
  ('incontinence', 36, 'During an incontinence assessment, which client statement requires the nurse to follow up because it may be contributing to the problem?', '[{"id": "a", "text": "\"I do my pelvic floor exercises three times a day.\""}, {"id": "b", "text": "\"I take a water pill (diuretic) every morning.\""}, {"id": "c", "text": "\"I drink about 2 liters of fluid every day.\""}, {"id": "d", "text": "\"I wear cotton underwear and loose clothing.\""}]'::jsonb, '["b"]', 'Diuretics, anticholinergics, and alpha-blockers all affect the bladder, so medication review is part of the assessment. Pelvic floor exercises, 2 L of fluid daily, and cotton underwear are recommended practices.'),
  ('incontinence', 37, 'A client with incontinence becomes tearful and says, "I''m so embarrassed. I smell like urine all the time." Which response by the nurse is best?', '[{"id": "a", "text": "\"Accidents happen, so try not to worry so much about it.\""}, {"id": "b", "text": "\"Let''s change the subject to something more pleasant.\""}, {"id": "c", "text": "\"This is distressing; let''s work on a plan together.\""}, {"id": "d", "text": "\"You''ll need to start wearing briefs all of the time.\""}]'::jsonb, '["c"]', 'Incontinence is distressing, and the nurse should preserve dignity with empathetic communication. Dismissing or changing the subject does not acknowledge the client''s distress.'),
  ('incontinence', 38, 'Which client report best indicates urge incontinence rather than stress incontinence?', '[{"id": "a", "text": "\"I leak right after a sudden, strong need to go.\""}, {"id": "b", "text": "\"I leak a little every time I sneeze hard.\""}, {"id": "c", "text": "\"I leak during my aerobics exercise class.\""}, {"id": "d", "text": "\"I leak when I laugh at my friend''s jokes.\""}]'::jsonb, '["a"]', 'Urge incontinence is triggered by a sudden urge from detrusor overactivity. Leakage with sneezing, exercise, or laughing reflects increased intra-abdominal pressure, which is stress incontinence.'),
  ('incontinence', 39, 'Which finding should the nurse expect in a client with overflow incontinence?', '[{"id": "a", "text": "Leakage only when laughing"}, {"id": "b", "text": "Constant dribbling of urine"}, {"id": "c", "text": "Sudden urges before leakage"}, {"id": "d", "text": "Leakage only on the way to the toilet"}]'::jsonb, '["b"]', 'Overflow incontinence produces constant dribbling and a feeling of incomplete voiding because the bladder does not fully empty. Leakage with laughing is stress incontinence.'),
  ('incontinence', 40, 'The nurse is reviewing assigned clients. Which client is at greatest risk for functional incontinence?', '[{"id": "a", "text": "A woman who recently gave birth vaginally"}, {"id": "b", "text": "A man with an enlarged prostate"}, {"id": "c", "text": "A client with Parkinson''s disease"}, {"id": "d", "text": "A client with severe vision problems"}]'::jsonb, '["d"]', 'Functional incontinence is caused by mobility issues, dementia, or vision problems that keep the client from reaching the toilet. Childbirth is linked to stress incontinence and an enlarged prostate to overflow incontinence.'),
  ('incontinence', 41, 'Which client should the nurse identify as most at risk for overflow incontinence?', '[{"id": "a", "text": "A man with benign prostatic hyperplasia"}, {"id": "b", "text": "A woman who is going through menopause"}, {"id": "c", "text": "A client recovering from a recent stroke"}, {"id": "d", "text": "A client with dementia who wanders"}]'::jsonb, '["a"]', 'BPH, spinal cord injury, and weak bladder muscle cause overflow incontinence. Menopause is a cause of stress incontinence, and stroke is a cause of urge incontinence.'),
  ('incontinence', 42, 'Which client history should the nurse recognize as increasing the risk for stress incontinence?', '[{"id": "a", "text": "Benign prostatic hyperplasia"}, {"id": "b", "text": "Spinal cord injury"}, {"id": "c", "text": "Multiple childbirths"}, {"id": "d", "text": "Advanced dementia"}]'::jsonb, '["c"]', 'Childbirth, aging, and menopause weaken the pelvic floor and cause stress incontinence. BPH and spinal cord injury are causes of overflow incontinence.'),
  ('incontinence', 43, 'A client with a spinal cord injury has reflex incontinence. Which intervention should the nurse include in the plan of care?', '[{"id": "a", "text": "Kegel exercises three times a day"}, {"id": "b", "text": "Scheduled intermittent catheterization"}, {"id": "c", "text": "Bedside commode within reach"}, {"id": "d", "text": "Pessary insertion and care"}]'::jsonb, '["b"]', 'Reflex incontinence is treated with intermittent catheterization while monitoring for autonomic dysreflexia. Kegel exercises and pessaries are treatments for stress incontinence.'),
  ('incontinence', 44, 'A client with chronic retention has been taught intermittent self-catheterization. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will catheterize myself on a regular schedule.\""}, {"id": "b", "text": "\"I will keep drinking 2 to 3 liters of fluid a day.\""}, {"id": "c", "text": "\"I will report it if my urine output changes.\""}, {"id": "d", "text": "\"An indwelling catheter would be better long term.\""}]'::jsonb, '["d"]', 'Intermittent catheterization is preferred over an indwelling catheter for chronic retention. Maintaining 2–3 L/day of fluid is correct teaching.'),
  ('incontinence', 45, 'For which client would the nurse expect Kegel exercises to be the key intervention?', '[{"id": "a", "text": "A man with BPH and constant dribbling"}, {"id": "b", "text": "A client with a spinal cord injury"}, {"id": "c", "text": "A client with dementia who wanders"}, {"id": "d", "text": "A woman who leaks when she laughs"}]'::jsonb, '["d"]', 'Stress incontinence, triggered by coughing, sneezing, or laughing, is treated with Kegel exercises and a pessary. Constant dribbling with BPH is overflow incontinence, treated with intermittent catheterization.'),
  ('incontinence', 46, 'The nurse anticipates a prescription for oxybutynin for which client?', '[{"id": "a", "text": "A client with detrusor overactivity and sudden urges"}, {"id": "b", "text": "A client who leaks only when coughing or sneezing"}, {"id": "c", "text": "A client with BPH and incomplete bladder emptying"}, {"id": "d", "text": "A client with dementia who cannot locate the toilet"}]'::jsonb, '["a"]', 'Oxybutynin is used for urge incontinence caused by detrusor overactivity. Incomplete emptying from BPH is overflow incontinence, which is treated with intermittent catheterization and alpha-blockers.'),
  ('incontinence', 47, 'A client with a spinal cord injury is found to have a severe headache and dangerously high blood pressure with a full bladder. Which sequence of actions is correct?', '[{"id": "a", "text": "Notify the provider, then wait for orders before moving"}, {"id": "b", "text": "Lay the client flat, then empty the bladder"}, {"id": "c", "text": "Sit the client upright, empty the bladder, notify the provider"}, {"id": "d", "text": "Give oral fluids, then recheck the BP in 4 hours"}]'::jsonb, '["c"]', 'For autonomic dysreflexia the nurse sits the client upright and empties the bladder immediately, then notifies the provider. Delaying care to wait for orders allows the life-threatening hypertension to continue.'),
  ('incontinence', 48, 'The nurse is caring for a man with overflow incontinence caused by benign prostatic hyperplasia (BPH). Which medication would the nurse expect to be prescribed?', '[{"id": "a", "text": "Oxybutynin"}, {"id": "b", "text": "Tamsulosin"}, {"id": "c", "text": "Tolterodine"}, {"id": "d", "text": "A diuretic"}]'::jsonb, '["b"]', 'Alpha-blockers such as tamsulosin are used for overflow incontinence from BPH. Oxybutynin and tolterodine are anticholinergics for urge incontinence and list urinary retention as a side effect.'),
  ('incontinence', 49, 'A client is incontinent although bladder function is normal. Which nursing assessment is most relevant to planning this client''s care?', '[{"id": "a", "text": "Mobility, cognition, and toilet access"}, {"id": "b", "text": "Pelvic floor strength during a cough"}, {"id": "c", "text": "Prostate size and urinary stream"}, {"id": "d", "text": "Severity of sudden urges to void"}]'::jsonb, '["a"]', 'Incontinence with normal bladder function is functional incontinence, so the nurse assesses mobility, cognition, and access to toileting facilities. Pelvic floor strength relates to stress incontinence.'),
  ('incontinence', 50, 'A client with stress incontinence asks what else, besides Kegel exercises, may help reduce leaking. Which recommendation is appropriate?', '[{"id": "a", "text": "\"Limit how much water you drink.\""}, {"id": "b", "text": "\"Avoid caffeine and alcohol.\""}, {"id": "c", "text": "\"Take oxybutynin as needed.\""}, {"id": "d", "text": "\"Use an indwelling catheter.\""}]'::jsonb, '["b"]', 'Treatment for stress incontinence includes Kegel exercises, a pessary, and avoiding caffeine and alcohol. Limiting water is discouraged because restricting fluids worsens incontinence and infection risk.'),
  ('calculi', 1, 'A client arrives at the emergency department with suspected renal calculi. Which pain description should the nurse expect the client to report?', '[{"id": "a", "text": "Colicky flank pain radiating to the groin"}, {"id": "b", "text": "Dull, constant pain located behind the sternum"}, {"id": "c", "text": "Burning epigastric pain relieved by eating"}, {"id": "d", "text": "Steady periumbilical pain that eases with rest"}]'::jsonb, '["a"]', 'Kidney stones cause severe, colicky flank pain that comes in waves and radiates from the flank to the groin and inner thigh. A steady pain that eases with rest does not match the wave-like renal colic.'),
  ('calculi', 2, 'A client with severe abdominal and flank pain is being evaluated for renal calculi versus appendicitis. Which finding most supports renal calculi?', '[{"id": "a", "text": "The client lies very still in one position"}, {"id": "b", "text": "The client paces and cannot get comfortable"}, {"id": "c", "text": "The client has no blood in the urine"}, {"id": "d", "text": "The client reports pain only when voiding"}]'::jsonb, '["b"]', 'Restlessness and inability to find a comfortable position distinguish renal colic from appendicitis. Absence of hematuria would not support a stone, since hematuria is an expected finding.'),
  ('calculi', 3, 'A client with a ureteral stone is writhing in severe pain and vomiting. Which action is the nurse''s priority?', '[{"id": "a", "text": "Teach the client about a low-oxalate diet"}, {"id": "b", "text": "Set up equipment to strain all urine"}, {"id": "c", "text": "Administer the prescribed analgesic"}, {"id": "d", "text": "Explain the stone analysis procedure"}]'::jsonb, '["c"]', 'Administering analgesics as ordered is the nursing care priority for renal colic. Straining urine is important but does not address the client''s immediate severe pain.'),
  ('calculi', 4, 'The nurse is preparing to manage pain for a client with a small kidney stone. Which medication does the nurse anticipate administering first?', '[{"id": "a", "text": "Allopurinol"}, {"id": "b", "text": "An oral antibiotic"}, {"id": "c", "text": "An opioid"}, {"id": "d", "text": "Ketorolac"}]'::jsonb, '["d"]', 'For renal colic, NSAIDs such as ketorolac are given first, with opioids reserved for severe pain. Allopurinol is used for uric acid stone prevention, not pain.'),
  ('calculi', 5, 'A client admitted with a kidney stone now has a fever and has had no urine output for several hours. What is the nurse''s priority action?', '[{"id": "a", "text": "Notify the provider immediately"}, {"id": "b", "text": "Encourage the client to drink more"}, {"id": "c", "text": "Recheck the temperature in 4 hours"}, {"id": "d", "text": "Strain the next voided urine sample"}]'::jsonb, '["a"]', 'Fever with no urine output means a stone is causing obstruction with infection, a medical emergency requiring a stat call to the provider and urologist consult. Waiting to recheck delays emergency treatment.'),
  ('calculi', 6, 'A client with a known kidney stone develops a fever and the urine output stops. The nurse recognizes these findings most likely indicate', '[{"id": "a", "text": "expected passage of the stone."}, {"id": "b", "text": "obstruction with infection."}, {"id": "c", "text": "a normal response to tamsulosin."}, {"id": "d", "text": "dehydration from vomiting only."}]'::jsonb, '["b"]', 'Fever plus no urine output signals a stone causing obstruction with infection, which is a medical emergency. This is not an expected part of stone passage.'),
  ('calculi', 7, 'A client with a small kidney stone asks why all urine must be strained. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"It removes blood clots from the urine.\""}, {"id": "b", "text": "\"It keeps the stone from moving upward.\""}, {"id": "c", "text": "\"It catches the stone so it can be analyzed.\""}, {"id": "d", "text": "\"It measures how much fluid you are drinking.\""}]'::jsonb, '["c"]', 'Urine is strained to catch the stone for type analysis. Analyzing the stone then guides dietary prevention.'),
  ('calculi', 8, 'The nurse is supervising an unlicensed assistive personnel (UAP) caring for a client with renal calculi. Which UAP action requires correction?', '[{"id": "a", "text": "Measuring and recording each voiding"}, {"id": "b", "text": "Encouraging the client to drink fluids"}, {"id": "c", "text": "Reporting a sudden drop in urine output"}, {"id": "d", "text": "Flushing urine without straining it"}]'::jsonb, '["d"]', 'All urine must be strained to collect any stone passed, so discarding urine unstrained requires correction. Encouraging fluids and reporting decreased output are appropriate.'),
  ('calculi', 9, 'A client passes a kidney stone into the strainer. The nurse explains that analyzing the stone is important because the results will', '[{"id": "a", "text": "guide dietary prevention."}, {"id": "b", "text": "determine the stone''s size."}, {"id": "c", "text": "show whether hydronephrosis exists."}, {"id": "d", "text": "replace the need for a CT scan."}]'::jsonb, '["a"]', 'Stone analysis determines the stone type, which guides dietary prevention. Hydronephrosis is detected by renal ultrasound, not stone analysis.'),
  ('calculi', 10, 'A nonpregnant adult with suspected renal calculi is being evaluated. Which diagnostic test does the nurse anticipate as the most accurate?', '[{"id": "a", "text": "KUB x-ray"}, {"id": "b", "text": "Non-contrast CT scan"}, {"id": "c", "text": "Urinalysis"}, {"id": "d", "text": "Renal ultrasound"}]'::jsonb, '["b"]', 'A non-contrast CT is the most accurate test and can detect all stone types, location, and size. A KUB x-ray is quick and cheap but misses some stone types.'),
  ('calculi', 11, 'A client who is 24 weeks pregnant presents with flank pain and hematuria. Which diagnostic test does the nurse anticipate?', '[{"id": "a", "text": "Non-contrast CT scan"}, {"id": "b", "text": "KUB x-ray"}, {"id": "c", "text": "Renal ultrasound"}, {"id": "d", "text": "Stone analysis"}]'::jsonb, '["c"]', 'Renal ultrasound is preferred in pregnancy because it uses no radiation. Although a non-contrast CT is the most accurate test overall, ultrasound is preferred for pregnant clients.'),
  ('calculi', 12, 'A renal ultrasound is ordered for a client with a suspected obstructing stone. In addition to avoiding radiation, which condition can this test detect?', '[{"id": "a", "text": "Hyperparathyroidism"}, {"id": "b", "text": "Elevated urine pH"}, {"id": "c", "text": "Uric acid crystals"}, {"id": "d", "text": "Hydronephrosis"}]'::jsonb, '["d"]', 'Renal ultrasound uses no radiation and detects hydronephrosis. Urine pH and crystals are found on urinalysis, not ultrasound.'),
  ('calculi', 13, 'The nurse reviews the urinalysis of a client with suspected renal calculi. Which findings are expected?', '[{"id": "a", "text": "Blood and crystals in the urine"}, {"id": "b", "text": "Glucose and ketones in the urine"}, {"id": "c", "text": "Absence of red blood cells"}, {"id": "d", "text": "Bilirubin and urobilinogen"}]'::jsonb, '["a"]', 'Urinalysis in renal calculi shows blood (hematuria), crystals, and pH, which guides stone type. Absence of red blood cells contradicts the expected hematuria.'),
  ('calculi', 14, 'A client with a small ureteral stone is prescribed tamsulosin (Flomax). The client asks how this drug helps. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It dissolves the stone in the ureter.\""}, {"id": "b", "text": "\"It relaxes the ureter so the stone passes.\""}, {"id": "c", "text": "\"It stops the kidney from forming crystals.\""}, {"id": "d", "text": "\"It treats the infection around the stone.\""}]'::jsonb, '["b"]', 'Tamsulosin is an alpha-blocker that relaxes ureter smooth muscle to facilitate stone passage. It does not dissolve the stone.'),
  ('calculi', 15, 'A client with a small kidney stone is discharged on tamsulosin. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will strain all of my urine at home.\""}, {"id": "b", "text": "\"I will drink plenty of fluids every day.\""}, {"id": "c", "text": "\"This medicine will dissolve my stone.\""}, {"id": "d", "text": "\"This medicine helps the stone pass.\""}]'::jsonb, '["c"]', 'Tamsulosin helps pass stones by relaxing the ureter; it does not dissolve them. Straining urine and drinking fluids are correct.'),
  ('calculi', 16, 'A client asks what is the single most important thing to do to prevent kidney stones from coming back. Which response by the nurse is best?', '[{"id": "a", "text": "\"Avoid all calcium in your diet.\""}, {"id": "b", "text": "\"Eat a high-protein diet daily.\""}, {"id": "c", "text": "\"Take tamsulosin every day.\""}, {"id": "d", "text": "\"Drink 2 to 3 liters of fluid daily.\""}]'::jsonb, '["d"]', 'Drinking 2–3 L/day of fluid is the most important prevention measure. A high-protein diet is a risk factor for stones.'),
  ('calculi', 17, 'A client with a small stone expected to pass on its own is receiving IV fluids and encouraged to drink. The client asks why. The nurse explains that hydration', '[{"id": "a", "text": "increases urine output to flush the stone."}, {"id": "b", "text": "decreases urine output to slow the stone."}, {"id": "c", "text": "breaks the stone into small fragments."}, {"id": "d", "text": "shrinks the stone by dissolving calcium."}]'::jsonb, '["a"]', 'For small stones, IV and oral hydration produce a high urine output that flushes the stone. Breaking stones into fragments is done by ESWL, not hydration.'),
  ('calculi', 18, 'A client asks which type of kidney stone is most common. The nurse should respond that the most common type is', '[{"id": "a", "text": "uric acid."}, {"id": "b", "text": "calcium oxalate."}, {"id": "c", "text": "struvite."}, {"id": "d", "text": "cystine."}]'::jsonb, '["b"]', 'Calcium oxalate is the most common stone type. Cystine stones are rare and caused by a genetic disorder.'),
  ('calculi', 19, 'The nurse has taught a client with calcium oxalate stones about diet. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will drink lemon water during the day.\""}, {"id": "b", "text": "\"I will keep my calcium intake moderate.\""}, {"id": "c", "text": "\"I will eat more spinach salads and nuts.\""}, {"id": "d", "text": "\"I will cut back on salty processed foods.\""}]'::jsonb, '["c"]', 'Clients with calcium oxalate stones should avoid spinach, nuts, chocolate, tea, beets, and wheat bran. Lemon water, moderate calcium, and limiting sodium are appropriate.'),
  ('calculi', 20, 'A client with calcium oxalate stones asks which beverage would help prevent new stones. Which recommendation should the nurse make?', '[{"id": "a", "text": "Hot black tea"}, {"id": "b", "text": "Chocolate milk"}, {"id": "c", "text": "Beer or wine"}, {"id": "d", "text": "Lemon water"}]'::jsonb, '["d"]', 'Lemon water is encouraged because citrate inhibits stones. Tea and chocolate are foods to avoid with calcium oxalate stones.'),
  ('calculi', 21, 'A client with calcium oxalate stones says, "I''m going to stop eating any calcium at all." Which response by the nurse is best?', '[{"id": "a", "text": "\"A moderate calcium intake is recommended.\""}, {"id": "b", "text": "\"Eliminating calcium is the main treatment.\""}, {"id": "c", "text": "\"Calcium does not matter for this stone type.\""}, {"id": "d", "text": "\"You should take extra calcium supplements.\""}]'::jsonb, '["a"]', 'For calcium oxalate stones, moderate calcium intake is encouraged rather than eliminating calcium. The client should instead avoid high-oxalate foods such as spinach and nuts.'),
  ('calculi', 22, 'The nurse is teaching a client with uric acid stones about diet. Which foods should the client avoid?', '[{"id": "a", "text": "Fresh fruits and vegetables"}, {"id": "b", "text": "Organ meats and shellfish"}, {"id": "c", "text": "Lemon water and other fluids"}, {"id": "d", "text": "Spinach and wheat bran only"}]'::jsonb, '["b"]', 'Uric acid stone prevention includes avoiding organ meats, red meat, shellfish, seafood, and alcohol. Fruits and vegetables are encouraged as part of an alkaline diet.'),
  ('calculi', 23, 'Which dietary pattern should the nurse encourage for a client with uric acid stones?', '[{"id": "a", "text": "A high-protein diet with red meat"}, {"id": "b", "text": "A diet rich in seafood and shellfish"}, {"id": "c", "text": "An alkaline diet of fruits and vegetables"}, {"id": "d", "text": "A diet that limits all fluid intake"}]'::jsonb, '["c"]', 'An alkaline diet of fruits and vegetables, plus fluids, is encouraged for uric acid stones. A high-protein diet is a cause of uric acid stones.'),
  ('calculi', 24, 'A client with recurrent uric acid stones is not responding to diet changes alone. Which medication does the nurse anticipate may be prescribed?', '[{"id": "a", "text": "Ketorolac"}, {"id": "b", "text": "Tamsulosin"}, {"id": "c", "text": "An antibiotic"}, {"id": "d", "text": "Allopurinol"}]'::jsonb, '["d"]', 'Allopurinol may be added if needed for uric acid stones along with an alkaline diet and fluids. Antibiotics are used to prevent UTIs in clients with struvite stones.'),
  ('calculi', 25, 'The nurse is reviewing client histories. Which client is at greatest risk for uric acid stones?', '[{"id": "a", "text": "A client with gout who eats a high-protein diet"}, {"id": "b", "text": "A client with recurrent urinary tract infections"}, {"id": "c", "text": "A client with a genetic disorder called cystinuria"}, {"id": "d", "text": "A client with hyperparathyroidism"}]'::jsonb, '["a"]', 'Uric acid stones are associated with a high-protein diet, gout, and acidic urine. Recurrent UTIs are linked to struvite stones.'),
  ('calculi', 26, 'A client with a history of chronic urinary tract infections is found to have a large stone that fills the renal pelvis. The nurse recognizes this is most likely which type of stone?', '[{"id": "a", "text": "Cystine"}, {"id": "b", "text": "Struvite"}, {"id": "c", "text": "Uric acid"}, {"id": "d", "text": "Calcium phosphate"}]'::jsonb, '["b"]', 'Struvite stones result from chronic UTIs with urease-producing bacteria and can form large staghorn calculi. Cystine stones are caused by a genetic disorder, not infection.'),
  ('calculi', 27, 'A client has had a struvite stone removed. Which intervention is most important to prevent recurrence?', '[{"id": "a", "text": "A low-calcium diet"}, {"id": "b", "text": "Daily allopurinol"}, {"id": "c", "text": "Treating UTIs to prevent infection"}, {"id": "d", "text": "Avoiding spinach and nuts"}]'::jsonb, '["c"]', 'Struvite stones are caused by chronic UTIs, so prevention involves aggressive treatment and antibiotics to prevent UTIs, plus fluids. Allopurinol is used for uric acid stones.'),
  ('calculi', 28, 'A client has cystine stones due to cystinuria. Which instruction should the nurse include in the teaching plan?', '[{"id": "a", "text": "\"Limit fluids to 1 liter daily.\""}, {"id": "b", "text": "\"Follow a high-protein diet.\""}, {"id": "c", "text": "\"Acidify your urine with meat.\""}, {"id": "d", "text": "\"Drink 3 to 4 liters of fluid daily.\""}]'::jsonb, '["d"]', 'Cystine stones require a very high fluid intake of 3–4 L/day and alkalinization of the urine, and high-protein foods should be avoided. A high-protein diet is the reverse of the recommendation.'),
  ('calculi', 29, 'A client with hyperparathyroidism and alkaline urine develops a kidney stone. The nurse anticipates this stone is most likely which type?', '[{"id": "a", "text": "Calcium phosphate"}, {"id": "b", "text": "Uric acid (urate)"}, {"id": "c", "text": "Struvite"}, {"id": "d", "text": "Cystine"}]'::jsonb, '["a"]', 'Calcium phosphate stones are associated with alkaline urine and hyperparathyroidism. Uric acid stones are associated with acidic urine and gout.'),
  ('calculi', 30, 'A client with recurrent kidney stones asks why the nurse recommended cutting back on salt. Which explanation is correct?', '[{"id": "a", "text": "\"Less sodium makes your urine more acidic.\""}, {"id": "b", "text": "\"Less sodium reduces calcium in your urine.\""}, {"id": "c", "text": "\"Less sodium helps your body hold on to fluid.\""}, {"id": "d", "text": "\"Less sodium lowers the uric acid in your blood.\""}]'::jsonb, '["b"]', 'For all stone types, excess sodium should be avoided because a low-sodium diet reduces urinary calcium. Holding on to fluid is not the purpose; hydration of 2–3 L/day is encouraged.'),
  ('calculi', 31, 'The nurse is screening clients at a health fair. Which client has the most risk factors for developing kidney stones?', '[{"id": "a", "text": "An active adult who drinks 3 liters of water daily"}, {"id": "b", "text": "An adult who eats a low-sodium, plant-based diet"}, {"id": "c", "text": "An obese, sedentary adult who drinks little fluid"}, {"id": "d", "text": "An adult with no family history who exercises daily"}]'::jsonb, '["c"]', 'Risk factors include dehydration, a sedentary lifestyle, and obesity. Drinking 2–3 L/day and a low-sodium diet are protective measures.'),
  ('calculi', 32, 'A client asks how not drinking enough fluid leads to kidney stones. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"Urine volume rises, which dilutes minerals.\""}, {"id": "b", "text": "\"Urine becomes more alkaline from the fluid loss.\""}, {"id": "c", "text": "\"The bladder overfills and pushes stones up.\""}, {"id": "d", "text": "\"Urine volume falls, so minerals become concentrated.\""}]'::jsonb, '["d"]', 'Dehydration decreases urine volume, which increases the concentration of minerals and promotes stone formation. A rise in urine volume is the reverse of what happens.'),
  ('calculi', 33, 'The nurse is monitoring a client with renal calculi. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Hourly urine output that has dropped sharply"}, {"id": "b", "text": "Pink-tinged urine during stone passage"}, {"id": "c", "text": "Pain that radiates toward the groin"}, {"id": "d", "text": "Small gritty particles in the strainer"}]'::jsonb, '["a"]', 'The nurse monitors urine output and reports oliguria or anuria, which can signal obstruction. Hematuria, pain radiating to the groin, and stone fragments are expected with renal calculi.'),
  ('calculi', 34, 'Which findings in a client with renal calculi should the nurse recognize as signs of infection?', '[{"id": "a", "text": "Restlessness and flank pain"}, {"id": "b", "text": "Fever, chills, and foul-smelling urine"}, {"id": "c", "text": "Nausea and vomiting with pain"}, {"id": "d", "text": "Pain radiating to the inner thigh"}]'::jsonb, '["b"]', 'Signs of infection include fever, chills, and foul-smelling urine. Restlessness, nausea, and radiating pain are expected manifestations of the stone itself.'),
  ('calculi', 35, 'A client returned from extracorporeal shock wave lithotripsy (ESWL) 3 hours ago. Which finding should the nurse recognize as expected?', '[{"id": "a", "text": "Temperature elevation with chills"}, {"id": "b", "text": "Cloudy, foul-smelling urine"}, {"id": "c", "text": "Blood-tinged urine"}, {"id": "d", "text": "A sharp drop in urine output"}]'::jsonb, '["c"]', 'Hematuria is expected after ESWL and should resolve in 24–48 hours. Fever, chills, and cloudy urine indicate infection and must be reported.'),
  ('calculi', 36, 'During assessment after ESWL, the nurse notes bruising over the client''s treated flank. Which action is appropriate?', '[{"id": "a", "text": "Notify the provider of possible bleeding"}, {"id": "b", "text": "Apply firm pressure to the flank area"}, {"id": "c", "text": "Prepare the client for an emergency CT"}, {"id": "d", "text": "Document the finding as an expected effect"}]'::jsonb, '["d"]', 'Bruising over the flank is expected after ESWL, so documenting it is appropriate. Notifying the provider is reserved for findings such as fever, chills, cloudy urine, worsening pain, or decreased output.'),
  ('calculi', 37, 'The nurse is caring for a client the day after ESWL. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Fever, chills, and cloudy urine"}, {"id": "b", "text": "Pink urine and flank bruising"}, {"id": "c", "text": "Stone fragments in the strainer"}, {"id": "d", "text": "Good oral intake of fluids"}]'::jsonb, '["a"]', 'Fever, chills, and cloudy urine after ESWL indicate infection and must be reported. Hematuria and flank bruising are expected after ESWL.'),
  ('calculi', 38, 'A client who had ESWL reports pain that is getting worse, and urine output has decreased. The nurse suspects which complication?', '[{"id": "a", "text": "Expected flank bruising"}, {"id": "b", "text": "Obstruction from fragments"}, {"id": "c", "text": "Normal stent irritation"}, {"id": "d", "text": "Expected post-ESWL hematuria"}]'::jsonb, '["b"]', 'Worsening pain and decreased urine output after ESWL suggest obstruction from stone fragments and should be reported. Flank bruising and hematuria are expected and would not explain falling output.'),
  ('calculi', 39, 'A client had a ureteral stent placed during ureteroscopy. Which statement should the nurse include in discharge teaching?', '[{"id": "a", "text": "\"Urgency means the stent has moved.\""}, {"id": "b", "text": "\"The stent stays in permanently.\""}, {"id": "c", "text": "\"Some frequency and urgency are normal.\""}, {"id": "d", "text": "\"Any blood in the urine is an emergency.\""}]'::jsonb, '["c"]', 'With a ureteral stent, frequency, urgency, and hematuria are normal, and the stent is removed at follow-up. The stent is not permanent.'),
  ('calculi', 40, 'A client scheduled for ESWL asks how the procedure works. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"A scope is passed through the urethra.\""}, {"id": "b", "text": "\"A needle is placed through your back.\""}, {"id": "c", "text": "\"A tube is placed to keep urine flowing.\""}, {"id": "d", "text": "\"Sound waves break up the stone externally.\""}]'::jsonb, '["d"]', 'ESWL uses sound waves to break the stone externally and is non-invasive. Passing a scope through the urethra describes ureteroscopy.'),
  ('calculi', 41, 'A client with a very large kidney stone is scheduled for percutaneous nephrolithotomy. The nurse explains that this procedure involves', '[{"id": "a", "text": "a direct puncture through the back into the kidney."}, {"id": "b", "text": "sound waves applied outside the body."}, {"id": "c", "text": "a scope passed through the urethra and bladder."}, {"id": "d", "text": "a stent placed to keep the ureter open."}]'::jsonb, '["a"]', 'Percutaneous nephrolithotomy is a direct puncture through the back into the kidney for large stones. External sound waves describe ESWL.'),
  ('calculi', 42, 'A client asks how a ureteroscopy will remove a kidney stone. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Sound waves break the stone from outside.\""}, {"id": "b", "text": "\"A scope goes through the urethra and bladder.\""}, {"id": "c", "text": "\"A small incision is made through your back.\""}, {"id": "d", "text": "\"Medicine relaxes the ureter so it can pass.\""}]'::jsonb, '["b"]', 'Ureteroscopy passes a scope through the urethra and bladder to fragment or retrieve the stone. A puncture through the back describes percutaneous nephrolithotomy.'),
  ('calculi', 43, 'A client with an obstructed ureter has a ureteral stent placed. The client asks what the stent is for. The nurse explains that it', '[{"id": "a", "text": "dissolves the remaining stone."}, {"id": "b", "text": "breaks the stone into fragments."}, {"id": "c", "text": "maintains the flow of urine."}, {"id": "d", "text": "prevents urinary tract infection."}]'::jsonb, '["c"]', 'A ureteral stent maintains urine flow when the ureter is obstructed. Breaking the stone into fragments is done by ESWL or ureteroscopy.'),
  ('calculi', 44, 'The nurse has taught a client about care after ESWL. Which client statement indicates understanding?', '[{"id": "a", "text": "\"A fever after the procedure is normal.\""}, {"id": "b", "text": "\"I can stop straining my urine at home.\""}, {"id": "c", "text": "\"I should limit fluids for the first day.\""}, {"id": "d", "text": "\"Blood in my urine should clear in 1–2 days.\""}]'::jsonb, '["d"]', 'Hematuria is expected after ESWL and should resolve in 24–48 hours. Fever is not expected and suggests infection; urine should still be strained and fluids encouraged.'),
  ('calculi', 45, 'A client with renal colic has vomited twice. The client asks why the vomiting is happening. The nurse''s explanation should be based on which cause?', '[{"id": "a", "text": "An adverse effect of tamsulosin"}, {"id": "b", "text": "A sign of a calcium oxalate diet"}, {"id": "c", "text": "A sign that the stone has passed"}, {"id": "d", "text": "The intensity of the client''s pain"}]'::jsonb, '["d"]', 'Nausea and vomiting with kidney stones occur from the pain intensity. Stone passage would not be indicated by vomiting.'),
  ('calculi', 46, 'A client with a kidney stone reports new urgency, frequency, and burning with urination. The nurse recognizes these symptoms most likely indicate the stone is', '[{"id": "a", "text": "near the bladder."}, {"id": "b", "text": "in the upper kidney."}, {"id": "c", "text": "completely dissolved."}, {"id": "d", "text": "a staghorn calculus."}]'::jsonb, '["a"]', 'Urgency, frequency, and dysuria occur when the stone is near the bladder. Staghorn calculi are large struvite stones that form in the kidney.'),
  ('calculi', 47, 'A client with renal calculi asks why the pain comes and goes in waves. Which response by the nurse is correct?', '[{"id": "a", "text": "\"The pain medicine is wearing off between doses.\""}, {"id": "b", "text": "\"The stone is moving through the urinary tract.\""}, {"id": "c", "text": "\"The stone has already passed into the bladder.\""}, {"id": "d", "text": "\"Waves of pain mean an infection is starting.\""}]'::jsonb, '["b"]', 'Renal colic is severe pain that comes in waves as the stone moves. Infection is signaled by fever, chills, and foul-smelling urine, not wave-like pain.'),
  ('calculi', 48, 'A client with renal colic received ketorolac but continues to report severe pain. Which medication does the nurse anticipate next?', '[{"id": "a", "text": "Allopurinol"}, {"id": "b", "text": "An antibiotic"}, {"id": "c", "text": "An opioid"}, {"id": "d", "text": "A second NSAID"}]'::jsonb, '["c"]', 'NSAIDs such as ketorolac are given first, and opioids are used if pain is severe. Allopurinol is for uric acid stone prevention, not pain relief.'),
  ('calculi', 49, 'The nurse receives report on four clients on a urology unit. Which client should the nurse see first?', '[{"id": "a", "text": "A client 4 hours post-ESWL with pink urine"}, {"id": "b", "text": "A client with a stent who reports urgency"}, {"id": "c", "text": "A client post-ESWL with flank bruising"}, {"id": "d", "text": "A client with a stone, fever, and no urine"}]'::jsonb, '["d"]', 'Fever with no urine output indicates obstruction with infection, a medical emergency. Pink urine and flank bruising after ESWL and urgency with a stent are expected findings.'),
  ('calculi', 50, 'A client in the emergency department needs a quick, inexpensive imaging test to look for a calcium-based kidney stone. Which test does the nurse anticipate?', '[{"id": "a", "text": "Renal ultrasound"}, {"id": "b", "text": "KUB x-ray"}, {"id": "c", "text": "Stone analysis"}, {"id": "d", "text": "Urinalysis"}]'::jsonb, '["b"]', 'A KUB x-ray is quick and cheap and detects calcium stones. Stone analysis requires a passed stone and determines type rather than imaging the stone.'),
  ('aki', 1, 'A client has had severe vomiting and diarrhea for 3 days and now has a sharply decreased urine output. The nurse recognizes that this client is most likely experiencing which type of acute kidney injury (AKI)?', '[{"id": "a", "text": "Intrarenal AKI caused by damage within the kidney tissue"}, {"id": "b", "text": "Prerenal AKI caused by insufficient blood flow to the kidney"}, {"id": "c", "text": "Postrenal AKI caused by obstruction after the kidney"}, {"id": "d", "text": "Intrarenal AKI caused by glomerular inflammation"}]'::jsonb, '["b"]', 'Dehydration is a prerenal cause: the problem is before the kidney, with insufficient blood flow reaching it. Postrenal AKI involves obstruction after the kidney, which this scenario does not describe.'),
  ('aki', 2, 'A client with benign prostatic hyperplasia (BPH) is diagnosed with acute kidney injury. Which treatment approach does the nurse anticipate as the primary focus of care?', '[{"id": "a", "text": "Giving a fluid bolus to restore renal perfusion"}, {"id": "b", "text": "Discontinuing all nephrotoxic medications"}, {"id": "c", "text": "Relieving the obstruction to urine flow"}, {"id": "d", "text": "Starting a high-potassium diet"}]'::jsonb, '["c"]', 'BPH causes postrenal AKI, and postrenal AKI is treated by relieving the obstruction. A fluid bolus is the approach for prerenal AKI, not an obstruction after the kidney.'),
  ('aki', 3, 'A client receiving an aminoglycoside antibiotic for a severe infection develops a rising serum creatinine. The nurse classifies this kidney injury as which type?', '[{"id": "a", "text": "Prerenal, from reduced cardiac output"}, {"id": "b", "text": "Postrenal, from a urinary obstruction"}, {"id": "c", "text": "Prerenal, from fluid volume loss"}, {"id": "d", "text": "Intrarenal, from a nephrotoxic drug"}]'::jsonb, '["d"]', 'Aminoglycosides are nephrotoxic drugs that damage kidney tissue directly, causing intrarenal AKI. Prerenal causes involve insufficient blood flow, such as dehydration or heart failure.'),
  ('aki', 4, 'A nurse is teaching a group of nursing students about intrarenal acute kidney injury. Which condition should the nurse identify as the most common cause of intrarenal AKI?', '[{"id": "a", "text": "Acute tubular necrosis"}, {"id": "b", "text": "Benign prostatic hyperplasia"}, {"id": "c", "text": "Severe dehydration"}, {"id": "d", "text": "Bilateral kidney stones"}]'::jsonb, '["a"]', 'Acute tubular necrosis (ATN) is the most common intrarenal AKI. BPH and kidney stones are postrenal causes, and dehydration is a prerenal cause.'),
  ('aki', 5, 'A client with an indwelling urinary catheter has had no urine drain into the collection bag for the past 2 hours. The nurse suspects postrenal acute kidney injury. Which finding best supports this suspicion?', '[{"id": "a", "text": "A blocked, nondraining catheter"}, {"id": "b", "text": "A recent dose of IV contrast dye"}, {"id": "c", "text": "A recent episode of severe bleeding"}, {"id": "d", "text": "A history of heart failure"}]'::jsonb, '["a"]', 'A blocked catheter is an obstruction after the kidney and is listed as a postrenal cause. Contrast dye causes intrarenal injury, and bleeding and heart failure are prerenal causes.'),
  ('aki', 6, 'A client in septic shock has remained hypotensive for many hours despite treatment. The nurse understands that this prolonged prerenal state places the client at risk for which complication?', '[{"id": "a", "text": "Postrenal injury from urinary obstruction"}, {"id": "b", "text": "Intrarenal injury from kidney ischemia"}, {"id": "c", "text": "Rapid entry into the recovery phase"}, {"id": "d", "text": "A large rise in urine output"}]'::jsonb, '["b"]', 'Ischemia from a prolonged prerenal state is a cause of intrarenal AKI. Postrenal injury results from obstruction after the kidney, not from prolonged hypoperfusion.'),
  ('aki', 7, 'A client who takes an ACE inhibitor and an NSAID daily develops decreased urine output and a rising creatinine. The nurse recognizes that these medications contribute to kidney injury by which mechanism?', '[{"id": "a", "text": "Obstructing urine flow from the kidneys"}, {"id": "b", "text": "Increasing the kidneys'' cardiac output"}, {"id": "c", "text": "Reducing blood flow to the kidneys"}, {"id": "d", "text": "Causing tumors within the bladder"}]'::jsonb, '["c"]', 'NSAIDs and ACE inhibitors are prerenal causes because they reduce renal perfusion. Obstruction of urine flow describes postrenal AKI, not the effect of these drugs.'),
  ('aki', 8, 'The nurse is reviewing the histories of four clients. Which client is at greatest risk for postrenal acute kidney injury?', '[{"id": "a", "text": "A client with extensive burns"}, {"id": "b", "text": "A client with heart failure"}, {"id": "c", "text": "A client receiving tobramycin"}, {"id": "d", "text": "A client with a stone in a solitary kidney"}]'::jsonb, '["d"]', 'Kidney stones in a solitary kidney obstruct urine flow after the kidney, a postrenal cause. Burns and heart failure are prerenal causes, and tobramycin is an intrarenal nephrotoxin.'),
  ('aki', 9, 'A client with dehydration is diagnosed with prerenal acute kidney injury. Which prescription does the nurse anticipate?', '[{"id": "a", "text": "A fluid bolus followed by monitoring of the response"}, {"id": "b", "text": "Strict fluid restriction to prevent fluid overload"}, {"id": "c", "text": "Urinary catheter irrigation to relieve obstruction"}, {"id": "d", "text": "Immediate dialysis to remove retained wastes"}]'::jsonb, '["a"]', 'Prerenal AKI is treated with fluids, using a fluid challenge (bolus) and monitoring the response. Fluid restriction is used in the oliguric phase to prevent overload, not to treat a prerenal fluid deficit.'),
  ('aki', 10, 'A client received IV contrast dye yesterday. Today the client has no symptoms and a normal urine output, but the creatinine has begun to rise. The nurse recognizes that the client is in which phase of acute kidney injury?', '[{"id": "a", "text": "Oliguric phase"}, {"id": "b", "text": "Diuretic phase"}, {"id": "c", "text": "Initiation phase"}, {"id": "d", "text": "Recovery phase"}]'::jsonb, '["c"]', 'The initiation phase is the onset of injury; the client may be asymptomatic while labs begin to rise. The oliguric phase would show urine output below 400 mL/day with fluid overload.'),
  ('aki', 11, 'A client with acute kidney injury has a 24-hour urine output of 250 mL, a rising potassium level, and new peripheral edema. The nurse recognizes that the client is in which phase, considered the most dangerous?', '[{"id": "a", "text": "Initiation phase"}, {"id": "b", "text": "Diuretic phase"}, {"id": "c", "text": "Recovery phase"}, {"id": "d", "text": "Oliguric phase"}]'::jsonb, '["d"]', 'The oliguric phase features urine output below 400 mL/day, rising BUN, creatinine, and potassium, and fluid overload; it is the most dangerous phase. The diuretic phase features high urine output, not oliguria.'),
  ('aki', 12, 'A client recovering from acute kidney injury now has a urine output of 4 L/day. The nurse should monitor this client most closely for which complications?', '[{"id": "a", "text": "Hyperkalemia and fluid overload"}, {"id": "b", "text": "Dehydration and hypokalemia"}, {"id": "c", "text": "Pulmonary edema and hypertension"}, {"id": "d", "text": "Peaked T-waves and muscle cramps"}]'::jsonb, '["b"]', 'In the diuretic phase, output rises to 3–5 L/day while the kidneys still filter poorly, creating a risk of dehydration and hypokalemia. Hyperkalemia and fluid overload are dangers of the oliguric phase.'),
  ('aki', 13, 'The nurse is discussing a client in the diuretic phase of acute kidney injury with a nursing student. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "The kidneys still cannot concentrate urine well in this phase."}, {"id": "b", "text": "I should watch this client''s sodium level for hyponatremia."}, {"id": "c", "text": "The high urine output means kidney filtering is back to normal."}, {"id": "d", "text": "Daily weights will help me detect dehydration in this client."}]'::jsonb, '["c"]', 'Despite large urine output in the diuretic phase, the kidneys still cannot concentrate or filter effectively. Monitoring for hyponatremia and dehydration is appropriate during this phase.'),
  ('aki', 14, 'A client is entering the recovery phase of acute kidney injury. The client''s spouse asks how long it will take for the kidney lab values to return to normal. Which response by the nurse is accurate?', '[{"id": "a", "text": "They usually return to normal within 24 hours."}, {"id": "b", "text": "They normalize gradually over weeks to months."}, {"id": "c", "text": "They will never return to normal after AKI."}, {"id": "d", "text": "They return to normal only after a transplant."}]'::jsonb, '["b"]', 'In the recovery phase, BUN and creatinine normalize over weeks to months, and the client may recover fully. AKI is described as potentially reversible, so stating it never recovers is incorrect.'),
  ('aki', 15, 'The nurse is caring for a client at risk for acute kidney injury. Which laboratory value is the best indicator of the client''s kidney function?', '[{"id": "a", "text": "Blood urea nitrogen"}, {"id": "b", "text": "Serum creatinine"}, {"id": "c", "text": "Serum sodium"}, {"id": "d", "text": "Blood pH"}]'::jsonb, '["b"]', 'Creatinine is the best indicator of kidney function. BUN also rises in dehydration, making it less specific.'),
  ('aki', 16, 'A client admitted with dehydration has an elevated BUN. A nursing student asks why the BUN is not used as the main indicator of kidney injury. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "BUN is cleared only by the kidneys."}, {"id": "b", "text": "BUN falls when the kidneys begin to fail."}, {"id": "c", "text": "BUN can also rise from dehydration alone."}, {"id": "d", "text": "BUN is a waste product of muscle tissue."}]'::jsonb, '["c"]', 'BUN rises with kidney failure but is also elevated in dehydration, so it is less specific. Creatinine, the muscle waste product cleared only by the kidneys, is the best indicator.'),
  ('aki', 17, 'The nurse is monitoring the hourly urine output of a 70-kg client at risk for acute kidney injury. Which hourly output meets the criterion for oliguria and should be reported?', '[{"id": "a", "text": "30 mL/hr"}, {"id": "b", "text": "40 mL/hr"}, {"id": "c", "text": "50 mL/hr"}, {"id": "d", "text": "60 mL/hr"}]'::jsonb, '["a"]', 'Oliguria is urine output below 0.5 mL/kg/hr; for a 70-kg client that is below 35 mL/hr, so 30 mL/hr qualifies. Outputs of 40 mL/hr or more are above this threshold.'),
  ('aki', 18, 'The nurse is reviewing the 24-hour intake and output records of four clients. Which client''s 24-hour urine output meets the definition of oliguria?', '[{"id": "a", "text": "1,200 mL"}, {"id": "b", "text": "800 mL"}, {"id": "c", "text": "500 mL"}, {"id": "d", "text": "350 mL"}]'::jsonb, '["d"]', 'Oliguria is urine output less than 400 mL/day, so only 350 mL meets the definition. An output of 500 mL is low but still above the 400 mL/day threshold.'),
  ('aki', 19, 'The nurse is reviewing the arterial blood gas results of a client in the oliguric phase of acute kidney injury. Which acid-base imbalance does the nurse expect?', '[{"id": "a", "text": "Metabolic alkalosis"}, {"id": "b", "text": "Respiratory alkalosis"}, {"id": "c", "text": "Metabolic acidosis"}, {"id": "d", "text": "Respiratory acidosis"}]'::jsonb, '["c"]', 'In AKI the pH falls because the kidneys cannot excrete hydrogen ions, producing metabolic acidosis. Alkalosis would require a rise in pH, which is the opposite direction.'),
  ('aki', 20, 'A nursing student is caring for a client with acute kidney injury. Which statement by the student about serum creatinine is correct?', '[{"id": "a", "text": "It is a muscle waste product cleared only by the kidneys."}, {"id": "b", "text": "It rises mainly because of a high dietary protein intake."}, {"id": "c", "text": "It decreases as kidney function begins to worsen."}, {"id": "d", "text": "It is a less specific kidney marker than the BUN."}]'::jsonb, '["a"]', 'Creatinine is a muscle waste product cleared only by the kidneys, making it most sensitive to kidney function changes. BUN, not creatinine, comes from protein breakdown and is the less specific marker.'),
  ('aki', 21, 'A client with acute kidney injury has a markedly elevated serum potassium level and reports muscle cramps. Which ECG finding does the nurse expect?', '[{"id": "a", "text": "Flattened T-waves"}, {"id": "b", "text": "Peaked T-waves"}, {"id": "c", "text": "Prominent U-waves"}, {"id": "d", "text": "A regular, slow rhythm"}]'::jsonb, '["b"]', 'Hyperkalemia causes muscle cramps and an irregular heartbeat with peaked T-waves on the ECG. A regular rhythm does not reflect the irregular heartbeat associated with hyperkalemia.'),
  ('aki', 22, 'A client with acute kidney injury reports a metallic taste in the mouth, and the nurse notes an ammonia odor on the client''s breath. The nurse recognizes these findings as signs of which condition?', '[{"id": "a", "text": "Hypokalemia"}, {"id": "b", "text": "Uremia"}, {"id": "c", "text": "Dehydration"}, {"id": "d", "text": "Hyponatremia"}]'::jsonb, '["b"]', 'A metallic taste and uremic breath with an ammonia smell are signs of uremia from waste buildup. Hypokalemia and hyponatremia are diuretic-phase concerns and are not linked to these findings.'),
  ('aki', 23, 'The nurse is assessing a client in the oliguric phase of acute kidney injury. Which finding indicates that the client is developing fluid overload?', '[{"id": "a", "text": "Crackles in the lungs and ankle edema"}, {"id": "b", "text": "Poor skin turgor and a dry mouth"}, {"id": "c", "text": "A 1-kg weight loss since yesterday"}, {"id": "d", "text": "Urine output of 4 L in 24 hours"}]'::jsonb, '["a"]', 'Fluid overload in AKI causes peripheral and pulmonary edema, shown by ankle edema and lung crackles. Weight loss and large urine output suggest fluid loss, as seen in the diuretic phase.'),
  ('aki', 24, 'A client in the oliguric phase of acute kidney injury has a newly elevated blood pressure. The nurse understands that this finding is caused by which factors?', '[{"id": "a", "text": "Dehydration and potassium loss"}, {"id": "b", "text": "Metabolic acidosis and hypokalemia"}, {"id": "c", "text": "Fluid overload and renin release"}, {"id": "d", "text": "Muscle breakdown and high carbohydrates"}]'::jsonb, '["c"]', 'Fatigue, weakness, and confusion in AKI are attributed to waste buildup. Low potassium is a diuretic-phase risk and is not listed as a cause of these findings.'),
  ('aki', 25, 'A client with acute kidney injury becomes increasingly fatigued, weak, and confused. The nurse recognizes that these findings are most likely related to which cause?', '[{"id": "a", "text": "Buildup of waste products"}, {"id": "b", "text": "Excessive urine production"}, {"id": "c", "text": "Low serum potassium levels"}, {"id": "d", "text": "Metabolic alkalosis"}]'::jsonb, '["a"]', 'Fatigue, weakness, and confusion in AKI result from waste buildup. Potassium is elevated, not low, in the oliguric phase, and the acid-base change is metabolic acidosis.'),
  ('aki', 26, 'A client with acute kidney injury weighs 2 kg more this morning than yesterday morning. The nurse estimates that the client has retained approximately how much fluid?', '[{"id": "a", "text": "0.5 L"}, {"id": "b", "text": "1 L"}, {"id": "c", "text": "2 L"}, {"id": "d", "text": "4 L"}]'::jsonb, '["c"]', 'Daily weights are the best indicator of fluid status, and 1 kg equals about 1 L of fluid, so a 2-kg gain reflects about 2 L. A 1-L estimate would correspond to only a 1-kg gain.'),
  ('aki', 27, 'The nurse is planning care for a client with acute kidney injury. Which assessment provides the best information about the client''s fluid status?', '[{"id": "a", "text": "Daily weight"}, {"id": "b", "text": "Skin turgor"}, {"id": "c", "text": "BUN level"}, {"id": "d", "text": "Thirst level"}]'::jsonb, '["a"]', 'Daily weight is the best assessment for fluid status in AKI. BUN is a waste marker that is also elevated in dehydration and is not the best gauge of fluid status.'),
  ('aki', 28, 'A client with acute kidney injury has a prescription for strict intake and output with hourly urine output via an indwelling urinary catheter. Which action by the unlicensed assistive personnel (UAP) requires correction by the nurse?', '[{"id": "a", "text": "Measuring and recording the catheter output every hour"}, {"id": "b", "text": "Weighing the client each morning"}, {"id": "c", "text": "Recording all oral fluids the client drinks"}, {"id": "d", "text": "Emptying and recording the catheter bag once per shift"}]'::jsonb, '["d"]', 'Strict I&O for AKI requires hourly urine output measurement through the Foley catheter, so measuring only once per shift is incorrect. Hourly recording, daily weights, and recording intake are all appropriate.'),
  ('aki', 29, 'A client in the oliguric phase of acute kidney injury has a serum potassium that is rising on each basic metabolic panel. Which intervention is the priority?', '[{"id": "a", "text": "Encourage the client to increase oral fluids"}, {"id": "b", "text": "Initiate continuous cardiac monitoring"}, {"id": "c", "text": "Assist the client to ambulate in the hall"}, {"id": "d", "text": "Offer a high-protein snack between meals"}]'::jsonb, '["b"]', 'Hyperkalemia carries a risk of cardiac arrhythmias, so continuous cardiac monitoring is required. Increasing fluids is inappropriate because fluids are restricted in the oliguric phase.'),
  ('aki', 30, 'The nurse reviews prescriptions for a client in the oliguric phase of acute kidney injury. Which prescription should the nurse question?', '[{"id": "a", "text": "Weigh the client daily before breakfast"}, {"id": "b", "text": "Measure urine output every hour"}, {"id": "c", "text": "Encourage 3 L of oral fluids per day"}, {"id": "d", "text": "Obtain a basic metabolic panel each shift"}]'::jsonb, '["c"]', 'Fluids are restricted in the oliguric phase to prevent fluid overload, so encouraging 3 L of fluids is unsafe. Daily weights, hourly output, and a BMP every shift are expected monitoring.'),
  ('aki', 31, 'The nurse provides dietary teaching to a client with acute kidney injury. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will eat extra protein to keep up my strength."}, {"id": "b", "text": "I will choose foods that are low in potassium."}, {"id": "c", "text": "I will limit the amount of sodium in my meals."}, {"id": "d", "text": "I will include plenty of carbohydrates for energy."}]'::jsonb, '["a"]', 'The AKI diet is low in protein to reduce BUN buildup, so eating extra protein is incorrect. Low potassium, low sodium, and high carbohydrates are all part of the prescribed diet.'),
  ('aki', 32, 'A client with acute kidney injury asks why the dietitian recommended a diet high in carbohydrates. Which response by the nurse is accurate?', '[{"id": "a", "text": "Carbohydrates help the kidneys excrete potassium."}, {"id": "b", "text": "Carbohydrates provide energy and prevent muscle breakdown."}, {"id": "c", "text": "Carbohydrates replace the protein lost in the urine."}, {"id": "d", "text": "Carbohydrates correct the metabolic acidosis of AKI."}]'::jsonb, '["b"]', 'High carbohydrates serve as an energy source to prevent muscle breakdown. Correcting metabolic acidosis is the role of sodium bicarbonate, not dietary carbohydrates.'),
  ('aki', 33, 'A client with acute kidney injury asks why the diet limits sodium. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Sodium increases the buildup of BUN."}, {"id": "b", "text": "Sodium raises the serum potassium level."}, {"id": "c", "text": "Sodium causes the body to retain fluid."}, {"id": "d", "text": "Sodium breaks down muscle tissue."}]'::jsonb, '["c"]', 'A low-sodium diet is used in AKI to reduce fluid retention. Limiting protein, not sodium, is what reduces BUN buildup.'),
  ('aki', 34, 'A client with acute kidney injury asks why potassium-containing foods must be limited. Which response by the nurse is accurate?', '[{"id": "a", "text": "To prevent high potassium that can cause heart rhythm problems"}, {"id": "b", "text": "To prevent waste products from building up in the blood"}, {"id": "c", "text": "To prevent the body from retaining too much fluid"}, {"id": "d", "text": "To prevent the muscles from being broken down for energy"}]'::jsonb, '["a"]', 'A low-potassium diet prevents hyperkalemia and the arrhythmias it causes. Preventing fluid retention is the purpose of sodium restriction, not potassium restriction.'),
  ('aki', 35, 'A client with acute kidney injury reports a headache and requests ibuprofen. Which response by the nurse is most appropriate?', '[{"id": "a", "text": "Ibuprofen is safe because it protects kidney blood flow."}, {"id": "b", "text": "Ibuprofen is avoided because it reduces blood flow to the kidneys."}, {"id": "c", "text": "Ibuprofen is safe as long as you drink extra fluids with it."}, {"id": "d", "text": "Ibuprofen is avoided because it raises your blood pressure."}]'::jsonb, '["b"]', 'NSAIDs are nephrotoxins to avoid in AKI because they reduce renal perfusion. Drinking extra fluids does not make an NSAID safe, and fluids may be restricted in AKI.'),
  ('aki', 36, 'A client with acute kidney injury must undergo an imaging study that requires IV contrast dye. Which action does the nurse anticipate before the procedure?', '[{"id": "a", "text": "Withholding all fluids for 12 hours"}, {"id": "b", "text": "Administering sodium polystyrene sulfonate"}, {"id": "c", "text": "Pre-hydrating the client"}, {"id": "d", "text": "Starting a high-sodium diet"}]'::jsonb, '["c"]', 'IV contrast dye is a nephrotoxin; if contrast is needed, the client should be pre-hydrated. Withholding fluids would do the opposite of pre-hydration.'),
  ('aki', 37, 'A client receiving IV gentamicin is at risk for acute kidney injury. Which action by the nurse is most important to reduce this risk?', '[{"id": "a", "text": "Monitoring the drug''s trough levels"}, {"id": "b", "text": "Giving each dose with an NSAID"}, {"id": "c", "text": "Encouraging a high-protein diet"}, {"id": "d", "text": "Restricting carbohydrate intake"}]'::jsonb, '["a"]', 'Gentamicin is a nephrotoxic aminoglycoside, and trough levels should be monitored. Giving an NSAID would add another nephrotoxin that reduces renal perfusion.'),
  ('aki', 38, 'A client with fluid overload from acute kidney injury is prescribed furosemide. The nurse understands that this medication will be effective only if which condition is present?', '[{"id": "a", "text": "Serum potassium is elevated"}, {"id": "b", "text": "The client is fluid restricted"}, {"id": "c", "text": "Metabolic acidosis is corrected"}, {"id": "d", "text": "Adequate renal blood flow exists"}]'::jsonb, '["d"]', 'Furosemide promotes diuresis and reduces fluid overload but must have enough blood flow to work. Elevated potassium is not a requirement for furosemide to be effective.'),
  ('aki', 39, 'The nurse teaches a client with acute kidney injury about sodium polystyrene sulfonate (Kayexalate). Which statement by the client indicates understanding?', '[{"id": "a", "text": "This medicine lowers potassium within a few minutes."}, {"id": "b", "text": "This medicine protects my heart without lowering potassium."}, {"id": "c", "text": "This medicine removes potassium through my stool."}, {"id": "d", "text": "This medicine removes potassium through my urine."}]'::jsonb, '["c"]', 'Kayexalate binds potassium in the GI tract and removes it via the stool; it is slow-acting. Stabilizing the heart without lowering potassium describes calcium gluconate.'),
  ('aki', 40, 'A nursing student is preparing to give IV calcium gluconate to a client with severe hyperkalemia. Which statement by the student requires correction by the nurse?', '[{"id": "a", "text": "It is given to stabilize the cardiac membrane."}, {"id": "b", "text": "It will lower the client''s serum potassium level."}, {"id": "c", "text": "It is used when hyperkalemia is severe."}, {"id": "d", "text": "It is given before the other potassium treatments."}]'::jsonb, '["b"]', 'Calcium gluconate stabilizes the cardiac membrane in severe hyperkalemia but does NOT lower potassium. It is given first to stabilize the heart, so the other statements are correct.'),
  ('aki', 41, 'A client with acute kidney injury has severe hyperkalemia with peaked T-waves on the monitor. Prescriptions include IV calcium gluconate, IV insulin with dextrose, and sodium polystyrene sulfonate. Which medication should the nurse administer first?', '[{"id": "a", "text": "IV insulin with dextrose"}, {"id": "b", "text": "Sodium polystyrene sulfonate"}, {"id": "c", "text": "Sodium bicarbonate"}, {"id": "d", "text": "IV calcium gluconate"}]'::jsonb, '["d"]', 'Calcium gluconate is given first to stabilize the heart, then insulin with glucose shifts potassium into cells, and Kayexalate removes potassium. Insulin with dextrose lowers potassium but does not protect the heart first.'),
  ('aki', 42, 'A client with acute kidney injury has severe hyperkalemia with peaked T-waves on the monitor. Prescriptions include IV calcium gluconate, IV insulin with dextrose, sodium bicarbonate, and sodium polystyrene sulfonate. Which medication should the nurse administer first?', '[{"id": "a", "text": "3, 2, 1"}, {"id": "b", "text": "1, 3, 2"}, {"id": "c", "text": "2, 1, 3"}, {"id": "d", "text": "2, 3, 1"}]'::jsonb, '["d"]', 'The sequence is calcium gluconate to stabilize the heart first, insulin with glucose to shift potassium into cells, then Kayexalate to remove potassium. Giving Kayexalate before insulin delays the rapid potassium shift.'),
  ('aki', 43, 'A client with hyperkalemia receives IV insulin with dextrose. The nurse understands that this treatment has which effect on serum potassium?', '[{"id": "a", "text": "A rapid but temporary decrease"}, {"id": "b", "text": "A slow but permanent decrease"}, {"id": "c", "text": "Removal of potassium in stool"}, {"id": "d", "text": "No change in the potassium level"}]'::jsonb, '["a"]', 'Insulin with dextrose drives potassium into cells, producing a rapid, temporary decrease in serum potassium. Removal via stool describes Kayexalate.'),
  ('aki', 44, 'A client with acute kidney injury and metabolic acidosis is prescribed IV sodium bicarbonate. In addition to treating the acidosis, the nurse anticipates which effect from this medication?', '[{"id": "a", "text": "Stabilization of the cardiac membrane"}, {"id": "b", "text": "Removal of potassium in the stool"}, {"id": "c", "text": "A temporary shift of potassium into cells"}, {"id": "d", "text": "An increase in diuresis to reduce overload"}]'::jsonb, '["c"]', 'Sodium bicarbonate treats metabolic acidosis and also temporarily shifts potassium into cells. Cardiac membrane stabilization is the action of calcium gluconate.'),
  ('aki', 45, 'The nurse is caring for four clients with acute kidney injury. Which client finding most indicates a need for dialysis?', '[{"id": "a", "text": "Hyperkalemia that persists despite medications"}, {"id": "b", "text": "A urine output of 3 L/day in the diuretic phase"}, {"id": "c", "text": "A creatinine that is starting to decrease"}, {"id": "d", "text": "Mild fatigue during the recovery phase"}]'::jsonb, '["a"]', 'Dialysis is indicated for severe AKI with refractory hyperkalemia, fluid overload, or uremia. High output in the diuretic phase and a falling creatinine do not meet these criteria.'),
  ('aki', 46, 'The nurse is caring for a client in the oliguric phase of acute kidney injury. Which finding should the nurse report to the health care provider immediately?', '[{"id": "a", "text": "Mild nausea after breakfast"}, {"id": "b", "text": "Report of a metallic taste"}, {"id": "c", "text": "Fatigue after ambulating"}, {"id": "d", "text": "New peaked T-waves on the ECG"}]'::jsonb, '["d"]', 'Hyperkalemia is a cardiac emergency shown by peaked T-waves on the ECG and must be reported immediately. Nausea, metallic taste, and fatigue are expected AKI symptoms that are not immediately life-threatening.'),
  ('aki', 47, 'The family of a client newly diagnosed with acute kidney injury asks why the team is working so quickly to find the cause. Which response by the nurse is most accurate?', '[{"id": "a", "text": "Early treatment of the cause can prevent permanent damage."}, {"id": "b", "text": "Kidney damage from AKI is permanent no matter what is done."}, {"id": "c", "text": "Identifying the cause decides when dialysis will be stopped."}, {"id": "d", "text": "The cause only matters once the recovery phase has started."}]'::jsonb, '["a"]', 'AKI is potentially reversible, and treating the cause early can prevent permanent kidney damage. Stating that damage is permanent regardless of treatment contradicts this.'),
  ('aki', 48, 'A client develops intrarenal acute kidney injury after receiving tobramycin. Which treatment approach does the nurse anticipate?', '[{"id": "a", "text": "Removal of the nephrotoxin and supportive care"}, {"id": "b", "text": "A fluid challenge with monitoring of the response"}, {"id": "c", "text": "Insertion of a catheter to relieve obstruction"}, {"id": "d", "text": "A high-potassium diet to replace urinary losses"}]'::jsonb, '["a"]', 'Intrarenal AKI is treated by removing the nephrotoxin and providing supportive care. A fluid challenge is the treatment approach for prerenal AKI.'),
  ('aki', 49, 'A client with heart failure and decreased cardiac output develops a sudden decrease in urine output and a rising creatinine. The nurse recognizes this as which type of acute kidney injury?', '[{"id": "a", "text": "Intrarenal"}, {"id": "b", "text": "Postrenal"}, {"id": "c", "text": "Prerenal"}, {"id": "d", "text": "Chronic"}]'::jsonb, '["c"]', 'Heart failure with decreased cardiac output is a prerenal cause because blood flow to the kidneys is insufficient. Postrenal AKI requires an obstruction after the kidney.'),
  ('aki', 50, 'A client in the oliguric phase of acute kidney injury has a basic metabolic panel drawn. Which set of results does the nurse expect?', '[{"id": "a", "text": "Decreased BUN, decreased creatinine, decreased potassium"}, {"id": "b", "text": "Increased BUN, increased creatinine, increased potassium"}, {"id": "c", "text": "Increased BUN, decreased creatinine, decreased potassium"}, {"id": "d", "text": "Decreased BUN, increased creatinine, decreased potassium"}]'::jsonb, '["b"]', 'In AKI, BUN, creatinine, and potassium all rise because the kidneys cannot excrete wastes or potassium. Any decrease in these values reverses the expected direction.'),
  ('ckd', 1, 'A client with diabetes has a glomerular filtration rate (GFR) of 45 mL/min. The nurse recognizes that this client is in which stage of chronic kidney disease (CKD)?', '[{"id": "a", "text": "Stage 2, mildly decreased"}, {"id": "b", "text": "Stage 3, moderately decreased"}, {"id": "c", "text": "Stage 4, severely decreased"}, {"id": "d", "text": "Stage 5, kidney failure"}]'::jsonb, '["b"]', 'Stage 3 CKD is a GFR of 30–59, described as moderately decreased. Stage 2 is a GFR of 60–89, which is higher than this client''s value.'),
  ('ckd', 2, 'A client with chronic kidney disease has a GFR of 12 mL/min. The nurse anticipates that the plan of care will focus on which treatment?', '[{"id": "a", "text": "Lifestyle changes alone to slow progression"}, {"id": "b", "text": "Dialysis or kidney transplantation"}, {"id": "c", "text": "Control of blood sugar to restore function"}, {"id": "d", "text": "Fluid restriction as the only therapy"}]'::jsonb, '["b"]', 'A GFR below 15 is Stage 5 (ESRD), which requires dialysis or transplant. Lifestyle modification alone is the focus of Stage 2, not kidney failure.'),
  ('ckd', 3, 'A client''s GFR has declined to 22 mL/min. Which intervention does the nurse anticipate including in the plan of care at this stage?', '[{"id": "a", "text": "Starting dialysis and transplant education"}, {"id": "b", "text": "Beginning hemodialysis three times weekly"}, {"id": "c", "text": "Lifestyle changes as the sole treatment"}, {"id": "d", "text": "No treatment because symptoms are absent"}]'::jsonb, '["a"]', 'A GFR of 15–29 is Stage 4, when uremia symptoms appear and dialysis/transplant education is prepared. Dialysis itself is required at Stage 5, not yet at Stage 4.'),
  ('ckd', 4, 'A client with hypertension has proteinuria on a routine urinalysis, and the GFR is 95 mL/min. The client has no symptoms. How does the nurse interpret these findings?', '[{"id": "a", "text": "There is no kidney disease because the GFR is normal."}, {"id": "b", "text": "These findings are consistent with Stage 1 CKD."}, {"id": "c", "text": "These findings are consistent with Stage 3 CKD."}, {"id": "d", "text": "The client has end-stage renal disease."}]'::jsonb, '["b"]', 'Stage 1 CKD has kidney damage markers such as proteinuria with a normal GFR of 90 or above, and it is often asymptomatic. A normal GFR does not rule out CKD when damage markers are present.'),
  ('ckd', 5, 'A client with Stage 2 chronic kidney disease and type 2 diabetes asks what the main treatment will be at this time. Which response by the nurse is most accurate?', '[{"id": "a", "text": "Lifestyle changes with control of blood pressure and blood sugar"}, {"id": "b", "text": "Fluid restriction and phosphate binders with every meal"}, {"id": "c", "text": "Preparing for dialysis access placement within the month"}, {"id": "d", "text": "Kidney transplant evaluation before symptoms develop"}]'::jsonb, '["a"]', 'Stage 2 CKD is usually asymptomatic and is managed with lifestyle modifications and BP/blood sugar control. Phosphate binders and fluid restriction are Stage 4 interventions.'),
  ('ckd', 6, 'The nurse is reviewing laboratory results for a client with chronic kidney disease. Which value does the nurse use to determine the client''s stage of CKD?', '[{"id": "a", "text": "Serum potassium"}, {"id": "b", "text": "Hemoglobin"}, {"id": "c", "text": "Serum phosphorus"}, {"id": "d", "text": "Glomerular filtration rate"}]'::jsonb, '["d"]', 'GFR is the core marker of CKD severity and is used for staging. Potassium, hemoglobin, and phosphorus change with CKD but are not the staging marker.'),
  ('ckd', 7, 'A client newly diagnosed with chronic kidney disease asks, ''Will my kidneys heal if I follow all the treatments?'' Which response by the nurse is most accurate?', '[{"id": "a", "text": "Yes, kidney function usually returns within a few months."}, {"id": "b", "text": "Yes, as long as you start dialysis right away."}, {"id": "c", "text": "No, but treatment can help slow the disease."}, {"id": "d", "text": "No, and treatment will not change the outcome."}]'::jsonb, '["c"]', 'CKD is irreversible, and the goal of treatment is to slow progression. Saying treatment will not change the outcome ignores this goal.'),
  ('ckd', 8, 'A nursing student asks how long a loss of kidney function must persist to be classified as chronic kidney disease. Which response by the nurse is correct?', '[{"id": "a", "text": "At least 2 weeks"}, {"id": "b", "text": "At least 1 month"}, {"id": "c", "text": "At least 3 months"}, {"id": "d", "text": "At least 12 months"}]'::jsonb, '["c"]', 'CKD is a progressive, irreversible loss of kidney function lasting 3 months or more. Shorter durations do not meet this definition.'),
  ('ckd', 9, 'The nurse is reviewing the laboratory results of a client with late-stage chronic kidney disease. Which pattern of results does the nurse expect?', '[{"id": "a", "text": "Low hemoglobin, low calcium, high phosphorus"}, {"id": "b", "text": "High hemoglobin, high calcium, low phosphorus"}, {"id": "c", "text": "Low hemoglobin, high calcium, low phosphorus"}, {"id": "d", "text": "High hemoglobin, low calcium, high phosphorus"}]'::jsonb, '["a"]', 'Anemia with decreased calcium and increased phosphorus is the classic late CKD triad. High calcium with low phosphorus reverses the expected direction of both values.'),
  ('ckd', 10, 'A client with chronic kidney disease has pallor, fatigue, and a low hemoglobin. The nurse understands that the primary cause of these findings is which factor?', '[{"id": "a", "text": "Excess phosphorus binding to the red blood cells"}, {"id": "b", "text": "Decreased erythropoietin production by the kidneys"}, {"id": "c", "text": "Loss of red blood cells through frequent urination"}, {"id": "d", "text": "Increased vitamin D activation in the kidneys"}]'::jsonb, '["b"]', 'In CKD, decreased EPO production leads to decreased RBC production, causing fatigue and pallor. Vitamin D activation is reduced, not increased, in CKD.'),
  ('ckd', 11, 'The nurse reviews the morning laboratory results for a client with Stage 4 chronic kidney disease. Which change should the nurse report to the health care provider first?', '[{"id": "a", "text": "A slight decrease in hemoglobin"}, {"id": "b", "text": "A gradual rise in BUN"}, {"id": "c", "text": "A sharp rise in serum potassium"}, {"id": "d", "text": "A GFR unchanged from last month"}]'::jsonb, '["c"]', 'Elevated potassium in CKD carries a risk of fatal cardiac arrhythmias, making it the priority. Anemia and rising BUN are expected CKD changes that are not immediately life-threatening.'),
  ('ckd', 12, 'A client with chronic kidney disease has a persistently elevated serum phosphorus level. The nurse recognizes that this client is at risk for which complication?', '[{"id": "a", "text": "Fluid overload"}, {"id": "b", "text": "Cardiac arrhythmias"}, {"id": "c", "text": "Uremic frost"}, {"id": "d", "text": "Renal osteodystrophy"}]'::jsonb, '["d"]', 'The kidneys cannot excrete phosphorus, and high phosphorus leads to bone weakness (renal osteodystrophy). Cardiac arrhythmias are the main risk of elevated potassium, not phosphorus.'),
  ('ckd', 13, 'A nursing student asks why a client with chronic kidney disease has a low serum calcium level. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Phosphorus binds calcium, and less vitamin D is activated."}, {"id": "b", "text": "Calcium is lost in the urine as kidney function declines."}, {"id": "c", "text": "Erythropoietin deficiency prevents calcium absorption."}, {"id": "d", "text": "High potassium levels push calcium into the cells."}]'::jsonb, '["a"]', 'Calcium falls in CKD because phosphorus binds calcium and less vitamin D is activated, causing bone disease. Erythropoietin deficiency causes anemia, not low calcium.'),
  ('ckd', 14, 'A client with chronic kidney disease has markedly elevated BUN and creatinine levels and reports a metallic taste. The nurse recognizes that these findings result from which process?', '[{"id": "a", "text": "Decreased erythropoietin production"}, {"id": "b", "text": "Waste buildup leading to uremia"}, {"id": "c", "text": "Low calcium from poor vitamin D activation"}, {"id": "d", "text": "Excess potassium causing arrhythmias"}]'::jsonb, '["b"]', 'The kidneys cannot excrete waste, causing azotemia that progresses to uremia with confusion and a metallic taste. Decreased EPO production causes anemia, not these findings.'),
  ('ckd', 15, 'A client with end-stage renal disease reports intense itching, and the nurse observes dry skin with visible deposits. The nurse recognizes this finding as related to which cause?', '[{"id": "a", "text": "Anemia from low erythropoietin"}, {"id": "b", "text": "Hypocalcemia from bone disease"}, {"id": "c", "text": "Uremic deposits on the skin"}, {"id": "d", "text": "An allergic reaction to binders"}]'::jsonb, '["c"]', 'Itchy, dry skin results from uremia deposits on the skin, known as uremic frost in ESRD. Anemia from low EPO causes pallor and fatigue rather than skin deposits.'),
  ('ckd', 16, 'A client with Stage 5 chronic kidney disease becomes drowsy and confused. The nurse suspects which complication?', '[{"id": "a", "text": "Renal osteodystrophy"}, {"id": "b", "text": "Anemia of CKD"}, {"id": "c", "text": "Fluid volume deficit"}, {"id": "d", "text": "Uremic encephalopathy"}]'::jsonb, '["d"]', 'Confusion and drowsiness in late CKD indicate uremic encephalopathy. Renal osteodystrophy is a bone complication of high phosphorus and does not cause confusion.'),
  ('ckd', 17, 'A client with Stage 4 chronic kidney disease has developed hypertension. The nurse understands that this finding is caused by which factors?', '[{"id": "a", "text": "Increased fluid volume and renin"}, {"id": "b", "text": "Low hemoglobin and low calcium"}, {"id": "c", "text": "High phosphorus and bone loss"}, {"id": "d", "text": "Uremic deposits in the blood vessels"}]'::jsonb, '["a"]', 'Hypertension in CKD results from increased fluid volume plus renin. Low hemoglobin reflects anemia from decreased EPO and does not explain hypertension.'),
  ('ckd', 18, 'A client with Stage 5 chronic kidney disease reports frequent muscle cramps. The nurse recognizes that this symptom is most likely related to which cause?', '[{"id": "a", "text": "Anemia"}, {"id": "b", "text": "Electrolyte imbalance"}, {"id": "c", "text": "Fluid deficit"}, {"id": "d", "text": "Uremic frost"}]'::jsonb, '["b"]', 'Muscle cramps in late CKD result from electrolyte imbalance. Anemia causes fatigue, weakness, and pallor rather than cramps.'),
  ('ckd', 19, 'The nurse is assessing a client with Stage 5 chronic kidney disease. Which skin finding does the nurse expect as a result of the client''s anemia?', '[{"id": "a", "text": "Flushing"}, {"id": "b", "text": "Jaundice"}, {"id": "c", "text": "Pallor"}, {"id": "d", "text": "Cyanosis"}]'::jsonb, '["c"]', 'Pallor results from anemia caused by decreased EPO. Flushing is the opposite of the pale skin expected with reduced red blood cell production.'),
  ('ckd', 20, 'A client with diabetes and chronic kidney disease is prescribed an ACE inhibitor. The client asks why this medication is needed. Which response by the nurse is most accurate?', '[{"id": "a", "text": "It replaces the hormone that makes red blood cells."}, {"id": "b", "text": "It binds phosphorus from food in the stomach."}, {"id": "c", "text": "It controls blood pressure and slows kidney damage."}, {"id": "d", "text": "It activates vitamin D to strengthen the bones."}]'::jsonb, '["c"]', 'ACE inhibitors and ARBs control BP, reduce proteinuria, and slow CKD progression, especially in DM and HTN. Replacing the hormone that makes red blood cells describes EPO.'),
  ('ckd', 21, 'The nurse is reviewing antihypertensive options for a client with chronic kidney disease. Which drug class is considered first-line because it also protects the kidneys?', '[{"id": "a", "text": "Loop diuretics"}, {"id": "b", "text": "ACE inhibitors or ARBs"}, {"id": "c", "text": "Phosphate binders"}, {"id": "d", "text": "Active vitamin D"}]'::jsonb, '["b"]', 'ACE inhibitors and ARBs are first-line for BP control and are kidney-protective. Loop diuretics reduce edema in early CKD but are not the first-line kidney-protective class.'),
  ('ckd', 22, 'The nurse teaches a client with chronic kidney disease about a newly prescribed phosphate binder. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will take the binder at bedtime each night."}, {"id": "b", "text": "I will take the binder along with my meals."}, {"id": "c", "text": "I will keep following my low-phosphorus diet."}, {"id": "d", "text": "I will keep all of my lab appointments."}]'::jsonb, '["a"]', 'Phosphate binders must be taken with meals, not at bedtime. Continuing the low-phosphorus diet and keeping lab appointments are correct parts of CKD teaching.'),
  ('ckd', 23, 'A client with chronic kidney disease asks why the phosphate binder must be taken with meals. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It must be absorbed into the blood to remove phosphorus."}, {"id": "b", "text": "It binds dietary phosphate before it can be absorbed."}, {"id": "c", "text": "It prevents the stomach upset caused by low calcium."}, {"id": "d", "text": "It helps the kidneys excrete phosphorus in the urine."}]'::jsonb, '["b"]', 'Phosphate binders are taken with meals to bind dietary phosphate in the GI tract before absorption. They act in the GI tract, not by increasing kidney excretion.'),
  ('ckd', 24, 'A client with chronic kidney disease is prescribed calcitriol (active vitamin D). The client asks why a supplement is necessary. Which response by the nurse is most accurate?', '[{"id": "a", "text": "Your kidneys cannot activate vitamin D, so this prevents bone disease."}, {"id": "b", "text": "Your kidneys make too much vitamin D, so this balances the excess."}, {"id": "c", "text": "Your kidneys need vitamin D to increase red blood cell production."}, {"id": "d", "text": "Your kidneys excrete potassium better when vitamin D is replaced."}]'::jsonb, '["a"]', 'The kidney cannot activate vitamin D in CKD, so active vitamin D is supplemented to prevent bone disease and low calcium. Red blood cell production is stimulated by EPO, not vitamin D.'),
  ('ckd', 25, 'A client with chronic kidney disease and anemia is starting epoetin alfa. The client asks what the medication does. Which response by the nurse is accurate?', '[{"id": "a", "text": "It lowers the potassium level in your blood."}, {"id": "b", "text": "It binds phosphorus in the foods you eat."}, {"id": "c", "text": "It helps your body make red blood cells."}, {"id": "d", "text": "It removes extra fluid through your urine."}]'::jsonb, '["c"]', 'Epoetin alfa stimulates RBC production to treat the anemia of CKD. Binding dietary phosphorus is the action of phosphate binders.'),
  ('ckd', 26, 'A client with chronic kidney disease has been receiving epoetin alfa for several weeks. Which finding best indicates that the medication is effective?', '[{"id": "a", "text": "Falling phosphorus and rising calcium"}, {"id": "b", "text": "Decreased edema in the ankles"}, {"id": "c", "text": "Lower blood pressure readings"}, {"id": "d", "text": "Rising hemoglobin and less fatigue"}]'::jsonb, '["d"]', 'EPO treats anemia by stimulating RBC production, so a rising hemoglobin with less fatigue shows effectiveness. Phosphorus and calcium changes reflect phosphate binders and vitamin D, not EPO.'),
  ('ckd', 27, 'A client with early chronic kidney disease and ankle edema is prescribed furosemide. The nurse explains that the purpose of this medication is to:', '[{"id": "a", "text": "Reduce the edema"}, {"id": "b", "text": "Raise the hemoglobin"}, {"id": "c", "text": "Bind dietary phosphate"}, {"id": "d", "text": "Activate vitamin D"}]'::jsonb, '["a"]', 'Loop diuretics such as furosemide reduce edema in early CKD. Binding dietary phosphate is the purpose of phosphate binders.'),
  ('ckd', 28, 'A client with chronic kidney disease requests ibuprofen for knee pain. Which response by the nurse is most appropriate?', '[{"id": "a", "text": "Ibuprofen is safe if you take it with your meals."}, {"id": "b", "text": "Ibuprofen is avoided because it reduces kidney blood flow."}, {"id": "c", "text": "Ibuprofen is safe because it lowers your blood pressure."}, {"id": "d", "text": "Ibuprofen is avoided because it raises your hemoglobin."}]'::jsonb, '["b"]', 'NSAIDs are avoided in CKD because they reduce renal perfusion and accelerate CKD progression. Taking ibuprofen with meals applies to phosphate binders and does not make an NSAID safe.'),
  ('ckd', 29, 'The nurse reviews new prescriptions for a client with Stage 3 chronic kidney disease. Which prescription should the nurse question?', '[{"id": "a", "text": "Daily blood pressure monitoring"}, {"id": "b", "text": "An angiotensin receptor blocker (ARB)"}, {"id": "c", "text": "A CT scan with IV contrast dye"}, {"id": "d", "text": "A complete blood count and BMP"}]'::jsonb, '["c"]', 'Contrast dye is nephrotoxic and should not be used in CKD. ARBs are first-line kidney-protective drugs, and BP monitoring and lab work are expected.'),
  ('ckd', 30, 'A client with chronic kidney disease develops an infection. Which type of prescribed medication should the nurse clarify with the health care provider?', '[{"id": "a", "text": "An active vitamin D supplement"}, {"id": "b", "text": "A phosphate binder with meals"}, {"id": "c", "text": "An ACE inhibitor for blood pressure"}, {"id": "d", "text": "An aminoglycoside antibiotic"}]'::jsonb, '["d"]', 'Aminoglycosides are nephrotoxic and accelerate CKD progression, so they should be avoided. Vitamin D, phosphate binders, and ACE inhibitors are standard CKD treatments.'),
  ('ckd', 31, 'The nurse provides diet teaching to a client with Stage 4 chronic kidney disease who is not receiving dialysis. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I should limit foods that are high in potassium."}, {"id": "b", "text": "I should eat enough calories to protect my muscles."}, {"id": "c", "text": "I should cut back on the salt in my meals."}, {"id": "d", "text": "I should increase protein to build up my strength."}]'::jsonb, '["d"]', 'The CKD diet is low in protein to reduce BUN and waste buildup. Limiting potassium and sodium and eating a high-calorie diet are correct.'),
  ('ckd', 32, 'A client with chronic kidney disease asks why potassium must be restricted in the diet. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "To prevent weakening of the bones"}, {"id": "b", "text": "To prevent cardiac arrhythmias"}, {"id": "c", "text": "To prevent buildup of waste products"}, {"id": "d", "text": "To prevent breakdown of muscle"}]'::jsonb, '["b"]', 'A low-potassium diet prevents cardiac arrhythmias. Preventing bone disease is the reason for restricting phosphorus, not potassium.'),
  ('ckd', 33, 'A client with chronic kidney disease asks why dietary phosphorus must be limited. Which response by the nurse is accurate?', '[{"id": "a", "text": "To prevent bone disease"}, {"id": "b", "text": "To prevent fluid retention"}, {"id": "c", "text": "To prevent heart rhythm problems"}, {"id": "d", "text": "To prevent muscle wasting"}]'::jsonb, '["a"]', 'A low-phosphorus diet prevents bone disease. Preventing fluid retention is the purpose of sodium restriction.'),
  ('ckd', 34, 'A client with chronic kidney disease and hypertension asks how limiting salt will help. Which response by the nurse is most accurate?', '[{"id": "a", "text": "It lowers your potassium level."}, {"id": "b", "text": "It reduces fluid retention and blood pressure."}, {"id": "c", "text": "It reduces the buildup of BUN."}, {"id": "d", "text": "It strengthens your bones."}]'::jsonb, '["b"]', 'A low-sodium diet reduces fluid retention and blood pressure. Reducing BUN buildup is the purpose of protein restriction.'),
  ('ckd', 35, 'A client with chronic kidney disease on a protein-restricted diet asks why the dietitian also recommends a high-calorie intake. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "To increase red blood cell production"}, {"id": "b", "text": "To lower the blood pressure"}, {"id": "c", "text": "To reduce the phosphorus level"}, {"id": "d", "text": "To prevent muscle protein breakdown"}]'::jsonb, '["d"]', 'A high-calorie diet prevents protein catabolism and muscle wasting. Increasing red blood cell production is the role of EPO, not calories.'),
  ('ckd', 36, 'The nurse is caring for four clients with chronic kidney disease. For which client does the nurse anticipate a prescription for fluid restriction?', '[{"id": "a", "text": "A client with Stage 1 CKD and proteinuria"}, {"id": "b", "text": "A client with Stage 2 CKD and no symptoms"}, {"id": "c", "text": "A client receiving dialysis for Stage 5 CKD"}, {"id": "d", "text": "A client with early CKD and no edema"}]'::jsonb, '["c"]', 'Fluid restriction is indicated for clients on dialysis or with severe overload. Clients in Stages 1 and 2 are often asymptomatic and are managed by controlling the underlying disease and lifestyle.'),
  ('ckd', 37, 'A client with chronic kidney disease monitors weight at home. Which weight change should the client report to the health care provider?', '[{"id": "a", "text": "A gain of 3 lb since yesterday"}, {"id": "b", "text": "A gain of 1 lb since yesterday"}, {"id": "c", "text": "A loss of 1 lb over 1 week"}, {"id": "d", "text": "No change over 3 days"}]'::jsonb, '["a"]', 'Sudden weight gain greater than 2 lb per day should be reported. A 1-lb gain in a day does not exceed this threshold.'),
  ('ckd', 38, 'The nurse teaches a client with chronic kidney disease when to contact the health care provider. Which statement by the client indicates understanding?', '[{"id": "a", "text": "I will call if my weight stays the same each day."}, {"id": "b", "text": "I will call if I become short of breath or swollen."}, {"id": "c", "text": "I will call only if my weight drops by 1 pound."}, {"id": "d", "text": "I will call if I need to take a binder with a meal."}]'::jsonb, '["b"]', 'Clients with CKD should report swelling, shortness of breath, or sudden weight gain over 2 lb/day. A stable weight is not a reason to call.'),
  ('ckd', 39, 'The nurse is preparing a home self-monitoring plan for a client with chronic kidney disease. Which activities should the nurse include?', '[{"id": "a", "text": "Weekly weight and monthly blood pressure"}, {"id": "b", "text": "Daily weight and daily blood pressure"}, {"id": "c", "text": "Daily blood glucose and weekly weight"}, {"id": "d", "text": "Monthly weight and weekly blood pressure"}]'::jsonb, '["b"]', 'Clients with CKD should monitor daily weight and blood pressure at home. Weekly or monthly checks are less frequent than the daily monitoring recommended.'),
  ('ckd', 40, 'A client with Stage 3 chronic kidney disease tells the nurse about plans for follow-up care. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will skip my lab appointments when I feel fine."}, {"id": "b", "text": "I will check my blood pressure at home every day."}, {"id": "c", "text": "I will weigh myself at home each day."}, {"id": "d", "text": "I will avoid taking ibuprofen for my aches."}]'::jsonb, '["a"]', 'Clients should keep all follow-up lab appointments for BMP, CBC, and GFR monitoring. Daily BP and weight checks and avoiding NSAIDs are correct.'),
  ('ckd', 41, 'The nurse teaches a client with Stage 4 chronic kidney disease about signs of uremia. Which group of symptoms should the client report?', '[{"id": "a", "text": "Confusion, bad breath, nausea, and worsening fatigue"}, {"id": "b", "text": "Increased appetite, energy, and urine output"}, {"id": "c", "text": "Weight loss, dry mouth, and low blood pressure"}, {"id": "d", "text": "Flushed skin, fast pulse, and frequent urination"}]'::jsonb, '["a"]', 'Signs of uremia to report include confusion, bad breath, nausea, and worsening fatigue. Increased energy and appetite are not signs of uremia.'),
  ('ckd', 42, 'A client with Stage 4 chronic kidney disease says, ''I''ll wait until my kidneys completely fail before I think about dialysis or a transplant.'' Which response by the nurse is most appropriate?', '[{"id": "a", "text": "That is reasonable, since planning is only needed at Stage 5."}, {"id": "b", "text": "Planning should begin well before you reach Stage 5."}, {"id": "c", "text": "That is reasonable, since dialysis is rarely needed in CKD."}, {"id": "d", "text": "Planning can wait until you have signs of uremia."}]'::jsonb, '["b"]', 'Planning for dialysis or transplant should begin well before Stage 5, and Stage 4 includes dialysis/transplant education. Waiting until Stage 5 delays needed preparation.'),
  ('ckd', 43, 'A client has a GFR of 35 mL/min. Which laboratory values should the nurse plan to monitor closely at this stage of chronic kidney disease?', '[{"id": "a", "text": "Potassium and phosphorus"}, {"id": "b", "text": "Sodium and glucose"}, {"id": "c", "text": "Magnesium and chloride"}, {"id": "d", "text": "Albumin and bilirubin"}]'::jsonb, '["a"]', 'A GFR of 30–59 is Stage 3, when potassium and phosphorus are monitored and nephrotoxins are avoided. The other lab pairs are not identified as Stage 3 priorities.'),
  ('ckd', 44, 'A client with a GFR of 50 mL/min asks which complications may start to develop at this stage of chronic kidney disease. Which response by the nurse is most accurate?', '[{"id": "a", "text": "Uremic frost and encephalopathy"}, {"id": "b", "text": "Anemia and bone disease"}, {"id": "c", "text": "Complete loss of kidney function"}, {"id": "d", "text": "No complications at this stage"}]'::jsonb, '["b"]', 'In Stage 3 (GFR 30–59), anemia and bone disease may begin. Uremic frost is a finding of ESRD, not Stage 3.'),
  ('ckd', 45, 'A client with chronic kidney disease says, ''Since I take a phosphate binder now, I don''t have to follow my diet restrictions anymore.'' Which response by the nurse is most appropriate?', '[{"id": "a", "text": "That is correct; the binder replaces the need for diet changes."}, {"id": "b", "text": "That is correct, but you should still limit your sodium."}, {"id": "c", "text": "You still need to strictly limit potassium, phosphorus, and sodium."}, {"id": "d", "text": "You only need to limit protein while taking the binder."}]'::jsonb, '["c"]', 'Clients with CKD must adhere strictly to a low potassium, phosphorus, and sodium diet. Limiting sodium alone leaves out the potassium and phosphorus restrictions.'),
  ('ckd', 46, 'The nurse receives report that a client with chronic kidney disease has an elevated serum potassium level. Which action should the nurse take first?', '[{"id": "a", "text": "Offer the client a high-calorie snack"}, {"id": "b", "text": "Administer the scheduled phosphate binder"}, {"id": "c", "text": "Weigh the client on the bed scale"}, {"id": "d", "text": "Place the client on a cardiac monitor"}]'::jsonb, '["d"]', 'Hyperkalemia causes arrhythmias, so the client needs cardiac monitoring. Weighing the client assesses fluid status but does not address the cardiac risk of high potassium.'),
  ('ckd', 47, 'A client with Stage 5 chronic kidney disease reports a poor appetite, nausea, and a metallic taste in the mouth. The nurse recognizes these symptoms as manifestations of which condition?', '[{"id": "a", "text": "Anemia"}, {"id": "b", "text": "Hypocalcemia"}, {"id": "c", "text": "Uremia"}, {"id": "d", "text": "Hyperkalemia"}]'::jsonb, '["c"]', 'Metallic taste, anorexia, and nausea/vomiting are manifestations of uremia. Anemia causes fatigue, weakness, and pallor rather than these GI symptoms.'),
  ('ckd', 48, 'The nurse is assessing a client with Stage 4 chronic kidney disease for fluid retention. Which areas should the nurse inspect for edema?', '[{"id": "a", "text": "Legs, ankles, and face"}, {"id": "b", "text": "Hands and fingertips only"}, {"id": "c", "text": "The abdomen only"}, {"id": "d", "text": "The scalp and neck"}]'::jsonb, '["a"]', 'Edema from fluid retention in late CKD occurs in the legs, ankles, and face. Limiting the assessment to the hands or abdomen would miss these sites.'),
  ('ckd', 49, 'A client with diabetes and chronic kidney disease takes an ACE inhibitor. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "This medicine helps control my blood pressure."}, {"id": "b", "text": "This medicine can help slow my kidney disease."}, {"id": "c", "text": "This medicine can reduce protein in my urine."}, {"id": "d", "text": "This medicine only treats my blood pressure."}]'::jsonb, '["d"]', 'ACE inhibitors control BP but also reduce proteinuria and slow CKD progression, so they do more than treat blood pressure. The other statements correctly describe these benefits.'),
  ('ckd', 50, 'A nursing student is preparing medications for a client with chronic kidney disease. Which plan by the student requires correction by the nurse?', '[{"id": "a", "text": "Giving the phosphate binder with the lunch tray"}, {"id": "b", "text": "Giving the phosphate binder at bedtime"}, {"id": "c", "text": "Checking the latest BMP before giving medications"}, {"id": "d", "text": "Holding a prescribed NSAID and notifying the provider"}]'::jsonb, '["b"]', 'Phosphate binders are given with meals, not at bedtime, so they can bind dietary phosphate. Holding an NSAID is appropriate because NSAIDs are avoided in CKD.'),
  ('dialysis', 1, 'A nurse is assessing a client''s left forearm arteriovenous (AV) fistula at the start of the shift. Which finding indicates the fistula is patent?', '[{"id": "a", "text": "No vibration on palpation and no sound on auscultation"}, {"id": "b", "text": "A vibration on palpation and a whooshing sound on auscultation"}, {"id": "c", "text": "No vibration on palpation but a whooshing sound on auscultation"}, {"id": "d", "text": "A vibration on palpation but no sound on auscultation"}]'::jsonb, '["b"]', 'A patent fistula has a palpable thrill (vibration/buzzing from blood flow) and an audible bruit (whooshing sound). Absence of these findings suggests a possible clot.'),
  ('dialysis', 2, 'A nurse cannot palpate a thrill or auscultate a bruit over a client''s AV fistula. Which action should the nurse take first?', '[{"id": "a", "text": "Reassess the fistula at the next scheduled dialysis"}, {"id": "b", "text": "Document the finding as expected for a mature fistula"}, {"id": "c", "text": "Notify the provider immediately of a possible clot"}, {"id": "d", "text": "Measure the blood pressure in the fistula arm"}]'::jsonb, '["c"]', 'Absence of a thrill and bruit indicates a possible clot, so the provider must be notified stat. Waiting to reassess delays care, and blood pressure must never be measured on the fistula arm.'),
  ('dialysis', 3, 'A charge nurse observes an unlicensed assistive personnel (UAP) caring for a client with a right forearm AV fistula. Which action by the UAP requires correction?', '[{"id": "a", "text": "Weighing the client before the dialysis treatment"}, {"id": "b", "text": "Helping the client remove a tight ring from the right hand"}, {"id": "c", "text": "Measuring blood pressure on the client''s left arm"}, {"id": "d", "text": "Measuring blood pressure on the client''s right arm"}]'::jsonb, '["d"]', 'No blood pressure measurements are permitted on the fistula arm because this may damage or occlude the access. Removing tight jewelry from the fistula arm is appropriate.'),
  ('dialysis', 4, 'A nurse teaches a client with a new AV fistula how to protect the access. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I can keep wearing my snug wristwatch on my fistula arm."}, {"id": "b", "text": "I will report it if I can no longer feel the vibration."}, {"id": "c", "text": "I will check for the buzzing feeling over my fistula."}, {"id": "d", "text": "I will remind staff not to draw blood from that arm."}]'::jsonb, '["a"]', 'Tight clothing or jewelry on the fistula arm may damage or occlude the access. Checking for the thrill, refusing blood draws on that arm, and reporting a lost thrill are correct.'),
  ('dialysis', 5, 'A client with a right forearm AV fistula needs blood drawn for laboratory tests. Which site should the nurse select?', '[{"id": "a", "text": "A vein in the right hand"}, {"id": "b", "text": "A vein in the right upper arm"}, {"id": "c", "text": "The right antecubital vein"}, {"id": "d", "text": "A vein in the left arm"}]'::jsonb, '["d"]', 'Blood draws are prohibited anywhere on the fistula arm because they may damage or occlude the access, so the nonfistula arm is used.'),
  ('dialysis', 6, 'A client asks why the surgeon recommends an AV fistula rather than an AV graft for hemodialysis. Which response by the nurse is accurate?', '[{"id": "a", "text": "A fistula has a higher clotting risk but is easier to place."}, {"id": "b", "text": "A fistula lasts longest and has the lowest infection risk."}, {"id": "c", "text": "A fistula is a synthetic tube that can be used right away."}, {"id": "d", "text": "A fistula is a temporary catheter placed in a large neck vein."}]'::jsonb, '["b"]', 'The AV fistula is the preferred access because it is the longest lasting with the lowest infection risk. A synthetic tube with higher clotting risk describes a graft.'),
  ('dialysis', 7, 'A client had an AV fistula created in the forearm yesterday and asks when it can be used for hemodialysis. The nurse should explain that the fistula usually needs how long to mature?', '[{"id": "a", "text": "24 hours"}, {"id": "b", "text": "1 week"}, {"id": "c", "text": "6 to 8 weeks"}, {"id": "d", "text": "6 to 8 months"}]'::jsonb, '["c"]', 'An AV fistula takes 6–8 weeks to mature before it can be used; a central venous catheter may be used while it matures.'),
  ('dialysis', 8, 'A client whose AV fistula was created 2 weeks ago now requires emergency hemodialysis. Which vascular access does the nurse anticipate will be used?', '[{"id": "a", "text": "A central venous catheter"}, {"id": "b", "text": "The newly created AV fistula"}, {"id": "c", "text": "A peritoneal catheter"}, {"id": "d", "text": "A synthetic AV graft"}]'::jsonb, '["a"]', 'A central venous catheter is the temporary access used in emergencies or while a fistula matures; the fistula needs 6–8 weeks to mature, and a peritoneal catheter is used for PD, not HD.'),
  ('dialysis', 9, 'A nurse is caring for four clients receiving hemodialysis. Which client''s vascular access carries the highest risk of infection?', '[{"id": "a", "text": "A client with a jugular central venous catheter"}, {"id": "b", "text": "A client with a mature AV fistula in the forearm"}, {"id": "c", "text": "A client with an AV fistula used for 2 years"}, {"id": "d", "text": "A client with a synthetic AV graft in the forearm"}]'::jsonb, '["a"]', 'The central venous catheter has the highest infection risk of the access types. A graft has a higher risk than a fistula, but the fistula has the lowest risk.'),
  ('dialysis', 10, 'A client with inadequate veins has an AV graft placed for hemodialysis. Which client statement indicates understanding of the access?', '[{"id": "a", "text": "My graft has the lowest infection risk of any dialysis access."}, {"id": "b", "text": "My graft is an artificial tube with a higher clotting risk than a fistula."}, {"id": "c", "text": "My graft is made from my own artery and vein joined together."}, {"id": "d", "text": "My graft is a temporary catheter until my fistula is ready."}]'::jsonb, '["b"]', 'An AV graft is a synthetic tube used when veins aren''t adequate and has higher infection and clotting risk than a fistula. The fistula, not the graft, joins the client''s own artery and vein and has the lowest infection risk.'),
  ('dialysis', 11, 'A client scheduled for hemodialysis at 0900 has an oral antihypertensive medication due at 0800. Which action should the nurse take?', '[{"id": "a", "text": "Withhold the medication before the dialysis treatment"}, {"id": "b", "text": "Administer a double dose to prevent high blood pressure"}, {"id": "c", "text": "Administer the medication as scheduled with a sip of water"}, {"id": "d", "text": "Administer the medication during the dialysis treatment"}]'::jsonb, '["a"]', 'Antihypertensives are held before HD because blood pressure drops significantly during dialysis, creating a risk of hypotension.'),
  ('dialysis', 12, 'A nurse is reviewing teaching with a client who receives hemodialysis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will let the staff check my fistula for the buzz and the whoosh."}, {"id": "b", "text": "I know that my blood pressure may drop during the treatment."}, {"id": "c", "text": "I will take my blood pressure pill right before I leave for dialysis."}, {"id": "d", "text": "I will not let anyone take my blood pressure on my fistula arm."}]'::jsonb, '["c"]', 'Antihypertensives should be held before HD because hypotension is the most common complication. Thrill and bruit checks and avoiding BP measurement on the fistula arm are correct.'),
  ('dialysis', 13, 'Before a client''s hemodialysis treatment, the nurse weighs the client. To which value should the nurse compare this weight?', '[{"id": "a", "text": "The last pre-dialysis weight"}, {"id": "b", "text": "The client''s reported usual weight"}, {"id": "c", "text": "The last post-dialysis dry weight"}, {"id": "d", "text": "The weight recorded on admission"}]'::jsonb, '["c"]', 'Pre-dialysis weight is compared with the last post-dialysis dry weight, which is the target weight with no edema or fluid overload.'),
  ('dialysis', 14, 'Which set of assessments should the nurse complete before initiating a client''s hemodialysis treatment?', '[{"id": "a", "text": "Thrill over the access, an antihypertensive dose, and baseline vital signs"}, {"id": "b", "text": "Weight, thrill and bruit over the access, and baseline vital signs"}, {"id": "c", "text": "Weight, blood pressure in the fistula arm, and a fistula-arm blood draw"}, {"id": "d", "text": "Baseline vital signs, peritoneal outflow color, and outflow volume"}]'::jsonb, '["b"]', 'Before HD the nurse assesses weight, the access site for thrill and bruit, and baseline vital signs. Antihypertensives are held, and BP or blood draws on the fistula arm are prohibited.'),
  ('dialysis', 15, 'During hemodialysis, a client becomes lightheaded and the blood pressure drops markedly from baseline. Which action should the nurse take?', '[{"id": "a", "text": "Slow the dialysis rate and place the client supine"}, {"id": "b", "text": "Administer the client''s scheduled antihypertensive"}, {"id": "c", "text": "Continue the current rate and recheck in 1 hour"}, {"id": "d", "text": "Raise the head of the bed and increase the dialysis rate"}]'::jsonb, '["a"]', 'Hypotension during HD is managed by slowing the rate, placing the client supine, and giving an NS bolus if needed. Increasing the rate or giving an antihypertensive would worsen hypotension.'),
  ('dialysis', 16, 'A client receiving hemodialysis asks why the blood pressure tends to drop during treatment. The nurse''s response should be based on which cause?', '[{"id": "a", "text": "Clot formation within the fistula"}, {"id": "b", "text": "Rapid removal of fluid during the treatment"}, {"id": "c", "text": "Infection introduced at the access site"}, {"id": "d", "text": "Rising potassium levels during the session"}]'::jsonb, '["b"]', 'Hypotension, the most common HD complication, is due to rapid fluid removal. Potassium is removed, not increased, during each session.'),
  ('dialysis', 17, 'During a client''s hemodialysis session, the client reports a headache, becomes restless, and appears confused. The nurse should recognize these findings as which complication?', '[{"id": "a", "text": "Peritonitis"}, {"id": "b", "text": "Access site bleeding"}, {"id": "c", "text": "Access site clotting"}, {"id": "d", "text": "Disequilibrium syndrome"}]'::jsonb, '["d"]', 'Disequilibrium syndrome causes headache, confusion, restlessness, and nausea from rapid fluid shifts in the brain. Peritonitis is a PD complication marked by cloudy outflow.'),
  ('dialysis', 18, 'A nurse suspects disequilibrium syndrome in a client receiving hemodialysis. Which action should the nurse take?', '[{"id": "a", "text": "Warm the dialysate to body temperature"}, {"id": "b", "text": "Increase the treatment rate to finish sooner"}, {"id": "c", "text": "Administer the client''s held antihypertensive"}, {"id": "d", "text": "Slow the treatment rate and provide supportive care"}]'::jsonb, '["d"]', 'Disequilibrium syndrome is managed by slowing the treatment rate and providing supportive care. Increasing the rate would worsen the rapid fluid shifts; warming dialysate applies to PD.'),
  ('dialysis', 19, 'One hour after completing hemodialysis, a client reports a headache and nausea and seems confused. How should the nurse interpret these findings?', '[{"id": "a", "text": "Early signs of peritonitis from the access"}, {"id": "b", "text": "Possible disequilibrium syndrome after treatment"}, {"id": "c", "text": "Expected fatigue that requires no follow-up"}, {"id": "d", "text": "A sign that the fistula has fully matured"}]'::jsonb, '["b"]', 'Disequilibrium syndrome causes headache, confusion, and nausea and can occur during or after HD. Peritonitis is a complication of PD.'),
  ('dialysis', 20, 'During hemodialysis, which finding should the nurse recognize as a complication to monitor for?', '[{"id": "a", "text": "Muscle cramps"}, {"id": "b", "text": "Rising blood pressure"}, {"id": "c", "text": "Cloudy dialysate outflow"}, {"id": "d", "text": "Weight gain during treatment"}]'::jsonb, '["a"]', 'Muscle cramps are a complication monitored during HD. Blood pressure drops rather than rises, fluid is removed so weight decreases, and cloudy outflow signals peritonitis in PD.'),
  ('dialysis', 21, 'After the dialysis needles are removed, a client''s fistula access site continues to ooze blood. Which action should the nurse take?', '[{"id": "a", "text": "Apply direct pressure to the site"}, {"id": "b", "text": "Leave the site open to air and recheck later"}, {"id": "c", "text": "Apply a tourniquet above the access"}, {"id": "d", "text": "Wrap the arm tightly with an elastic bandage"}]'::jsonb, '["a"]', 'Bleeding at the access site is managed by applying pressure. Tight wraps or constriction on the fistula arm may damage or occlude the access.'),
  ('dialysis', 22, 'A client who returned from hemodialysis 30 minutes ago reports dizziness when standing. Which assessment is the nurse''s priority?', '[{"id": "a", "text": "Thrill over the access"}, {"id": "b", "text": "Serum potassium"}, {"id": "c", "text": "Blood pressure"}, {"id": "d", "text": "Daily weight"}]'::jsonb, '["c"]', 'After HD the nurse monitors BP because it may still be low post-procedure, which fits the client''s dizziness on standing.'),
  ('dialysis', 23, 'Which action should the nurse take after a client completes hemodialysis?', '[{"id": "a", "text": "Measure blood pressure on the fistula arm"}, {"id": "b", "text": "Wrap the fistula arm tightly overnight"}, {"id": "c", "text": "Assess the access site for bleeding or hematoma"}, {"id": "d", "text": "Draw post-treatment labs from the fistula arm"}]'::jsonb, '["c"]', 'After HD the access site is assessed for bleeding or hematoma. Blood draws, BP measurements, and tight wraps on the fistula arm may damage or occlude the access.'),
  ('dialysis', 24, 'A client receiving hemodialysis asks what the term dry weight means. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The weight recorded the day dialysis first started"}, {"id": "b", "text": "The target weight with no edema or fluid overload"}, {"id": "c", "text": "The weight at which fluid overload is present"}, {"id": "d", "text": "The weight measured before each treatment begins"}]'::jsonb, '["b"]', 'Dry weight is the post-dialysis target reached by removing fluid each HD session, with no edema and no fluid overload. The pre-treatment weight is compared against it.'),
  ('dialysis', 25, 'Which laboratory trend best indicates that a client''s hemodialysis is providing adequate treatment?', '[{"id": "a", "text": "Potassium rises above 5.0 after each session"}, {"id": "b", "text": "BUN decreases while creatinine steadily climbs"}, {"id": "c", "text": "BUN and creatinine increase after each session"}, {"id": "d", "text": "BUN and creatinine decrease after each session"}]'::jsonb, '["d"]', 'Dialysis removes waste, so reduced BUN and creatinine with each session indicate effective clearance. Potassium is also removed with each session.'),
  ('dialysis', 26, 'A nurse reviews post-dialysis potassium levels for four clients. Which result indicates the treatment goal has been met?', '[{"id": "a", "text": "4.3 mEq/L"}, {"id": "b", "text": "5.8 mEq/L"}, {"id": "c", "text": "6.2 mEq/L"}, {"id": "d", "text": "7.1 mEq/L"}]'::jsonb, '["a"]', 'The potassium goal on dialysis is a reduced level within the normal range of 3.5–5.0 to prevent cardiac arrhythmias; the other values remain above normal.'),
  ('dialysis', 27, 'A client receiving dialysis asks why erythropoietin (EPO) has been prescribed. Which response by the nurse is accurate?', '[{"id": "a", "text": "It helps remove waste products from your blood."}, {"id": "b", "text": "It prevents clots from forming in your fistula."}, {"id": "c", "text": "It lowers your potassium level between treatments."}, {"id": "d", "text": "It corrects the anemia caused by kidney disease."}]'::jsonb, '["d"]', 'EPO therapy corrects the anemia of CKD. Over-correction of hemoglobin actually leads to clots, so EPO does not prevent clotting.'),
  ('dialysis', 28, 'A nurse reviews hemoglobin results for four clients receiving EPO with dialysis. Which result should the nurse report?', '[{"id": "a", "text": "10.4 g/dL"}, {"id": "b", "text": "11.0 g/dL"}, {"id": "c", "text": "11.8 g/dL"}, {"id": "d", "text": "14.2 g/dL"}]'::jsonb, '["d"]', 'The target hemoglobin with EPO is 10–12 g/dL; 14.2 g/dL indicates over-correction, which should be avoided because it leads to clots.'),
  ('dialysis', 29, 'A nurse is reviewing the glomerular filtration rates (GFR) of four clients with chronic kidney disease. Which client is at the stage when dialysis is initiated?', '[{"id": "a", "text": "GFR of 12"}, {"id": "b", "text": "GFR of 25"}, {"id": "c", "text": "GFR of 40"}, {"id": "d", "text": "GFR of 58"}]'::jsonb, '["a"]', 'Dialysis is initiated at CKD Stage 5, defined by a GFR below 15; the other clients have GFRs above this threshold.'),
  ('dialysis', 30, 'A client with chronic kidney disease who has had episodes of unstable blood pressure asks which type of dialysis is gentler. Which response by the nurse is accurate?', '[{"id": "a", "text": "Peritoneal dialysis, because it offers better hemodynamic stability"}, {"id": "b", "text": "Hemodialysis, because it removes fluid more rapidly"}, {"id": "c", "text": "Peritoneal dialysis, because it removes waste more rapidly"}, {"id": "d", "text": "Hemodialysis, because it uses an external dialyzer"}]'::jsonb, '["a"]', 'PD is slower and gentler with better hemodynamic stability. HD provides rapid fluid and waste removal, which is not gentler.'),
  ('dialysis', 31, 'A nurse teaches a client who is starting in-center hemodialysis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will usually go for treatment three times a week."}, {"id": "b", "text": "Each of my treatments will last about 30 minutes."}, {"id": "c", "text": "My blood will be returned to me after it is filtered."}, {"id": "d", "text": "My blood will be filtered through an artificial kidney."}]'::jsonb, '["b"]', 'HD is done 3 times per week for 3–5 hours per session, not 30 minutes. Blood is removed, filtered through a dialyzer (artificial kidney), and returned.'),
  ('dialysis', 32, 'A client beginning peritoneal dialysis asks what filters the blood during treatment. Which structure should the nurse identify?', '[{"id": "a", "text": "A central venous catheter"}, {"id": "b", "text": "An external dialyzer"}, {"id": "c", "text": "The peritoneal membrane"}, {"id": "d", "text": "An AV fistula"}]'::jsonb, '["c"]', 'In PD, dialysate is instilled into the peritoneal cavity and the peritoneal membrane acts as the filter. The dialyzer and vascular access are used in HD.'),
  ('dialysis', 33, 'A client who works during the day wants peritoneal dialysis exchanges to occur at night while sleeping. Which type of dialysis is most appropriate?', '[{"id": "a", "text": "In-center hemodialysis three times weekly"}, {"id": "b", "text": "Continuous ambulatory peritoneal dialysis (CAPD)"}, {"id": "c", "text": "Automated peritoneal dialysis (APD)"}, {"id": "d", "text": "Hemodialysis through a central venous catheter"}]'::jsonb, '["c"]', 'In APD, a machine (cycler) performs exchanges overnight while the client sleeps. CAPD uses manual exchanges during waking hours.'),
  ('dialysis', 34, 'A nurse teaches a client about continuous ambulatory peritoneal dialysis (CAPD). Which client statement indicates understanding?', '[{"id": "a", "text": "A machine will do my exchanges overnight while I sleep."}, {"id": "b", "text": "I will do manual exchanges 4 to 5 times a day while awake."}, {"id": "c", "text": "I will need a fistula in my arm for the exchanges."}, {"id": "d", "text": "I will go to a dialysis center three times each week."}]'::jsonb, '["b"]', 'CAPD involves manual exchanges 4–5 times per day done at home while awake. Overnight machine exchanges describe APD, and a fistula is HD access.'),
  ('dialysis', 35, 'A nurse observes a nursing student preparing a peritoneal dialysis exchange. Which action by the student requires correction?', '[{"id": "a", "text": "Heating the dialysate bag in a microwave"}, {"id": "b", "text": "Recording the volume of the outflow"}, {"id": "c", "text": "Using strict sterile technique for the connection"}, {"id": "d", "text": "Warming the dialysate to body temperature"}]'::jsonb, '["a"]', 'Dialysate is warmed to body temperature before instilling but must never be microwaved. Sterile technique and recording outflow are correct.'),
  ('dialysis', 36, 'During instillation of peritoneal dialysate, a client reports abdominal cramping. Which factor in the preparation is the most likely cause?', '[{"id": "a", "text": "The dialysate was instilled without being warmed"}, {"id": "b", "text": "The previous outflow was clear and straw-colored"}, {"id": "c", "text": "The dialysate was warmed to body temperature"}, {"id": "d", "text": "The connection was handled with sterile technique"}]'::jsonb, '["a"]', 'Cold dialysate causes cramps, which is why it must be warmed to body temperature before instilling.'),
  ('dialysis', 37, 'A nurse is performing a peritoneal dialysis exchange for a client. Which action is the nurse''s highest priority to prevent peritonitis?', '[{"id": "a", "text": "Repositioning the client from side to side"}, {"id": "b", "text": "Using strict sterile technique throughout"}, {"id": "c", "text": "Recording the outflow volume after draining"}, {"id": "d", "text": "Warming the dialysate in a microwave"}]'::jsonb, '["b"]', 'Strict sterile technique at all times is the #1 priority to prevent peritonitis. Microwaving dialysate is never done.'),
  ('dialysis', 38, 'Which sequence reflects the correct steps of a peritoneal dialysis exchange?', '[{"id": "a", "text": "Drain, instill, dwell, record outflow"}, {"id": "b", "text": "Dwell, instill, record outflow, drain"}, {"id": "c", "text": "Instill, drain, dwell, record outflow"}, {"id": "d", "text": "Instill, dwell, drain, record outflow"}]'::jsonb, '["d"]', 'The PD procedure is to instill dialysate, allow it to dwell, drain it, and then record the outflow.'),
  ('dialysis', 39, 'A nurse reviews peritoneal dialysis outflow findings for four clients. Which finding should the nurse report immediately?', '[{"id": "a", "text": "Cloudy outflow in a client with an established catheter"}, {"id": "b", "text": "Blood-tinged outflow on the second exchange with a new catheter"}, {"id": "c", "text": "Outflow less than inflow that improves after repositioning"}, {"id": "d", "text": "Clear, straw-colored outflow in a client at home"}]'::jsonb, '["a"]', 'Cloudy or turbid outflow indicates peritonitis and is reported immediately. Clear straw-colored outflow is expected, and blood-tinged outflow may be normal with a new catheter.'),
  ('dialysis', 40, 'A client receiving peritoneal dialysis at home reports abdominal pain and fever. The nurse finds rebound tenderness and cloudy outflow. Which complication do these findings indicate?', '[{"id": "a", "text": "Kinked catheter tubing"}, {"id": "b", "text": "Hypotension from fluid removal"}, {"id": "c", "text": "Disequilibrium syndrome"}, {"id": "d", "text": "Peritonitis"}]'::jsonb, '["d"]', 'Cloudy dialysate with abdominal pain, fever, and rebound tenderness are the signs of peritonitis. Kinked tubing reduces outflow volume rather than causing cloudy outflow and fever.'),
  ('dialysis', 41, 'A client receiving peritoneal dialysis has cloudy outflow, fever, and abdominal pain, and the provider has been notified. Which action does the nurse anticipate before antibiotics are started?', '[{"id": "a", "text": "Repositioning the client side to side"}, {"id": "b", "text": "Warming the next bag of dialysate"}, {"id": "c", "text": "Sending the outflow fluid for culture"}, {"id": "d", "text": "Increasing the dwell time of the exchange"}]'::jsonb, '["c"]', 'With signs of peritonitis, the fluid is sent for culture and then IV or intraperitoneal antibiotics are started stat. Repositioning addresses low outflow, not peritonitis.'),
  ('dialysis', 42, 'A client''s peritoneal dialysis catheter was inserted 2 days ago. The outflow from the second exchange is blood-tinged. How should the nurse interpret this finding?', '[{"id": "a", "text": "An indication the dialysate was too cold"}, {"id": "b", "text": "Evidence that the tubing is kinked"}, {"id": "c", "text": "A sign of peritonitis requiring antibiotics"}, {"id": "d", "text": "A finding that may be normal with a new catheter"}]'::jsonb, '["d"]', 'Blood-tinged outflow may be normal for a few exchanges with a new catheter. Peritonitis is signaled by cloudy or turbid outflow, and cold dialysate causes cramps.'),
  ('dialysis', 43, 'During a peritoneal dialysis exchange, the nurse notes the outflow volume is less than the inflow volume. Which action should the nurse take first?', '[{"id": "a", "text": "Keep the client flat and still in bed"}, {"id": "b", "text": "Check the tubing for kinks"}, {"id": "c", "text": "Instill an additional bag of dialysate"}, {"id": "d", "text": "Report suspected peritonitis to the provider"}]'::jsonb, '["b"]', 'When outflow is less than inflow, the nurse checks the tubing for kinks and repositions the client side to side or has the client ambulate. Low outflow alone is not a sign of peritonitis.'),
  ('dialysis', 44, 'A nurse teaches a client on home peritoneal dialysis what to do if less fluid drains out than was instilled. Which client statement indicates understanding?', '[{"id": "a", "text": "I will stop dialysis because this means infection."}, {"id": "b", "text": "I will check for kinks, turn side to side, or walk."}, {"id": "c", "text": "I will instill another full bag of fluid right away."}, {"id": "d", "text": "I will lie flat and stay still until it drains out."}]'::jsonb, '["b"]', 'If outflow is less than inflow, the client checks the tubing for kinks and changes position side to side or ambulates. Lying still does not help drainage, and low outflow alone is not infection.'),
  ('dialysis', 45, 'A nurse teaches a client beginning peritoneal dialysis about complications. Which complication should the nurse identify as the most common and dangerous for this client?', '[{"id": "a", "text": "Disequilibrium syndrome"}, {"id": "b", "text": "Fistula clotting"}, {"id": "c", "text": "Hypotension"}, {"id": "d", "text": "Peritonitis"}]'::jsonb, '["d"]', 'Peritonitis is the most common and dangerous complication of PD. Hypotension is the most common complication of HD, not PD.'),
  ('dialysis', 46, 'A nurse notes erythema and drainage at the insertion site of a client''s hemodialysis central venous catheter. Which action should the nurse take?', '[{"id": "a", "text": "Document the finding as expected for a catheter"}, {"id": "b", "text": "Wait until the next session to report it"}, {"id": "c", "text": "Report the finding to the provider promptly"}, {"id": "d", "text": "Massage the site to promote the drainage"}]'::jsonb, '["c"]', 'Access site infection is monitored for erythema and drainage, which must be reported promptly. The central venous catheter carries the highest infection risk.'),
  ('dialysis', 47, 'A client asks the nurse to describe an AV fistula. Which description is accurate?', '[{"id": "a", "text": "A large catheter placed in the jugular vein"}, {"id": "b", "text": "A surgical connection of an artery and a vein under the skin"}, {"id": "c", "text": "A catheter placed into the peritoneal cavity"}, {"id": "d", "text": "A synthetic tube connecting an artery and a vein"}]'::jsonb, '["b"]', 'An AV fistula is a surgical connection of an artery and vein under the skin, usually in the forearm. A synthetic tube describes an AV graft.'),
  ('dialysis', 48, 'A nurse compares hemodialysis with peritoneal dialysis for a client choosing a modality. Which feature is specific to hemodialysis?', '[{"id": "a", "text": "It is performed by a cycler overnight at home"}, {"id": "b", "text": "It provides slower, gentler fluid removal"}, {"id": "c", "text": "It requires vascular access for blood removal"}, {"id": "d", "text": "It uses the peritoneal membrane as the filter"}]'::jsonb, '["c"]', 'HD removes blood, filters it through a dialyzer, and requires vascular access. The peritoneal membrane, overnight cycler, and slower gentler removal describe PD.'),
  ('dialysis', 49, 'A nurse is caring for a hospitalized client with an AV fistula. How often should the nurse assess the fistula for a thrill and bruit?', '[{"id": "a", "text": "Once a week"}, {"id": "b", "text": "Only before dialysis"}, {"id": "c", "text": "Only if pain is reported"}, {"id": "d", "text": "Every shift"}]'::jsonb, '["d"]', 'The nurse should feel for a thrill and listen for a bruit each shift; absence suggests a possible clot.'),
  ('dialysis', 50, 'A client receiving hemodialysis asks why potassium levels are monitored so closely. Which response by the nurse is accurate?', '[{"id": "a", "text": "High potassium is needed to keep blood pressure stable."}, {"id": "b", "text": "Potassium must rise to support the effects of your EPO."}, {"id": "c", "text": "Keeping potassium normal helps prevent heart rhythm problems."}, {"id": "d", "text": "High potassium is needed to keep the fistula from clotting."}]'::jsonb, '["c"]', 'Potassium is removed with each session and kept in the normal range of 3.5–5.0 to prevent cardiac arrhythmias.'),
  ('dds', 1, 'A client asks what causes dialysis disequilibrium syndrome (DDS). Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Slow urea removal lets toxins build up in the brain over time."}, {"id": "b", "text": "Rapid urea removal shifts water out of the brain, causing shrinkage."}, {"id": "c", "text": "Rapid urea removal shifts water into the brain, causing swelling."}, {"id": "d", "text": "Dialysis adds urea to the blood, which then crosses into the brain."}]'::jsonb, '["c"]', 'Rapid urea removal creates an osmotic shift that moves water into brain cells, causing cerebral edema and increased ICP. Water moves into, not out of, the brain.'),
  ('dds', 2, 'Which statement describes the osmotic relationship between the brain and the blood that develops in DDS?', '[{"id": "a", "text": "The brain remains hypertonic compared to the blood."}, {"id": "b", "text": "The brain and blood quickly reach equal osmolality."}, {"id": "c", "text": "The brain becomes hypotonic compared to the blood."}, {"id": "d", "text": "The blood becomes hypertonic compared to the brain."}]'::jsonb, '["a"]', 'Because urea leaves the brain more slowly than the blood, the brain remains hypertonic compared to blood, drawing water into brain cells.'),
  ('dds', 3, 'A nurse is precepting a new graduate on a hemodialysis unit. Which statement by the new graduate indicates understanding of the cause of DDS?', '[{"id": "a", "text": "DDS results from the dialysis procedure itself, regardless of rate."}, {"id": "b", "text": "DDS results from dialyzing too slowly in a client with a low BUN."}, {"id": "c", "text": "DDS results from dialyzing too fast in a client with very high BUN."}, {"id": "d", "text": "DDS results from an infection introduced at the access site."}]'::jsonb, '["c"]', 'It is not dialysis itself that causes DDS; it is dialyzing too fast in a client with a very high BUN.'),
  ('dds', 4, 'Why does the brain become hypertonic relative to the blood during rapid hemodialysis?', '[{"id": "a", "text": "Urea is returned to the blood faster than it leaves the brain."}, {"id": "b", "text": "Urea clearance from the brain is faster than clearance from the blood."}, {"id": "c", "text": "Water leaves brain cells faster than urea is removed from them."}, {"id": "d", "text": "Urea clearance from the brain lags behind clearance from the blood."}]'::jsonb, '["d"]', 'Rapid HD removes urea from the blood quickly, but urea clearance from the brain lags behind, leaving the brain hypertonic.'),
  ('dds', 5, 'A client in a first hemodialysis session is being monitored for DDS. Which symptom typically appears earliest in the progression?', '[{"id": "a", "text": "Headache"}, {"id": "b", "text": "Blurred vision"}, {"id": "c", "text": "Seizures"}, {"id": "d", "text": "Coma"}]'::jsonb, '["a"]', 'DDS symptoms progress from headache to nausea/vomiting, confusion, seizures, and coma as ICP rises, so headache is the earliest.'),
  ('dds', 6, 'A client with DDS who initially reported a headache and nausea is now restless. Which new finding indicates the most advanced progression?', '[{"id": "a", "text": "Seizure activity"}, {"id": "b", "text": "Blurred vision"}, {"id": "c", "text": "Worsening headache"}, {"id": "d", "text": "Increasing restlessness"}]'::jsonb, '["a"]', 'Symptoms worsen as ICP increases, progressing from headache and nausea through restlessness and blurred vision to seizures and then coma.'),
  ('dds', 7, 'Which sequence reflects the typical progression of DDS symptoms as intracranial pressure rises?', '[{"id": "a", "text": "Confusion, headache, seizures, nausea"}, {"id": "b", "text": "Seizures, confusion, nausea, headache"}, {"id": "c", "text": "Nausea, seizures, headache, confusion"}, {"id": "d", "text": "Headache, nausea, confusion, seizures"}]'::jsonb, '["d"]', 'DDS progresses from headache to nausea/vomiting, then confusion, then seizures, and finally coma.'),
  ('dds', 8, 'Thirty minutes after completing a first hemodialysis session, a client reports a headache and nausea. Which interpretation by the nurse is most accurate?', '[{"id": "a", "text": "DDS is possible because it can occur shortly after dialysis."}, {"id": "b", "text": "DDS is unlikely because it occurs only at the start of dialysis."}, {"id": "c", "text": "DDS is unlikely because symptoms only begin days later."}, {"id": "d", "text": "These are expected effects that need no further assessment."}]'::jsonb, '["a"]', 'DDS occurs during or shortly after dialysis, and the first HD session carries the highest risk, so these symptoms must be evaluated.'),
  ('dds', 9, 'During a client''s hemodialysis session, the client becomes confused and restless. Which action should the nurse take first?', '[{"id": "a", "text": "Continue the current rate and reassess in 30 minutes."}, {"id": "b", "text": "Increase the dialysis rate to finish the session sooner."}, {"id": "c", "text": "Reduce the dialysis rate and notify the provider."}, {"id": "d", "text": "Document the confusion as expected during dialysis."}]'::jsonb, '["c"]', 'Confusion or restlessness during HD is the highest priority: notify the provider and reduce the dialysis rate immediately. The session must not continue at the same rate.'),
  ('dds', 10, 'Which statement by a nurse caring for a client during a first hemodialysis session requires correction?', '[{"id": "a", "text": "Some confusion is expected during a first session."}, {"id": "b", "text": "A new headache during dialysis must be reported."}, {"id": "c", "text": "The client needs frequent neurological checks."}, {"id": "d", "text": "Seizure precautions should be in place for this client."}]'::jsonb, '["a"]', 'Any confusion, headache, or neurological change during dialysis is never normal and requires stopping or slowing dialysis and notifying the provider.'),
  ('dds', 11, 'A client receiving hemodialysis reports a new headache. Another nurse suggests waiting to see whether it resolves before calling the provider. Which response is most appropriate?', '[{"id": "a", "text": "We can reassess the headache at the next session."}, {"id": "b", "text": "We can wait until the session ends to report it."}, {"id": "c", "text": "We can wait one hour and call if it gets worse."}, {"id": "d", "text": "We should alert the provider now instead of waiting."}]'::jsonb, '["d"]', 'The provider should be alerted without waiting to see whether symptoms resolve, because a headache during dialysis may signal DDS.'),
  ('dds', 12, 'A client receiving hemodialysis develops DDS, and the provider prescribes IV mannitol. Which action should the nurse take first?', '[{"id": "a", "text": "Administer the IV mannitol."}, {"id": "b", "text": "Administer IV lorazepam."}, {"id": "c", "text": "Prepare for ICP monitoring."}, {"id": "d", "text": "Slow or stop the dialysis rate."}]'::jsonb, '["d"]', 'Slowing or stopping dialysis is the first action because it reduces ongoing urea removal and the osmotic gradient. Mannitol follows, and lorazepam is for seizures.'),
  ('dds', 13, 'A nurse is assigned four clients receiving hemodialysis. Which client is at highest risk for DDS?', '[{"id": "a", "text": "A client undergoing a first hemodialysis session"}, {"id": "b", "text": "A client completing a routine weekly session"}, {"id": "c", "text": "A client who has received hemodialysis for 3 years"}, {"id": "d", "text": "A client with a modest pre-dialysis BUN level"}]'::jsonb, '["a"]', 'The first hemodialysis session is the most common time for DDS because the body has not adapted.'),
  ('dds', 14, 'Which pre-dialysis laboratory finding most increases a client''s risk for DDS?', '[{"id": "a", "text": "A BUN that has been stable for months"}, {"id": "b", "text": "A low blood urea nitrogen (BUN)"}, {"id": "c", "text": "A very high blood urea nitrogen (BUN)"}, {"id": "d", "text": "A BUN within the client''s usual range"}]'::jsonb, '["c"]', 'A very high pre-dialysis BUN increases risk because the greater the osmotic gradient, the higher the risk.'),
  ('dds', 15, 'A nurse explains to a client why a very high BUN increases the risk of DDS. Which explanation is accurate?', '[{"id": "a", "text": "A higher BUN lowers the osmolality of the brain tissue."}, {"id": "b", "text": "A higher BUN causes water to leave the brain more quickly."}, {"id": "c", "text": "A higher BUN prevents urea from being removed from the blood."}, {"id": "d", "text": "A higher BUN creates a greater osmotic gradient during removal."}]'::jsonb, '["d"]', 'The greater the osmotic gradient created as urea is removed, the higher the risk of water shifting into the brain.'),
  ('dds', 16, 'A 7-year-old child is scheduled for hemodialysis. The parent asks why children are at higher risk for DDS. Which response by the nurse is accurate?', '[{"id": "a", "text": "Children have larger blood volumes, so urea is removed more quickly."}, {"id": "b", "text": "Children clear urea from the brain faster than from the blood."}, {"id": "c", "text": "Children are at lower risk than adults because they adapt quickly."}, {"id": "d", "text": "Children have smaller blood volumes, so fluid shifts have more impact."}]'::jsonb, '["d"]', 'Pediatric clients are high risk because their smaller blood volume makes rapid fluid shifts more impactful.'),
  ('dds', 17, 'Which client receiving hemodialysis is at greatest risk for DDS?', '[{"id": "a", "text": "A 38-year-old completing a routine weekly session"}, {"id": "b", "text": "A 50-year-old with no neurological history after 5 years"}, {"id": "c", "text": "A 45-year-old in a routine session after 2 years of dialysis"}, {"id": "d", "text": "An 80-year-old with a prior head injury in a first session"}]'::jsonb, '["d"]', 'This client has several risk factors: first HD session, older age with reduced compensatory mechanisms, and a pre-existing neurological condition such as head injury.'),
  ('dds', 18, 'An 84-year-old client is beginning hemodialysis. The nurse identifies the client as high risk for DDS for which reason?', '[{"id": "a", "text": "Older adults have larger blood volumes than children."}, {"id": "b", "text": "Older adults have reduced compensatory mechanisms."}, {"id": "c", "text": "Older adults clear urea from the brain more quickly."}, {"id": "d", "text": "Older adults rarely develop neurological complications."}]'::jsonb, '["b"]', 'Elderly clients are at high risk for DDS because of reduced compensatory mechanisms.'),
  ('dds', 19, 'A nurse reviews the history of a client who is about to begin hemodialysis. Which finding increases the client''s risk for DDS?', '[{"id": "a", "text": "A modest pre-dialysis BUN level"}, {"id": "b", "text": "Several years of uneventful hemodialysis"}, {"id": "c", "text": "No previous neurological conditions"}, {"id": "d", "text": "A history of a brain tumor"}]'::jsonb, '["d"]', 'Pre-existing neurological conditions such as head injury or brain tumor increase the risk of DDS.'),
  ('dds', 20, 'A client with a very high BUN is scheduled for a first hemodialysis session. Which prescription should the nurse expect?', '[{"id": "a", "text": "A longer session aimed at complete urea clearance"}, {"id": "b", "text": "A longer session with a higher blood flow rate"}, {"id": "c", "text": "A shorter session with a lower blood flow rate"}, {"id": "d", "text": "A standard session at the maximum blood flow rate"}]'::jsonb, '["c"]', 'Prevention of DDS includes a slower dialysis rate for first sessions, with shorter duration and lower blood flow, rather than complete clearance.'),
  ('dds', 21, 'What is the goal for BUN reduction during a client''s first hemodialysis session to help prevent DDS?', '[{"id": "a", "text": "Complete clearance of all the BUN"}, {"id": "b", "text": "A reduction of about 50% to 60%"}, {"id": "c", "text": "A reduction of about 25% to 30%"}, {"id": "d", "text": "A reduction of about 75% to 80%"}]'::jsonb, '["c"]', 'The first session targets a modest BUN reduction of 25–30%, not complete clearance, to limit the osmotic shift.'),
  ('dds', 22, 'Which statement by a nurse preparing a client for a first hemodialysis session requires correction?', '[{"id": "a", "text": "We should clear as much urea as possible in this session."}, {"id": "b", "text": "This session will be shorter than a routine treatment."}, {"id": "c", "text": "I will perform frequent neurological checks during it."}, {"id": "d", "text": "We will run this session at a lower blood flow rate."}]'::jsonb, '["a"]', 'The first session aims for a modest BUN reduction, not complete clearance, with a shorter duration, lower blood flow, and frequent neurological checks.'),
  ('dds', 23, 'Which dialysate adjustment helps prevent DDS in a high-risk client?', '[{"id": "a", "text": "Increasing the blood flow rate through the dialyzer"}, {"id": "b", "text": "Decreasing the dialysate sodium concentration"}, {"id": "c", "text": "Removing sodium from the dialysate entirely"}, {"id": "d", "text": "Increasing the dialysate sodium concentration"}]'::jsonb, '["d"]', 'Increasing the dialysate sodium concentration slows the osmotic shift. Increasing blood flow would speed urea removal and raise the risk.'),
  ('dds', 24, 'A provider prescribes IV mannitol before a first hemodialysis session for a client with a very high BUN. The nurse understands that the purpose is to:', '[{"id": "a", "text": "Raise the BUN level before dialysis begins"}, {"id": "b", "text": "Prevent cerebral edema in a very high-risk client"}, {"id": "c", "text": "Treat seizures that have already occurred"}, {"id": "d", "text": "Increase the speed of urea removal from the blood"}]'::jsonb, '["b"]', 'Prophylactic mannitol is used for very high-risk clients because it draws water out of the brain, reducing cerebral edema. Seizures are treated with benzodiazepines.'),
  ('dds', 25, 'A client with DDS receives IV mannitol. Which finding best indicates that the medication is effective?', '[{"id": "a", "text": "The client reports a worsening headache."}, {"id": "b", "text": "The client becomes more alert and oriented."}, {"id": "c", "text": "The client develops new blurred vision."}, {"id": "d", "text": "The client has a new seizure."}]'::jsonb, '["b"]', 'Mannitol draws water out of the brain, reducing cerebral edema and ICP. Because symptoms worsen as ICP rises, improved alertness indicates effectiveness.'),
  ('dds', 26, 'A nurse administers hypertonic saline to a client with DDS. Which statement explains how this treatment works?', '[{"id": "a", "text": "It speeds urea removal from the blood during dialysis."}, {"id": "b", "text": "It raises serum osmolality to pull water from brain cells."}, {"id": "c", "text": "It replaces the urea lost from the brain during dialysis."}, {"id": "d", "text": "It lowers serum osmolality to push water into brain cells."}]'::jsonb, '["b"]', 'Hypertonic saline raises serum osmolality, which pulls water from brain cells and treats cerebral edema.'),
  ('dds', 27, 'A client with DDS begins having a seizure during hemodialysis. Which action should the nurse anticipate?', '[{"id": "a", "text": "Increasing the dialysis rate"}, {"id": "b", "text": "Waiting to see whether the seizure stops"}, {"id": "c", "text": "Administering IV lorazepam"}, {"id": "d", "text": "Placing the client in a prone position"}]'::jsonb, '["c"]', 'If seizures occur, anticonvulsants such as IV lorazepam or diazepam are given. The provider should never be delayed to see whether symptoms resolve.'),
  ('dds', 28, 'A client with DDS is vomiting during hemodialysis. In which position should the nurse place the client?', '[{"id": "a", "text": "Prone"}, {"id": "b", "text": "Side-lying"}, {"id": "c", "text": "Supine with the head flat"}, {"id": "d", "text": "Trendelenburg"}]'::jsonb, '["b"]', 'Supportive care for DDS includes placing the client in a side-lying position if vomiting.'),
  ('dds', 29, 'Which set of precautions should the nurse implement for a client at high risk for DDS?', '[{"id": "a", "text": "Side rail padding applied only after a seizure begins"}, {"id": "b", "text": "Padded side rails, suction at bedside, and oxygen available"}, {"id": "c", "text": "Side rails lowered and suction stored outside the room"}, {"id": "d", "text": "Oxygen removed from the room and side rails unpadded"}]'::jsonb, '["b"]', 'Seizure precautions for DDS include padded rails, suction at the bedside, and oxygen available.'),
  ('dds', 30, 'A nurse is caring for clients with suspected DDS. Which finding indicates that dialysis should be discontinued rather than slowed?', '[{"id": "a", "text": "Mild headache"}, {"id": "b", "text": "Restlessness and confusion"}, {"id": "c", "text": "Nausea and vomiting"}, {"id": "d", "text": "Uncontrolled seizures"}]'::jsonb, '["d"]', 'Dialysis is discontinued in severe DDS, such as coma or uncontrolled seizures, which requires emergency management. Earlier symptoms call for slowing the rate and notifying the provider.'),
  ('dds', 31, 'A client develops severe DDS during hemodialysis. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "Intracranial pressure monitoring"}, {"id": "b", "text": "Extending the session for full clearance"}, {"id": "c", "text": "Administering hypotonic IV fluids"}, {"id": "d", "text": "Increasing the blood flow rate"}]'::jsonb, '["a"]', 'ICP monitoring is used if DDS is severe. Increasing the flow rate or aiming for full clearance would worsen the osmotic shift.'),
  ('dds', 32, 'A nurse is monitoring a high-risk client during a first hemodialysis session. Which assessment is the priority throughout the session?', '[{"id": "a", "text": "Neurological status and level of consciousness"}, {"id": "b", "text": "Appetite, oral intake, and meal preferences"}, {"id": "c", "text": "Skin turgor and condition of the forearm skin"}, {"id": "d", "text": "Bowel sounds and abdominal girth measurement"}]'::jsonb, '["a"]', 'Vital signs, neurological status, and LOC are monitored throughout the session to detect DDS early.'),
  ('dds', 33, 'Before a first hemodialysis session for a client at high risk for DDS, which medications should the nurse ensure are available?', '[{"id": "a", "text": "Dextrose and hypotonic saline"}, {"id": "b", "text": "Hypotonic saline and free water"}, {"id": "c", "text": "Potassium and hypotonic saline"}, {"id": "d", "text": "Mannitol and hypertonic saline"}]'::jsonb, '["d"]', 'Mannitol and hypertonic saline should be kept available for high-risk clients because both pull water out of the brain.'),
  ('dds', 34, 'A nurse teaches the family of a client starting hemodialysis about DDS. Which family statement indicates understanding?', '[{"id": "a", "text": "If he gets a headache, we will let him sleep it off during dialysis."}, {"id": "b", "text": "If he seems restless, it is just nerves from his first session."}, {"id": "c", "text": "If he gets a headache or is confused, we will tell the nurse right away."}, {"id": "d", "text": "If he becomes confused, we will wait to see whether it passes."}]'::jsonb, '["c"]', 'The client and family are taught that headache or confusion during dialysis must be reported immediately.'),
  ('dds', 35, 'A nurse teaches a client about warning signs during hemodialysis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will report it if I start to feel confused during treatment."}, {"id": "b", "text": "A headache during dialysis is normal, so I will just rest."}, {"id": "c", "text": "I will tell staff if my vision becomes blurred during dialysis."}, {"id": "d", "text": "I will tell the nurse if I get a headache during dialysis."}]'::jsonb, '["b"]', 'A headache during dialysis is never normal and must be reported immediately because it can signal DDS.'),
  ('dds', 36, 'A nurse is supervising the care of a client during hemodialysis. Which action requires correction?', '[{"id": "a", "text": "Checking neurological status only at the end of the session"}, {"id": "b", "text": "Keeping suction equipment at the bedside"}, {"id": "c", "text": "Assessing level of consciousness during the session"}, {"id": "d", "text": "Monitoring vital signs throughout the session"}]'::jsonb, '["a"]', 'Neurological assessment must be continuous during all dialysis sessions, not only at the end. Monitoring vitals and LOC and keeping suction at the bedside are correct.'),
  ('dds', 37, 'A client who has received hemodialysis for 4 years asks why the nurse keeps checking orientation during treatment. Which response is accurate?', '[{"id": "a", "text": "Neurological checks are done because confusion is expected."}, {"id": "b", "text": "Neurological checks are needed only during the first session."}, {"id": "c", "text": "Neurological checks are done during every dialysis session."}, {"id": "d", "text": "Neurological checks are done only for children on dialysis."}]'::jsonb, '["c"]', 'Continuous neurological assessment is performed during all dialysis sessions, not only first sessions, and confusion during dialysis is never normal.'),
  ('dds', 38, 'Which sequence correctly describes the development of DDS?', '[{"id": "a", "text": "Increased ICP, cerebral edema, osmotic shift, rapid urea removal"}, {"id": "b", "text": "Rapid urea removal, osmotic shift, cerebral edema, increased ICP"}, {"id": "c", "text": "Cerebral edema, rapid urea removal, increased ICP, osmotic shift"}, {"id": "d", "text": "Osmotic shift, increased ICP, rapid urea removal, cerebral edema"}]'::jsonb, '["b"]', 'Rapid urea removal creates an osmotic shift, water enters the brain causing cerebral edema, and ICP rises.'),
  ('dds', 39, 'During a first hemodialysis session, a client becomes restless and reports blurred vision. Which explanation for these findings is most likely?', '[{"id": "a", "text": "Fatigue from the length of the session"}, {"id": "b", "text": "Cerebral edema from rapid urea removal"}, {"id": "c", "text": "Expected anxiety about a first session"}, {"id": "d", "text": "A normal adjustment that resolves alone"}]'::jsonb, '["b"]', 'Restlessness and blurred vision during dialysis are DDS symptoms caused by water moving into brain cells, producing cerebral edema; neurological change during dialysis is never normal.'),
  ('dds', 40, 'A nurse prepares to administer mannitol to a client with DDS. Which statement describes the action of this medication?', '[{"id": "a", "text": "An osmotic diuretic that draws water out of the brain"}, {"id": "b", "text": "A diuretic that speeds urea removal by the dialyzer"}, {"id": "c", "text": "A hypotonic solution that moves water into the brain"}, {"id": "d", "text": "An anticonvulsant that stops seizure activity"}]'::jsonb, '["a"]', 'Mannitol is an osmotic diuretic that draws water out of the brain, reducing cerebral edema and ICP. Anticonvulsants such as lorazepam treat seizures.'),
  ('dds', 41, 'A 9-year-old child is scheduled for a first hemodialysis session. Which plan best reduces the risk of DDS?', '[{"id": "a", "text": "A higher blood flow rate and a shorter session"}, {"id": "b", "text": "A lower blood flow rate and a shorter session"}, {"id": "c", "text": "A higher blood flow rate for complete clearance"}, {"id": "d", "text": "A standard adult rate and a longer session"}]'::jsonb, '["b"]', 'First-time clients, including high-risk pediatric clients, receive a lower blood flow rate and shorter duration to allow gradual urea removal.'),
  ('dds', 42, 'A client asks why the nurse slowed the dialysis machine after the client reported a headache. Which response by the nurse is accurate?', '[{"id": "a", "text": "Slowing is a routine step that is unrelated to the headache."}, {"id": "b", "text": "Slowing allows more fluid to move into the brain cells."}, {"id": "c", "text": "Slowing reduces ongoing urea removal and the osmotic gradient."}, {"id": "d", "text": "Slowing increases urea removal so the headache will resolve."}]'::jsonb, '["c"]', 'Slowing or stopping dialysis is the first action for DDS because it reduces ongoing urea removal and the osmotic gradient.'),
  ('dds', 43, 'A client with DDS is receiving 3% sodium chloride. Which laboratory change reflects the intended effect?', '[{"id": "a", "text": "Increased blood urea nitrogen"}, {"id": "b", "text": "Unchanged serum osmolality"}, {"id": "c", "text": "Increased serum osmolality"}, {"id": "d", "text": "Decreased serum osmolality"}]'::jsonb, '["c"]', 'Hypertonic 3% saline works by raising serum osmolality, which pulls water from brain cells.'),
  ('dds', 44, 'A client develops restlessness and confusion from DDS during hemodialysis. Which supportive intervention should the nurse implement?', '[{"id": "a", "text": "Increase the blood flow rate"}, {"id": "b", "text": "Remove suction from the bedside"}, {"id": "c", "text": "Provide oxygen therapy"}, {"id": "d", "text": "Place the client in a prone position"}]'::jsonb, '["c"]', 'Supportive care for DDS includes oxygen therapy, side-lying positioning if vomiting, and seizure precautions such as suction at the bedside.'),
  ('dds', 45, 'A client with DDS becomes unresponsive and cannot be aroused during hemodialysis. Which action should the nurse anticipate?', '[{"id": "a", "text": "Slightly slowing the rate and continuing dialysis"}, {"id": "b", "text": "Discontinuing dialysis for emergency management"}, {"id": "c", "text": "Increasing the rate to clear the urea more quickly"}, {"id": "d", "text": "Continuing at the current rate to finish the session"}]'::jsonb, '["b"]', 'Severe DDS with coma or uncontrolled seizures requires discontinuing dialysis and emergency management.'),
  ('dds', 46, 'For which client should the nurse anticipate a prescription for prophylactic mannitol before hemodialysis?', '[{"id": "a", "text": "A client on long-term dialysis with no symptoms"}, {"id": "b", "text": "A client on long-term dialysis with a stable BUN"}, {"id": "c", "text": "A client in a routine session with a modest BUN"}, {"id": "d", "text": "A client in a first session with a very high BUN"}]'::jsonb, '["d"]', 'Prophylactic mannitol is for very high-risk clients; the first HD session and a very high BUN are the highest risk factors.'),
  ('dds', 47, 'The provider prescribes hypertonic saline for a client with DDS. Which solution should the nurse verify before administration?', '[{"id": "a", "text": "3% sodium chloride"}, {"id": "b", "text": "Sterile water"}, {"id": "c", "text": "0.45% sodium chloride"}, {"id": "d", "text": "0.225% sodium chloride"}]'::jsonb, '["a"]', 'The hypertonic saline used for DDS is 3% NaCl, which raises serum osmolality to pull water from brain cells.'),
  ('dds', 48, 'Which action by an unlicensed assistive personnel (UAP) caring for a client at high risk for DDS requires correction?', '[{"id": "a", "text": "Removing the padding from the side rails"}, {"id": "b", "text": "Keeping the suction equipment at the bedside"}, {"id": "c", "text": "Leaving the oxygen setup in the room"}, {"id": "d", "text": "Reporting the client''s new headache to the nurse"}]'::jsonb, '["a"]', 'Safety measures for DDS include seizure precautions with padded side rails, suction at the bedside, and oxygen available.'),
  ('dds', 49, 'A client starting hemodialysis asks whether DDS is common. Which response by the nurse is accurate?', '[{"id": "a", "text": "It is common and mild, so no monitoring is needed."}, {"id": "b", "text": "It is rare but dangerous, so we watch you closely."}, {"id": "c", "text": "It is a harmless effect that does not need reporting."}, {"id": "d", "text": "It occurs in every first session and resolves alone."}]'::jsonb, '["b"]', 'DDS is a rare but dangerous neurological complication, so neurological status is monitored throughout dialysis.'),
  ('dds', 50, 'A client with DDS has prescriptions for IV mannitol and IV lorazepam. What is the purpose of the lorazepam?', '[{"id": "a", "text": "To raise serum osmolality"}, {"id": "b", "text": "To treat seizures if they occur"}, {"id": "c", "text": "To reduce ongoing urea removal"}, {"id": "d", "text": "To draw water out of the brain"}]'::jsonb, '["b"]', 'Benzodiazepines such as lorazepam are given if seizures occur. Mannitol draws water out of the brain, and hypertonic saline raises serum osmolality.'),
  ('gn', 1, 'A 7-year-old child is brought to the clinic with dark, cola-colored urine and puffy eyelids. Which finding in the health history is most significant?', '[{"id": "a", "text": "A fall from a bicycle three days ago"}, {"id": "b", "text": "A sore throat that resolved two weeks ago"}, {"id": "c", "text": "A routine immunization given last month"}, {"id": "d", "text": "A recent change in laundry detergent"}]'::jsonb, '["b"]', 'Acute glomerulonephritis often follows a streptococcal infection such as pharyngitis, with onset 1–3 weeks later. The other events are not identified as precipitating causes of glomerulonephritis.'),
  ('gn', 2, 'The nurse is reviewing the history of a child with suspected acute glomerulonephritis. Which previous infection is most consistent with this diagnosis?', '[{"id": "a", "text": "Viral gastroenteritis"}, {"id": "b", "text": "Bacterial cystitis"}, {"id": "c", "text": "Streptococcal impetigo"}, {"id": "d", "text": "Pinworm infestation"}]'::jsonb, '["c"]', 'Acute glomerulonephritis often follows a streptococcal infection of the throat (pharyngitis) or skin (impetigo). The other infections are not described as triggers.'),
  ('gn', 3, 'The parent of a child with post-streptococcal glomerulonephritis asks how a throat infection could affect the kidneys. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Immune complexes deposit in the kidney filters and inflame them.\""}, {"id": "b", "text": "\"The strep bacteria travel to the kidneys and form an abscess.\""}, {"id": "c", "text": "\"The throat infection caused stones to form inside the kidneys.\""}, {"id": "d", "text": "\"The antibiotics for the throat damaged the kidney filters.\""}]'::jsonb, '["a"]', 'Glomerulonephritis results from immune complex deposition in the glomeruli, which causes inflammation and decreased filtration. It is not a direct bacterial invasion of the kidney.'),
  ('gn', 4, 'A nurse in a pediatric clinic is screening children for risk of acute post-streptococcal glomerulonephritis. Which child is in the age group most commonly affected?', '[{"id": "a", "text": "A 6-month-old infant"}, {"id": "b", "text": "A 2-year-old toddler"}, {"id": "c", "text": "A 15-year-old adolescent"}, {"id": "d", "text": "An 8-year-old child"}]'::jsonb, '["d"]', 'Acute glomerulonephritis is most common in children ages 5–10 years. The infant, toddler, and adolescent fall outside this peak range.'),
  ('gn', 5, 'The parent of a 6-year-old child newly diagnosed with acute glomerulonephritis asks whether the child will need dialysis. Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"Most children with this condition need lifelong dialysis.\""}, {"id": "b", "text": "\"In children it usually resolves on its own with supportive care.\""}, {"id": "c", "text": "\"It nearly always progresses to permanent kidney failure.\""}, {"id": "d", "text": "\"A kidney transplant is usually needed within the first year.\""}]'::jsonb, '["b"]', 'Acute glomerulonephritis is generally self-limiting in children, although it may progress in adults. Progression to ESRD and dialysis describes chronic glomerulonephritis.'),
  ('gn', 6, 'A client with chronic glomerulonephritis asks what to expect from the disease over time. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It usually clears within weeks after a course of penicillin.\""}, {"id": "b", "text": "\"It typically appears one to three weeks after strep throat.\""}, {"id": "c", "text": "\"It can progress to kidney failure requiring dialysis or a transplant.\""}, {"id": "d", "text": "\"It mainly affects school-age children and then resolves.\""}]'::jsonb, '["c"]', 'Chronic glomerulonephritis is a progressive destruction of glomeruli that leads to ESRD and the need for dialysis or transplant. The 1–3 week post-strep onset and resolution in children describe acute glomerulonephritis.'),
  ('gn', 7, 'The nurse is reviewing the medical histories of several clients. Which condition is associated with the development of chronic glomerulonephritis?', '[{"id": "a", "text": "Lupus nephritis"}, {"id": "b", "text": "Allergic rhinitis"}, {"id": "c", "text": "Healed ankle fracture"}, {"id": "d", "text": "Tension headaches"}]'::jsonb, '["a"]', 'Chronic glomerulonephritis is associated with IgA nephropathy, lupus nephritis, and diabetic nephropathy. The other conditions are not listed associations.'),
  ('gn', 8, 'A nursing student is comparing acute and chronic glomerulonephritis. Which feature is characteristic of chronic glomerulonephritis?', '[{"id": "a", "text": "Onset one to three weeks after a strep infection"}, {"id": "b", "text": "Highest incidence in children ages 5 to 10 years"}, {"id": "c", "text": "Usually self-limiting without lasting damage"}, {"id": "d", "text": "Progressive destruction of glomeruli over years"}]'::jsonb, '["d"]', 'Chronic glomerulonephritis involves progressive destruction of glomeruli over years, often with no clear precipitating cause. The other options describe acute glomerulonephritis.'),
  ('gn', 9, 'When assessing a child admitted with acute glomerulonephritis, which urine appearance does the nurse expect?', '[{"id": "a", "text": "Pale yellow urine in large amounts"}, {"id": "b", "text": "Cola- or tea-colored urine"}, {"id": "c", "text": "Clear urine with a fruity odor"}, {"id": "d", "text": "Cloudy urine with a fishy odor"}]'::jsonb, '["b"]', 'Hematuria in glomerulonephritis produces cola-, tea-, or rust-colored urine. Large amounts of pale urine would contradict the expected oliguria.'),
  ('gn', 10, 'The nurse is assessing a child with acute glomerulonephritis for edema. Which finding is the nurse most likely to observe?', '[{"id": "a", "text": "Ankle swelling, mainly late in the evening"}, {"id": "b", "text": "Sacral swelling, mainly after long bed rest"}, {"id": "c", "text": "Swelling around the eyes, mainly in the morning"}, {"id": "d", "text": "Finger swelling, mainly after hand washing"}]'::jsonb, '["c"]', 'The classic edema of glomerulonephritis is periorbital, with puffiness around the eyes that is especially noticeable in the morning.'),
  ('gn', 11, 'The parent of a child with acute glomerulonephritis asks why the child''s blood pressure is elevated. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The kidneys are holding on to extra sodium and water.\""}, {"id": "b", "text": "\"Your child is anxious about being in the hospital.\""}, {"id": "c", "text": "\"The strep bacteria are infecting the blood vessels.\""}, {"id": "d", "text": "\"The heart muscle has been weakened by the infection.\""}]'::jsonb, '["a"]', 'Hypertension in glomerulonephritis results from sodium and water retention. It is not caused by direct bacterial infection of the vessels.'),
  ('gn', 12, 'An adult client with acute glomerulonephritis has a 24-hour urine output of 350 mL. How should the nurse interpret this finding?', '[{"id": "a", "text": "Output within the expected normal range"}, {"id": "b", "text": "Polyuria related to tubular damage"}, {"id": "c", "text": "Expected diuresis from furosemide"}, {"id": "d", "text": "Oliguria related to decreased filtration"}]'::jsonb, '["d"]', 'Oliguria is defined as a urine output of less than 400 mL/day in adults, so 350 mL/day is oliguria. It is not normal output or diuresis.'),
  ('gn', 13, 'The parent of a child with glomerulonephritis reports that the child''s urine looks frothy. The nurse recognizes that this finding indicates which condition?', '[{"id": "a", "text": "Glucose spilling into the urine"}, {"id": "b", "text": "Protein passing into the urine"}, {"id": "c", "text": "Bilirubin from liver damage"}, {"id": "d", "text": "Bacteria from a bladder infection"}]'::jsonb, '["b"]', 'Frothy or foamy urine is a sign of proteinuria, which is a classic finding in glomerulonephritis.'),
  ('gn', 14, 'The nurse performs a physical assessment on a client with acute glomerulonephritis. Which finding should the nurse expect?', '[{"id": "a", "text": "Polyuria with pale urine"}, {"id": "b", "text": "Bradycardia with low blood pressure"}, {"id": "c", "text": "Costovertebral angle tenderness"}, {"id": "d", "text": "Dry mucous membranes with weight loss"}]'::jsonb, '["c"]', 'Flank pain and costovertebral tenderness are listed signs of glomerulonephritis. Polyuria and low blood pressure are the opposite of the expected oliguria and hypertension.'),
  ('gn', 15, 'A child is being evaluated for post-streptococcal glomerulonephritis. Which laboratory result confirms a recent streptococcal infection?', '[{"id": "a", "text": "Elevated ASO titer"}, {"id": "b", "text": "Decreased ASO titer"}, {"id": "c", "text": "Elevated C3 level"}, {"id": "d", "text": "Decreased BUN level"}]'::jsonb, '["a"]', 'An elevated anti-streptolysin O (ASO) titer confirms recent streptococcal infection. C3 is decreased, not elevated, in post-strep glomerulonephritis.'),
  ('gn', 16, 'The nurse reviews the urinalysis of a child with acute glomerulonephritis. Which finding is considered the hallmark of this condition?', '[{"id": "a", "text": "Glucose"}, {"id": "b", "text": "Ketones"}, {"id": "c", "text": "Nitrites"}, {"id": "d", "text": "RBC casts"}]'::jsonb, '["d"]', 'Urinalysis in glomerulonephritis shows RBCs, WBCs, protein, and hematuria, with RBC casts as the hallmark finding.'),
  ('gn', 17, 'Which complement level result should the nurse expect in a child with post-streptococcal glomerulonephritis?', '[{"id": "a", "text": "Elevated C3 from increased production"}, {"id": "b", "text": "Decreased C3 from consumption"}, {"id": "c", "text": "Normal C3 with elevated C4"}, {"id": "d", "text": "Elevated C3 and elevated C4"}]'::jsonb, '["b"]', 'C3 is decreased in post-strep glomerulonephritis because it is consumed in the immune complex reaction. It is not elevated.'),
  ('gn', 18, 'The nurse reviews the metabolic panel of a client with glomerulonephritis. Which set of findings is expected?', '[{"id": "a", "text": "Decreased BUN, decreased creatinine, increased GFR"}, {"id": "b", "text": "Decreased BUN, increased creatinine, increased GFR"}, {"id": "c", "text": "Increased BUN, increased creatinine, decreased GFR"}, {"id": "d", "text": "Normal BUN, decreased creatinine, normal GFR"}]'::jsonb, '["c"]', 'Decreased glomerular filtration leads to elevated BUN and creatinine with a reduced GFR. The other combinations reverse the expected direction.'),
  ('gn', 19, 'A client with glomerulonephritis is scheduled for a diagnostic procedure that will determine the type and severity of the disease. Which procedure is the gold standard for this purpose?', '[{"id": "a", "text": "Renal biopsy"}, {"id": "b", "text": "ASO titer"}, {"id": "c", "text": "24-hour urine protein"}, {"id": "d", "text": "Routine urinalysis"}]'::jsonb, '["a"]', 'Renal biopsy is the gold standard for diagnosing the type and severity of glomerulonephritis. The ASO titer only confirms a recent strep infection.'),
  ('gn', 20, 'A client with glomerulonephritis has completed a 24-hour urine collection. Which result does the nurse anticipate?', '[{"id": "a", "text": "Absence of protein"}, {"id": "b", "text": "Decreased protein"}, {"id": "c", "text": "Normal protein"}, {"id": "d", "text": "Elevated protein"}]'::jsonb, '["d"]', 'A 24-hour urine protein test in glomerulonephritis is expected to show elevated proteinuria.'),
  ('gn', 21, 'The nurse teaches the parent of a child with post-streptococcal glomerulonephritis about the prescribed penicillin. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"The penicillin treats the strep infection that came first.\""}, {"id": "b", "text": "\"The penicillin will reverse the damage to the kidneys.\""}, {"id": "c", "text": "\"The penicillin helps keep the strep from spreading.\""}, {"id": "d", "text": "\"Limiting salt will help lower my child''s blood pressure.\""}]'::jsonb, '["b"]', 'Penicillin eradicates the underlying strep infection and prevents spread, but it does NOT reverse glomerulonephritis. The other statements are accurate.'),
  ('gn', 22, 'A client with chronic glomerulonephritis is prescribed an ACE inhibitor. The nurse explains that this medication is expected to accomplish which outcome?', '[{"id": "a", "text": "Eradicate the underlying strep infection"}, {"id": "b", "text": "Remove immune complexes from the glomeruli"}, {"id": "c", "text": "Control blood pressure and reduce proteinuria"}, {"id": "d", "text": "Replace the protein lost in the urine"}]'::jsonb, '["c"]', 'ACE inhibitors and ARBs control blood pressure, reduce proteinuria, and slow progression. Eradicating strep is the purpose of antibiotics.'),
  ('gn', 23, 'A child with acute glomerulonephritis is receiving furosemide. Which finding indicates that the medication is having the desired effect?', '[{"id": "a", "text": "Reduced periorbital edema"}, {"id": "b", "text": "Rising ASO titer"}, {"id": "c", "text": "New crackles in the lung bases"}, {"id": "d", "text": "Weight gain of 1 kg overnight"}]'::jsonb, '["a"]', 'Furosemide is given to reduce edema and fluid overload, so decreasing periorbital edema shows effectiveness. New crackles and weight gain indicate worsening fluid overload.'),
  ('gn', 24, 'For which client with glomerulonephritis should the nurse anticipate a prescription for corticosteroids?', '[{"id": "a", "text": "A child with uncomplicated post-strep glomerulonephritis"}, {"id": "b", "text": "A child with strep pharyngitis and no kidney findings"}, {"id": "c", "text": "A child whose urine color is gradually improving"}, {"id": "d", "text": "An adult with rapidly progressive glomerulonephritis"}]'::jsonb, '["d"]', 'Corticosteroids are indicated for autoimmune-related or rapidly progressive glomerulonephritis. Post-strep glomerulonephritis in children is generally self-limiting.'),
  ('gn', 25, 'A client with long-standing chronic glomerulonephritis has progressed to end-stage renal disease. Which treatment should the nurse anticipate?', '[{"id": "a", "text": "Penicillin to reverse glomerular damage"}, {"id": "b", "text": "Dialysis or kidney transplant"}, {"id": "c", "text": "Bed rest until urine color clears"}, {"id": "d", "text": "Antidiarrheal medication"}]'::jsonb, '["b"]', 'Chronic glomerulonephritis leads to ESRD, which requires dialysis or transplant. Penicillin does not reverse glomerulonephritis.'),
  ('gn', 26, 'The nurse is planning the diet for a child hospitalized with acute post-streptococcal glomerulonephritis. Which diet should the nurse anticipate?', '[{"id": "a", "text": "High-sodium, high-protein diet"}, {"id": "b", "text": "Low-sodium, high-protein diet"}, {"id": "c", "text": "Low-sodium, low-protein diet"}, {"id": "d", "text": "High-sodium, low-protein diet"}]'::jsonb, '["c"]', 'The diet for glomerulonephritis is low in sodium and low in protein. Sodium is restricted to reduce edema and hypertension.'),
  ('gn', 27, 'The parent of a child with acute glomerulonephritis asks why salt is being limited. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It reduces swelling and lowers blood pressure.\""}, {"id": "b", "text": "\"It helps the antibiotic kill the strep bacteria.\""}, {"id": "c", "text": "\"It increases the amount of protein in the urine.\""}, {"id": "d", "text": "\"It prevents the blood pressure from dropping.\""}]'::jsonb, '["a"]', 'A low-sodium diet reduces edema and hypertension. Salt restriction does not affect antibiotic action.'),
  ('gn', 28, 'A client with glomerulonephritis asks why dietary protein is being limited. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Protein directly raises your blood pressure.\""}, {"id": "b", "text": "\"It lowers the workload on the damaged kidney filters.\""}, {"id": "c", "text": "\"Protein is what turns the urine cola-colored.\""}, {"id": "d", "text": "\"Protein blocks the action of the antibiotic.\""}]'::jsonb, '["b"]', 'A low-protein diet reduces the workload on damaged glomeruli. Blood pressure is lowered by sodium restriction, not protein restriction.'),
  ('gn', 29, 'A child with acute glomerulonephritis has become oliguric. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "Push oral fluids every hour"}, {"id": "b", "text": "Allow fluids freely and weigh weekly"}, {"id": "c", "text": "Restrict fluids and measure strict I&O"}, {"id": "d", "text": "Increase fluids and stop daily weights"}]'::jsonb, '["c"]', 'Fluid restriction is indicated if the client is oliguric, along with strict monitoring of intake and output. Pushing fluids would worsen fluid retention.'),
  ('gn', 30, 'An adult client with glomerulonephritis weighs 1 kg more than on the previous morning. The nurse estimates that this weight gain represents retention of approximately how much fluid?', '[{"id": "a", "text": "250 mL"}, {"id": "b", "text": "500 mL"}, {"id": "c", "text": "2 L"}, {"id": "d", "text": "1 L"}]'::jsonb, '["d"]', 'A daily weight gain of 2 lb (1 kg) equals about 1 L of fluid retention.'),
  ('gn', 31, 'The nurse is supervising an unlicensed assistive personnel (UAP) caring for a child with acute glomerulonephritis. Which action by the UAP requires correction?', '[{"id": "a", "text": "Skipping today''s weight because the child was weighed on admission"}, {"id": "b", "text": "Recording all oral intake and urine output on the I&O sheet"}, {"id": "c", "text": "Reporting the color of the child''s urine to the nurse"}, {"id": "d", "text": "Keeping the child in bed during the acute phase"}]'::jsonb, '["a"]', 'Nursing management for glomerulonephritis includes daily weights along with I&O and blood pressure monitoring, so skipping the weight requires correction. The other actions are appropriate.'),
  ('gn', 32, 'A 7-year-old child in the acute phase of glomerulonephritis asks to go to the playroom. Which activity order does the nurse expect for this phase?', '[{"id": "a", "text": "Ambulate in the hallway four times daily"}, {"id": "b", "text": "Bed rest during the acute phase"}, {"id": "c", "text": "Active play to promote circulation"}, {"id": "d", "text": "Unrestricted activity as tolerated"}]'::jsonb, '["b"]', 'Bed rest is part of nursing management during the acute phase of glomerulonephritis.'),
  ('gn', 33, 'The nurse is caring for a child with acute glomerulonephritis. Which finding should the nurse report to the health care provider immediately?', '[{"id": "a", "text": "Fatigue after a bath"}, {"id": "b", "text": "Urine gradually lighter in color"}, {"id": "c", "text": "New crackles in both lung bases"}, {"id": "d", "text": "Mild malaise in the afternoon"}]'::jsonb, '["c"]', 'Crackles are a sign of fluid overload, which the nurse must assess for and report. Gradually lightening urine is an expected improvement, and malaise and fatigue are common symptoms.'),
  ('gn', 34, 'A child has been treated for acute glomerulonephritis for several days. Which finding indicates that the child''s condition is improving?', '[{"id": "a", "text": "Urine is becoming darker"}, {"id": "b", "text": "Urine is becoming frothier"}, {"id": "c", "text": "Eyelid puffiness is increasing"}, {"id": "d", "text": "Urine is gradually lightening"}]'::jsonb, '["d"]', 'The nurse monitors urine color and expects gradual improvement as glomerulonephritis resolves. Darker or frothier urine indicates ongoing hematuria or proteinuria.'),
  ('gn', 35, 'The nurse is teaching the parent of a child recovering from acute glomerulonephritis. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"The urine color should be back to normal by tomorrow.\""}, {"id": "b", "text": "\"I expect the urine color to improve gradually.\""}, {"id": "c", "text": "\"The puffiness around the eyes may be worse in the morning.\""}, {"id": "d", "text": "\"I need to keep salt low in my child''s meals.\""}]'::jsonb, '["a"]', 'Urine color is expected to improve gradually, not overnight. The other statements reflect correct understanding of morning periorbital edema and sodium restriction.'),
  ('gn', 36, 'Which cluster of findings is most consistent with acute post-streptococcal glomerulonephritis?', '[{"id": "a", "text": "Polyuria, hypotension, and pale urine"}, {"id": "b", "text": "Oliguria, hypertension, and periorbital edema"}, {"id": "c", "text": "Polyuria, hypertension, and sacral edema"}, {"id": "d", "text": "Oliguria, hypotension, and clear urine"}]'::jsonb, '["b"]', 'Post-strep glomerulonephritis presents with cola-colored urine, periorbital edema, hypertension, oliguria, and an elevated ASO titer. Polyuria and hypotension are not expected.'),
  ('gn', 37, 'In addition to urinary changes, which symptoms does the nurse expect a client with glomerulonephritis to report?', '[{"id": "a", "text": "Excessive urination at night"}, {"id": "b", "text": "Dizziness from low blood pressure"}, {"id": "c", "text": "Fatigue, malaise, and headache"}, {"id": "d", "text": "Increased appetite and weight loss"}]'::jsonb, '["c"]', 'Malaise, fatigue, and headache are listed symptoms of glomerulonephritis. Excessive urination and low blood pressure contradict the expected oliguria and hypertension.'),
  ('gn', 38, 'The nurse is developing a plan of care for a client with glomerulonephritis. Which laboratory values should the nurse plan to monitor closely?', '[{"id": "a", "text": "Liver enzymes and bilirubin"}, {"id": "b", "text": "Hemoglobin A1C and lipids"}, {"id": "c", "text": "Thyroid hormone levels"}, {"id": "d", "text": "BUN, creatinine, and electrolytes"}]'::jsonb, '["d"]', 'Nursing management of glomerulonephritis includes monitoring BUN, creatinine, electrolytes, and blood pressure to track kidney function.'),
  ('gn', 39, 'A child is diagnosed with streptococcal impetigo. The parent asks when signs of kidney involvement would appear if glomerulonephritis develops. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Within the first 24 hours\""}, {"id": "b", "text": "\"About one to three weeks later\""}, {"id": "c", "text": "\"About three to six months later\""}, {"id": "d", "text": "\"Only after several years\""}]'::jsonb, '["b"]', 'Post-strep glomerulonephritis occurs 1–3 weeks after the strep infection. Progression over years describes chronic glomerulonephritis.'),
  ('gn', 40, 'The parent of a child with acute glomerulonephritis asks why the child''s urine looks like cola. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It contains blood from the inflamed kidney filters.\""}, {"id": "b", "text": "\"It contains bile from an inflamed liver.\""}, {"id": "c", "text": "\"It is concentrated because of excess fluid intake.\""}, {"id": "d", "text": "\"It is colored by dye from the penicillin.\""}]'::jsonb, '["a"]', 'Cola-, tea-, or rust-colored urine in glomerulonephritis reflects hematuria, with blood and protein in the urine.'),
  ('gn', 41, 'Which client history should the nurse identify as a risk factor for chronic glomerulonephritis?', '[{"id": "a", "text": "Recent appendectomy"}, {"id": "b", "text": "Childhood tonsillectomy"}, {"id": "c", "text": "Seasonal allergies"}, {"id": "d", "text": "Diabetic nephropathy"}]'::jsonb, '["d"]', 'Chronic glomerulonephritis is associated with IgA nephropathy, lupus nephritis, and diabetic nephropathy. The other histories are not listed associations.'),
  ('gn', 42, 'A client with IgA nephropathy is being taught about chronic glomerulonephritis. Which statement by the client indicates correct understanding?', '[{"id": "a", "text": "\"This will go away within a few weeks.\""}, {"id": "b", "text": "\"Penicillin will cure my kidney disease.\""}, {"id": "c", "text": "\"I may eventually need dialysis or a transplant.\""}, {"id": "d", "text": "\"It only occurs after a strep throat infection.\""}]'::jsonb, '["c"]', 'Chronic glomerulonephritis, often with no clear precipitating cause, progresses to ESRD requiring dialysis or transplant. It does not resolve in weeks or respond to penicillin.'),
  ('gn', 43, 'A client with chronic glomerulonephritis has been taking an ARB for 3 months. Which finding best indicates that the therapy is effective?', '[{"id": "a", "text": "Rising blood pressure readings"}, {"id": "b", "text": "Blood pressure at goal with less proteinuria"}, {"id": "c", "text": "Increasing weight with ankle edema"}, {"id": "d", "text": "Darker urine with more foam"}]'::jsonb, '["b"]', 'ACE inhibitors and ARBs control blood pressure, reduce proteinuria, and slow progression, so controlled blood pressure with less proteinuria shows effectiveness.'),
  ('gn', 44, 'A child is diagnosed with post-streptococcal glomerulonephritis. Which prescribed medication treats the underlying infection?', '[{"id": "a", "text": "Furosemide"}, {"id": "b", "text": "An ACE inhibitor"}, {"id": "c", "text": "Corticosteroid"}, {"id": "d", "text": "Penicillin"}]'::jsonb, '["d"]', 'Antibiotics such as penicillin are used to eradicate the underlying strep infection. Furosemide reduces edema, and ACE inhibitors control blood pressure.'),
  ('gn', 45, 'The parent of a child with acute glomerulonephritis asks why furosemide was prescribed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It kills the strep bacteria.\""}, {"id": "b", "text": "\"It removes extra fluid and swelling.\""}, {"id": "c", "text": "\"It replaces protein lost in the urine.\""}, {"id": "d", "text": "\"It raises the blood pressure.\""}]'::jsonb, '["b"]', 'Diuretics such as furosemide are given to reduce edema and fluid overload. Antibiotics, not diuretics, treat the strep infection.'),
  ('gn', 46, 'The parent of a child with suspected glomerulonephritis asks what an elevated ASO titer means. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The kidneys have permanent scarring.\""}, {"id": "b", "text": "\"Your child recently had a strep infection.\""}, {"id": "c", "text": "\"Your child is allergic to penicillin.\""}, {"id": "d", "text": "\"Your child has a bladder infection.\""}]'::jsonb, '["b"]', 'An elevated anti-streptolysin O titer confirms a recent streptococcal infection. It does not indicate kidney scarring.'),
  ('gn', 47, 'A client with acute glomerulonephritis has a blood pressure higher than baseline and new swelling of both ankles. The nurse suspects which problem?', '[{"id": "a", "text": "Dehydration"}, {"id": "b", "text": "Fluid overload"}, {"id": "c", "text": "Recovery from the acute phase"}, {"id": "d", "text": "Recurrent strep infection"}]'::jsonb, '["b"]', 'Signs of fluid overload include crackles, peripheral edema, and hypertension. These findings are not signs of dehydration or recovery.'),
  ('gn', 48, 'Which sequence correctly describes the development of post-streptococcal glomerulonephritis?', '[{"id": "a", "text": "Strep infection, immune complex deposition, glomerular inflammation, decreased filtration"}, {"id": "b", "text": "Decreased filtration, strep infection, glomerular inflammation, immune complex deposition"}, {"id": "c", "text": "Glomerular inflammation, strep infection, decreased filtration, immune complex deposition"}, {"id": "d", "text": "Immune complex deposition, decreased filtration, strep infection, glomerular inflammation"}]'::jsonb, '["a"]', 'Glomerulonephritis follows a strep infection; immune complexes deposit in the glomeruli, causing inflammation and then decreased filtration.'),
  ('gn', 49, 'Which statement by a nursing student about acute glomerulonephritis requires correction by the nurse educator?', '[{"id": "a", "text": "\"It often follows strep pharyngitis.\""}, {"id": "b", "text": "\"It is most common in children ages 5 to 10.\""}, {"id": "c", "text": "\"It is generally self-limiting in children.\""}, {"id": "d", "text": "\"It usually leads to ESRD in children.\""}]'::jsonb, '["d"]', 'Acute glomerulonephritis is generally self-limiting in children; progression to ESRD is the course of chronic glomerulonephritis. The other statements are accurate.'),
  ('gn', 50, 'The parent of a child with acute glomerulonephritis reports that the child''s eyes look very puffy each morning on waking. How should the nurse interpret this finding?', '[{"id": "a", "text": "An allergic reaction to the antibiotic"}, {"id": "b", "text": "A sign of dehydration from fluid limits"}, {"id": "c", "text": "A sign of a new eye infection"}, {"id": "d", "text": "An expected finding of fluid retention"}]'::jsonb, '["d"]', 'Periorbital edema, especially in the morning, is a classic sign of glomerulonephritis caused by fluid retention.'),
  ('hus', 1, 'The nurse is reviewing the pathophysiology of hemolytic uremic syndrome (HUS). Which set of findings makes up the classic triad?', '[{"id": "a", "text": "Hemolytic anemia, thrombocytopenia, and acute kidney injury"}, {"id": "b", "text": "Hematuria, hypertension, and periorbital edema"}, {"id": "c", "text": "Polycythemia, thrombocytosis, and acute kidney injury"}, {"id": "d", "text": "Hemolytic anemia, leukocytosis, and liver failure"}]'::jsonb, '["a"]', 'HUS is defined by the triad of hemolytic anemia, thrombocytopenia, and acute kidney injury. Platelets are decreased, not increased.'),
  ('hus', 2, 'A nurse in a pediatric clinic is caring for several children with diarrhea. Which child is in the age group most commonly affected by hemolytic uremic syndrome?', '[{"id": "a", "text": "A 12-year-old child"}, {"id": "b", "text": "A 9-year-old child"}, {"id": "c", "text": "A 3-year-old child"}, {"id": "d", "text": "A 16-year-old adolescent"}]'::jsonb, '["c"]', 'HUS is most common in children under 5 years of age, so the 3-year-old is in the highest-risk group.'),
  ('hus', 3, 'A 3-year-old child is brought to the emergency department with pallor and decreased urine output. Which finding in the history is most significant?', '[{"id": "a", "text": "A fall at the playground two days ago"}, {"id": "b", "text": "Bloody diarrhea that began about a week ago"}, {"id": "c", "text": "A sore throat that resolved last month"}, {"id": "d", "text": "A new brand of toddler formula last week"}]'::jsonb, '["b"]', 'HUS begins with bloody diarrhea, and the triad develops 5–10 days later. A preceding sore throat is not the described trigger.'),
  ('hus', 4, 'The nurse is obtaining a dietary history from the parent of a child with suspected hemolytic uremic syndrome. Which food is most likely to be the source?', '[{"id": "a", "text": "Well-cooked chicken"}, {"id": "b", "text": "Pasteurized milk"}, {"id": "c", "text": "Toasted bread"}, {"id": "d", "text": "Undercooked hamburger"}]'::jsonb, '["d"]', 'Sources of E. coli O157:H7 include undercooked ground beef, contaminated produce, and unpasteurized juices. Pasteurized milk is not a listed source.'),
  ('hus', 5, 'A nursing student asks which organism is the most common trigger of hemolytic uremic syndrome. Which response by the nurse is correct?', '[{"id": "a", "text": "Shiga toxin-producing E. coli O157:H7"}, {"id": "b", "text": "Group A beta-hemolytic streptococcus"}, {"id": "c", "text": "Methicillin-resistant Staphylococcus"}, {"id": "d", "text": "Candida albicans from the gut"}]'::jsonb, '["a"]', 'The most common trigger of HUS is E. coli O157:H7, a Shiga toxin-producing E. coli (STEC).'),
  ('hus', 6, 'The parent of a child with hemolytic uremic syndrome asks how a diarrheal illness could harm the kidneys. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The bacteria travel up and infect the kidneys directly.\""}, {"id": "b", "text": "\"A toxin damages vessel linings, and tiny clots form.\""}, {"id": "c", "text": "\"Dehydration from the diarrhea dried out the kidneys.\""}, {"id": "d", "text": "\"Antibodies from a sore throat attack the kidneys.\""}]'::jsonb, '["b"]', 'Shiga toxin damages the endothelium, leading to microthrombi that cause hemolysis, platelet consumption, and renal injury.'),
  ('hus', 7, 'A child developed bloody diarrhea after eating at a picnic. The parent asks when hemolytic uremic syndrome would develop if it is going to occur. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Within 12 hours of the first bloody stool\""}, {"id": "b", "text": "\"About one to three weeks after a sore throat\""}, {"id": "c", "text": "\"About 5 to 10 days after the bloody diarrhea\""}, {"id": "d", "text": "\"Several months after the diarrhea resolves\""}]'::jsonb, '["c"]', 'The HUS triad develops about 5–10 days after bloody diarrhea begins.'),
  ('hus', 8, 'The nurse is taking a history from the parent of a child admitted with hemolytic uremic syndrome. Which symptoms during the prior week are consistent with the prodrome?', '[{"id": "a", "text": "Productive cough and wheezing"}, {"id": "b", "text": "Rash on the palms and soles"}, {"id": "c", "text": "Ear pain and nasal congestion"}, {"id": "d", "text": "Cramping, fever, and bloody diarrhea"}]'::jsonb, '["d"]', 'The HUS prodrome includes watery then bloody diarrhea, abdominal cramps, and fever 5–10 days before HUS.'),
  ('hus', 9, 'When assessing a child with hemolytic uremic syndrome, which findings does the nurse attribute to hemolytic anemia?', '[{"id": "a", "text": "Pallor and jaundice"}, {"id": "b", "text": "Petechiae and bruising"}, {"id": "c", "text": "Edema and hypertension"}, {"id": "d", "text": "Seizures and confusion"}]'::jsonb, '["a"]', 'Pallor, jaundice, and fatigue result from hemolytic anemia. Petechiae and bruising result from thrombocytopenia.'),
  ('hus', 10, 'Which assessment finding in a child with hemolytic uremic syndrome is a direct result of thrombocytopenia?', '[{"id": "a", "text": "Jaundice"}, {"id": "b", "text": "Petechiae"}, {"id": "c", "text": "Oliguria"}, {"id": "d", "text": "Hypertension"}]'::jsonb, '["b"]', 'Petechiae and easy bruising are caused by thrombocytopenia. Jaundice reflects hemolytic anemia, and oliguria reflects AKI.'),
  ('hus', 11, 'A child with hemolytic uremic syndrome is being monitored for kidney involvement. Which finding is the hallmark of acute kidney injury onset?', '[{"id": "a", "text": "Pale skin"}, {"id": "b", "text": "Easy bruising"}, {"id": "c", "text": "Decreased urine output"}, {"id": "d", "text": "Yellow sclera"}]'::jsonb, '["c"]', 'Oliguria or anuria is the hallmark of AKI onset in HUS. Pallor and jaundice reflect anemia, and bruising reflects thrombocytopenia.'),
  ('hus', 12, 'The nurse is caring for a 4-year-old child with hemolytic uremic syndrome. Which finding should the nurse report to the health care provider immediately?', '[{"id": "a", "text": "Fatigue after a bath"}, {"id": "b", "text": "Pale skin and nail beds"}, {"id": "c", "text": "A few small bruises on the shins"}, {"id": "d", "text": "New onset of confusion"}]'::jsonb, '["d"]', 'Neurological changes such as confusion or seizures indicate cerebral involvement and require immediate attention. Pallor, fatigue, and bruising are expected findings of anemia and thrombocytopenia.'),
  ('hus', 13, 'A peripheral blood smear is obtained for a child with suspected hemolytic uremic syndrome. Which finding is considered the hallmark?', '[{"id": "a", "text": "Schistocytes"}, {"id": "b", "text": "Sickle cells"}, {"id": "c", "text": "Target cells"}, {"id": "d", "text": "Blast cells"}]'::jsonb, '["a"]', 'Schistocytes, or fragmented RBCs, are the hallmark finding on the peripheral smear in HUS.'),
  ('hus', 14, 'Which complete blood count results should the nurse expect in a child with hemolytic uremic syndrome?', '[{"id": "a", "text": "Increased hemoglobin and increased platelets"}, {"id": "b", "text": "Decreased hemoglobin and decreased platelets"}, {"id": "c", "text": "Increased hemoglobin and decreased platelets"}, {"id": "d", "text": "Decreased hemoglobin and increased platelets"}]'::jsonb, '["b"]', 'The CBC in HUS shows decreased hemoglobin from anemia and decreased platelets from thrombocytopenia.'),
  ('hus', 15, 'A child with hemolytic uremic syndrome has an elevated LDH level. How should the nurse interpret this result?', '[{"id": "a", "text": "It indicates a strep infection"}, {"id": "b", "text": "It indicates dehydration"}, {"id": "c", "text": "It reflects RBC destruction"}, {"id": "d", "text": "It reflects platelet clumping"}]'::jsonb, '["c"]', 'An elevated LDH in HUS reflects RBC destruction from hemolysis.'),
  ('hus', 16, 'The nurse reviews the basic metabolic panel of a child with hemolytic uremic syndrome. Which findings are expected?', '[{"id": "a", "text": "Decreased BUN and decreased creatinine"}, {"id": "b", "text": "Decreased BUN and increased creatinine"}, {"id": "c", "text": "Increased BUN and decreased creatinine"}, {"id": "d", "text": "Increased BUN and increased creatinine"}]'::jsonb, '["d"]', 'The BMP in HUS shows elevated BUN and creatinine with electrolyte imbalances, reflecting AKI.'),
  ('hus', 17, 'Which urinalysis findings should the nurse expect for a child with hemolytic uremic syndrome?', '[{"id": "a", "text": "Hematuria, proteinuria, and casts"}, {"id": "b", "text": "Glucose, ketones, and nitrites"}, {"id": "c", "text": "Bilirubin, glucose, and crystals"}, {"id": "d", "text": "Nitrites, leukocytes, and yeast"}]'::jsonb, '["a"]', 'Urinalysis in HUS shows hematuria, proteinuria, and casts.'),
  ('hus', 18, 'A child with bloody diarrhea and suspected E. coli O157:H7 infection is admitted. Which prescription should the nurse question?', '[{"id": "a", "text": "IV fluids for fluid management"}, {"id": "b", "text": "An oral antibiotic"}, {"id": "c", "text": "Daily weights"}, {"id": "d", "text": "Hourly urine output measurement"}]'::jsonb, '["b"]', 'Antibiotics should be avoided because they worsen Shiga toxin release and increase the risk of HUS progression. Fluid management, daily weights, and hourly output are appropriate.'),
  ('hus', 19, 'The nurse teaches the parent of a child recovering from E. coli O157:H7 diarrhea. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I will wash my hands after handling raw meat.\""}, {"id": "b", "text": "\"I will avoid giving my child unpasteurized juice.\""}, {"id": "c", "text": "\"I will give loperamide if the diarrhea returns.\""}, {"id": "d", "text": "\"I will cook ground beef thoroughly at home.\""}]'::jsonb, '["c"]', 'Antidiarrheals such as loperamide slow gut motility, increase toxin absorption, and worsen HUS. The other statements reflect correct prevention teaching.'),
  ('hus', 20, 'The parent of a child with HUS asks why the child cannot be given medicine to stop the diarrhea. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It would cause the platelets to drop further.\""}, {"id": "b", "text": "\"It would make the child''s anemia much worse.\""}, {"id": "c", "text": "\"It would interfere with the IV fluids.\""}, {"id": "d", "text": "\"Slowing the bowel lets more toxin be absorbed.\""}]'::jsonb, '["d"]', 'Antidiarrheals slow gut motility, which increases toxin absorption and worsens HUS.'),
  ('hus', 21, 'The parent of a child with suspected Shiga toxin-producing E. coli infection asks why antibiotics are not being given. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Antibiotics can increase release of the toxin.\""}, {"id": "b", "text": "\"Antibiotics cannot reach the large intestine.\""}, {"id": "c", "text": "\"The infection is caused by a virus, not bacteria.\""}, {"id": "d", "text": "\"Antibiotics will be started after the diarrhea stops.\""}]'::jsonb, '["a"]', 'Antibiotics are avoided because they worsen Shiga toxin release and increase the risk of HUS progression. The cause is a bacterium, E. coli O157:H7.'),
  ('hus', 22, 'Which treatment approach does the nurse anticipate for a child with typical hemolytic uremic syndrome?', '[{"id": "a", "text": "Antibiotic therapy to clear the E. coli"}, {"id": "b", "text": "Supportive fluid and electrolyte management"}, {"id": "c", "text": "Antidiarrheal drugs to limit fluid loss"}, {"id": "d", "text": "Routine platelet transfusions every day"}]'::jsonb, '["b"]', 'Treatment of HUS is supportive, including fluid management and electrolyte correction. Antibiotics and antidiarrheals are avoided.'),
  ('hus', 23, 'A child with hemolytic uremic syndrome has become anuric, and the creatinine continues to rise. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "Loperamide administration"}, {"id": "b", "text": "Broad-spectrum antibiotics"}, {"id": "c", "text": "Dialysis"}, {"id": "d", "text": "Platelet transfusion"}]'::jsonb, '["c"]', 'Dialysis, either peritoneal or hemodialysis, is indicated if AKI is severe. Antibiotics and antidiarrheals are avoided in HUS.'),
  ('hus', 24, 'A child with hemolytic uremic syndrome has a low platelet count and a few petechiae but no active bleeding. Which statement about platelet transfusion is accurate?', '[{"id": "a", "text": "It is given to every child with a low count"}, {"id": "b", "text": "It is given routinely before each lab draw"}, {"id": "c", "text": "It is given to make petechiae fade faster"}, {"id": "d", "text": "It is reserved for life-threatening bleeding"}]'::jsonb, '["d"]', 'Platelet transfusions are given only if there is life-threatening bleeding.'),
  ('hus', 25, 'A child with hemolytic uremic syndrome is severely anemic, pale, and fatigued. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "Blood transfusion"}, {"id": "b", "text": "Oral antibiotic"}, {"id": "c", "text": "Antidiarrheal medication"}, {"id": "d", "text": "Platelet transfusion"}]'::jsonb, '["a"]', 'Blood transfusions are given for severe anemia in HUS. Platelet transfusions are reserved for life-threatening bleeding.'),
  ('hus', 26, 'For which client should the nurse anticipate a prescription for eculizumab?', '[{"id": "a", "text": "A child with typical HUS after bloody diarrhea"}, {"id": "b", "text": "A child with atypical, complement-mediated HUS"}, {"id": "c", "text": "A child with E. coli diarrhea but normal labs"}, {"id": "d", "text": "A child with HUS who needs a blood transfusion"}]'::jsonb, '["b"]', 'Eculizumab, a monoclonal antibody, is used for atypical HUS, which is complement-mediated. Typical HUS is managed with supportive care.'),
  ('hus', 27, 'The nurse is planning care for a child with hemolytic uremic syndrome. How often should the nurse measure urine output?', '[{"id": "a", "text": "Once per shift"}, {"id": "b", "text": "Once daily"}, {"id": "c", "text": "Every hour"}, {"id": "d", "text": "Every 24 hours"}]'::jsonb, '["c"]', 'Nursing care includes strict I&O with hourly urine output to watch for oliguria or anuria.'),
  ('hus', 28, 'The parent of a child with hemolytic uremic syndrome asks why the child is weighed every morning. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"To decide when antibiotics can start.\""}, {"id": "b", "text": "\"To measure how much blood was lost.\""}, {"id": "c", "text": "\"To track the child''s platelet count.\""}, {"id": "d", "text": "\"To detect fluid building up in the body.\""}]'::jsonb, '["d"]', 'Daily weights are used to detect fluid retention in children with HUS.'),
  ('hus', 29, 'A child with hemolytic uremic syndrome has a blood pressure above the expected range for age. The nurse recognizes that this finding is most likely related to which cause?', '[{"id": "a", "text": "Fluid overload"}, {"id": "b", "text": "Dehydration"}, {"id": "c", "text": "Antibiotic reaction"}, {"id": "d", "text": "Low platelet count"}]'::jsonb, '["a"]', 'Hypertension in HUS results from fluid overload, so the nurse monitors blood pressure closely.'),
  ('hus', 30, 'The nurse is supervising an unlicensed assistive personnel (UAP) caring for a child with HUS and a low platelet count. Which action by the UAP requires correction?', '[{"id": "a", "text": "Recording each urine output on the I&O sheet"}, {"id": "b", "text": "Giving the child a firm-bristled toothbrush"}, {"id": "c", "text": "Weighing the child before breakfast each day"}, {"id": "d", "text": "Reporting new bruises on the child''s arms"}]'::jsonb, '["b"]', 'Bleeding precautions for thrombocytopenia include using a soft toothbrush. The other actions support I&O, daily weights, and bleeding assessment.'),
  ('hus', 31, 'A child with hemolytic uremic syndrome has thrombocytopenia. Which prescription should the nurse clarify with the health care provider?', '[{"id": "a", "text": "IV fluids for fluid management"}, {"id": "b", "text": "Daily weight before breakfast"}, {"id": "c", "text": "Intramuscular injection of a medication"}, {"id": "d", "text": "Hourly urine output measurement"}]'::jsonb, '["c"]', 'Bleeding precautions for thrombocytopenia include no IM injections. Fluid management, daily weights, and hourly output are appropriate care.'),
  ('hus', 32, 'The parents of a 2-year-old child with hemolytic uremic syndrome are tearful at the bedside as the child begins dialysis. Which nursing action is most appropriate?', '[{"id": "a", "text": "Ask the parents to wait outside during care"}, {"id": "b", "text": "Limit the parents'' questions to rounds"}, {"id": "c", "text": "Tell the parents there is nothing to fear"}, {"id": "d", "text": "Provide emotional support to the family"}]'::jsonb, '["d"]', 'Nursing care for HUS includes providing emotional support to both the child and the parents.'),
  ('hus', 33, 'The nurse is teaching a parent group about preventing E. coli O157:H7 infection. To what minimum internal temperature should ground beef be cooked?', '[{"id": "a", "text": "160°F (71°C)"}, {"id": "b", "text": "120°F (49°C)"}, {"id": "c", "text": "130°F (54°C)"}, {"id": "d", "text": "140°F (60°C)"}]'::jsonb, '["a"]', 'Ground beef should be cooked to an internal temperature of at least 160°F (71°C) to prevent infection.'),
  ('hus', 34, 'The nurse teaches a parent how to prevent hemolytic uremic syndrome. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I will wash produce carefully before serving it.\""}, {"id": "b", "text": "\"Fresh unpasteurized juice is a healthier choice.\""}, {"id": "c", "text": "\"I will wash my hands after handling raw meat.\""}, {"id": "d", "text": "\"I will cook ground beef to the proper temperature.\""}]'::jsonb, '["b"]', 'Unpasteurized milk and juice should be avoided because they are a source of E. coli O157:H7. The other statements reflect correct prevention.'),
  ('hus', 35, 'After teaching about E. coli O157:H7 prevention, which statement by a parent indicates correct understanding?', '[{"id": "a", "text": "\"Rinsing my hands with water alone is enough.\""}, {"id": "b", "text": "\"I only need to wash my hands after cooking.\""}, {"id": "c", "text": "\"I will wash my hands well after touching raw meat.\""}, {"id": "d", "text": "\"Hand washing is needed only if the meat smells bad.\""}]'::jsonb, '["c"]', 'Prevention teaching includes washing hands thoroughly after handling raw meat.'),
  ('hus', 36, 'A home health nurse observes a parent cutting raw ground beef and then slicing salad vegetables on the same unwashed board. Which teaching topic is the priority?', '[{"id": "a", "text": "Choosing pasteurized juice"}, {"id": "b", "text": "Cooking temperatures for chicken"}, {"id": "c", "text": "Signs of dehydration in toddlers"}, {"id": "d", "text": "Preventing kitchen cross-contamination"}]'::jsonb, '["d"]', 'Using the same unwashed board for raw meat and produce risks spreading E. coli, so preventing cross-contamination in the kitchen is the priority teaching.'),
  ('hus', 37, 'A parent asks how to make raw vegetables safer for a family after a neighborhood E. coli outbreak. Which response by the nurse is most appropriate?', '[{"id": "a", "text": "\"Wash produce carefully before eating it.\""}, {"id": "b", "text": "\"Serve produce only with unpasteurized juice.\""}, {"id": "c", "text": "\"Store produce next to raw ground beef.\""}, {"id": "d", "text": "\"Avoid produce and serve only ground beef.\""}]'::jsonb, '["a"]', 'Contaminated produce is a source of E. coli O157:H7, so produce should be washed carefully.'),
  ('hus', 38, 'The parent of a child with hemolytic uremic syndrome asks why the child has become anemic. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The bone marrow has stopped making red cells.\""}, {"id": "b", "text": "\"Red cells break apart as they pass through damaged small vessels.\""}, {"id": "c", "text": "\"Blood is being lost through the kidneys into the urine only.\""}, {"id": "d", "text": "\"The child is not absorbing iron because of the diarrhea.\""}]'::jsonb, '["b"]', 'In microangiopathic hemolytic anemia, RBCs are destroyed as they pass through damaged microvasculature, producing low hemoglobin and schistocytes.'),
  ('hus', 39, 'A nursing student asks why the platelet count falls in hemolytic uremic syndrome. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Platelets are lost in the bloody diarrhea.\""}, {"id": "b", "text": "\"The spleen stops releasing stored platelets.\""}, {"id": "c", "text": "\"Platelets are consumed in tiny clots.\""}, {"id": "d", "text": "\"Antibiotics suppress platelet production.\""}]'::jsonb, '["c"]', 'Platelets are consumed in microclots, which lowers the platelet count and causes petechiae and bleeding risk.'),
  ('hus', 40, 'Which sequence correctly describes how acute kidney injury develops in hemolytic uremic syndrome?', '[{"id": "a", "text": "Decreased GFR, microthrombi, oliguria, increased creatinine"}, {"id": "b", "text": "Oliguria, decreased GFR, microthrombi, increased creatinine"}, {"id": "c", "text": "Increased creatinine, oliguria, microthrombi, decreased GFR"}, {"id": "d", "text": "Microthrombi, decreased GFR, oliguria, increased creatinine"}]'::jsonb, '["d"]', 'Microthrombi occlude the renal microvasculature, decreasing GFR and leading to oliguria or anuria and rising creatinine.'),
  ('hus', 41, 'A child with hemolytic uremic syndrome has developed acute kidney injury. Which additional findings should the nurse expect?', '[{"id": "a", "text": "Edema and hypertension"}, {"id": "b", "text": "Polyuria and hypotension"}, {"id": "c", "text": "Dry skin and weight loss"}, {"id": "d", "text": "Bradycardia and polyuria"}]'::jsonb, '["a"]', 'Edema and hypertension are signs of HUS, reflecting fluid retention with kidney injury. Polyuria contradicts the expected oliguria.'),
  ('hus', 42, 'A toddler with hemolytic uremic syndrome has become increasingly irritable and is not responding normally to the parents. How should the nurse interpret this change?', '[{"id": "a", "text": "An expected reaction to hospital routines"}, {"id": "b", "text": "A possible sign of severe disease with neurological involvement"}, {"id": "c", "text": "A side effect of the soft toothbrush"}, {"id": "d", "text": "A normal response to daily weights"}]'::jsonb, '["b"]', 'Irritability and neurological symptoms such as confusion or seizures occur in severe cases of HUS and must be reported.'),
  ('hus', 43, 'A 4-year-old child had bloody diarrhea one week ago. Which set of laboratory findings would reflect all three components of the classic HUS triad?', '[{"id": "a", "text": "Decreased hemoglobin, increased platelets, decreased creatinine"}, {"id": "b", "text": "Increased hemoglobin, decreased platelets, increased creatinine"}, {"id": "c", "text": "Decreased hemoglobin, decreased platelets, increased creatinine"}, {"id": "d", "text": "Increased hemoglobin, increased platelets, decreased creatinine"}]'::jsonb, '["c"]', 'The HUS triad is hemolytic anemia (low hemoglobin), thrombocytopenia (low platelets), and AKI (rising creatinine). Increased platelets or falling creatinine would not fit the triad.'),
  ('hus', 44, 'Which diagnostic test will identify the organism responsible for a child''s hemolytic uremic syndrome?', '[{"id": "a", "text": "Peripheral blood smear"}, {"id": "b", "text": "LDH level"}, {"id": "c", "text": "Urinalysis"}, {"id": "d", "text": "Stool culture"}]'::jsonb, '["d"]', 'A stool culture identifies E. coli O157:H7 (STEC). The smear shows schistocytes, and LDH reflects RBC destruction.'),
  ('hus', 45, 'The nurse is planning care for a child with hemolytic uremic syndrome. Which laboratory values should the nurse plan to monitor closely?', '[{"id": "a", "text": "CBC, BUN, creatinine, and electrolytes"}, {"id": "b", "text": "Liver enzymes and lipase only"}, {"id": "c", "text": "Thyroid hormone and cortisol"}, {"id": "d", "text": "Hemoglobin A1C and lipid panel"}]'::jsonb, '["a"]', 'Nursing care for HUS includes close monitoring of CBC, BUN, creatinine, and electrolytes.'),
  ('hus', 46, 'A child with hemolytic uremic syndrome has rising BUN and creatinine levels. Which part of the disease process do these values reflect?', '[{"id": "a", "text": "Hemolytic anemia"}, {"id": "b", "text": "Thrombocytopenia"}, {"id": "c", "text": "Acute kidney injury"}, {"id": "d", "text": "Diarrheal prodrome"}]'::jsonb, '["c"]', 'Uremia, with elevated BUN and creatinine, results from the acute kidney injury component of HUS.'),
  ('hus', 47, 'The parent of a child with hemolytic uremic syndrome asks why the child''s skin and eyes look yellow. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The platelets are too low.\""}, {"id": "b", "text": "\"Red blood cells are breaking down.\""}, {"id": "c", "text": "\"The kidneys are making too much urine.\""}, {"id": "d", "text": "\"The child is reacting to an antibiotic.\""}]'::jsonb, '["b"]', 'Pallor, jaundice, and fatigue are manifestations of hemolytic anemia, in which RBCs are destroyed. Low platelets cause petechiae and bruising.'),
  ('hus', 48, 'A child with hemolytic uremic syndrome weighs more this morning than yesterday, and urine output has decreased. How should the nurse interpret these findings?', '[{"id": "a", "text": "Improving kidney function"}, {"id": "b", "text": "Expected growth for age"}, {"id": "c", "text": "Response to antibiotic therapy"}, {"id": "d", "text": "Fluid retention"}]'::jsonb, '["d"]', 'Daily weights are used to detect fluid retention; weight gain with decreasing output suggests the child is retaining fluid.'),
  ('hus', 49, 'The nurse is teaching a parent about safe food preparation to prevent hemolytic uremic syndrome. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I will wash produce carefully.\""}, {"id": "b", "text": "\"I will avoid unpasteurized milk.\""}, {"id": "c", "text": "\"I will keep raw meat away from salads.\""}, {"id": "d", "text": "\"Hamburger is safe once it looks brown outside.\""}]'::jsonb, '["d"]', 'Ground beef must be cooked to an internal temperature of at least 160°F (71°C); outside color does not confirm safety. The other statements are correct.'),
  ('hus', 50, 'The nurse is developing a plan of care for a child with hemolytic uremic syndrome and a low platelet count. Which intervention should be included?', '[{"id": "a", "text": "Use a soft toothbrush for oral care"}, {"id": "b", "text": "Give medications by IM injection"}, {"id": "c", "text": "Give antidiarrheals for loose stools"}, {"id": "d", "text": "Use a firm toothbrush twice daily"}]'::jsonb, '["a"]', 'Bleeding precautions for thrombocytopenia include a soft toothbrush and no IM injections.'),
  ('pkd', 1, 'A client with autosomal dominant polycystic kidney disease (ADPKD) asks about the chance of passing the disease to a child. The other parent is unaffected. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Each child has a 50% chance of inheriting it.\""}, {"id": "b", "text": "\"Each child has a 25% chance of inheriting it.\""}, {"id": "c", "text": "\"Every child you have will inherit the disease.\""}, {"id": "d", "text": "\"A child can only inherit it if both parents have it.\""}]'::jsonb, '["a"]', 'In ADPKD, one affected parent passes the disease to 50% of offspring. Requiring both parents to carry the gene describes ARPKD.'),
  ('pkd', 2, 'An infant is diagnosed with autosomal recessive polycystic kidney disease (ARPKD). Neither parent has kidney disease. The parents ask how their infant inherited the disorder. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Only one parent needs to pass on the gene.\""}, {"id": "b", "text": "\"Both of you must carry the gene for it to occur.\""}, {"id": "c", "text": "\"It is caused by an infection during pregnancy.\""}, {"id": "d", "text": "\"It develops from kidney stones in infancy.\""}]'::jsonb, '["b"]', 'ARPKD is rare, and both parents must carry the gene. A single affected parent passing the gene describes ADPKD.'),
  ('pkd', 3, 'A 22-year-old client whose parent has ADPKD asks when symptoms typically begin. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Symptoms usually begin in early infancy.\""}, {"id": "b", "text": "\"Symptoms usually begin in the teenage years.\""}, {"id": "c", "text": "\"Symptoms usually begin between ages 30 and 40.\""}, {"id": "d", "text": "\"Symptoms usually begin after age 70.\""}]'::jsonb, '["c"]', 'ADPKD symptoms develop in adulthood, typically at ages 30–40. Onset in infancy or childhood describes ARPKD.'),
  ('pkd', 4, 'A prenatal ultrasound shows oligohydramnios and enlarged fetal kidneys. The nurse recognizes that these findings are consistent with which condition?', '[{"id": "a", "text": "Adult-onset ADPKD"}, {"id": "b", "text": "Mitral valve prolapse"}, {"id": "c", "text": "Cerebral aneurysm"}, {"id": "d", "text": "ARPKD"}]'::jsonb, '["d"]', 'ARPKD may present prenatally as oligohydramnios with enlarged kidneys. ADPKD symptoms develop in adulthood.'),
  ('pkd', 5, 'A nursing student asks which form of polycystic kidney disease is most common. Which response by the nurse is correct?', '[{"id": "a", "text": "ADPKD, which accounts for about 90% of cases"}, {"id": "b", "text": "ARPKD, which accounts for about 90% of cases"}, {"id": "c", "text": "ADPKD, which accounts for about 10% of cases"}, {"id": "d", "text": "ARPKD, which accounts for about 50% of cases"}]'::jsonb, '["a"]', 'ADPKD is the most common form, accounting for 90% of PKD cases. ARPKD is rare.'),
  ('pkd', 6, 'A client with a family history of ADPKD undergoes genetic testing. Which result would confirm the diagnosis?', '[{"id": "a", "text": "A WT1 gene mutation"}, {"id": "b", "text": "A PKD1 or PKD2 gene mutation"}, {"id": "c", "text": "An extra copy of chromosome 21"}, {"id": "d", "text": "A missing X chromosome"}]'::jsonb, '["b"]', 'ADPKD is caused by PKD1 (chromosome 16) or PKD2 gene mutations, and genetic testing confirms these mutations.'),
  ('pkd', 7, 'The nurse is caring for a 38-year-old client with ADPKD. Which associated condition should the nurse include in the assessment?', '[{"id": "a", "text": "Hepatic fibrosis"}, {"id": "b", "text": "Oligohydramnios"}, {"id": "c", "text": "Mitral valve prolapse"}, {"id": "d", "text": "Aniridia"}]'::jsonb, '["c"]', 'ADPKD is associated with cerebral (berry) aneurysms, hepatic cysts, mitral valve prolapse, and diverticulosis. Hepatic fibrosis is associated with ARPKD.'),
  ('pkd', 8, 'The nurse is caring for a child with autosomal recessive polycystic kidney disease. Which associated condition should the nurse anticipate?', '[{"id": "a", "text": "Mitral valve prolapse"}, {"id": "b", "text": "Diverticulosis"}, {"id": "c", "text": "Berry aneurysm"}, {"id": "d", "text": "Hepatic fibrosis"}]'::jsonb, '["d"]', 'ARPKD is associated with hepatic fibrosis. Mitral valve prolapse, diverticulosis, and berry aneurysms are associated with ADPKD.'),
  ('pkd', 9, 'A nursing student is comparing the two types of polycystic kidney disease. Which statement by the student is accurate?', '[{"id": "a", "text": "\"ARPKD is more severe and can be fatal in newborns.\""}, {"id": "b", "text": "\"ADPKD is rare and requires two carrier parents.\""}, {"id": "c", "text": "\"ARPKD usually causes symptoms at ages 30 to 40.\""}, {"id": "d", "text": "\"ADPKD is associated mainly with hepatic fibrosis.\""}]'::jsonb, '["a"]', 'ARPKD is more severe and often fatal in newborns with severe disease. The other statements reverse features of ADPKD and ARPKD.'),
  ('pkd', 10, 'A client with ADPKD asks why the flank and back pain occur. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Stones are blocking both ureters.\""}, {"id": "b", "text": "\"Enlarged cystic kidneys press on nearby structures.\""}, {"id": "c", "text": "\"The kidneys are shrinking and scarring.\""}, {"id": "d", "text": "\"Blood pressure medicine is irritating the kidneys.\""}]'::jsonb, '["b"]', 'Flank and back pain in PKD results from enlarged cystic kidneys pushing on surrounding structures. The kidneys enlarge rather than shrink.'),
  ('pkd', 11, 'A client with polycystic kidney disease reports blood in the urine. The nurse understands that this is most likely caused by which mechanism?', '[{"id": "a", "text": "Renin secretion from compressed vessels"}, {"id": "b", "text": "Reduced urine concentrating ability"}, {"id": "c", "text": "Cysts rupturing into the collecting system"}, {"id": "d", "text": "Immune complexes in the glomeruli"}]'::jsonb, '["c"]', 'Hematuria in PKD occurs when cysts rupture into the collecting system. Renin secretion explains hypertension, and reduced concentrating ability explains nocturia.'),
  ('pkd', 12, 'A client with ADPKD asks why blood pressure has become elevated. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Cysts are rupturing into the urine.\""}, {"id": "b", "text": "\"Drinking 2 to 3 liters a day raises pressure.\""}, {"id": "c", "text": "\"The kidneys can no longer concentrate urine.\""}, {"id": "d", "text": "\"Compressed kidney vessels release renin.\""}]'::jsonb, '["d"]', 'Hypertension in PKD results from renin secretion caused by compressed renal vasculature. Cyst rupture causes hematuria, not hypertension.'),
  ('pkd', 13, 'During a physical assessment of a client with advanced ADPKD, which finding should the nurse expect?', '[{"id": "a", "text": "Palpably enlarged kidneys on both sides"}, {"id": "b", "text": "A single small kidney on one side"}, {"id": "c", "text": "Kidneys that cannot be palpated at all"}, {"id": "d", "text": "One enlarged kidney with a normal other side"}]'::jsonb, '["a"]', 'PKD causes palpably enlarged kidneys bilaterally.'),
  ('pkd', 14, 'A client with polycystic kidney disease reports waking several times each night to urinate. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Your blood pressure medicine is causing it.\""}, {"id": "b", "text": "\"Your kidneys are less able to concentrate urine.\""}, {"id": "c", "text": "\"A cyst has ruptured into your bladder.\""}, {"id": "d", "text": "\"Your kidneys are making too much renin.\""}]'::jsonb, '["b"]', 'Nocturia in PKD results from reduced concentrating ability. Renin secretion is the cause of hypertension.'),
  ('pkd', 15, 'A client with ADPKD has fever and symptoms of a urinary tract infection. Which treatment should the nurse anticipate?', '[{"id": "a", "text": "Tolvaptan to shrink the cysts"}, {"id": "b", "text": "An NSAID for the fever"}, {"id": "c", "text": "Antibiotics to treat the infection"}, {"id": "d", "text": "Fluid restriction to 1 L/day"}]'::jsonb, '["c"]', 'Antibiotics are used to treat cyst infections and UTIs because cysts can harbor bacteria. NSAIDs are avoided because they are nephrotoxic.'),
  ('pkd', 16, 'A client with polycystic kidney disease and a history of renal calculi asks why a high fluid intake is recommended. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It raises your blood pressure to a safe level.\""}, {"id": "b", "text": "\"It increases the size of the kidneys.\""}, {"id": "c", "text": "\"It replaces the need for blood pressure medicine.\""}, {"id": "d", "text": "\"It dilutes the urine and helps prevent stones.\""}]'::jsonb, '["d"]', 'Adequate hydration of 2–3 L/day dilutes urine and helps prevent calculi. Fluids do not raise blood pressure or enlarge the kidneys.'),
  ('pkd', 17, 'The nurse is teaching a client with early ADPKD about daily fluid intake. Which amount should the nurse recommend?', '[{"id": "a", "text": "2–3 L per day"}, {"id": "b", "text": "500 mL per day"}, {"id": "c", "text": "1 L per day"}, {"id": "d", "text": "5–6 L per day"}]'::jsonb, '["a"]', 'Clients with PKD are encouraged to drink 2–3 L/day of fluid unless they have ESRD.'),
  ('pkd', 18, 'The nurse is caring for several clients with polycystic kidney disease. For which client should the nurse NOT encourage a fluid intake of 2–3 L/day?', '[{"id": "a", "text": "A client with a history of renal calculi"}, {"id": "b", "text": "A client with end-stage renal disease"}, {"id": "c", "text": "A client newly diagnosed with ADPKD"}, {"id": "d", "text": "A client with recurrent urinary infections"}]'::jsonb, '["b"]', 'Fluid intake of 2–3 L/day is encouraged in PKD unless the client has ESRD.'),
  ('pkd', 19, 'A client with ADPKD suddenly reports "the worst headache of my life." Which action should the nurse take first?', '[{"id": "a", "text": "Give acetaminophen and reassess in 1 hour"}, {"id": "b", "text": "Encourage the client to drink more fluids"}, {"id": "c", "text": "Notify the provider as an emergency"}, {"id": "d", "text": "Dim the lights and let the client rest"}]'::jsonb, '["c"]', 'A sudden, severe thunderclap headache in ADPKD is a ruptured cerebral aneurysm until proven otherwise and is a medical emergency. Treating it as a routine headache delays care.'),
  ('pkd', 20, 'The nurse teaches a client with ADPKD about warning signs of complications. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will have my blood pressure checked regularly.\""}, {"id": "b", "text": "\"I will avoid contact sports like football.\""}, {"id": "c", "text": "\"I will use acetaminophen instead of NSAIDs.\""}, {"id": "d", "text": "\"If I get a sudden severe headache, I will wait it out.\""}]'::jsonb, '["d"]', 'Clients with ADPKD must report a sudden severe headache immediately because it may indicate an aneurysm. The other statements are correct.'),
  ('pkd', 21, 'A nursing student asks which complication of ADPKD is the most dangerous. Which response by the nurse is correct?', '[{"id": "a", "text": "Cerebral aneurysm"}, {"id": "b", "text": "Nocturia"}, {"id": "c", "text": "Hepatic cysts"}, {"id": "d", "text": "Diverticulosis"}]'::jsonb, '["a"]', 'Cerebral aneurysm is the most dangerous complication of ADPKD, and a severe headache is an emergency.'),
  ('pkd', 22, 'A client with ADPKD has a parent who had a cerebral aneurysm. Which diagnostic study should the nurse anticipate?', '[{"id": "a", "text": "Renal biopsy of one kidney"}, {"id": "b", "text": "MRA or CT angiography of the brain"}, {"id": "c", "text": "Chest x-ray of both lungs"}, {"id": "d", "text": "Stool culture for bacteria"}]'::jsonb, '["b"]', 'MRA or CT angiography of the brain is used to screen for cerebral aneurysm in ADPKD when there is a family history.'),
  ('pkd', 23, 'A 35-year-old client with a parent who has ADPKD reports flank pain. Which diagnostic test is the first-line screening study?', '[{"id": "a", "text": "Genetic testing"}, {"id": "b", "text": "MRA of the brain"}, {"id": "c", "text": "Renal ultrasound"}, {"id": "d", "text": "Kidney transplant workup"}]'::jsonb, '["c"]', 'Renal ultrasound is the first-line screening test and shows bilateral cysts.'),
  ('pkd', 24, 'The adult children of a client with ADPKD ask how they can find out whether they carry the disease. Which test should the nurse explain?', '[{"id": "a", "text": "Urinalysis"}, {"id": "b", "text": "Basic metabolic panel"}, {"id": "c", "text": "Liver function tests"}, {"id": "d", "text": "Genetic testing"}]'::jsonb, '["d"]', 'Genetic testing confirms PKD1/PKD2 mutations and screens family members.'),
  ('pkd', 25, 'A client with ADPKD whose ultrasound showed bilateral cysts is scheduled for an MRI of the kidneys. The client asks the purpose of the MRI. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It better characterizes the cysts and stages the disease.\""}, {"id": "b", "text": "\"It removes fluid from the largest cysts.\""}, {"id": "c", "text": "\"It screens your family for the gene.\""}, {"id": "d", "text": "\"It measures how well the liver is working.\""}]'::jsonb, '["a"]', 'CT or MRI provides better characterization of cysts and staging. Genetic testing, not imaging, screens family members.'),
  ('pkd', 26, 'The nurse teaches a newly diagnosed client about ADPKD management. Which statement by the client indicates correct understanding?', '[{"id": "a", "text": "\"Surgery to remove the cysts will cure my disease.\""}, {"id": "b", "text": "\"Treatment aims to slow progression and control complications.\""}, {"id": "c", "text": "\"Once my blood pressure is normal, the disease is cured.\""}, {"id": "d", "text": "\"Antibiotics will clear the cysts from my kidneys.\""}]'::jsonb, '["b"]', 'There is no cure for PKD; management focuses on slowing progression and controlling complications.'),
  ('pkd', 27, 'A client with ADPKD has a persistently elevated blood pressure. Which class of medication should the nurse anticipate as first-line therapy?', '[{"id": "a", "text": "Loop diuretics"}, {"id": "b", "text": "Corticosteroids"}, {"id": "c", "text": "ACE inhibitors or ARBs"}, {"id": "d", "text": "Nonsteroidal anti-inflammatory drugs"}]'::jsonb, '["c"]', 'ACE inhibitors and ARBs manage blood pressure in PKD. NSAIDs are avoided because they are nephrotoxic.'),
  ('pkd', 28, 'A client with ADPKD has been taking an ARB for several months. Which finding best indicates that the medication is effective?', '[{"id": "a", "text": "Increased frequency of nocturia"}, {"id": "b", "text": "Larger cysts on ultrasound"}, {"id": "c", "text": "Rising serum creatinine"}, {"id": "d", "text": "Lower blood pressure with less proteinuria"}]'::jsonb, '["d"]', 'ACE inhibitors and ARBs are first-line for hypertension and also reduce proteinuria.'),
  ('pkd', 29, 'A client with ADPKD is started on tolvaptan. Which laboratory test should the nurse plan to monitor?', '[{"id": "a", "text": "Liver function tests"}, {"id": "b", "text": "Platelet count"}, {"id": "c", "text": "ASO titer"}, {"id": "d", "text": "Stool culture"}]'::jsonb, '["a"]', 'Tolvaptan, a V2 receptor antagonist approved for ADPKD, requires monitoring of liver function tests (LFTs).'),
  ('pkd', 30, 'A client with ADPKD asks how tolvaptan will help. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It treats infections inside the cysts.\""}, {"id": "b", "text": "\"It slows the growth of the cysts.\""}, {"id": "c", "text": "\"It cures the disease in most clients.\""}, {"id": "d", "text": "\"It replaces the need for fluids.\""}]'::jsonb, '["b"]', 'Tolvaptan is a V2 receptor antagonist that slows cyst growth. There is no cure for PKD, and antibiotics treat cyst infections.'),
  ('pkd', 31, 'A client with ADPKD now has a GFR of 12. Which plan of care should the nurse anticipate?', '[{"id": "a", "text": "Starting tolvaptan to cure the disease"}, {"id": "b", "text": "Increasing fluids to 3 L/day"}, {"id": "c", "text": "Preparing for dialysis or transplant"}, {"id": "d", "text": "Stopping all blood pressure checks"}]'::jsonb, '["c"]', 'Dialysis or kidney transplant is end-stage management when GFR is below 15. Increased fluid intake is not encouraged in ESRD.'),
  ('pkd', 32, 'The nurse teaches a client with ADPKD about pain management. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll use acetaminophen for my back pain.\""}, {"id": "b", "text": "\"I''ll avoid taking large doses of acetaminophen.\""}, {"id": "c", "text": "\"I''ll tell my provider about any new pain.\""}, {"id": "d", "text": "\"I''ll take an NSAID when my flank pain flares.\""}]'::jsonb, '["d"]', 'NSAIDs should be avoided because they are nephrotoxic and worsen kidney function. Acetaminophen in limited doses is the preferred analgesic.'),
  ('pkd', 33, 'A client with ADPKD asks which over-the-counter pain reliever is safest for flank pain. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Acetaminophen, used cautiously and not in large doses\""}, {"id": "b", "text": "\"An NSAID, because it reduces kidney inflammation\""}, {"id": "c", "text": "\"An NSAID, taken with plenty of fluids\""}, {"id": "d", "text": "\"Acetaminophen, in doses as large as needed\""}]'::jsonb, '["a"]', 'Acetaminophen is the preferred analgesic but should be used cautiously, avoiding large doses. NSAIDs are nephrotoxic.'),
  ('pkd', 34, 'A client with ADPKD has been taught about analgesic use. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will not take NSAIDs for my pain.\""}, {"id": "b", "text": "\"Acetaminophen is safe, so I can take large doses.\""}, {"id": "c", "text": "\"Acetaminophen is the preferred pain reliever.\""}, {"id": "d", "text": "\"I will use acetaminophen cautiously.\""}]'::jsonb, '["b"]', 'Acetaminophen is preferred but must be used cautiously and large doses avoided.'),
  ('pkd', 35, 'A 30-year-old client with ADPKD plays on a weekend rugby team. Which teaching should the nurse provide?', '[{"id": "a", "text": "\"Increase protein intake on game days.\""}, {"id": "b", "text": "\"Take an NSAID before each game.\""}, {"id": "c", "text": "\"Avoid contact sports to prevent cyst rupture.\""}, {"id": "d", "text": "\"Limit fluids during games to protect the kidneys.\""}]'::jsonb, '["c"]', 'Clients with PKD should avoid contact sports or activities with risk of abdominal trauma because of cyst rupture.'),
  ('pkd', 36, 'The nurse is reviewing dietary teaching with a client with ADPKD. Which instruction is appropriate?', '[{"id": "a", "text": "\"Increase caffeine to promote urine flow.\""}, {"id": "b", "text": "\"Limit fluids to less than 1 L per day.\""}, {"id": "c", "text": "\"Increase sodium to raise urine output.\""}, {"id": "d", "text": "\"Avoid caffeine because it may stimulate cyst growth.\""}]'::jsonb, '["d"]', 'Caffeine should be avoided because it may stimulate cyst growth. Fluids of 2–3 L/day are encouraged unless the client has ESRD.'),
  ('pkd', 37, 'The nurse is reviewing the medication orders for a client with polycystic kidney disease. Which type of drug should the nurse recognize as nephrotoxic?', '[{"id": "a", "text": "Aminoglycosides"}, {"id": "b", "text": "Acetaminophen in limited doses"}, {"id": "c", "text": "ACE inhibitors"}, {"id": "d", "text": "ARBs"}]'::jsonb, '["a"]', 'Nephrotoxic drugs to avoid in PKD include NSAIDs, aminoglycosides, and contrast dye. ACE inhibitors and ARBs are first-line for blood pressure.'),
  ('pkd', 38, 'A client with polycystic kidney disease is scheduled for a procedure that requires contrast dye. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Encourage an NSAID before the procedure"}, {"id": "b", "text": "Clarify the order because contrast is nephrotoxic"}, {"id": "c", "text": "Withhold the client''s ACE inhibitor indefinitely"}, {"id": "d", "text": "Restrict all fluids for 24 hours afterward"}]'::jsonb, '["b"]', 'Contrast dye is a nephrotoxic agent that clients with PKD should avoid, so the nurse should clarify the order. NSAIDs are also nephrotoxic.'),
  ('pkd', 39, 'A client with ADPKD and the client''s partner are planning to have children. Which referral is most appropriate?', '[{"id": "a", "text": "Physical therapy"}, {"id": "b", "text": "Dietitian for a high-protein diet"}, {"id": "c", "text": "Genetic counseling"}, {"id": "d", "text": "Sports medicine clinic"}]'::jsonb, '["c"]', 'Genetic counseling is a nursing priority because ADPKD carries a 50% inheritance risk.'),
  ('pkd', 40, 'The spouse and adult children of a client newly diagnosed with ADPKD appear anxious during a clinic visit. Which nursing action is most appropriate?', '[{"id": "a", "text": "Tell them the disease is easily cured"}, {"id": "b", "text": "Limit the discussion to the client only"}, {"id": "c", "text": "Advise them that screening is unnecessary"}, {"id": "d", "text": "Provide emotional support to the whole family"}]'::jsonb, '["d"]', 'PKD is a chronic, progressive, genetic disease that affects the whole family, so emotional support is a nursing priority.'),
  ('pkd', 41, 'A client with ADPKD has declining renal function. Which diet should the nurse anticipate?', '[{"id": "a", "text": "Low-protein, low-sodium diet"}, {"id": "b", "text": "High-protein, high-sodium diet"}, {"id": "c", "text": "High-protein, low-sodium diet"}, {"id": "d", "text": "Low-protein, high-sodium diet"}]'::jsonb, '["a"]', 'A low-protein, low-sodium diet is recommended as renal function declines in PKD.'),
  ('pkd', 42, 'The nurse is planning ongoing care for a client with ADPKD. Which assessment addresses the leading modifiable complication?', '[{"id": "a", "text": "Daily abdominal girth"}, {"id": "b", "text": "Blood pressure monitoring"}, {"id": "c", "text": "Weekly temperature checks"}, {"id": "d", "text": "Hourly neurological checks"}]'::jsonb, '["b"]', 'Monitoring blood pressure is a priority because hypertension is the leading modifiable complication of PKD.'),
  ('pkd', 43, 'Which laboratory values should the nurse plan to monitor regularly in a client with ADPKD?', '[{"id": "a", "text": "ASO titer and C3"}, {"id": "b", "text": "Platelets and LDH"}, {"id": "c", "text": "BUN, creatinine, and GFR"}, {"id": "d", "text": "Stool culture and smear"}]'::jsonb, '["c"]', 'Nursing priorities for PKD include regular monitoring of BUN, creatinine, and GFR.'),
  ('pkd', 44, 'A CT scan of a client with ADPKD shows cysts in the liver. How should the nurse interpret this finding?', '[{"id": "a", "text": "Metastatic spread from the kidneys"}, {"id": "b", "text": "A side effect of tolvaptan"}, {"id": "c", "text": "An unrelated incidental tumor"}, {"id": "d", "text": "An extra-renal manifestation of PKD"}]'::jsonb, '["d"]', 'Extra-renal cysts in the liver, pancreas, or spleen are extra-renal manifestations of PKD.'),
  ('pkd', 45, 'Which finding helps the nurse distinguish ARPKD from ADPKD?', '[{"id": "a", "text": "Symptoms appear in infancy or childhood"}, {"id": "b", "text": "Symptoms appear between ages 30 and 40"}, {"id": "c", "text": "Only one parent needs to carry the gene"}, {"id": "d", "text": "It accounts for 90% of PKD cases"}]'::jsonb, '["a"]', 'ARPKD symptoms present in infancy or childhood. Onset at ages 30–40, single-parent inheritance, and 90% of cases describe ADPKD.'),
  ('pkd', 46, 'Which group of findings is most consistent with polycystic kidney disease?', '[{"id": "a", "text": "Periorbital edema, cola urine, and low C3"}, {"id": "b", "text": "Flank pain, hematuria, hypertension, enlarged kidneys"}, {"id": "c", "text": "Painless mass, hypotension, and small kidneys"}, {"id": "d", "text": "Polyuria, hypotension, and shrunken kidneys"}]'::jsonb, '["b"]', 'PKD presents with flank pain, hematuria, hypertension, and enlarged kidneys.'),
  ('pkd', 47, 'A client newly diagnosed with polycystic kidney disease asks what is happening to the kidneys. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Stones are slowly blocking the kidney tubes.\""}, {"id": "b", "text": "\"An infection is causing the kidneys to swell.\""}, {"id": "c", "text": "\"Fluid-filled cysts gradually replace normal tissue.\""}, {"id": "d", "text": "\"A tumor is growing inside one of the kidneys.\""}]'::jsonb, '["c"]', 'PKD is a genetic disorder in which fluid-filled cysts replace normal kidney tissue, leading to progressive kidney failure.'),
  ('pkd', 48, 'A client with ADPKD asks about the long-term outlook for kidney function. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Kidney function usually returns to normal.\""}, {"id": "b", "text": "\"The cysts usually disappear by age 50.\""}, {"id": "c", "text": "\"Only one kidney is ever affected.\""}, {"id": "d", "text": "\"It may progress to end-stage disease needing dialysis.\""}]'::jsonb, '["d"]', 'PKD causes progressive renal insufficiency leading to ESRD, which requires dialysis or transplant.'),
  ('pkd', 49, 'The nurse reviews the urinalysis of a client with polycystic kidney disease. Which findings are expected?', '[{"id": "a", "text": "Hematuria and proteinuria"}, {"id": "b", "text": "Ketones and glucose"}, {"id": "c", "text": "Bilirubin and urobilinogen"}, {"id": "d", "text": "Crystals and yeast only"}]'::jsonb, '["a"]', 'Urinalysis in PKD may show hematuria, proteinuria, and possible infection.'),
  ('pkd', 50, 'The nurse is teaching a client with ADPKD about safe activity. Which statement by the client indicates correct understanding?', '[{"id": "a", "text": "\"Contact sports are fine if I drink more fluids.\""}, {"id": "b", "text": "\"I will avoid activities that risk injury to my abdomen.\""}, {"id": "c", "text": "\"Only my back needs protection, not my abdomen.\""}, {"id": "d", "text": "\"I can return to football once my blood pressure is normal.\""}]'::jsonb, '["b"]', 'Clients with PKD should avoid contact sports and activities with abdominal trauma risk because of cyst rupture.'),
  ('wilms', 1, 'A nurse in a pediatric clinic is reviewing risk for Wilms tumor. Which child is in the peak age range for this tumor?', '[{"id": "a", "text": "A 3-year-old child"}, {"id": "b", "text": "A 10-year-old child"}, {"id": "c", "text": "A 15-year-old adolescent"}, {"id": "d", "text": "A 6-month-old infant"}]'::jsonb, '["a"]', 'Wilms tumor is the most common renal malignancy in children, with a peak age of 2–5 years.'),
  ('wilms', 2, 'A parent brings a 4-year-old child to the clinic after noticing a lump in the child''s abdomen. Which description of the mass is most consistent with Wilms tumor?', '[{"id": "a", "text": "Painful, soft, and on both sides"}, {"id": "b", "text": "Painless, firm, smooth, and on one side"}, {"id": "c", "text": "Painful, irregular, and pulsating"}, {"id": "d", "text": "Painless, soft, and in the groin"}]'::jsonb, '["b"]', 'Wilms tumor typically presents as a painless, palpable abdominal mass that is smooth, firm, and unilateral, often found by a parent during a bath.'),
  ('wilms', 3, 'A 3-year-old child is admitted with a suspected Wilms tumor. Which nursing action is the priority?', '[{"id": "a", "text": "Palpate the mass to measure its size"}, {"id": "b", "text": "Massage the abdomen to relieve discomfort"}, {"id": "c", "text": "Post a sign stating not to palpate the abdomen"}, {"id": "d", "text": "Press on the flank to check for tenderness"}]'::jsonb, '["c"]', 'The abdomen must never be palpated because pressure can rupture the tumor capsule and spread cancer. Palpating, massaging, or pressing on the abdomen is unsafe.'),
  ('wilms', 4, 'The parent of a child with a suspected Wilms tumor asks why the staff will not feel the child''s abdomen. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Touching the belly causes the child too much pain.\""}, {"id": "b", "text": "\"Pressure may cause the kidney to stop making urine.\""}, {"id": "c", "text": "\"The mass is too deep to feel on examination.\""}, {"id": "d", "text": "\"Pressure could rupture the tumor and spread the cancer.\""}]'::jsonb, '["d"]', 'Pressure can rupture the tumor capsule, causing cancer to spread to the peritoneum and lymph nodes. The mass is typically painless and palpable, so pain and depth are not the reasons.'),
  ('wilms', 5, 'The nurse teaches the parents of a child with Wilms tumor about home care. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"Gently rubbing my child''s belly will help with comfort.\""}, {"id": "b", "text": "\"I will tell the babysitter not to press on the belly.\""}, {"id": "c", "text": "\"I will report any fever or blood in the urine right away.\""}, {"id": "d", "text": "\"My child should avoid contact sports after surgery.\""}]'::jsonb, '["a"]', 'All caregivers must be told not to press on or massage the child''s abdomen; this is a strict contraindication. The other statements are correct.'),
  ('wilms', 6, 'The parent of a child with Wilms tumor asks whether blood in the urine is always present with this tumor. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, it is present in every child.\""}, {"id": "b", "text": "\"No, it occurs in about 20% of children.\""}, {"id": "c", "text": "\"No, it occurs only after surgery.\""}, {"id": "d", "text": "\"Yes, it is the first sign in most children.\""}]'::jsonb, '["b"]', 'Hematuria is present in about 20% of cases of Wilms tumor. The most common finding is a painless abdominal mass.'),
  ('wilms', 7, 'The nurse is assessing a 4-year-old child newly diagnosed with Wilms tumor. Which vital sign finding should the nurse anticipate?', '[{"id": "a", "text": "Low blood pressure"}, {"id": "b", "text": "Slow respiratory rate"}, {"id": "c", "text": "Elevated blood pressure"}, {"id": "d", "text": "Low body temperature"}]'::jsonb, '["c"]', 'Hypertension occurs in Wilms tumor because of renin secretion by the tumor.'),
  ('wilms', 8, 'In addition to an abdominal mass, which findings should the nurse expect when assessing a child with Wilms tumor?', '[{"id": "a", "text": "Weight gain and high fever"}, {"id": "b", "text": "Polyuria and increased appetite"}, {"id": "c", "text": "Periorbital edema and cola urine"}, {"id": "d", "text": "Low-grade fever and anorexia"}]'::jsonb, '["d"]', 'Children with Wilms tumor may have low-grade fever, anorexia, weight loss, and nausea. Weight gain and increased appetite are not expected.'),
  ('wilms', 9, 'The parent of a child with Wilms tumor asks whether the tumor causes pain. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Discomfort may occur if the mass becomes large.\""}, {"id": "b", "text": "\"Severe pain is usually the first sign.\""}, {"id": "c", "text": "\"Pain occurs only with bilateral tumors.\""}, {"id": "d", "text": "\"Pain is constant from the start.\""}]'::jsonb, '["a"]', 'The mass is typically painless, but abdominal pain or discomfort may occur if the mass is large.'),
  ('wilms', 10, 'The parent of a child with Wilms tumor asks whether both kidneys are usually affected. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Both kidneys are affected in most children.\""}, {"id": "b", "text": "\"Usually only one kidney is affected.\""}, {"id": "c", "text": "\"Both kidneys are always affected.\""}, {"id": "d", "text": "\"The tumor starts outside the kidneys.\""}]'::jsonb, '["b"]', 'Wilms tumor is usually unilateral; it is bilateral in only 5–10% of cases.'),
  ('wilms', 11, 'A 2-year-old child has aniridia and genitourinary anomalies. The nurse recognizes that this child has an increased risk of which condition?', '[{"id": "a", "text": "Polycystic kidney disease"}, {"id": "b", "text": "Hemolytic uremic syndrome"}, {"id": "c", "text": "Wilms tumor"}, {"id": "d", "text": "Glomerulonephritis"}]'::jsonb, '["c"]', 'Wilms tumor is associated with WAGR syndrome, which includes Wilms tumor, aniridia, and genitourinary anomalies.'),
  ('wilms', 12, 'A nursing student asks about the genetic basis of Wilms tumor. Which response by the nurse is accurate?', '[{"id": "a", "text": "A PKD1 gene mutation"}, {"id": "b", "text": "An extra chromosome 21"}, {"id": "c", "text": "A PKD2 gene mutation"}, {"id": "d", "text": "A WT1 tumor suppressor gene mutation"}]'::jsonb, '["d"]', 'Wilms tumor is associated with a mutation in the WT1 tumor suppressor gene.'),
  ('wilms', 13, 'The parents of a child newly diagnosed with Wilms tumor ask about their child''s chances of survival. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"With treatment, more than 90% of children survive.\""}, {"id": "b", "text": "\"With treatment, about half of children survive.\""}, {"id": "c", "text": "\"Survival is rare even with treatment.\""}, {"id": "d", "text": "\"Treatment rarely changes the outcome.\""}]'::jsonb, '["a"]', 'The prognosis for Wilms tumor is excellent, with an overall survival rate greater than 90% with treatment.'),
  ('wilms', 14, 'A child with Wilms tumor is being evaluated for metastasis. To which site does Wilms tumor primarily spread?', '[{"id": "a", "text": "Brain"}, {"id": "b", "text": "Lungs"}, {"id": "c", "text": "Bone"}, {"id": "d", "text": "Skin"}]'::jsonb, '["b"]', 'The lung is the primary metastasis site for Wilms tumor.'),
  ('wilms', 15, 'The parents of a child with Wilms tumor ask what the main treatment will be. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Radiation alone is the main treatment.\""}, {"id": "b", "text": "\"Antibiotics are the main treatment.\""}, {"id": "c", "text": "\"Removal of the affected kidney is the main treatment.\""}, {"id": "d", "text": "\"Dialysis is the main treatment.\""}]'::jsonb, '["c"]', 'Nephrectomy, removal of the affected kidney, is the primary treatment for Wilms tumor.'),
  ('wilms', 16, 'A child with an abdominal mass is suspected of having Wilms tumor. Which diagnostic test does the nurse anticipate first?', '[{"id": "a", "text": "Renal biopsy"}, {"id": "b", "text": "Chest x-ray"}, {"id": "c", "text": "CT of the chest"}, {"id": "d", "text": "Abdominal ultrasound"}]'::jsonb, '["d"]', 'Abdominal ultrasound is the first-line, non-invasive diagnostic test for Wilms tumor.'),
  ('wilms', 17, 'The parent of a child with Wilms tumor asks why a CT scan of the abdomen and chest is needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It stages the tumor and checks for spread.\""}, {"id": "b", "text": "\"It removes part of the tumor for testing.\""}, {"id": "c", "text": "\"It shrinks the tumor before surgery.\""}, {"id": "d", "text": "\"It measures how much urine is made.\""}]'::jsonb, '["a"]', 'CT of the abdomen and chest is used for staging and to check for metastasis.'),
  ('wilms', 18, 'A child''s Wilms tumor is found to involve both kidneys. The nurse understands that this is classified as which stage?', '[{"id": "a", "text": "Stage III"}, {"id": "b", "text": "Stage V"}, {"id": "c", "text": "Stage I"}, {"id": "d", "text": "Stage IV"}]'::jsonb, '["b"]', 'Stage V Wilms tumor is defined by bilateral kidney involvement.'),
  ('wilms', 19, 'A child''s Wilms tumor is confined to the kidney and completely resectable. The nurse understands that this is classified as which stage?', '[{"id": "a", "text": "Stage II"}, {"id": "b", "text": "Stage III"}, {"id": "c", "text": "Stage I"}, {"id": "d", "text": "Stage V"}]'::jsonb, '["c"]', 'Stage I Wilms tumor is confined to the kidney and is completely resectable.'),
  ('wilms', 20, 'A child''s Wilms tumor has spread through the bloodstream to the lungs. The nurse understands that this is classified as which stage?', '[{"id": "a", "text": "Stage I"}, {"id": "b", "text": "Stage II"}, {"id": "c", "text": "Stage V"}, {"id": "d", "text": "Stage IV"}]'::jsonb, '["d"]', 'Stage IV Wilms tumor involves hematogenous metastasis to sites such as the lungs and liver.'),
  ('wilms', 21, 'After nephrectomy, a child is found to have residual tumor in the abdomen with lymph node involvement. The nurse understands that this is classified as which stage?', '[{"id": "a", "text": "Stage III"}, {"id": "b", "text": "Stage I"}, {"id": "c", "text": "Stage II"}, {"id": "d", "text": "Stage V"}]'::jsonb, '["a"]', 'Stage III Wilms tumor involves residual tumor in the abdomen after surgery with lymph node involvement.'),
  ('wilms', 22, 'A child''s Wilms tumor extended beyond the kidney but was completely removed during surgery. The nurse understands that this is classified as which stage?', '[{"id": "a", "text": "Stage I"}, {"id": "b", "text": "Stage II"}, {"id": "c", "text": "Stage IV"}, {"id": "d", "text": "Stage V"}]'::jsonb, '["b"]', 'Stage II Wilms tumor extends beyond the kidney but is completely removed surgically.'),
  ('wilms', 23, 'The parents of a child scheduled for nephrectomy for Wilms tumor ask when a tissue sample of the tumor will be obtained. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Several weeks after the surgery\""}, {"id": "b", "text": "\"Only if the tumor comes back later\""}, {"id": "c", "text": "\"During the surgery to remove the kidney\""}, {"id": "d", "text": "\"Only after chemotherapy is finished\""}]'::jsonb, '["c"]', 'In Wilms tumor, the affected kidney is removed by nephrectomy, with a biopsy taken intraoperatively.'),
  ('wilms', 24, 'A child returns to the unit after a nephrectomy for Wilms tumor. Which assessment is most important for the nurse to monitor closely?', '[{"id": "a", "text": "Head circumference"}, {"id": "b", "text": "Hair loss pattern"}, {"id": "c", "text": "Hearing acuity"}, {"id": "d", "text": "Urine output"}]'::jsonb, '["d"]', 'Urine output must be monitored closely after nephrectomy because only one kidney remains and it must maintain adequate function.'),
  ('wilms', 25, 'A child is 4 hours post-nephrectomy for Wilms tumor. Which set of findings should the nurse report immediately?', '[{"id": "a", "text": "Falling blood pressure and rising heart rate"}, {"id": "b", "text": "Rising blood pressure and slowing heart rate"}, {"id": "c", "text": "Mild incisional pain relieved by analgesics"}, {"id": "d", "text": "Steady urine output and stable vital signs"}]'::jsonb, '["a"]', 'Signs of bleeding or hemorrhage after nephrectomy include decreased blood pressure, increased heart rate, and hematuria.'),
  ('wilms', 26, 'The parent of a child who had a nephrectomy for Wilms tumor asks why blood pressure is still being checked frequently. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Blood pressure always drops after the tumor is removed.\""}, {"id": "b", "text": "\"High blood pressure may continue after surgery.\""}, {"id": "c", "text": "\"Blood pressure checks are needed only for chemotherapy.\""}, {"id": "d", "text": "\"Blood pressure is checked to measure urine output.\""}]'::jsonb, '["b"]', 'The nurse monitors blood pressure after surgery because hypertension may persist post-op.'),
  ('wilms', 27, 'A 4-year-old child is reporting pain on the first day after a nephrectomy for Wilms tumor. Which intervention is appropriate for the nurse to include?', '[{"id": "a", "text": "Massage the abdomen around the incision"}, {"id": "b", "text": "Withhold analgesics to monitor urine output"}, {"id": "c", "text": "Give analgesics and help reposition the child"}, {"id": "d", "text": "Give an NSAID to reduce inflammation"}]'::jsonb, '["c"]', 'Post-op pain management includes analgesics, repositioning, and comfort measures. NSAIDs are avoided to protect the remaining kidney, and the abdomen should not be massaged.'),
  ('wilms', 28, 'The nurse is reviewing post-nephrectomy prescriptions for a child with Wilms tumor. Which prescription should the nurse question?', '[{"id": "a", "text": "Analgesic for incisional pain"}, {"id": "b", "text": "Strict measurement of urine output"}, {"id": "c", "text": "Blood pressure monitoring every 4 hours"}, {"id": "d", "text": "An NSAID for pain"}]'::jsonb, '["d"]', 'Nephrotoxic medications such as NSAIDs should be avoided to protect the remaining kidney.'),
  ('wilms', 29, 'A child who had a nephrectomy for Wilms tumor develops an infection. Which class of antibiotic should the nurse question because of its effect on the remaining kidney?', '[{"id": "a", "text": "Aminoglycoside"}, {"id": "b", "text": "Antiemetic"}, {"id": "c", "text": "Analgesic"}, {"id": "d", "text": "Antipyretic"}]'::jsonb, '["a"]', 'Aminoglycosides, like NSAIDs, are nephrotoxic and should be avoided to protect the remaining kidney.'),
  ('wilms', 30, 'The nurse is teaching the parents of a child after nephrectomy for Wilms tumor about diet. Which instruction is appropriate?', '[{"id": "a", "text": "\"Offer a high-sodium diet to support blood pressure.\""}, {"id": "b", "text": "\"Avoid a high-sodium diet and keep your child well hydrated.\""}, {"id": "c", "text": "\"Limit fluids to reduce the workload on the kidney.\""}, {"id": "d", "text": "\"Increase salty snacks to replace lost electrolytes.\""}]'::jsonb, '["b"]', 'After nephrectomy, the child should avoid a high-sodium diet and maintain adequate hydration.'),
  ('wilms', 31, 'The nurse teaches the parents of a child after nephrectomy for Wilms tumor about activity. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"My child should avoid rough contact games.\""}, {"id": "b", "text": "\"I''ll make sure my child wears a medical alert band.\""}, {"id": "c", "text": "\"My child can play tackle football once the incision heals.\""}, {"id": "d", "text": "\"I''ll protect my child from blows to the abdomen.\""}]'::jsonb, '["c"]', 'Children who have had a nephrectomy should avoid contact sports and abdominal trauma to protect the remaining kidney.'),
  ('wilms', 32, 'A child with Wilms tumor is receiving chemotherapy after nephrectomy. Which side effects should the nurse monitor for?', '[{"id": "a", "text": "Weight gain and hair growth"}, {"id": "b", "text": "Hypotension and polyuria"}, {"id": "c", "text": "Periorbital edema and hematuria"}, {"id": "d", "text": "Nausea, alopecia, and immunosuppression"}]'::jsonb, '["d"]', 'Post-op nursing care includes monitoring for chemotherapy side effects of nausea, alopecia, and immunosuppression.'),
  ('wilms', 33, 'The parents of a child who had a nephrectomy ask how to alert others, such as emergency personnel, about the child''s condition. Which recommendation by the nurse is appropriate?', '[{"id": "a", "text": "\"Have your child wear a medical alert band.\""}, {"id": "b", "text": "\"Keep the surgical report in the car.\""}, {"id": "c", "text": "\"Tell only the school nurse about it.\""}, {"id": "d", "text": "\"No special identification is needed.\""}]'::jsonb, '["a"]', 'After surgery, the child should wear a "Protect My Kidney" or medical alert band.'),
  ('wilms', 34, 'The nurse is preparing discharge teaching for the parents of a child after nephrectomy for Wilms tumor. Which finding should the parents be taught to report immediately?', '[{"id": "a", "text": "A good appetite at meals"}, {"id": "b", "text": "Blood in the urine"}, {"id": "c", "text": "Normal-colored urine"}, {"id": "d", "text": "Increased energy for play"}]'::jsonb, '["b"]', 'Parents should report any fever, hematuria, abdominal pain, or swelling immediately.'),
  ('wilms', 35, 'The parents of a child who completed treatment for Wilms tumor ask why follow-up visits are still needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"To remove the second kidney if needed.\""}, {"id": "b", "text": "\"To start dialysis on a regular schedule.\""}, {"id": "c", "text": "\"Scans and labs check for tumor recurrence.\""}, {"id": "d", "text": "\"To check whether the kidney regrows.\""}]'::jsonb, '["c"]', 'Regular follow-up with CT scans and labs is needed to monitor for recurrence.'),
  ('wilms', 36, 'The nurse reviews the urinalysis of a child with suspected Wilms tumor. Which finding is associated with this tumor?', '[{"id": "a", "text": "Glucose"}, {"id": "b", "text": "Ketones"}, {"id": "c", "text": "Nitrites"}, {"id": "d", "text": "Hematuria"}]'::jsonb, '["d"]', 'Urinalysis in Wilms tumor may show hematuria.'),
  ('wilms', 37, 'A basic metabolic panel is ordered for a child with Wilms tumor. The parent asks why. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It checks kidney function with BUN and creatinine.\""}, {"id": "b", "text": "\"It checks for spread of the tumor to the lungs.\""}, {"id": "c", "text": "\"It identifies the stage of the tumor.\""}, {"id": "d", "text": "\"It confirms the gene that caused the tumor.\""}]'::jsonb, '["a"]', 'The BMP evaluates renal function through creatinine and BUN. Chest imaging checks for lung metastasis.'),
  ('wilms', 38, 'A child with Wilms tumor is scheduled to begin chemotherapy after nephrectomy. Which medications should the nurse anticipate?', '[{"id": "a", "text": "Penicillin and furosemide"}, {"id": "b", "text": "Vincristine and actinomycin D"}, {"id": "c", "text": "Tolvaptan and an ARB"}, {"id": "d", "text": "Eculizumab and loperamide"}]'::jsonb, '["b"]', 'Chemotherapy for Wilms tumor includes vincristine and actinomycin D.'),
  ('wilms', 39, 'The parents of a child newly diagnosed with Wilms tumor ask about the overall treatment plan. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Chemotherapy alone, with no surgery\""}, {"id": "b", "text": "\"Dialysis followed by a kidney transplant\""}, {"id": "c", "text": "\"Nephrectomy and chemotherapy, possibly radiation\""}, {"id": "d", "text": "\"Antibiotics until the mass disappears\""}]'::jsonb, '["c"]', 'Treatment of Wilms tumor is nephrectomy plus chemotherapy, with or without radiation.'),
  ('wilms', 40, 'A child with Wilms tumor is at home receiving chemotherapy. Which finding reported by the parent requires immediate follow-up?', '[{"id": "a", "text": "Thinning hair"}, {"id": "b", "text": "Mild fatigue"}, {"id": "c", "text": "Decreased appetite"}, {"id": "d", "text": "Fever"}]'::jsonb, '["d"]', 'Parents should report any fever immediately; chemotherapy can cause immunosuppression. Hair loss is an expected chemotherapy side effect.'),
  ('wilms', 41, 'The nurse is supervising an unlicensed assistive personnel (UAP) caring for a child after nephrectomy for Wilms tumor. Which action by the UAP requires correction?', '[{"id": "a", "text": "Limiting the child''s fluids to rest the remaining kidney"}, {"id": "b", "text": "Recording the child''s urine output after each void"}, {"id": "c", "text": "Reporting blood in the child''s urine to the nurse"}, {"id": "d", "text": "Helping the child change position in bed"}]'::jsonb, '["a"]', 'After nephrectomy, adequate hydration should be maintained, so limiting fluids requires correction. Recording output, reporting hematuria, and repositioning are appropriate.'),
  ('wilms', 42, 'The nurse is taking a history from the parent of a child with suspected Wilms tumor. Which history is most typical of how this tumor is discovered?', '[{"id": "a", "text": "The child had severe colicky abdominal pain"}, {"id": "b", "text": "A parent noticed a lump during bath time"}, {"id": "c", "text": "The child had several weeks of bloody stools"}, {"id": "d", "text": "A school screening found high blood sugar"}]'::jsonb, '["b"]', 'The painless abdominal mass of Wilms tumor is often found by a parent during a bath.'),
  ('wilms', 43, 'The nurse is assessing several children after nephrectomy for Wilms tumor. Which finding requires immediate action?', '[{"id": "a", "text": "Incisional pain rated 3 on a 0–10 scale"}, {"id": "b", "text": "Urine output steady over the last 4 hours"}, {"id": "c", "text": "Blood pressure falling and heart rate rising"}, {"id": "d", "text": "Nausea after the first chemotherapy dose"}]'::jsonb, '["c"]', 'Decreased blood pressure with increased heart rate signals possible bleeding or hemorrhage after nephrectomy. Nausea is an expected chemotherapy side effect.'),
  ('wilms', 44, 'The parent of a child who had a nephrectomy asks why the child''s urine is being measured so carefully. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"To check for chemotherapy side effects.\""}, {"id": "b", "text": "\"To decide when to stop pain medicine.\""}, {"id": "c", "text": "\"To see whether the tumor has spread.\""}, {"id": "d", "text": "\"Only one kidney remains to do the work.\""}]'::jsonb, '["d"]', 'Urine output is monitored closely because only one kidney remains and it must maintain adequate function.'),
  ('wilms', 45, 'The parent of a child with an abdominal mass hears the term nephroblastoma and asks what it means. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is another name for Wilms tumor.\""}, {"id": "b", "text": "\"It is a type of kidney infection.\""}, {"id": "c", "text": "\"It is a cyst that is not cancer.\""}, {"id": "d", "text": "\"It is a kind of kidney stone.\""}]'::jsonb, '["a"]', 'Nephroblastoma is another name for Wilms tumor, the most common kidney cancer in children.'),
  ('wilms', 46, 'A 3-year-old child with Wilms tumor has an elevated blood pressure before surgery. The parent asks what is causing it. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Your child is in pain from the mass.\""}, {"id": "b", "text": "\"The tumor releases a substance called renin.\""}, {"id": "c", "text": "\"Your child is drinking too much fluid.\""}, {"id": "d", "text": "\"The tumor has spread to the lungs.\""}]'::jsonb, '["b"]', 'Hypertension in Wilms tumor results from renin secretion by the tumor. The mass itself is typically painless.'),
  ('wilms', 47, 'A chest x-ray is ordered for a child newly diagnosed with Wilms tumor. The parent asks why a chest study is needed for a kidney tumor. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"To check the heart size before surgery.\""}, {"id": "b", "text": "\"To look for pneumonia from the tumor.\""}, {"id": "c", "text": "\"To check whether the tumor has spread to the lungs.\""}, {"id": "d", "text": "\"To measure lung growth for your child''s age.\""}]'::jsonb, '["c"]', 'A chest x-ray or CT is used to check for lung metastasis, because the lung is the primary metastasis site.'),
  ('wilms', 48, 'The parent of a child who had a nephrectomy for Wilms tumor asks why contact sports must be avoided. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Exercise raises the risk of tumor recurrence.\""}, {"id": "b", "text": "\"Physical activity worsens chemotherapy nausea.\""}, {"id": "c", "text": "\"Sports can cause the incision to reopen for years.\""}, {"id": "d", "text": "\"It protects your child''s one remaining kidney.\""}]'::jsonb, '["d"]', 'Contact sports are avoided to protect the solitary kidney that remains after nephrectomy.'),
  ('wilms', 49, 'Which sequence of diagnostic imaging should the nurse anticipate for a child with a suspected Wilms tumor?', '[{"id": "a", "text": "Abdominal ultrasound, then CT of the abdomen and chest"}, {"id": "b", "text": "CT of the abdomen and chest, then abdominal ultrasound"}, {"id": "c", "text": "Chest x-ray only, then nephrectomy without imaging"}, {"id": "d", "text": "Renal biopsy, then abdominal ultrasound"}]'::jsonb, '["a"]', 'Abdominal ultrasound is the first-line, non-invasive test, and CT of the abdomen and chest is then used for staging and to check for metastasis.'),
  ('wilms', 50, 'The nurse is reviewing discharge teaching with the parents of a child who completed treatment for Wilms tumor. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"We will keep all follow-up CT scan appointments.\""}, {"id": "b", "text": "\"Now that surgery is over, no more scans are needed.\""}, {"id": "c", "text": "\"Labs will help check whether the tumor has returned.\""}, {"id": "d", "text": "\"We will report any swelling of the abdomen right away.\""}]'::jsonb, '["b"]', 'Regular follow-up with CT scans and labs is needed to monitor for recurrence. The other statements are correct.'),
  ('pheo', 1, 'A client with pheochromocytoma is admitted for evaluation. Which finding should the nurse expect during a hypertensive episode?', '[{"id": "a", "text": "Profuse sweating"}, {"id": "b", "text": "Slow heart rate"}, {"id": "c", "text": "Low blood glucose"}, {"id": "d", "text": "Recent weight gain"}]'::jsonb, '["a"]', 'Pheochromocytoma causes paroxysmal hypertension with headache, palpitations, and diaphoresis. Low blood glucose is a post-op concern; before surgery hyperglycemia is expected.'),
  ('pheo', 2, 'A client newly diagnosed with pheochromocytoma asks where the tumor is located. The nurse explains that the tumor arises from the', '[{"id": "a", "text": "renal pelvis."}, {"id": "b", "text": "adrenal medulla."}, {"id": "c", "text": "pituitary gland."}, {"id": "d", "text": "bladder wall."}]'::jsonb, '["b"]', 'Pheochromocytoma is a rare tumor of the adrenal medulla. It is not a tumor of the kidney or bladder.'),
  ('pheo', 3, 'The nurse is explaining the cause of symptoms to a client with pheochromocytoma. The tumor produces excess amounts of which hormones?', '[{"id": "a", "text": "Insulin and glucagon"}, {"id": "b", "text": "Cortisol and aldosterone"}, {"id": "c", "text": "Epinephrine and norepinephrine"}, {"id": "d", "text": "Thyroxine and calcitonin"}]'::jsonb, '["c"]', 'Pheochromocytoma secretes excess catecholamines, epinephrine and norepinephrine, which cause severe hypertension. The other hormone pairs are not what this tumor secretes.'),
  ('pheo', 4, 'The nurse is planning the physical assessment of a client with suspected pheochromocytoma. Which assessment technique is contraindicated?', '[{"id": "a", "text": "Auscultating heart sounds"}, {"id": "b", "text": "Measuring blood pressure"}, {"id": "c", "text": "Checking blood glucose"}, {"id": "d", "text": "Palpating the abdomen"}]'::jsonb, '["d"]', 'The abdomen must not be palpated because it can trigger a catecholamine surge and hypertensive crisis. Frequent blood pressure and glucose monitoring are nursing priorities.'),
  ('pheo', 5, 'A new graduate nurse asks why abdominal palpation is avoided for a client with pheochromocytoma. Which explanation by the preceptor is correct?', '[{"id": "a", "text": "\"It can trigger a catecholamine surge and crisis.\""}, {"id": "b", "text": "\"It can cause the tumor to spread to the other side.\""}, {"id": "c", "text": "\"It can cause a sudden, severe drop in blood pressure.\""}, {"id": "d", "text": "\"It can cause the blood glucose to drop suddenly.\""}]'::jsonb, '["a"]', 'Palpating the abdomen triggers a catecholamine surge leading to hypertensive crisis. It causes a spike, not a drop, in blood pressure.'),
  ('pheo', 6, 'A client with pheochromocytoma is being prepared for adrenalectomy. Which medication should the nurse expect to be started first?', '[{"id": "a", "text": "Propranolol"}, {"id": "b", "text": "Phenoxybenzamine"}, {"id": "c", "text": "Insulin"}, {"id": "d", "text": "A decongestant"}]'::jsonb, '["b"]', 'Alpha-blockers such as phenoxybenzamine are started first, before any beta-blocker. Propranolol is a beta-blocker that is added only after alpha-blockade.'),
  ('pheo', 7, 'Which finding should the nurse anticipate as an additional manifestation in a client with pheochromocytoma?', '[{"id": "a", "text": "Slow heart rate"}, {"id": "b", "text": "Weight gain"}, {"id": "c", "text": "Chest pain"}, {"id": "d", "text": "Low blood pressure"}]'::jsonb, '["c"]', 'Along with paroxysmal hypertension, headache, palpitations, and diaphoresis, clients may have tremors, anxiety, chest pain, hyperglycemia, and weight loss. Weight gain is the opposite of the expected weight loss.'),
  ('pheo', 8, 'A client with pheochromocytoma who has not yet received any antihypertensive medication has a new prescription for propranolol only. What is the nurse''s best action?', '[{"id": "a", "text": "Give the dose and recheck the BP in 1 hour"}, {"id": "b", "text": "Hold the dose until the heart rate is above 100"}, {"id": "c", "text": "Give half the dose and monitor the heart rate"}, {"id": "d", "text": "Clarify the order since an alpha-blocker comes first"}]'::jsonb, '["d"]', 'A beta-blocker must never be started before an alpha-blocker because it causes unopposed alpha stimulation that worsens hypertension. The nurse should question the order rather than give any portion of the dose.'),
  ('pheo', 9, 'A nursing student asks why a beta-blocker is never started before an alpha-blocker in a client with pheochromocytoma. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It leaves alpha effects unopposed and worsens hypertension.\""}, {"id": "b", "text": "\"It causes the client''s blood glucose to rise dangerously.\""}, {"id": "c", "text": "\"It causes the heart rate to rise faster than the blood pressure.\""}, {"id": "d", "text": "\"It makes the tumor harder to locate on a CT or MRI scan.\""}]'::jsonb, '["a"]', 'Starting a beta-blocker before an alpha-blocker causes unopposed alpha stimulation, which worsens hypertension. Beta-blockers are given after alpha-blockade to control tachycardia, not to raise heart rate.'),
  ('pheo', 10, 'A client with pheochromocytoma asks why phenoxybenzamine is needed before surgery. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"It raises your blood sugar before the operation.\""}, {"id": "b", "text": "\"It slows your racing heart rate before surgery.\""}, {"id": "c", "text": "\"It widens blood vessels and lowers blood pressure.\""}, {"id": "d", "text": "\"It shrinks the tumor so surgery is not needed.\""}]'::jsonb, '["c"]', 'Alpha-blockers such as phenoxybenzamine dilate vessels, lower BP, and prevent intra-operative hypertensive crisis. Slowing the heart rate is the role of the beta-blocker added afterward.'),
  ('pheo', 11, 'A client with pheochromocytoma who is already receiving phenoxybenzamine is started on propranolol. The nurse understands the purpose of propranolol is to', '[{"id": "a", "text": "dilate the blood vessels."}, {"id": "b", "text": "raise the blood glucose."}, {"id": "c", "text": "prevent orthostatic hypotension."}, {"id": "d", "text": "control tachycardia."}]'::jsonb, '["d"]', 'Beta-blockers such as propranolol are given after the alpha-blocker to control tachycardia. Dilating blood vessels is the action of the alpha-blocker.'),
  ('pheo', 12, 'The nurse is teaching a client with pheochromocytoma about preparation for adrenalectomy. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will keep taking my alpha-blocker as prescribed.\""}, {"id": "b", "text": "\"I will follow a low-salt diet before my surgery.\""}, {"id": "c", "text": "\"I will avoid aged cheese and wine before surgery.\""}, {"id": "d", "text": "\"I will try to stay calm and avoid stressful events.\""}]'::jsonb, '["b"]', 'A high-sodium diet with IV hydration is used before surgery to prevent orthostatic hypotension after surgery, so a low-salt diet is incorrect. Continuing the alpha-blocker and avoiding tyramine foods and stress are correct.'),
  ('pheo', 13, 'A client asks why the pre-operative plan for pheochromocytoma includes a high-sodium diet. The nurse explains that the diet helps to', '[{"id": "a", "text": "prevent orthostatic hypotension after surgery."}, {"id": "b", "text": "raise the blood pressure before the operation."}, {"id": "c", "text": "increase catecholamine release from the tumor."}, {"id": "d", "text": "prevent hyperglycemia during the operation."}]'::jsonb, '["a"]', 'A high-sodium diet with IV hydration prevents orthostatic hypotension post-op. Raising BP before surgery is not the goal, since alpha-blockers are given pre-op to lower BP.'),
  ('pheo', 14, 'A client with pheochromocytoma is receiving IV fluids the day before adrenalectomy and asks why, since he is not dehydrated. Which response by the nurse is best?', '[{"id": "a", "text": "\"The fluids will help flush the tumor''s hormones out.\""}, {"id": "b", "text": "\"The fluids will help prevent low BP after surgery.\""}, {"id": "c", "text": "\"The fluids will help keep your blood sugar from rising.\""}, {"id": "d", "text": "\"The fluids will help your heart rate slow down.\""}]'::jsonb, '["b"]', 'IV hydration together with a high-sodium diet prevents orthostatic hypotension post-op. Slowing the heart rate is the role of the beta-blocker, not IV fluids.'),
  ('pheo', 15, 'A client asks what the main treatment for pheochromocytoma is. The nurse responds that the primary treatment is', '[{"id": "a", "text": "lifelong beta-blocker therapy."}, {"id": "b", "text": "a tyramine-free diet."}, {"id": "c", "text": "surgical adrenalectomy."}, {"id": "d", "text": "a clonidine regimen."}]'::jsonb, '["c"]', 'Adrenalectomy is the primary treatment for pheochromocytoma. Clonidine is used in a suppression test to differentiate pheochromocytoma from other causes of hypertension, not as the main treatment.'),
  ('pheo', 16, 'A client returns to the unit after adrenalectomy for pheochromocytoma. The nurse should closely monitor for which blood pressure change?', '[{"id": "a", "text": "Paroxysmal hypertension"}, {"id": "b", "text": "A widening pulse pressure"}, {"id": "c", "text": "Steady rise in blood pressure"}, {"id": "d", "text": "Hypotension"}]'::jsonb, '["d"]', 'After adrenalectomy, the nurse watches for hypotension due to the drop in catecholamines. Paroxysmal hypertension is the pre-operative problem that surgery treats.'),
  ('pheo', 17, 'A client is 6 hours post-adrenalectomy for pheochromocytoma. Which glucose-related complication should the nurse monitor for?', '[{"id": "a", "text": "Hypoglycemia"}, {"id": "b", "text": "Hyperglycemia"}, {"id": "c", "text": "Ketoacidosis"}, {"id": "d", "text": "Glycosuria"}]'::jsonb, '["a"]', 'Hypoglycemia is a post-op concern after adrenalectomy. Hyperglycemia is the pre-op finding from excess catecholamines.'),
  ('pheo', 18, 'The nurse reviews laboratory results for a client with untreated pheochromocytoma. Which result should the nurse expect?', '[{"id": "a", "text": "Low serum glucose"}, {"id": "b", "text": "High serum glucose"}, {"id": "c", "text": "Low serum sodium"}, {"id": "d", "text": "High serum potassium"}]'::jsonb, '["b"]', 'Before surgery, hyperglycemia is expected with pheochromocytoma. Low glucose is the post-op concern after the tumor is removed.'),
  ('pheo', 19, 'Which pattern of blood glucose should the nurse anticipate in a client before and after adrenalectomy for pheochromocytoma?', '[{"id": "a", "text": "Low before surgery; high after surgery"}, {"id": "b", "text": "Normal before surgery; high after surgery"}, {"id": "c", "text": "High before surgery; low after surgery"}, {"id": "d", "text": "High before surgery; high after surgery"}]'::jsonb, '["c"]', 'Hyperglycemia occurs pre-op, and hypoglycemia is a risk post-op. The reversed pattern (low before, high after) is incorrect.'),
  ('pheo', 20, 'The nurse has taught a client with pheochromocytoma how to avoid triggering episodes. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will avoid decongestants when I have a cold.\""}, {"id": "b", "text": "\"I will try to keep my home quiet and calm.\""}, {"id": "c", "text": "\"I will keep all of my follow-up appointments.\""}, {"id": "d", "text": "\"I can still have aged cheese and wine with dinner.\""}]'::jsonb, '["d"]', 'Tyramine-rich foods such as aged cheese and wine are triggers and should be avoided. Avoiding decongestants, keeping a calm environment, and lifelong follow-up are correct.'),
  ('pheo', 21, 'The nurse is reviewing the home medication list of a client with suspected pheochromocytoma. Which medication should the nurse report to the provider as a potential trigger?', '[{"id": "a", "text": "An MAO inhibitor antidepressant"}, {"id": "b", "text": "Phenoxybenzamine started for blood pressure"}, {"id": "c", "text": "Propranolol added after the alpha-blocker"}, {"id": "d", "text": "IV hydration ordered before surgery"}]'::jsonb, '["a"]', 'MAO inhibitors and decongestants are triggers for pheochromocytoma episodes. Phenoxybenzamine, propranolol given after alpha-blockade, and IV hydration are part of the planned treatment.'),
  ('pheo', 22, 'The charge nurse is assigning a room to a client admitted with pheochromocytoma. Which room is most appropriate?', '[{"id": "a", "text": "A shared room with a talkative roommate"}, {"id": "b", "text": "A private room in a quiet area"}, {"id": "c", "text": "A room beside the busy nurses'' station"}, {"id": "d", "text": "A room next to the unit''s family lounge"}]'::jsonb, '["b"]', 'A calm, quiet environment helps prevent stress-induced episodes. Noisy, busy locations add stress, which is a trigger.'),
  ('pheo', 23, 'A client with pheochromocytoma reports that headaches and palpitations often occur during workouts at the gym. The nurse recognizes that', '[{"id": "a", "text": "exercise is unrelated to these episodes."}, {"id": "b", "text": "exercise lowers catecholamine release."}, {"id": "c", "text": "exercise is a known trigger of episodes."}, {"id": "d", "text": "exercise causes hypoglycemia in this condition."}]'::jsonb, '["c"]', 'Stress, surgery, and exercise are listed triggers of pheochromocytoma episodes. Exercise does not lower catecholamine release.'),
  ('pheo', 24, 'A provider suspects pheochromocytoma in a client with episodic severe hypertension. Which test does the nurse anticipate as the most sensitive screening test?', '[{"id": "a", "text": "CT scan of the abdomen"}, {"id": "b", "text": "Clonidine suppression test"}, {"id": "c", "text": "24-hour urine catecholamines"}, {"id": "d", "text": "Plasma-free metanephrines"}]'::jsonb, '["d"]', 'Plasma-free metanephrines is the most sensitive screening test. CT of the abdomen locates the tumor rather than screening for it.'),
  ('pheo', 25, 'A client with suspected pheochromocytoma is scheduled for a 24-hour urine collection for catecholamines. The client asks the purpose of the test. The nurse explains that it', '[{"id": "a", "text": "confirms excess hormone secretion."}, {"id": "b", "text": "locates the tumor in the adrenal gland."}, {"id": "c", "text": "rules out other causes of hypertension."}, {"id": "d", "text": "measures blood glucose over a full day."}]'::jsonb, '["a"]', 'The 24-hour urine catecholamine test confirms excess hormone secretion. Locating the tumor is done with CT or MRI of the abdomen.'),
  ('pheo', 26, 'After laboratory tests confirm excess catecholamine secretion, a client is scheduled for a CT scan of the abdomen. The nurse explains that the purpose of this scan is to', '[{"id": "a", "text": "measure catecholamine levels in the blood."}, {"id": "b", "text": "locate the adrenal tumor."}, {"id": "c", "text": "confirm excess hormone secretion."}, {"id": "d", "text": "screen for hyperglycemia."}]'::jsonb, '["b"]', 'CT or MRI of the abdomen locates the adrenal tumor. Confirming excess hormone secretion is the purpose of the 24-hour urine catecholamine test.'),
  ('pheo', 27, 'A client with severe hypertension is scheduled for a clonidine suppression test. The nurse understands that the purpose of this test is to', '[{"id": "a", "text": "locate the adrenal tumor on CT or MRI imaging."}, {"id": "b", "text": "treat an acute hypertensive crisis in the client."}, {"id": "c", "text": "differentiate pheochromocytoma from other causes of hypertension."}, {"id": "d", "text": "screen for low blood glucose after an adrenalectomy."}]'::jsonb, '["c"]', 'The clonidine suppression test differentiates pheochromocytoma from other causes of hypertension. Locating the tumor is done with CT or MRI.'),
  ('pheo', 28, 'The nurse is caring for a client hospitalized with pheochromocytoma awaiting surgery. Which assessment is the priority?', '[{"id": "a", "text": "Daily abdominal girth by palpation"}, {"id": "b", "text": "Weekly weight measurement"}, {"id": "c", "text": "Daily urine strain for stones"}, {"id": "d", "text": "Frequent blood pressure checks"}]'::jsonb, '["d"]', 'Blood pressure must be monitored frequently because it can spike dangerously high. Palpating the abdomen is contraindicated because it can trigger a hypertensive crisis.'),
  ('pheo', 29, 'A client with pheochromocytoma has a hypertensive crisis. The nurse monitors for which life-threatening consequence?', '[{"id": "a", "text": "Stroke"}, {"id": "b", "text": "Weight gain"}, {"id": "c", "text": "Hypoglycemia"}, {"id": "d", "text": "Bradycardia"}]'::jsonb, '["a"]', 'A hypertensive crisis is a life-threatening BP spike that can lead to stroke, MI, and organ damage. Hypoglycemia is a post-op concern, not a consequence of crisis.'),
  ('pheo', 30, 'A client with pheochromocytoma on telemetry develops an irregular heart rhythm. The nurse recognizes the most likely cause is', '[{"id": "a", "text": "low catecholamine levels."}, {"id": "b", "text": "excess catecholamines."}, {"id": "c", "text": "a high-sodium diet."}, {"id": "d", "text": "post-op hypoglycemia."}]'::jsonb, '["b"]', 'Arrhythmias in pheochromocytoma occur because excess catecholamines disrupt heart rhythm. Low catecholamine levels occur after tumor removal and cause hypotension.'),
  ('pheo', 31, 'A client with bilateral pheochromocytoma is scheduled to have both adrenal glands removed. The nurse should plan to monitor for which complication that is otherwise rare?', '[{"id": "a", "text": "Hypertensive crisis from palpation"}, {"id": "b", "text": "Arrhythmias from excess hormones"}, {"id": "c", "text": "Adrenal insufficiency"}, {"id": "d", "text": "Pre-op hyperglycemia"}]'::jsonb, '["c"]', 'Adrenal insufficiency is a rare complication that occurs if both adrenal glands are removed. Arrhythmias result from excess catecholamines before the tumor is removed.'),
  ('pheo', 32, 'The nurse is providing discharge teaching to a client after adrenalectomy for pheochromocytoma. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will keep all of my follow-up visits for life.\""}, {"id": "b", "text": "\"I will report any return of headaches or palpitations.\""}, {"id": "c", "text": "\"I will continue to avoid aged cheese and wine for now.\""}, {"id": "d", "text": "\"Now that the tumor is out, I won''t need more follow-up.\""}]'::jsonb, '["d"]', 'Lifelong follow-up is needed because of the risk of recurrence or metastasis. Keeping follow-up visits and reporting returning symptoms are correct.'),
  ('pheo', 33, 'A client who had a benign pheochromocytoma removed asks why lifelong follow-up is needed. The nurse explains that follow-up is necessary because of the risk of', '[{"id": "a", "text": "recurrence or metastasis."}, {"id": "b", "text": "permanent hyperglycemia."}, {"id": "c", "text": "chronic orthostatic hypotension."}, {"id": "d", "text": "tyramine intolerance."}]'::jsonb, '["a"]', 'Lifelong follow-up is needed because of the risk of recurrence or metastasis. Hyperglycemia is a pre-op finding, not the reason for lifelong follow-up.'),
  ('pheo', 34, 'A client newly diagnosed with pheochromocytoma asks, "Is this cancer, and is it in both of my adrenal glands?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is usually malignant and affects both glands.\""}, {"id": "b", "text": "\"It is usually benign and affects one gland.\""}, {"id": "c", "text": "\"It is usually malignant but affects one gland.\""}, {"id": "d", "text": "\"It is usually benign but affects both glands.\""}]'::jsonb, '["b"]', 'Pheochromocytoma is usually benign and unilateral; it is rarely bilateral or malignant. The other options reverse one or both of these features.'),
  ('pheo', 35, 'A client with pheochromocytoma reports episodes of trembling hands and sudden feelings of panic. The nurse recognizes these findings as', '[{"id": "a", "text": "signs of post-op hypoglycemia."}, {"id": "b", "text": "unrelated anxiety needing a separate workup."}, {"id": "c", "text": "manifestations of pheochromocytoma."}, {"id": "d", "text": "adverse effects of a high-sodium diet."}]'::jsonb, '["c"]', 'Tremors and anxiety/panic attacks are listed manifestations of pheochromocytoma. The client has not had surgery, so post-op hypoglycemia does not apply.'),
  ('pheo', 36, 'A client with pheochromocytoma reports losing 5 kg over several months without trying. How should the nurse interpret this finding?', '[{"id": "a", "text": "It suggests the tumor has been removed"}, {"id": "b", "text": "It indicates post-op adrenal insufficiency"}, {"id": "c", "text": "It results from a high-sodium diet"}, {"id": "d", "text": "It is a manifestation of pheochromocytoma"}]'::jsonb, '["d"]', 'Weight loss is a listed manifestation of pheochromocytoma. Adrenal insufficiency is a rare post-op complication after both glands are removed and does not apply to this client.'),
  ('pheo', 37, 'A client''s blood pressure is normal at clinic visits, but she reports sudden severe spikes with headache at home. How should the nurse interpret this pattern in relation to suspected pheochromocytoma?', '[{"id": "a", "text": "It is consistent, since hypertension may be episodic"}, {"id": "b", "text": "It rules out the diagnosis, since hypertension is constant"}, {"id": "c", "text": "It rules out the diagnosis, since it causes hypotension"}, {"id": "d", "text": "It is consistent only if both adrenal glands are involved"}]'::jsonb, '["a"]', 'Pheochromocytoma causes continuous or episodic, life-threatening hypertension, so normal readings between spikes fit the diagnosis. Hypertension does not have to be constant.'),
  ('pheo', 38, 'A client with pheochromocytoma reports a severe headache during an episode. The nurse understands that this headache is caused by', '[{"id": "a", "text": "low blood glucose."}, {"id": "b", "text": "a sudden spike in blood pressure."}, {"id": "c", "text": "orthostatic hypotension."}, {"id": "d", "text": "the high-sodium diet."}]'::jsonb, '["b"]', 'Headache in pheochromocytoma results from a sudden BP spike. Orthostatic hypotension is a post-op concern and would not cause this episodic headache.'),
  ('pheo', 39, 'A client asks why blood pressure medicine is needed for weeks before the tumor can be removed. The nurse explains that surgery itself can trigger catecholamine release and that the alpha-blocker helps to', '[{"id": "a", "text": "raise blood glucose during the operation."}, {"id": "b", "text": "slow the heart rate during the operation."}, {"id": "c", "text": "prevent a hypertensive crisis during surgery."}, {"id": "d", "text": "prevent hypoglycemia during the operation."}]'::jsonb, '["c"]', 'Surgery is a trigger, and alpha-blockers given first dilate vessels, lower BP, and prevent intra-operative hypertensive crisis. Slowing the heart rate is the role of the beta-blocker.'),
  ('pheo', 40, 'A client''s blood pressure drops sharply a few hours after adrenalectomy for pheochromocytoma. The family asks why. The nurse explains that the drop is caused by', '[{"id": "a", "text": "a reaction to the high-sodium diet."}, {"id": "b", "text": "a surge of catecholamines from the tumor."}, {"id": "c", "text": "excess fluid from IV hydration."}, {"id": "d", "text": "sudden catecholamine withdrawal."}]'::jsonb, '["d"]', 'Post-op hypotension results from sudden catecholamine withdrawal after the tumor is removed. A catecholamine surge would raise, not lower, blood pressure.'),
  ('pheo', 41, 'Which parameters are most important for the nurse to monitor in the first hours after adrenalectomy for pheochromocytoma?', '[{"id": "a", "text": "Blood pressure and blood glucose"}, {"id": "b", "text": "Urine catecholamines and weight"}, {"id": "c", "text": "Abdominal palpation and girth"}, {"id": "d", "text": "Plasma metanephrines and weight"}]'::jsonb, '["a"]', 'After adrenalectomy the nurse watches for hypotension and hypoglycemia, so blood pressure and glucose are priorities. Catecholamine and metanephrine levels are diagnostic tests, not immediate post-op monitoring.'),
  ('pheo', 42, 'A client with pheochromocytoma has been on phenoxybenzamine for 2 weeks; BP is improved but the client still has a racing heart. Which medication does the nurse anticipate being added?', '[{"id": "a", "text": "An MAO inhibitor"}, {"id": "b", "text": "Propranolol"}, {"id": "c", "text": "A decongestant"}, {"id": "d", "text": "Clonidine for testing"}]'::jsonb, '["b"]', 'After alpha-blockade, beta-blockers such as propranolol are added to control tachycardia. MAO inhibitors and decongestants are triggers to avoid.'),
  ('pheo', 43, 'A client with pheochromocytoma becomes very upset after a stressful phone call and reports a pounding headache and racing heart. What is the nurse''s first action?', '[{"id": "a", "text": "Palpate the abdomen for a mass"}, {"id": "b", "text": "Encourage a brisk walk to relax"}, {"id": "c", "text": "Offer a snack of cheese and crackers"}, {"id": "d", "text": "Measure the client''s blood pressure"}]'::jsonb, '["d"]', 'Emotional stress is a trigger, and BP must be monitored frequently because it can spike dangerously high. Palpating the abdomen could worsen the episode by triggering a catecholamine surge.'),
  ('pheo', 44, 'The nurse has taught a client with pheochromocytoma about avoiding triggers before a family celebration. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I will skip the wine and aged cheese at the party.\""}, {"id": "b", "text": "\"I will take a decongestant for my stuffy nose.\""}, {"id": "c", "text": "\"I will do an intense workout to burn off stress.\""}, {"id": "d", "text": "\"I will start propranolol before my alpha-blocker.\""}]'::jsonb, '["a"]', 'Tyramine-rich foods such as aged cheese and wine are triggers to avoid. Decongestants and exercise are also triggers, and a beta-blocker must never be started before an alpha-blocker.'),
  ('pheo', 45, 'The nurse is reviewing pre-operative medications for a client with pheochromocytoma. The nurse identifies phenoxybenzamine as belonging to which drug class?', '[{"id": "a", "text": "Beta-blocker"}, {"id": "b", "text": "Decongestant"}, {"id": "c", "text": "Alpha-blocker"}, {"id": "d", "text": "MAO inhibitor"}]'::jsonb, '["c"]', 'Phenoxybenzamine is an alpha-blocker and is given first. Propranolol is the beta-blocker given afterward.'),
  ('pheo', 46, 'A client with pheochromocytoma asks about using an over-the-counter cold medicine. Which response by the nurse is best?', '[{"id": "a", "text": "\"Cold medicines are safe once your blood pressure is controlled.\""}, {"id": "b", "text": "\"Decongestants are safe as long as you take them with food.\""}, {"id": "c", "text": "\"Decongestants can trigger an episode, so avoid them.\""}, {"id": "d", "text": "\"Cold medicines are safe if you avoid exercise that day.\""}]'::jsonb, '["c"]', 'Decongestants, like MAO inhibitors, are triggers that should be avoided. Exercise is also a trigger, but avoiding it does not make a decongestant safe.'),
  ('pheo', 47, 'The nurse is observing an unlicensed assistive personnel (UAP) caring for a client with pheochromocytoma. Which UAP action requires immediate correction?', '[{"id": "a", "text": "Keeping the room quiet and the lights dim"}, {"id": "b", "text": "Reporting a sudden rise in BP right away"}, {"id": "c", "text": "Taking vital signs at the scheduled times"}, {"id": "d", "text": "Massaging the abdomen to ease cramping"}]'::jsonb, '["d"]', 'The abdomen must not be palpated because pressure can trigger a catecholamine surge and hypertensive crisis. A calm, quiet environment and prompt BP reporting are appropriate.'),
  ('pheo', 48, 'Which group of findings should the nurse recognize as the classic presentation of pheochromocytoma?', '[{"id": "a", "text": "Hypotension, bradycardia, and dry skin"}, {"id": "b", "text": "Hypertension, headache, palpitations, and sweating"}, {"id": "c", "text": "Hypotension, hypoglycemia, and weight gain"}, {"id": "d", "text": "Hypertension, bradycardia, and dry skin"}]'::jsonb, '["b"]', 'Pheochromocytoma causes paroxysmal hypertension, headache, palpitations, and diaphoresis from excess catecholamines. Hypotension and hypoglycemia are post-op concerns, not the classic presentation.'),
  ('pheo', 49, 'A client with pheochromocytoma has received phenoxybenzamine for several days before surgery. Which finding indicates the medication is having the desired effect?', '[{"id": "a", "text": "Blood pressure has decreased"}, {"id": "b", "text": "Blood glucose has increased"}, {"id": "c", "text": "Headaches are more frequent"}, {"id": "d", "text": "Weight loss has continued"}]'::jsonb, '["a"]', 'Alpha-blockers such as phenoxybenzamine dilate vessels and lower BP, so a decrease in blood pressure shows effectiveness. More frequent headaches suggest ongoing BP spikes.'),
  ('pheo', 50, 'A client with suspected pheochromocytoma reports sudden episodes of a racing heart, headache, and sweating. Which additional finding should the nurse expect during these episodes?', '[{"id": "a", "text": "Severe hypotension"}, {"id": "b", "text": "Slow heart rate"}, {"id": "c", "text": "Low blood glucose"}, {"id": "d", "text": "Severe hypertension"}]'::jsonb, '["d"]', 'Palpitations, headache, and diaphoresis occur with paroxysmal, severe hypertension from excess catecholamines. Hypotension is a post-op concern after the tumor is removed, not a finding during episodes.')
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale)
  JOIN _renal_seed_map m USING (source_key)
 CROSS JOIN _renal_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _renal_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Renal seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
